import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  descricao?: string;
  tema: string;
  categoria: string;
  nivelDificuldade: 'Iniciante' | 'Intermediário' | 'Avançado';
  professorResponsavel: string;
  professorId: string;
  capaUrl: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
  biografiaDocente?: string;
  fotoDocenteUrl?: string;
  materialApoioUrl?: string;
}

export interface Material {
  id: string;
  title: string;
  url: string;
  courseId: string;
  type: 'pdf' | 'video' | 'link' | 'drive';
  createdAt: any;
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

export interface Exam {
  id: string;
  title: string;
  courseId: string;
  type: 'activity' | 'evaluation';
  passingGrade: number;
  questions: Question[];
  createdAt: any;
}

export interface ExamResult {
  id?: string;
  userId: string;
  userName?: string;
  examId: string;
  score: number;
  passed: boolean;
  attempt: number;
  completedAt: any;
}

export interface Enrollment {
  id: string;
  userId: string;
  courseId: string;
  enrolledAt: any;
  progress: number; // 0-100
}

export interface Feedback {
  id: string;
  userId: string;
  userName: string;
  courseId: string;
  comment: string;
  rating: number;
  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    }, (error) => {
      console.error("Erro na sincronização:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center p-12">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  return (
    <SchoolManagement 
      user={user} 
      courses={myCourses} 
      activeSub={activeSubView} 
    />
  );
};

export default ProfessorView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ExamResult, 
  Enrollment, 
  ProfessorSubView, 
  Material,
  Feedback
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  Pencil,
  Trash2,
  ListChecks,
  Users,
  BarChart3,
  Download,
  Calendar,
  BookOpen,
  ArrowRightCircle,
  GraduationCap,
  ExternalLink,
  FileText,
  PlayCircle,
  Video,
  MessageSquare,
  BarChart,
  Radio,
  Search,
  Filter,
  Image as ImageIcon
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // Common States
  const [exams, setExams] = useState<Exam[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  // Modals & Forms
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [selectedCourseId, setSelectedCourseId] = useState<string>(courses[0]?.id || '');

  // --- 1. REAL-TIME DATA FETCHING ---
  useEffect(() => {
    setLoading(true);
    const unsubExams = onSnapshot(query(collection(db, 'exams'), orderBy('createdAt', 'desc')), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    });
    const unsubMaterials = onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    });
    const unsubFeedback = onSnapshot(query(collection(db, 'feedback'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    });
    const unsubEnroll = onSnapshot(collection(db, 'inscricoes'), (snap) => {
      setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
    });
    const unsubResults = onSnapshot(collection(db, 'exam_results'), (snap) => {
      setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
    });

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    return () => {
      unsubExams(); unsubMaterials(); unsubFeedback(); unsubEnroll(); unsubResults();
    };
  }, []);

  // --- 2. LOGIC HELPERS ---
  const diaryData = useMemo(() => {
    return enrollments
      .filter(e => e.courseId === selectedCourseId)
      .map(enroll => {
        const student = allStudents.find(s => s.uid === enroll.userId);
        const results = examResults.filter(r => r.userId === enroll.userId && exams.find(ex => ex.id === r.examId)?.courseId === selectedCourseId);
        const avg = results.length > 0 ? Math.round(results.reduce((a, b) => a + b.score, 0) / results.length) : 0;
        return {
          ...enroll,
          studentName: student?.displayName || 'Aluno',
          studentPhoto: student?.photoURL,
          avgScore: avg,
          status: enroll.progress >= 100 ? (avg >= 70 ? 'aprovado' : 'reprovado') : 'cursando'
        };
      });
  }, [enrollments, allStudents, examResults, selectedCourseId, exams]);

  // --- 3. EXAM ENGINE STATES ---
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [activeExam, setActiveExam] = useState<Exam | null>(null);
  const [currentQ, setCurrentQ] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);

  // --- 4. MODAL FORMS DATA ---
  const [courseForm, setCourseForm] = useState({
    nome: '', descricao: '', categoria: '', nivelDificuldade: 'Iniciante', capaUrl: '', status: 'rascunho', professorResponsavel: user.displayName
  });
  const [examForm, setExamForm] = useState({
    title: '', courseId: '', type: 'activity', passingGrade: 70, questions: [] as Question[]
  });

  // Actions
  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = { ...courseForm, professorId: user.uid, createdAt: serverTimestamp(), inscritos: 0 };
    if (editingItem) await updateDoc(doc(db, 'cursos', editingItem.id), payload);
    else await addDoc(collection(db, 'cursos'), payload);
    setIsCourseModalOpen(false); setEditingItem(null);
  };

  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (examForm.questions.length === 0) return alert("Adicione pelo menos uma questão.");
    const payload = { ...examForm, createdAt: serverTimestamp(), authorId: user.uid };
    if (editingItem) await updateDoc(doc(db, 'exams', editingItem.id), payload);
    else await addDoc(collection(db, 'exams'), payload);
    setIsExamModalOpen(false); setEditingItem(null);
  };

  const handleDeleteCourse = async (id: string) => {
    if (confirm("Excluir curso permanentemente?")) await deleteDoc(doc(db, 'cursos', id));
  };

  const finishExam = async () => {
    if (!activeExam) return;
    let correct = 0;
    activeExam.questions.forEach((q, i) => { if (userAnswers[i] === q.correctOptionIndex) correct++; });
    const score = Math.round((correct / activeExam.questions.length) * 100);
    setFinalScore(score);
    await addDoc(collection(db, 'exam_results'), {
      userId: user.uid, examId: activeExam.id, score, passed: score >= activeExam.passingGrade, completedAt: serverTimestamp()
    });
    setExamStatus('result');
  };

  // --- 5. RENDER COMPONENTS ---

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* 1. CURSOS */}
      {activeSub === 'cursos' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <div className="flex justify-between items-center mb-6">
            <Header title="Gestão de Cursos" desc="Organize sua grade acadêmica e matrizes curriculares." />
            <button onClick={() => { setEditingItem(null); setCourseForm({ ...courseForm, nome: '' }); setIsCourseModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
              <Plus size={16} /> Novo Curso
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {courses.map(c => (
              <div key={c.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden group hover:border-indigo-300 transition-all">
                <div className="h-40 bg-slate-100 relative overflow-hidden">
                  <img src={c.capaUrl || 'https://images.unsplash.com/photo-1504052434569-70ad5836ab65?q=80&w=2070&auto=format&fit=crop'} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  <div className="absolute top-2 right-2 flex gap-1">
                    <button onClick={() => { setEditingItem(c); setCourseForm(c as any); setIsCourseModalOpen(true); }} className="p-2 bg-white/90 backdrop-blur rounded-lg text-slate-600 hover:text-indigo-600 transition-colors shadow-sm"><Pencil size={14} /></button>
                    <button onClick={() => handleDeleteCourse(c.id)} className="p-2 bg-white/90 backdrop-blur rounded-lg text-slate-600 hover:text-red-600 transition-colors shadow-sm"><Trash2 size={14} /></button>
                  </div>
                </div>
                <div className="p-5">
                  <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-md">{c.categoria}</span>
                  <h3 className="font-bold text-slate-900 mt-2 mb-1">{c.nome}</h3>
                  <p className="text-xs text-slate-500 line-clamp-2 h-8">{c.descricao}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Biblioteca de Materiais" desc="Arquivos, PDFs e links inteligentes para seus alunos." />
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {materials.map(m => {
              const isDrive = m.url.includes('drive.google');
              return (
                <a href={m.url} target="_blank" rel="noreferrer" key={m.id} className="bg-white p-5 rounded-2xl border border-slate-200 flex flex-col items-center text-center group hover:border-indigo-400 hover:shadow-lg transition-all">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 ${isDrive ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                    {isDrive ? <Video size={24} /> : <FileText size={24} />}
                  </div>
                  <h4 className="text-sm font-bold text-slate-900 mb-1">{m.title}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{m.type}</p>
                  <ExternalLink size={14} className="mt-4 text-slate-300 group-hover:text-indigo-600" />
                </a>
              );
            })}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO (EXAMES) */}
      {activeSub === 'avaliacao' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <div className="flex justify-between items-center mb-6">
            <Header title="Banco de Provas" desc="Crie avaliações complexas com correção automática." />
            <button onClick={() => { setEditingItem(null); setIsExamModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-700 shadow-lg">Nova Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between group">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${ex.type === 'evaluation' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{ex.type}</span>
                    <h3 className="font-bold text-slate-900 text-sm">{ex.title}</h3>
                  </div>
                  <p className="text-xs text-slate-400">Nota de Corte: {ex.passingGrade}% | {ex.questions.length} Questões</p>
                </div>
                <button onClick={() => { setActiveExam(ex); setExamStatus('briefing'); }} className="p-3 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 transition-all"><PlayCircle size={18} /></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. DIARIO */}
      {activeSub === 'diario' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Pauta de Notas" desc="Controle absoluto sobre o desempenho dos discentes." />
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <div className="p-4 border-b bg-slate-50 flex items-center justify-between">
              <select value={selectedCourseId} onChange={e => setSelectedCourseId(e.target.value)} className="bg-white border rounded-lg px-3 py-1.5 text-xs font-bold outline-none">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button className="flex items-center gap-2 text-xs font-bold text-indigo-600"><Download size={14} /> Exportar</button>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-tighter">
                <tr>
                  <th className="px-6 py-4">Aluno</th>
                  <th className="px-6 py-4">Progresso</th>
                  <th className="px-6 py-4">Média</th>
                  <th className="px-6 py-4">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {diaryData.map((d, i) => (
                  <tr key={i} className="hover:bg-slate-50/50">
                    <td className="px-6 py-4 flex items-center gap-3">
                      <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 font-bold text-xs">{d.studentName.charAt(0)}</div>
                      <span className="text-xs font-bold text-slate-900">{d.studentName}</span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="w-24 h-1.5 bg-slate-100 rounded-full"><div className="h-full bg-emerald-500 rounded-full" style={{ width: `${d.progress}%` }}></div></div>
                    </td>
                    <td className="px-6 py-4 font-black text-slate-900 text-xs">{d.avgScore}%</td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${d.status === 'aprovado' ? 'bg-emerald-100 text-emerald-700' : d.status === 'reprovado' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-500'}`}>{d.status}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 5. FREQUENCIA */}
      {activeSub === 'frequencia' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Mapa de Frequência" desc="Acompanhe o engajamento diário dos alunos." />
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {diaryData.map((d, i) => (
              <div key={i} className="bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">{d.studentName.charAt(0)}</div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-900">{d.studentName}</h4>
                    <p className="text-[10px] text-slate-400 uppercase font-bold">{d.progress}% concluído</p>
                  </div>
                </div>
                <div className={`w-3 h-3 rounded-full ${d.progress > 0 ? 'bg-emerald-500 animate-pulse' : 'bg-slate-200'}`}></div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 6. RELATORIO */}
      {activeSub === 'relatorio' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Métricas Avançadas" desc="Dados analíticos sobre a eficácia do ensino." />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl">
              <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-2">Total de Alunos</p>
              <h2 className="text-4xl font-black">{allStudents.length}</h2>
              <div className="mt-6 flex items-center gap-2 text-xs font-bold text-emerald-400"><Sparkles size={14} /> Crescimento de 12%</div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-200">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Média de Notas</p>
              <h2 className="text-4xl font-black text-slate-900">84.5%</h2>
              <div className="mt-6 flex items-center gap-2 text-xs font-bold text-indigo-600"><ListChecks size={14} /> Dentro da meta</div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-200">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Cursos Ativos</p>
              <h2 className="text-4xl font-black text-slate-900">{courses.length}</h2>
              <div className="mt-6 flex items-center gap-2 text-xs font-bold text-slate-400"><BookOpen size={14} /> Matriz acadêmica completa</div>
            </div>
          </div>
        </div>
      )}

      {/* 7. LIVE */}
      {activeSub === 'live' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Auditório Virtual" desc="Transmissão em tempo real e agendamentos." />
          <div className="bg-indigo-600 rounded-3xl p-10 text-white flex flex-col items-center text-center">
            <Radio size={64} className="mb-6 animate-pulse" />
            <h2 className="text-2xl font-black mb-2">Nenhuma Aula Iniciada</h2>
            <p className="text-indigo-100 text-sm max-w-sm mb-8">Agende uma nova transmissão para notificar seus alunos e abrir a sala de conferência.</p>
            <button className="bg-white text-indigo-600 px-8 py-3 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:scale-105 transition-all">Agendar Transmissão</button>
          </div>
        </div>
      )}

      {/* 8. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="animate-in slide-in-from-left-4 duration-300">
          <Header title="Mural de Voz" desc="O que os alunos estão dizendo sobre suas aulas." />
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {feedbacks.map(f => (
              <div key={f.id} className="bg-white p-6 rounded-3xl border border-slate-200 relative">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-400">{f.userName.charAt(0)}</div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-900">{f.userName}</h4>
                    <div className="flex gap-0.5 text-amber-400">
                      {[...Array(5)].map((_, i) => <Sparkles key={i} size={10} fill={i < f.rating ? "currentColor" : "none"} />)}
                    </div>
                  </div>
                </div>
                <p className="text-sm text-slate-600 italic leading-relaxed">"{f.comment}"</p>
                <MessageSquare className="absolute top-6 right-6 text-slate-50" size={48} />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* --- EXAM ENGINE OVERLAY --- */}
      {activeExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[500] bg-slate-950 flex items-center justify-center p-0 md:p-10 animate-in fade-in duration-500">
          <div className="bg-white w-full max-w-5xl h-full md:h-[80vh] md:rounded-[40px] shadow-2xl overflow-hidden flex flex-col relative">

            {examStatus === 'briefing' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in-95">
                <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mb-8"><Sparkles size={48} className="animate-spin-slow" /></div>
                <h2 className="text-3xl font-black text-slate-900 italic mb-2 tracking-tighter">Prepare seu coração...</h2>
                <p className="text-slate-500 max-w-md mb-10">O conhecimento é a luz que ilumina a jornada. Respire fundo antes de começar esta avaliação.</p>
                <button onClick={() => setExamStatus('tutorial')} className="bg-slate-900 text-white px-12 py-4 rounded-3xl font-black uppercase text-sm tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Avançar</button>
              </div>
            )}

            {examStatus === 'tutorial' && (
              <div className="flex-1 p-12 flex flex-col justify-center max-w-2xl mx-auto animate-in slide-in-from-right-10">
                <h2 className="text-2xl font-black text-indigo-600 uppercase mb-8 tracking-widest">Instruções</h2>
                <div className="space-y-6 text-slate-600 font-medium">
                  <div className="flex gap-4">
                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center shrink-0 font-bold text-xs">1</div>
                    <p>Você terá que responder {activeExam.questions.length} questões objetivas.</p>
                  </div>
                  <div className="flex gap-4">
                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center shrink-0 font-bold text-xs">2</div>
                    <p>A nota de aprovação é {activeExam.passingGrade}%.</p>
                  </div>
                </div>
                <button onClick={() => { setCurrentQ(0); setUserAnswers({}); setExamStatus('running'); }} className="mt-12 bg-indigo-600 text-white py-5 rounded-3xl font-black uppercase text-sm tracking-widest shadow-xl shadow-indigo-200">Iniciar Prova</button>
              </div>
            )}

            {examStatus === 'running' && (
              <div className="flex-1 flex flex-col h-full animate-in fade-in">
                <div className="p-8 border-b flex items-center justify-between">
                  <h3 className="font-bold text-slate-900">{activeExam.title}</h3>
                  <span className="text-2xl font-black text-slate-200">{currentQ + 1}/{activeExam.questions.length}</span>
                </div>
                <div className="flex-1 p-8 md:p-12 overflow-y-auto bg-slate-50/50">
                  <div className="max-w-3xl mx-auto">
                    <h2 className="text-xl md:text-2xl font-bold text-slate-800 mb-10 leading-tight">{activeExam.questions[currentQ].text}</h2>
                    <div className="grid grid-cols-1 gap-4">
                      {activeExam.questions[currentQ].options.map((opt, i) => (
                        <button key={i} onClick={() => setUserAnswers({...userAnswers, [currentQ]: i})} className={`p-6 rounded-3xl text-left border-2 transition-all flex items-center gap-6 ${userAnswers[currentQ] === i ? 'border-indigo-600 bg-indigo-50' : 'border-white bg-white shadow-sm hover:border-slate-200'}`}>
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-xs ${userAnswers[currentQ] === i ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>{String.fromCharCode(65+i)}</div>
                          <span className="font-bold text-slate-700">{opt}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="p-8 border-t bg-white flex justify-between">
                  <button disabled={currentQ === 0} onClick={() => setCurrentQ(v => v - 1)} className="text-slate-400 font-bold flex items-center gap-2 hover:text-slate-900 transition-colors disabled:opacity-30"><ChevronLeft size={18} /> Anterior</button>
                  {currentQ === activeExam.questions.length - 1 ? (
                    <button onClick={finishExam} className="bg-indigo-600 text-white px-12 py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">Finalizar</button>
                  ) : (
                    <button onClick={() => setCurrentQ(v => v + 1)} className="bg-slate-900 text-white px-10 py-4 rounded-2xl font-black uppercase text-xs tracking-widest">Próxima <ChevronRight size={18} /></button>
                  )}
                </div>
              </div>
            )}

            {examStatus === 'result' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
                <div className={`w-28 h-28 rounded-full flex items-center justify-center mb-8 shadow-2xl ${finalScore >= activeExam.passingGrade ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'}`}><Trophy size={56} /></div>
                <h2 className="text-4xl font-black text-slate-900 italic tracking-tighter mb-4">Seu Desempenho</h2>
                <div className="text-8xl font-black text-slate-900 mb-10 tabular-nums">{finalScore}%</div>
                <button onClick={() => { setExamStatus('idle'); setActiveExam(null); }} className="bg-slate-900 text-white px-12 py-4 rounded-3xl font-black uppercase text-sm tracking-widest shadow-xl">Concluir</button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* --- COURSE MODAL --- */}
      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[400] bg-slate-950/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xl rounded-[40px] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-8 border-b flex justify-between items-center">
              <h3 className="text-xl font-bold">{editingItem ? 'Editar Curso' : 'Novo Curso'}</h3>
              <button onClick={() => setIsCourseModalOpen(false)} className="text-slate-400"><X /></button>
            </div>
            <form onSubmit={handleSaveCourse} className="p-8 overflow-y-auto space-y-6">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Nome do Curso</label>
                <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Categoria</label>
                  <select required value={courseForm.categoria} onChange={e => setCourseForm({...courseForm, categoria: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm font-bold outline-none">
                    <option value="">Selecione...</option>
                    <option value="Doutrina">Doutrina</option>
                    <option value="História">História</option>
                    <option value="Liderança">Liderança</option>
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Nível</label>
                  <select value={courseForm.nivelDificuldade} onChange={e => setCourseForm({...courseForm, nivelDificuldade: e.target.value as any})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm font-bold outline-none">
                    <option value="Iniciante">Iniciante</option>
                    <option value="Intermediário">Intermediário</option>
                    <option value="Avançado">Avançado</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">URL da Capa</label>
                <input required value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none" />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Descrição</label>
                <textarea rows={3} value={courseForm.descricao} onChange={e => setCourseForm({...courseForm, descricao: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none resize-none" />
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-3xl font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-100">Salvar Matriz</button>
            </form>
          </div>
        </div>
      )}

      {/* --- EXAM MODAL --- */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[400] bg-slate-950/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-[40px] overflow-hidden shadow-2xl flex flex-col max-h-[95vh]">
             <div className="p-8 border-b flex justify-between items-center">
                <h3 className="text-xl font-bold">Configurar Avaliação</h3>
                <button onClick={() => setIsExamModalOpen(false)} className="text-slate-400"><X /></button>
             </div>
             <form onSubmit={handleSaveExam} className="p-8 overflow-y-auto space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Título</label>
                    <input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm font-bold outline-none" />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Curso</label>
                    <select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm font-bold outline-none">
                      <option value="">Selecione...</option>
                      {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-4">
                   <div className="flex justify-between items-center">
                     <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Questões ({examForm.questions.length})</h4>
                     <button type="button" onClick={() => setExamForm({...examForm, questions: [...examForm.questions, { id: Date.now().toString(), text: '', options: ['', '', '', ''], correctOptionIndex: 0 }]})} className="text-indigo-600 font-bold text-xs uppercase">+ Adicionar</button>
                   </div>
                   {examForm.questions.map((q, idx) => (
                     <div key={idx} className="p-6 bg-slate-50 rounded-3xl space-y-4">
                        <input placeholder="Enunciado da pergunta..." value={q.text} onChange={e => { const qs = [...examForm.questions]; qs[idx].text = e.target.value; setExamForm({...examForm, questions: qs}); }} className="w-full bg-white border-none rounded-xl p-3 text-xs font-bold" />
                        <div className="grid grid-cols-2 gap-2">
                           {q.options.map((opt, oIdx) => (
                             <div key={oIdx} className="flex items-center gap-2">
                               <input type="radio" checked={q.correctOptionIndex === oIdx} onChange={() => { const qs = [...examForm.questions]; qs[idx].correctOptionIndex = oIdx; setExamForm({...examForm, questions: qs}); }} />
                               <input placeholder={`Opção ${oIdx+1}`} value={opt} onChange={e => { const qs = [...examForm.questions]; qs[idx].options[oIdx] = e.target.value; setExamForm({...examForm, questions: qs}); }} className="bg-white border-none rounded-lg p-2 text-[10px] flex-1" />
                             </div>
                           ))}
                        </div>
                     </div>
                   ))}
                </div>
                <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-3xl font-black uppercase text-xs tracking-widest">Publicar Prova</button>
             </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ExamResult, 
  Enrollment, 
  ProfessorSubView, 
  Material,
  Feedback
} from './types';
import { 
  Plus, 
  X, 
  Trophy,
  Pencil,
  Trash2,
  Download,
  BookOpen,
  ChevronRight,
  ChevronLeft,
  Sparkles,
  PlayCircle,
  FileText,
  Video,
  ExternalLink,
  MessageSquare,
  Radio,
  Clock,
  ShieldCheck,
  ListChecks
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // Global States
  const [exams, setExams] = useState<Exam[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  // Filters
  const [selectedCourseId, setSelectedCourseId] = useState<string>(courses[0]?.id || '');

  // Modals & Forms
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);

  // Sync Data
  useEffect(() => {
    setLoading(true);
    const unsubExams = onSnapshot(query(collection(db, 'exams'), orderBy('createdAt', 'desc')), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    });
    const unsubMaterials = onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    });
    const unsubFeedback = onSnapshot(query(collection(db, 'feedback'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    });
    const unsubEnroll = onSnapshot(collection(db, 'inscricoes'), (snap) => {
      setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
    });
    const unsubResults = onSnapshot(collection(db, 'exam_results'), (snap) => {
      setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
    });

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    return () => {
      unsubExams(); unsubMaterials(); unsubFeedback(); unsubEnroll(); unsubResults();
    };
  }, []);

  // Lógica de Dados para o Diário de Classe
  const diaryData = useMemo(() => {
    if (!selectedCourseId) return [];

    return enrollments
      .filter(e => e.courseId === selectedCourseId)
      .map(enroll => {
        const student = allStudents.find(s => s.uid === enroll.userId);

        // Filtra resultados deste aluno para exames deste curso
        const studentResults = examResults.filter(r => {
          const exam = exams.find(ex => ex.id === r.examId);
          return r.userId === enroll.userId && exam?.courseId === selectedCourseId;
        });

        // Separa atividades de avaliações
        const activityScores = studentResults
          .filter(r => exams.find(ex => ex.id === r.examId)?.type === 'activity')
          .map(r => r.score);

        const evaluationScores = studentResults
          .filter(r => exams.find(ex => ex.id === r.examId)?.type === 'evaluation')
          .map(r => r.score);

        const activityAvg = activityScores.length > 0 
          ? activityScores.reduce((a, b) => a + b, 0) / activityScores.length 
          : 0;

        // Nota da avaliação oficial (maior nota obtida)
        const finalExamScore = evaluationScores.length > 0 ? Math.max(...evaluationScores) : 0;

        // Média Final Simples
        const finalAvg = (activityAvg + finalExamScore) / 2;

        return {
          studentName: student?.displayName || 'Aluno',
          progress: enroll.progress || 0,
          activityScore: parseFloat(activityAvg.toFixed(1)),
          finalExamScore: parseFloat(finalExamScore.toFixed(1)),
          finalAvg: parseFloat(finalAvg.toFixed(1)),
          status: finalAvg >= 70 ? 'Aprovado' : 'Em Recuperação'
        };
      });
  }, [enrollments, allStudents, examResults, selectedCourseId, exams]);

  // Exam Engine States
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [activeExam, setActiveExam] = useState<Exam | null>(null);
  const [currentQ, setCurrentQ] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);

  // Forms Actions
  const [courseForm, setCourseForm] = useState({
    nome: '', descricao: '', categoria: '', nivelDificuldade: 'Iniciante', capaUrl: '', status: 'rascunho', professorResponsavel: user.displayName
  });
  const [examForm, setExamForm] = useState({
    title: '', courseId: '', type: 'activity', passingGrade: 70, questions: [] as Question[]
  });

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = { ...courseForm, professorId: user.uid, createdAt: serverTimestamp(), inscritos: 0 };
    if (editingItem) await updateDoc(doc(db, 'cursos', editingItem.id), payload);
    else await addDoc(collection(db, 'cursos'), payload);
    setIsCourseModalOpen(false); setEditingItem(null);
  };

  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (examForm.questions.length === 0) return alert("Adicione questões.");
    const payload = { ...examForm, createdAt: serverTimestamp(), authorId: user.uid };
    if (editingItem) await updateDoc(doc(db, 'exams', editingItem.id), payload);
    else await addDoc(collection(db, 'exams'), payload);
    setIsExamModalOpen(false); setEditingItem(null);
  };

  const finishExam = async () => {
    if (!activeExam) return;
    let correct = 0;
    activeExam.questions.forEach((q, i) => { if (userAnswers[i] === q.correctOptionIndex) correct++; });
    const score = Math.round((correct / activeExam.questions.length) * 100);
    setFinalScore(score);
    await addDoc(collection(db, 'exam_results'), {
      userId: user.uid, examId: activeExam.id, score, passed: score >= activeExam.passingGrade, completedAt: serverTimestamp()
    });
    setExamStatus('result');
  };

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  return (
    <div className="space-y-6">

      {/* 1. CURSOS */}
      {activeSub === 'cursos' && (
        <div className="animate-in slide-in-from-left-4">
          <div className="flex justify-between items-center mb-6">
            <Header title="Gestão de Cursos" desc="Organize sua grade acadêmica e matrizes curriculares." />
            <button onClick={() => { setEditingItem(null); setIsCourseModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 shadow-lg">Novo Curso</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {courses.map(c => (
              <div key={c.id} className="bg-white rounded-2xl border border-slate-200 overflow-hidden group hover:border-indigo-300 transition-all">
                <div className="h-40 bg-slate-100 relative">
                  <img src={c.capaUrl} className="w-full h-full object-cover" />
                  <div className="absolute top-2 right-2 flex gap-1">
                    <button onClick={() => { setEditingItem(c); setCourseForm(c as any); setIsCourseModalOpen(true); }} className="p-2 bg-white rounded-lg text-slate-600"><Pencil size={14} /></button>
                  </div>
                </div>
                <div className="p-5">
                  <span className="text-[10px] font-bold text-indigo-600 uppercase bg-indigo-50 px-2 py-0.5 rounded">{c.categoria}</span>
                  <h3 className="font-bold text-slate-900 mt-2">{c.nome}</h3>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="animate-in slide-in-from-left-4">
          <Header title="Biblioteca" desc="Materiais de apoio vinculados aos cursos." />
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {materials.map(m => (
              <a href={m.url} target="_blank" rel="noreferrer" key={m.id} className="bg-white p-5 rounded-2xl border border-slate-200 text-center hover:border-indigo-400">
                <div className="w-12 h-12 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center mx-auto mb-4"><FileText size={24} /></div>
                <h4 className="text-sm font-bold text-slate-900">{m.title}</h4>
                <p className="text-[10px] text-slate-400 uppercase mt-1">{m.type}</p>
              </a>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="animate-in slide-in-from-left-4">
          <div className="flex justify-between items-center mb-6">
            <Header title="Banco de Provas" desc="Avaliações objetivas com correção em tempo real." />
            <button onClick={() => { setEditingItem(null); setIsExamModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-xs font-bold">Nova Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between">
                <div>
                  <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${ex.type === 'evaluation' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{ex.type}</span>
                  <h3 className="font-bold text-slate-900 text-sm mt-1">{ex.title}</h3>
                </div>
                <button onClick={() => { setActiveExam(ex); setExamStatus('briefing'); }} className="p-3 bg-slate-900 text-white rounded-xl hover:bg-indigo-600"><PlayCircle size={18} /></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. DIÁRIO DE CLASSE (TABELA ACADÊMICA PURA) */}
      {activeSub === 'diario' && (
        <div className="animate-in slide-in-from-left-4 space-y-6">
          <Header title="Diário de Classe" desc="Controle numérico de desempenho e progresso acadêmico." />

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <div className="p-4 border-b bg-slate-50 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filtro:</span>
                <select 
                  value={selectedCourseId} 
                  onChange={e => setSelectedCourseId(e.target.value)} 
                  className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  <option value="">Selecione um curso...</option>
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <button className="flex items-center gap-2 text-xs font-bold text-slate-600 hover:text-indigo-600 transition-colors">
                <Download size={14} /> Exportar Pauta
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50/80 text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-slate-100">
                  <tr>
                    <th className="px-6 py-4">Aluno</th>
                    <th className="px-6 py-4">Progresso</th>
                    <th className="px-6 py-4">Nota: Atividades</th>
                    <th className="px-6 py-4">Nota: Prova Final</th>
                    <th className="px-6 py-4">Média Final</th>
                    <th className="px-6 py-4">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {loading ? (
                    <tr><td colSpan={6} className="px-6 py-10 text-center text-xs text-slate-400 font-medium">Sincronizando registros acadêmicos...</td></tr>
                  ) : diaryData.length > 0 ? (
                    diaryData.map((d, i) => (
                      <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                          <span className="text-xs font-bold text-slate-900">{d.studentName}</span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            <div className="w-16 h-1 bg-slate-100 rounded-full overflow-hidden">
                              <div className="h-full bg-indigo-500" style={{ width: `${d.progress}%` }}></div>
                            </div>
                            <span className="text-[10px] font-black text-slate-400">{d.progress}%</span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm font-bold text-slate-600">{d.activityScore}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm font-bold text-slate-600">{d.finalExamScore}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm font-black text-slate-900">{d.finalAvg}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`text-[10px] font-black uppercase tracking-widest ${
                            d.status === 'Aprovado' ? 'text-emerald-600' : 'text-amber-500'
                          }`}>
                            {d.status}
                          </span>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr><td colSpan={6} className="px-6 py-10 text-center text-xs text-slate-400 font-medium italic">Nenhuma inscrição encontrada para este curso.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* OUTRAS ABAS (Isoladas) */}
      {activeSub === 'frequencia' && <Header title="Frequência" desc="Mapa de engajamento diário." />}
      {activeSub === 'relatorio' && <Header title="Relatórios" desc="Métricas avançadas de desempenho." />}
      {activeSub === 'live' && <Header title="Live" desc="Sala de transmissão em tempo real." />}
      {activeSub === 'feedback' && <Header title="Feedbacks" desc="Opinião dos alunos sobre as aulas." />}

      {/* MODAIS (COURSE & EXAM) - Mantidos intactos conforme solicitado */}
      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[500] bg-slate-950/60 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xl rounded-3xl p-8">
            <h2 className="text-xl font-bold mb-6">Configurar Matriz</h2>
            <form onSubmit={handleSaveCourse} className="space-y-4">
              <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Nome do Curso" className="w-full p-3 bg-slate-50 border-none rounded-xl" />
              <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold">Salvar</button>
            </form>
          </div>
        </div>
      )}

      {/* ENGINE DE PROVAS - Mantido intacto */}
      {activeExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[600] bg-slate-950 flex items-center justify-center">
           {/* ... UI do Motor de Provas ... */}
           <div className="bg-white w-full max-w-4xl h-full md:h-[80vh] rounded-3xl overflow-hidden flex flex-col p-10 items-center justify-center text-center">
              {examStatus === 'briefing' && (
                <div className="space-y-6">
                  <h2 className="text-3xl font-black italic">Respire fundo...</h2>
                  <p className="text-slate-500 max-w-md">O conhecimento é luz. Faça sua avaliação com calma.</p>
                  <button onClick={() => setExamStatus('tutorial')} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-bold">Começar</button>
                </div>
              )}
              {/* Reset state if finished or error */}
              {(examStatus === 'tutorial' || examStatus === 'running' || examStatus === 'result') && (
                <button onClick={() => setExamStatus('idle')} className="mt-10 text-slate-400 font-bold text-xs uppercase underline">Sair da Prova</button>
              )}
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

