  displayName: string;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  descricao?: string;
  tema: string;
  categoria: string;
  nivelDificuldade: 'Iniciante' | 'Intermediário' | 'Avançado';
  professorResponsavel: string;
  professorId: string;
  capaUrl: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
  biografiaDocente?: string;
  fotoDocenteUrl?: string;
  materialApoioUrl?: string;
}

