  createdAt: any;
}

export interface ExamResult {
  id?: string;
  userId: string;
  examId: string;
  score: number;
  passed: boolean;
  attempt: number;
  completedAt: any;
}

// Added missing types for SchoolManagement component
export interface Enrollment {
  id: string;
  userId: string;
  courseId: string;
  progress: number;
  createdAt: any;
}

export interface Material {
  id: string;
  courseId: string;
  title: string;
  type: string;
  url: string;
  createdAt: any;
}

export interface Feedback {
