  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  doc, 
  serverTimestamp 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  User as UserIcon, 
  FileText, 
  Image as ImageIcon,
  Trash2,
  Pencil
} from 'lucide-react';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

type ModalTab = 'geral' | 'docente' | 'midias';

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [activeTab, setActiveTab] = useState<ModalTab>('geral');

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tema: '',
    categoria: '',
    nivelDificuldade: 'Iniciante' as Course['nivelDificuldade'],
    capaUrl: '',
    status: 'rascunho' as Course['status'],
    professorResponsavel: user.displayName || '',
    biografiaDocente: '',
    fotoDocenteUrl: '',
    materialApoioUrl: ''
  });

  // 1. LISTAGEM EM TEMPO REAL
  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    }, (error) => {
      console.error("Erro na sincronização em tempo real:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  // 2. SALVAMENTO NO FIRESTORE
  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coursePayload = {
        ...formData,
        professorId: user.uid,
        inscritos: editingCourse ? editingCourse.inscritos : 0,
        createdAt: editingCourse ? editingCourse.createdAt : serverTimestamp(),
      };

      if (editingCourse) {
        const courseRef = doc(db, 'cursos', editingCourse.id);
        await updateDoc(courseRef, coursePayload);
      } else {
        await addDoc(collection(db, 'cursos'), coursePayload);
      }

      setIsModalOpen(false);
      setEditingCourse(null);
      resetForm();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
      alert("Erro ao salvar curso no banco de dados.");
    }
  };

  // 3. EXCLUSÃO DE CURSO
  const handleDeleteCourse = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Evita abrir o modal de edição ao clicar na lixeira
    if (confirm('Tem certeza que deseja excluir este curso e todos os seus dados permanentemente? Esta ação não pode ser desfeita.')) {
      try {
        await deleteDoc(doc(db, 'cursos', courseId));
      } catch (error) {
        console.error("Erro ao excluir curso:", error);
        alert("Erro ao excluir o curso.");
      }
    }
  };

  const resetForm = () => {
    setFormData({
      nome: '',
      descricao: '',
      tema: '',
      categoria: '',
      nivelDificuldade: 'Iniciante',
      capaUrl: '',
      status: 'rascunho',
      professorResponsavel: user.displayName || '',
      biografiaDocente: '',
      fotoDocenteUrl: '',
      materialApoioUrl: ''
    });
    setActiveTab('geral');
  };

  const openEditModal = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      nome: course.nome,
      descricao: course.descricao || '',
      tema: course.tema || '',
      categoria: course.categoria,
      nivelDificuldade: course.nivelDificuldade,
      capaUrl: course.capaUrl,
      status: course.status,
      professorResponsavel: course.professorResponsavel,
      biografiaDocente: course.biografiaDocente || '',
      fotoDocenteUrl: course.fotoDocenteUrl || '',
      materialApoioUrl: course.materialApoioUrl || ''
    });
    setActiveTab('geral');
    setIsModalOpen(true);
  };

  // RENDERIZAÇÃO CONDICIONAL BASEADA NA SUBVIEW DA SIDEBAR
  // Added fix for missing activeSub prop and expanded conditional to delegate more subviews to SchoolManagement
  const shouldDelegateToManagement = ['avaliacao', 'diario', 'materiais', 'feedback', 'relatorio', 'frequencia', 'live'].includes(activeSubView || '');

  if (shouldDelegateToManagement) {
    return <SchoolManagement user={user} courses={myCourses} activeSub={activeSubView as ProfessorSubView} />;
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Portal do Professor</h1>
          <p className="text-slate-500 text-sm">Olá, {user.displayName}. Gerencie seu conteúdo acadêmico aqui.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setEditingCourse(null); setIsModalOpen(true); }}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-sm"
        >
          <Plus size={18} />
          Criar Novo Conteúdo
        </button>
      </header>

      {/* Alerta de Contexto */}
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex gap-3 items-start">
        <Info className="text-indigo-600 mt-0.5 shrink-0" size={18} />
        <div>
          <p className="text-sm font-semibold text-indigo-900 leading-none mb-1">Sincronização Ativa</p>
          <p className="text-xs text-indigo-700">Seus cursos estão sendo listados em tempo real do Firestore para seu ID: {user.uid}.</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Pesquisar nos meus cursos..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
          <button className="flex items-center gap-2 text-slate-600 px-3 py-1.5 border border-slate-200 rounded-lg text-xs font-semibold hover:bg-slate-50">
            <Filter size={14} />
            Filtrar por Status
          </button>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
          </div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 p-4">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                className="border border-slate-100 p-4 rounded-xl hover:shadow-md transition-all cursor-pointer group bg-slate-50/50 relative"
                onClick={() => openEditModal(course)}
              >
                <div className="flex justify-between items-start mb-3">
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                    course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'
                  }`}>
                    {course.status}
                  </span>
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); openEditModal(course); }}
                      className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"
                      title="Editar"
                    >
                      <Pencil size={14} />
                    </button>
                    <button 
                      onClick={(e) => handleDeleteCourse(course.id, e)}
                      className="p-1.5 text-slate-300 hover:text-red-600 hover:bg-white rounded-lg transition-all"
                      title="Excluir"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>

                {course.capaUrl && (
                  <div className="w-full h-32 mb-3 overflow-hidden rounded-lg bg-slate-200">
                    <img src={course.capaUrl} alt={course.nome} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  </div>
                )}

                <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-1">{course.nome}</h3>
                <div className="flex gap-2 mb-2">
                   <span className="text-[9px] bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.categoria}</span>
                   <span className="text-[9px] bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.nivelDificuldade}</span>
                </div>
                <p className="text-xs text-slate-500 line-clamp-2 mb-4 h-8">{course.descricao || 'Sem descrição cadastrada.'}</p>
                <div className="flex items-center justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider pt-3 border-t border-slate-100">
                  <span>{course.inscritos} Alunos</span>
                  <button className="text-indigo-600 hover:underline">Ver Detalhes</button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-12 opacity-50">
            <div className="bg-slate-100 p-4 rounded-full mb-4 text-slate-400">
              <BookOpen size={40} />
            </div>
            <p className="text-slate-600 font-bold text-sm">Nenhum curso sob sua gestão</p>
            <p className="text-xs text-slate-400 mt-1 max-w-xs mx-auto">Crie seu primeiro curso ou peça ao diretor para vinculá-lo como professor de uma turma existente.</p>
          </div>
        )}
      </div>

      {/* Modal de Cadastro/Edição com Abas */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Header Modal */}
            <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900">{editingCourse ? 'Editar Matriz Acadêmica' : 'Nova Matriz Acadêmica'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-lg transition-colors">
                <X size={20} className="text-slate-500" />
              </button>
            </div>

            {/* Abas (Tabs) */}
            <div className="flex border-b border-slate-100 px-6 bg-slate-50/50">
              {(['geral', 'docente', 'midias'] as ModalTab[]).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-4 py-3 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${
                    activeTab === tab 
                      ? 'border-indigo-600 text-indigo-600' 
                      : 'border-transparent text-slate-400 hover:text-slate-600'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    {tab === 'geral' && <FileText size={14} />}
                    {tab === 'docente' && <UserIcon size={14} />}
                    {tab === 'midias' && <ImageIcon size={14} />}
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </div>
                </button>
              ))}
            </div>

            <form onSubmit={handleSaveCourse} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
              {/* ABA GERAL */}
              {activeTab === 'geral' && (
                <div className="space-y-4 animate-in slide-in-from-left-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nome do Curso</label>
                    <input 
                      required
                      type="text" 
                      value={formData.nome}
                      onChange={(e) => setFormData({...formData, nome: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Ex: Teologia Sistemática I"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Categoria</label>
                      <select 
                        required
                        value={formData.categoria}
                        onChange={(e) => setFormData({...formData, categoria: e.target.value})}
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      >
                        <option value="">Selecione...</option>
                        <option value="Básico">Básico</option>
                        <option value="Doutrina">Doutrina</option>
                        <option value="História">História</option>
                        <option value="Liderança">Liderança</option>
                        <option value="Família">Família</option>
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nível</label>
                      <select 
                        value={formData.nivelDificuldade}
                        onChange={(e) => setFormData({...formData, nivelDificuldade: e.target.value as any})}
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      >
                        <option value="Iniciante">Iniciante</option>
                        <option value="Intermediário">Intermediário</option>
                        <option value="Avançado">Avançado</option>
                      </select>
                    </div>
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Ementa / Descrição</label>
                    <textarea 
                      rows={4}
                      value={formData.descricao}
                      onChange={(e) => setFormData({...formData, descricao: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none transition-all"
                      placeholder="Resumo do que será abordado no curso..."
                    ></textarea>
                  </div>
                </div>
              )}

              {/* ABA DOCENTE */}
              {activeTab === 'docente' && (
                <div className="space-y-4 animate-in slide-in-from-right-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nome do Professor Responsável</label>
                    <input 
                      required
                      type="text" 
                      value={formData.professorResponsavel}
                      onChange={(e) => setFormData({...formData, professorResponsavel: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Nome completo do docente"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL da Foto do Professor</label>
                    <input 
                      type="url" 
                      value={formData.fotoDocenteUrl}
                      onChange={(e) => setFormData({...formData, fotoDocenteUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="https://exemplo.com/foto-professor.jpg"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Biografia Acadêmica</label>
                    <textarea 
                      rows={4}
                      value={formData.biografiaDocente}
                      onChange={(e) => setFormData({...formData, biografiaDocente: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none transition-all"
                      placeholder="Mini currículo do professor..."
                    ></textarea>
                  </div>
                </div>
              )}

              {/* ABA MÍDIAS */}
              {activeTab === 'midias' && (
                <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL da Capa do Curso</label>
                    <input 
                      required
                      type="url" 
                      value={formData.capaUrl}
                      onChange={(e) => setFormData({...formData, capaUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="https://exemplo.com/capa-curso.jpg"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL do Material de Apoio (PDF/Drive)</label>
                    <input 
                      type="url" 
                      value={formData.materialApoioUrl}
                      onChange={(e) => setFormData({...formData, materialApoioUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Link para material complementar"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Status de Publicação</label>
                    <select 
                      value={formData.status}
                      onChange={(e) => setFormData({...formData, status: e.target.value as any})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all font-bold"
                    >
                      <option value="rascunho">Rascunho (Privado)</option>
                      <option value="ativo">Ativo (Publicado)</option>
                    </select>
                  </div>
                </div>
              )}

              <div className="pt-6 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-slate-200 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 active:scale-95"
                >
                  {editingCourse ? 'Atualizar Matriz' : 'Salvar Matriz'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  descricao?: string;
  tema: string;
  categoria: string;
  nivelDificuldade: 'Iniciante' | 'Intermediário' | 'Avançado';
  professorResponsavel: string;
  professorId: string;
  capaUrl: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
  biografiaDocente?: string;
  fotoDocenteUrl?: string;
  materialApoioUrl?: string;
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

export interface Exam {
  id: string;
  title: string;
  courseId: string;
  type: 'activity' | 'evaluation';
  passingGrade: number;
  questions: Question[];
  createdAt: any;
  authorId?: string;
  updatedAt?: any;
}

export interface ExamResult {
  id?: string;
  userId: string;
  examId: string;
  score: number;
  passed: boolean;
  attempt: number;
  completedAt: any;
  userRole?: string;
  userName?: string;
}

export interface Enrollment {
  id: string;
  userId: string;
  courseId: string;
  progress: number;
  enrolledAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  doc, 
  serverTimestamp 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  User as UserIcon, 
  FileText, 
  Image as ImageIcon,
  Trash2,
  Pencil
} from 'lucide-react';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

type ModalTab = 'geral' | 'docente' | 'midias';

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [activeTab, setActiveTab] = useState<ModalTab>('geral');

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tema: '',
    categoria: '',
    nivelDificuldade: 'Iniciante' as Course['nivelDificuldade'],
    capaUrl: '',
    status: 'rascunho' as Course['status'],
    professorResponsavel: user.displayName || '',
    biografiaDocente: '',
    fotoDocenteUrl: '',
    materialApoioUrl: ''
  });

  // 1. LISTAGEM EM TEMPO REAL
  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    }, (error) => {
      console.error("Erro na sincronização em tempo real:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  // 2. SALVAMENTO NO FIRESTORE
  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coursePayload = {
        ...formData,
        professorId: user.uid,
        inscritos: editingCourse ? editingCourse.inscritos : 0,
        createdAt: editingCourse ? editingCourse.createdAt : serverTimestamp(),
      };

      if (editingCourse) {
        const courseRef = doc(db, 'cursos', editingCourse.id);
        await updateDoc(courseRef, coursePayload);
      } else {
        await addDoc(collection(db, 'cursos'), coursePayload);
      }

      setIsModalOpen(false);
      setEditingCourse(null);
      resetForm();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
      alert("Erro ao salvar curso no banco de dados.");
    }
  };

  // 3. EXCLUSÃO DE CURSO
  const handleDeleteCourse = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Evita abrir o modal de edição ao clicar na lixeira
    if (confirm('Tem certeza que deseja excluir este curso e todos os seus dados permanentemente? Esta ação não pode ser desfeita.')) {
      try {
        await deleteDoc(doc(db, 'cursos', courseId));
      } catch (error) {
        console.error("Erro ao excluir curso:", error);
        alert("Erro ao excluir o curso.");
      }
    }
  };

  const resetForm = () => {
    setFormData({
      nome: '',
      descricao: '',
      tema: '',
      categoria: '',
      nivelDificuldade: 'Iniciante',
      capaUrl: '',
      status: 'rascunho',
      professorResponsavel: user.displayName || '',
      biografiaDocente: '',
      fotoDocenteUrl: '',
      materialApoioUrl: ''
    });
    setActiveTab('geral');
  };

  const openEditModal = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      nome: course.nome,
      descricao: course.descricao || '',
      tema: course.tema || '',
      categoria: course.categoria,
      nivelDificuldade: course.nivelDificuldade,
      capaUrl: course.capaUrl,
      status: course.status,
      professorResponsavel: course.professorResponsavel,
      biografiaDocente: course.biografiaDocente || '',
      fotoDocenteUrl: course.fotoDocenteUrl || '',
      materialApoioUrl: course.materialApoioUrl || ''
    });
    setActiveTab('geral');
    setIsModalOpen(true);
  };

  // RENDERIZAÇÃO CONDICIONAL BASEADA NA SUBVIEW DA SIDEBAR
  if (activeSubView === 'avaliacao' || activeSubView === 'diario') {
    return <SchoolManagement user={user} courses={myCourses} activeSub={activeSubView} />;
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Portal do Professor</h1>
          <p className="text-slate-500 text-sm">Olá, {user.displayName}. Gerencie seu conteúdo acadêmico aqui.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setEditingCourse(null); setIsModalOpen(true); }}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-sm"
        >
          <Plus size={18} />
          Criar Novo Conteúdo
        </button>
      </header>

      {/* Alerta de Contexto */}
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex gap-3 items-start">
        <Info className="text-indigo-600 mt-0.5 shrink-0" size={18} />
        <div>
          <p className="text-sm font-semibold text-indigo-900 leading-none mb-1">Sincronização Ativa</p>
          <p className="text-xs text-indigo-700">Seus cursos estão sendo listados em tempo real do Firestore para seu ID: {user.uid}.</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Pesquisar nos meus cursos..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
          <button className="flex items-center gap-2 text-slate-600 px-3 py-1.5 border border-slate-200 rounded-lg text-xs font-semibold hover:bg-slate-50">
            <Filter size={14} />
            Filtrar por Status
          </button>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
          </div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 p-4">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                className="border border-slate-100 p-4 rounded-xl hover:shadow-md transition-all cursor-pointer group bg-slate-50/50 relative"
                onClick={() => openEditModal(course)}
              >
                <div className="flex justify-between items-start mb-3">
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                    course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'
                  }`}>
                    {course.status}
                  </span>
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); openEditModal(course); }}
                      className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"
                      title="Editar"
                    >
                      <Pencil size={14} />
                    </button>
                    <button 
                      onClick={(e) => handleDeleteCourse(course.id, e)}
                      className="p-1.5 text-slate-300 hover:text-red-600 hover:bg-white rounded-lg transition-all"
                      title="Excluir"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>

                {course.capaUrl && (
                  <div className="w-full h-32 mb-3 overflow-hidden rounded-lg bg-slate-200">
                    <img src={course.capaUrl} alt={course.nome} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  </div>
                )}

                <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-1">{course.nome}</h3>
                <div className="flex gap-2 mb-2">
                   <span className="text-[9px] bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.categoria}</span>
                   <span className="text-[9px] bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.nivelDificuldade}</span>
                </div>
                <p className="text-xs text-slate-500 line-clamp-2 mb-4 h-8">{course.descricao || 'Sem descrição cadastrada.'}</p>
                <div className="flex items-center justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider pt-3 border-t border-slate-100">
                  <span>{course.inscritos} Alunos</span>
                  <button className="text-indigo-600 hover:underline">Ver Detalhes</button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-12 opacity-50">
            <div className="bg-slate-100 p-4 rounded-full mb-4 text-slate-400">
              <BookOpen size={40} />
            </div>
            <p className="text-slate-600 font-bold text-sm">Nenhum curso sob sua gestão</p>
            <p className="text-xs text-slate-400 mt-1 max-w-xs mx-auto">Crie seu primeiro curso ou peça ao diretor para vinculá-lo como professor de uma turma existente.</p>
          </div>
        )}
      </div>

      {/* Modal de Cadastro/Edição com Abas */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Header Modal */}
            <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900">{editingCourse ? 'Editar Matriz Acadêmica' : 'Nova Matriz Acadêmica'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-lg transition-colors">
                <X size={20} className="text-slate-500" />
              </button>
            </div>

            {/* Abas (Tabs) */}
            <div className="flex border-b border-slate-100 px-6 bg-slate-50/50">
              {(['geral', 'docente', 'midias'] as ModalTab[]).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-4 py-3 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${
                    activeTab === tab 
                      ? 'border-indigo-600 text-indigo-600' 
                      : 'border-transparent text-slate-400 hover:text-slate-600'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    {tab === 'geral' && <FileText size={14} />}
                    {tab === 'docente' && <UserIcon size={14} />}
                    {tab === 'midias' && <ImageIcon size={14} />}
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </div>
                </button>
              ))}
            </div>

            <form onSubmit={handleSaveCourse} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
              {/* ABA GERAL */}
              {activeTab === 'geral' && (
                <div className="space-y-4 animate-in slide-in-from-left-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nome do Curso</label>
                    <input 
                      required
                      type="text" 
                      value={formData.nome}
                      onChange={(e) => setFormData({...formData, nome: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Ex: Teologia Sistemática I"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Categoria</label>
                      <select 
                        required
                        value={formData.categoria}
                        onChange={(e) => setFormData({...formData, categoria: e.target.value})}
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      >
                        <option value="">Selecione...</option>
                        <option value="Básico">Básico</option>
                        <option value="Doutrina">Doutrina</option>
                        <option value="História">História</option>
                        <option value="Liderança">Liderança</option>
                        <option value="Família">Família</option>
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nível</label>
                      <select 
                        value={formData.nivelDificuldade}
                        onChange={(e) => setFormData({...formData, nivelDificuldade: e.target.value as any})}
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      >
                        <option value="Iniciante">Iniciante</option>
                        <option value="Intermediário">Intermediário</option>
                        <option value="Avançado">Avançado</option>
                      </select>
                    </div>
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Ementa / Descrição</label>
                    <textarea 
                      rows={4}
                      value={formData.descricao}
                      onChange={(e) => setFormData({...formData, descricao: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none transition-all"
                      placeholder="Resumo do que será abordado no curso..."
                    ></textarea>
                  </div>
                </div>
              )}

              {/* ABA DOCENTE */}
              {activeTab === 'docente' && (
                <div className="space-y-4 animate-in slide-in-from-right-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nome do Professor Responsável</label>
                    <input 
                      required
                      type="text" 
                      value={formData.professorResponsavel}
                      onChange={(e) => setFormData({...formData, professorResponsavel: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Nome completo do docente"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL da Foto do Professor</label>
                    <input 
                      type="url" 
                      value={formData.fotoDocenteUrl}
                      onChange={(e) => setFormData({...formData, fotoDocenteUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="https://exemplo.com/foto-professor.jpg"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Biografia Acadêmica</label>
                    <textarea 
                      rows={4}
                      value={formData.biografiaDocente}
                      onChange={(e) => setFormData({...formData, biografiaDocente: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none transition-all"
                      placeholder="Mini currículo do professor..."
                    ></textarea>
                  </div>
                </div>
              )}

              {/* ABA MÍDIAS */}
              {activeTab === 'midias' && (
                <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-300">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL da Capa do Curso</label>
                    <input 
                      required
                      type="url" 
                      value={formData.capaUrl}
                      onChange={(e) => setFormData({...formData, capaUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="https://exemplo.com/capa-curso.jpg"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">URL do Material de Apoio (PDF/Drive)</label>
                    <input 
                      type="url" 
                      value={formData.materialApoioUrl}
                      onChange={(e) => setFormData({...formData, materialApoioUrl: e.target.value})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="Link para material complementar"
                    />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Status de Publicação</label>
                    <select 
                      value={formData.status}
                      onChange={(e) => setFormData({...formData, status: e.target.value as any})}
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm transition-all font-bold"
                    >
                      <option value="rascunho">Rascunho (Privado)</option>
                      <option value="ativo">Ativo (Publicado)</option>
                    </select>
                  </div>
                </div>
              )}

              <div className="pt-6 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-slate-200 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 active:scale-95"
                >
                  {editingCourse ? 'Atualizar Matriz' : 'Salvar Matriz'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { Exam, Question, User, Course, ProfessorSubView, Enrollment, ExamResult } from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  MousePointer2,
  ListChecks,
  Download
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // Existing Exam State
  const [exams, setExams] = useState<Exam[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExamId, setEditingExamId] = useState<string | null>(null);

  // Existing Exam Engine State
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);
  const [attemptError, setAttemptError] = useState<string | null>(null);
  const [attemptInfo, setAttemptInfo] = useState({ current: 0, max: 0 });

  // Existing Exam Form State
  const [examTitle, setExamTitle] = useState('');
  const [examCourseId, setExamCourseId] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [questions, setQuestions] = useState<Question[]>([]);

  // NEW: Diary State
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [selectedCourseForDiary, setSelectedCourseForDiary] = useState<string>(courses[0]?.id || '');

  // 1. Existing Snapshot for Exams
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Exam));
      setExams(fetched);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // 2. NEW: Snapshot for Diary Data (Only if activeSub is diario)
  useEffect(() => {
    if (activeSub !== 'diario') return;

    const unsubEnroll = onSnapshot(collection(db, 'inscricoes'), (snap) => {
      setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
    });

    const unsubResults = onSnapshot(collection(db, 'exam_results'), (snap) => {
      setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
    });

    const fetchStudents = async () => {
      const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snap = await getDocs(q);
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
    };
    fetchStudents();

    return () => {
      unsubEnroll();
      unsubResults();
    };
  }, [activeSub]);

  // 3. NEW: Diary Data Calculation Logic
  const diaryData = useMemo(() => {
    if (!selectedCourseForDiary) return [];

    // Filter enrollments for the selected course
    const courseEnrollments = enrollments.filter(e => e.courseId === selectedCourseForDiary);

    return courseEnrollments.map(enroll => {
      const student = allStudents.find(s => s.uid === enroll.userId);
      const studentName = student?.displayName || 'Aluno Desconhecido';

      // Get all results for this student in this course
      const studentResults = examResults.filter(r => {
        // Find exam for this result to check courseId
        const exam = exams.find(e => e.id === r.examId);
        return r.userId === enroll.userId && exam?.courseId === selectedCourseForDiary;
      });

      // Calculate averages
      const activities = studentResults.filter(r => {
        const exam = exams.find(e => e.id === r.examId);
        return exam?.type === 'activity';
      });
      const evaluations = studentResults.filter(r => {
        const exam = exams.find(e => e.id === r.examId);
        return exam?.type === 'evaluation';
      });

      const avgActivity = activities.length > 0 
        ? activities.reduce((acc, curr) => acc + curr.score, 0) / activities.length 
        : 0;

      const avgEvaluation = evaluations.length > 0
        ? evaluations.reduce((acc, curr) => acc + curr.score, 0) / evaluations.length
        : 0;

      const finalAverage = (avgActivity + avgEvaluation) / 2;
      const status = finalAverage >= 70 ? 'Aprovado' : 'Em Recuperação';

      return {
        studentName,
        progress: enroll.progress || 0,
        avgActivity: parseFloat(avgActivity.toFixed(1)),
        avgEvaluation: parseFloat(avgEvaluation.toFixed(1)),
        finalAverage: parseFloat(finalAverage.toFixed(1)),
        status
      };
    });
  }, [enrollments, examResults, allStudents, exams, selectedCourseForDiary]);


  // --- EXISTING HANDLERS (DO NOT TOUCH) ---
  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (questions.length === 0) return;

    const payload = {
      title: examTitle,
      courseId: examCourseId,
      type: examType,
      passingGrade: passingGrade,
      questions: questions,
      updatedAt: serverTimestamp(),
      authorId: user.uid
    };

    try {
      if (editingExamId) {
        await updateDoc(doc(db, 'exams', editingExamId), payload);
      } else {
        await addDoc(collection(db, 'exams'), {
          ...payload,
          createdAt: serverTimestamp()
        });
      }
      setIsModalOpen(false);
      resetExamForm();
    } catch (err) {
      console.error("Erro ao salvar exame:", err);
    }
  };

  const resetExamForm = () => {
    setExamTitle('');
    setExamCourseId('');
    setExamType('activity');
    setPassingGrade(70);
    setQuestions([]);
    setEditingExamId(null);
  };

  const handleEditExam = (exam: Exam) => {
    setEditingExamId(exam.id);
    setExamTitle(exam.title);
    setExamCourseId(exam.courseId);
    setExamType(exam.type);
    setPassingGrade(exam.passingGrade);
    setQuestions(exam.questions);
    setIsModalOpen(true);
  };

  const handleDeleteExam = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir esta avaliação permanentemente?")) {
      try {
        await deleteDoc(doc(db, 'exams', id));
      } catch (err) {
        console.error("Erro ao deletar exame:", err);
      }
    }
  };

  const addQuestion = () => {
    const newQ: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: '',
      options: ['', '', '', ''],
      correctOptionIndex: 0
    };
    setQuestions([...questions, newQ]);
  };

  const startExamFlow = async (exam: Exam) => {
    setAttemptError(null);
    const isPrivilegedUser = user.role === 'diretor' || user.role === 'professor';
    const q = query(
      collection(db, 'exam_results'), 
      where('userId', '==', user.uid),
      where('examId', '==', exam.id)
    );
    const attemptDocs = await getDocs(q);
    const maxAttempts = exam.type === 'evaluation' ? 1 : 3;

    if (!isPrivilegedUser && attemptDocs.size >= maxAttempts) {
      setAttemptError(`Limite de ${maxAttempts} tentativa(s) atingido.`);
      return;
    }

    setAttemptInfo({ 
      current: isPrivilegedUser ? 0 : attemptDocs.size + 1, 
      max: isPrivilegedUser ? 999 : maxAttempts 
    });

    setSelectedExam(exam);
    setUserAnswers({});
    setCurrentQuestionIdx(0);
    setExamStatus('briefing');
  };

  const finishExam = async () => {
    if (!selectedExam) return;
    let correctOnes = 0;
    selectedExam.questions.forEach((q, idx) => {
      if (userAnswers[idx] === q.correctOptionIndex) {
        correctOnes++;
      }
    });
    const score = Math.round((correctOnes / selectedExam.questions.length) * 100);
    setFinalScore(score);
    try {
      await addDoc(collection(db, 'exam_results'), {
        userId: user.uid,
        userName: user.displayName,
        userRole: user.role,
        examId: selectedExam.id,
        score,
        passed: score >= selectedExam.passingGrade,
        attempt: attemptInfo.current,
        completedAt: serverTimestamp()
      });
      setExamStatus('result');
    } catch (err) {
      console.error("Erro ao salvar resultado:", err);
    }
  };

  const startActualQuestions = () => {
    setCurrentQuestionIdx(0);
    setExamStatus('running');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* ----------------------------------------------------------------------- */}
      {/* CASE: AVALIAÇÃO (EXISTING LOGIC) */}
      {/* ----------------------------------------------------------------------- */}
      {activeSub === 'avaliacao' && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">Avaliações e Atividades</h2>
              <p className="text-xs text-slate-500">Gestão do conhecimento e progresso discente.</p>
            </div>
            <button 
              onClick={() => { resetExamForm(); setIsModalOpen(true); }}
              className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
            >
              <Plus size={16} /> Nova Avaliação
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(exam => (
              <div key={exam.id} className="bg-white border border-slate-200 p-5 rounded-2xl hover:border-indigo-200 transition-all group relative overflow-hidden">
                <div className="flex justify-between items-start mb-4">
                  <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider ${
                    exam.type === 'evaluation' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'
                  }`}>
                    {exam.type === 'evaluation' ? 'Avaliação Oficial' : 'Atividade'}
                  </span>
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={() => handleEditExam(exam)}
                      className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                      title="Editar prova"
                    >
                      <Pencil size={14} />
                    </button>
                    <button 
                      onClick={() => handleDeleteExam(exam.id)}
                      className="p-1.5 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                      title="Excluir prova"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{exam.title}</h3>
                <p className="text-[10px] text-slate-400 font-bold mb-6">
                  VINCULADO: {courses.find(c => c.id === exam.courseId)?.nome || 'Sem Categoria'}
                </p>

                <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                  <div className="flex items-center gap-4 text-[10px] text-slate-400 font-bold uppercase">
                    <span className="flex items-center gap-1"><Clock size={12} /> {exam.questions.length} Qs</span>
                    <span className="flex items-center gap-1 text-indigo-500"><ShieldCheck size={12} /> {exam.passingGrade}%</span>
                  </div>
                  <button 
                    onClick={() => startExamFlow(exam)}
                    className="bg-slate-900 text-white px-4 py-1.5 rounded-lg text-[11px] font-bold hover:bg-slate-800 transition-all active:scale-95 shadow-sm"
                  >
                    {user.role === 'aluno' ? 'Iniciar' : 'Testar Prova'}
                  </button>
                </div>

                {attemptError && selectedExam?.id === exam.id && (
                  <div className="absolute inset-0 bg-white/90 backdrop-blur-[1px] flex items-center justify-center p-6 animate-in fade-in zoom-in-95">
                    <div className="text-center space-y-2">
                      <AlertCircle className="mx-auto text-red-500" size={24} />
                      <p className="text-xs font-bold text-red-600">{attemptError}</p>
                      <button onClick={() => setAttemptError(null)} className="text-[10px] font-black uppercase text-slate-400 hover:text-slate-600">Fechar</button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </>
      )}

      {/* ----------------------------------------------------------------------- */}
      {/* CASE: DIÁRIO DE CLASSE (NEW IMPLEMENTATION) */}
      {/* ----------------------------------------------------------------------- */}
      {activeSub === 'diario' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">Diário de Classe</h2>
              <p className="text-xs text-slate-500">Pauta eletrônica de notas e progresso acadêmico.</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            {/* Toolbar */}
            <div className="p-4 border-b bg-slate-50 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filtrar Curso:</span>
                <select 
                  value={selectedCourseForDiary} 
                  onChange={e => setSelectedCourseForDiary(e.target.value)} 
                  className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  <option value="">Selecione...</option>
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <button className="flex items-center gap-2 text-xs font-bold text-slate-600 hover:text-indigo-600 transition-colors">
                <Download size={14} /> Exportar
              </button>
            </div>

            {/* Table */}
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50/80 text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-slate-100">
                  <tr>
                    <th className="px-6 py-4">Aluno</th>
                    <th className="px-6 py-4">Progresso</th>
                    <th className="px-6 py-4">Nota Atividade</th>
                    <th className="px-6 py-4">Nota Prova</th>
                    <th className="px-6 py-4">Média Final</th>
                    <th className="px-6 py-4">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {diaryData.length > 0 ? (
                    diaryData.map((d, i) => (
                      <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                          <span className="text-xs font-bold text-slate-900">{d.studentName}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-xs font-medium text-slate-600">{d.progress}% concluído</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-xs font-bold text-slate-600">{d.avgActivity}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-xs font-bold text-slate-600">{d.avgEvaluation}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm font-black text-slate-900">{d.finalAverage}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`text-[10px] font-black uppercase tracking-widest ${
                            d.status === 'Aprovado' ? 'text-emerald-600' : 'text-amber-500'
                          }`}>
                            {d.status}
                          </span>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan={6} className="px-6 py-12 text-center text-slate-400 text-xs font-medium italic">
                        Selecione um curso ou aguarde sincronização. Nenhum aluno encontrado.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ----------------------------------------------------------------------- */}
      {/* SHARED MODALS & OVERLAYS (EXAM ENGINE) */}
      {/* ----------------------------------------------------------------------- */}

      {/* MOTOR DA PROVA: INTERFACE DE EXECUÇÃO */}
      {selectedExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[400] bg-slate-50 flex items-center justify-center p-0 md:p-6 animate-in fade-in duration-300 overflow-hidden">
          <div className="bg-white w-full max-w-4xl h-full md:h-[90vh] md:rounded-3xl shadow-2xl border border-slate-200 flex flex-col relative overflow-hidden">

            {/* 1. BRIEFING (PAZ) */}
            {examStatus === 'briefing' && (
              <div className="flex-1 flex flex-col items-center justify-center p-10 text-center space-y-8 animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center animate-pulse">
                  <Sparkles size={40} />
                </div>
                <div className="max-w-xl space-y-4">
                  <h2 className="text-2xl font-black text-slate-900 italic tracking-tight">Respire fundo...</h2>
                  <p className="text-slate-600 text-base leading-relaxed">
                    Este é o seu momento de consolidar o que aprendeu. Faça sua avaliação com tranquilidade e paz, 
                    sabendo que o conhecimento é um presente e que a integridade caminha de mãos dadas com a sabedoria. 
                    Deus abençoe seu desempenho!
                  </p>
                </div>
                <button 
                  onClick={() => setExamStatus('tutorial')}
                  className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-bold text-sm hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 flex items-center gap-2 group"
                >
                  Avançar <ChevronRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="text-xs text-slate-400 font-bold hover:text-slate-600">Voltar para o portal</button>
              </div>
            )}

            {/* 2. TUTORIAL (INFORMAÇÃO E DICAS) */}
            {examStatus === 'tutorial' && (
              <div className="flex-1 flex flex-col p-8 md:p-12 overflow-y-auto animate-in slide-in-from-right-4 duration-500">
                <div className="max-w-2xl mx-auto w-full space-y-8 pb-10">
                  <div className="flex items-center gap-3 text-indigo-600 mb-2">
                    <Info size={24} />
                    <h2 className="text-xl font-black uppercase tracking-tight">Instruções da Avaliação</h2>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Informações Gerais</p>
                      <h3 className="font-bold text-slate-900 mb-1">{selectedExam.title}</h3>
                      <p className="text-xs text-slate-500">{selectedExam.questions.length} Questões objetivas</p>
                      <p className="text-xs font-bold text-indigo-600 mt-2">Média: {selectedExam.passingGrade}% para aprovação</p>
                    </div>
                    <div className="bg-indigo-50 p-5 rounded-2xl border border-indigo-100">
                      <p className="text-[10px] font-bold text-indigo-400 uppercase mb-2">Sua Tentativa</p>
                      <p className="text-sm font-bold text-indigo-900">
                        {user.role === 'aluno' 
                          ? `Tentativa ${attemptInfo.current} de ${attemptInfo.max}` 
                          : 'Modo de Pré-visualização (Acesso Ilimitado)'}
                      </p>
                      <p className="text-[10px] text-indigo-600 mt-1 uppercase font-bold tracking-wider">Atenção: Progresso será salvo no envio</p>
                    </div>
                  </div>

                  {/* DICAS IMPORTANTES */}
                  <div className="bg-emerald-50/50 border border-emerald-100 p-6 rounded-2xl space-y-4">
                    <div className="flex items-center gap-2 text-emerald-700 font-bold text-xs uppercase tracking-widest">
                      <ListChecks size={16} /> Dicas para um bom desempenho
                    </div>
                    <ul className="space-y-2 text-sm text-emerald-800">
                      <li className="flex items-center gap-2">• Leia atentamente o enunciado.</li>
                      <li className="flex items-center gap-2">• Escolha apenas uma alternativa.</li>
                      <li className="flex items-center gap-2">• Clique em Próximo para avançar entre as perguntas.</li>
                    </ul>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-xs font-bold text-slate-900 uppercase tracking-widest">Controles:</h4>
                    <div className="grid grid-cols-1 gap-3">
                      <div className="flex gap-4 items-start p-4 bg-white border border-slate-100 rounded-xl">
                        <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center shrink-0"><MousePointer2 size={16} /></div>
                        <div>
                          <p className="text-sm font-bold text-slate-800">Marcação</p>
                          <p className="text-xs text-slate-500">Toque ou clique no card da resposta para selecioná-la.</p>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="pt-8">
                    <button 
                      onClick={startActualQuestions}
                      className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95"
                    >
                      Estou Pronto para Começar
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* 3. MOTOR DE EXECUÇÃO (QUESTÕES) */}
            {examStatus === 'running' && (
              <div className="h-full flex flex-col animate-in fade-in duration-300">
                <div className="p-6 bg-slate-900 text-white flex items-center justify-between shrink-0 shadow-lg relative z-10">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest leading-none mb-1">{selectedExam.type}</span>
                    <h2 className="font-bold text-base md:text-lg line-clamp-1">{selectedExam.title}</h2>
                  </div>
                  <div className="text-right">
                    <span className="text-2xl font-black text-white/30 tabular-nums leading-none">
                      {currentQuestionIdx + 1}/{selectedExam.questions.length}
                    </span>
                  </div>
                </div>

                {/* AREA DE CONTEÚDO SCROLLABLE */}
                <div className="flex-1 overflow-y-auto bg-slate-50/50">
                  <div className="max-w-2xl mx-auto p-6 md:p-12 space-y-10 pb-40">
                    <div className="space-y-4">
                      <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-md uppercase">Questão {currentQuestionIdx + 1}</span>
                      <h3 className="text-lg md:text-xl font-bold text-slate-800 leading-tight">
                        {selectedExam.questions[currentQuestionIdx].text}
                      </h3>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                      {selectedExam.questions[currentQuestionIdx].options.map((opt, oIdx) => (
                        <button 
                          key={oIdx}
                          onClick={() => setUserAnswers({...userAnswers, [currentQuestionIdx]: oIdx})}
                          className={`flex items-center gap-4 p-5 rounded-2xl text-left border-2 transition-all group ${
                            userAnswers[currentQuestionIdx] === oIdx 
                              ? 'border-indigo-600 bg-indigo-50/50 shadow-md ring-1 ring-indigo-200' 
                              : 'border-white hover:border-slate-200 bg-white shadow-sm'
                          }`}
                        >
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-black transition-all shrink-0 ${
                            userAnswers[currentQuestionIdx] === oIdx ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'
                          }`}>
                            {String.fromCharCode(65 + oIdx)}
                          </div>
                          <span className={`text-sm font-semibold leading-tight ${userAnswers[currentQuestionIdx] === oIdx ? 'text-indigo-900 font-bold' : 'text-slate-600'}`}>
                            {opt}
                          </span>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* RODAPÉ DE NAVEGAÇÃO FIXO */}
                <div className="p-6 bg-white border-t border-slate-100 flex items-center justify-between shrink-0 shadow-[0_-4px_20px_rgba(0,0,0,0.05)] relative z-10">
                  <button 
                    disabled={currentQuestionIdx === 0}
                    onClick={() => {
                      setCurrentQuestionIdx(v => v - 1);
                      document.querySelector('.overflow-y-auto')?.scrollTo(0,0);
                    }}
                    className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-50 disabled:opacity-0 transition-all"
                  >
                    <ChevronLeft size={16} /> Anterior
                  </button>

                  {currentQuestionIdx === selectedExam.questions.length - 1 ? (
                    <button 
                      onClick={finishExam}
                      className="bg-indigo-600 text-white px-10 py-3 rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 active:scale-95"
                    >
                      Finalizar Prova
                    </button>
                  ) : (
                    <button 
                      onClick={() => {
                        setCurrentQuestionIdx(v => v + 1);
                        document.querySelector('.overflow-y-auto')?.scrollTo(0,0);
                      }}
                      className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white rounded-xl text-sm font-bold hover:bg-slate-800 transition-all active:scale-95"
                    >
                      Próxima <ChevronRight size={16} />
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* 4. RESULTADO FINAL (SUCESSO) */}
            {examStatus === 'result' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in-95 duration-500">
                <div className={`w-24 h-24 rounded-full flex items-center justify-center mb-6 shadow-2xl ${
                  finalScore >= selectedExam.passingGrade ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                }`}>
                  <Trophy size={48} />
                </div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 italic tracking-tight">
                  {finalScore >= selectedExam.passingGrade ? 'Excelente Desempenho!' : 'Bom Esforço!'}
                </h2>
                <p className="text-slate-500 text-sm mb-8 font-medium">Sua nota nesta avaliação foi de:</p>
                <div className="text-7xl font-black text-slate-900 mb-10 tabular-nums">
                  {finalScore}<span className="text-3xl text-slate-300">%</span>
                </div>
                <div className="flex flex-col gap-3 w-full max-w-xs">
                  <button 
                    onClick={() => {setExamStatus('idle'); setSelectedExam(null);}}
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95"
                  >
                    Voltar ao Portal Acadêmico
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* MODAL DE CRIAÇÃO / EDIÇÃO DE PROVA */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-900">{editingExamId ? 'Editar Matriz Acadêmica' : 'Configurar Nova Avaliação'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Título da Prova</label>
                  <input required value={examTitle} onChange={e => setExamTitle(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Curso Vinculado</label>
                  <select required value={examCourseId} onChange={e => setExamCourseId(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                    <option value="">Selecione o Curso...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Tipo de Teste</label>
                  <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                    <option value="activity">Atividade Livre (3 tentativas)</option>
                    <option value="evaluation">Avaliação Oficial (1 tentativa)</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nota de Corte (%)</label>
                  <input type="number" value={passingGrade} onChange={e => setPassingGrade(parseInt(e.target.value))} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
              </div>

              <div className="space-y-4 pt-4">
                <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Banco de Questões ({questions.length})</h4>
                  <button type="button" onClick={addQuestion} className="text-indigo-600 text-xs font-black hover:underline uppercase tracking-tighter">+ Adicionar Pergunta</button>
                </div>

                {questions.map((q, idx) => (
                  <div key={idx} className="p-5 border border-slate-100 rounded-2xl bg-slate-50/50 space-y-4 relative group hover:border-indigo-200 transition-all">
                    <button 
                      type="button"
                      onClick={() => setQuestions(questions.filter((_, i) => i !== idx))}
                      className="absolute top-3 right-3 p-1.5 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <X size={16} />
                    </button>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-indigo-500 uppercase">Enunciado</label>
                      <textarea 
                        rows={2}
                        placeholder={`Digite a pergunta ${idx + 1}...`}
                        className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold transition-all resize-none"
                        value={q.text}
                        onChange={e => {
                          const updated = [...questions];
                          updated[idx].text = e.target.value;
                          setQuestions(updated);
                        }}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Alternativas (Marque a correta)</label>
                      {q.options.map((opt, oIdx) => (
                        <div key={oIdx} className="flex items-center gap-3">
                          <input 
                            type="radio" 
                            name={`correct-ans-${idx}`}
                            checked={q.correctOptionIndex === oIdx} 
                            onChange={() => {
                              const updated = [...questions];
                              updated[idx].correctOptionIndex = oIdx;
                              setQuestions(updated);
                            }} 
                            className="w-4 h-4 text-indigo-600 focus:ring-indigo-500"
                          />
                          <input 
                            placeholder={`Opção ${String.fromCharCode(65 + oIdx)}`}
                            className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none focus:border-indigo-400 transition-all"
                            value={opt}
                            onChange={e => {
                              const updated = [...questions];
                              updated[idx].options[oIdx] = e.target.value;
                              setQuestions(updated);
                            }}
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 active:scale-[0.98]">
                {editingExamId ? 'Atualizar Avaliação' : 'Publicar na Plataforma'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

