      setAttemptError(`Limite de ${maxAttempts} tentativa(s) atingido.`);
      return;
    }

    setAttemptInfo({ 
      current: isPrivilegedUser ? 0 : attemptDocs.size + 1, 
      max: isPrivilegedUser ? 999 : maxAttempts 
