      {/* ----------------------------------------------------------------------- */}
      {/* SHARED MODALS & OVERLAYS (EXAM ENGINE) */}
      {/* ----------------------------------------------------------------------- */}

      {/* MOTOR DA PROVA: INTERFACE DE EXECUÇÃO */}
      {selectedExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[400] bg-slate-50 flex items-center justify-center p-0 md:p-6 animate-in fade-in duration-300 overflow-hidden">
          <div className="bg-white w-full max-w-4xl h-full md:h-[90vh] md:rounded-3xl shadow-2xl border border-slate-200 flex flex-col relative overflow-hidden">

            {/* 1. BRIEFING (PAZ) */}
            {examStatus === 'briefing' && (
              <div className="flex-1 flex flex-col items-center justify-center p-10 text-center space-y-8 animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center animate-pulse">
                  <Sparkles size={40} />
                </div>
                <div className="max-w-xl space-y-4">
                  <h2 className="text-2xl font-black text-slate-900 italic tracking-tight">Respire fundo...</h2>
                  <p className="text-slate-600 text-base leading-relaxed">
                    Este é o seu momento de consolidar o que aprendeu. Faça sua avaliação com tranquilidade e paz, 
                    sabendo que o conhecimento é um presente e que a integridade caminha de mãos dadas com a sabedoria. 
                    Deus abençoe seu desempenho!
                  </p>
                </div>
                <button 
                  onClick={() => setExamStatus('tutorial')}
                  className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-bold text-sm hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 flex items-center gap-2 group"
                >
                  Avançar <ChevronRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="text-xs text-slate-400 font-bold hover:text-slate-600">Voltar para o portal</button>
              </div>
            )}

            {/* 2. TUTORIAL (INFORMAÇÃO E DICAS) */}
            {examStatus === 'tutorial' && (
              <div className="flex-1 flex flex-col p-8 md:p-12 overflow-y-auto animate-in slide-in-from-right-4 duration-500">
                <div className="max-w-2xl mx-auto w-full space-y-8 pb-10">
                  <div className="flex items-center gap-3 text-indigo-600 mb-2">
                    <Info size={24} />
                    <h2 className="text-xl font-black uppercase tracking-tight">Instruções da Avaliação</h2>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Informações Gerais</p>
                      <h3 className="font-bold text-slate-900 mb-1">{selectedExam.title}</h3>
                      <p className="text-xs text-slate-500">{selectedExam.questions.length} Questões objetivas</p>
                      <p className="text-xs font-bold text-indigo-600 mt-2">Média: {selectedExam.passingGrade}% para aprovação</p>
                    </div>
                    <div className="bg-indigo-50 p-5 rounded-2xl border border-indigo-100">
                      <p className="text-[10px] font-bold text-indigo-400 uppercase mb-2">Sua Tentativa</p>
                      <p className="text-sm font-bold text-indigo-900">
                        {user.role === 'aluno' 
                          ? `Tentativa ${attemptInfo.current} de ${attemptInfo.max}` 
                          : 'Modo de Pré-visualização (Acesso Ilimitado)'}
                      </p>
                      <p className="text-[10px] text-indigo-600 mt-1 uppercase font-bold tracking-wider">Atenção: Progresso será salvo no envio</p>
                    </div>
                  </div>

                  {/* DICAS IMPORTANTES */}
                  <div className="bg-emerald-50/50 border border-emerald-100 p-6 rounded-2xl space-y-4">
                    <div className="flex items-center gap-2 text-emerald-700 font-bold text-xs uppercase tracking-widest">
                      <ListChecks size={16} /> Dicas para um bom desempenho
                    </div>
                    <ul className="space-y-2 text-sm text-emerald-800">
                      <li className="flex items-center gap-2">• Leia atentamente o enunciado.</li>
                      <li className="flex items-center gap-2">• Escolha apenas uma alternativa.</li>
                      <li className="flex items-center gap-2">• Clique em Próximo para avançar entre as perguntas.</li>
                    </ul>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-xs font-bold text-slate-900 uppercase tracking-widest">Controles:</h4>
                    <div className="grid grid-cols-1 gap-3">
                      <div className="flex gap-4 items-start p-4 bg-white border border-slate-100 rounded-xl">
                        <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center shrink-0"><MousePointer2 size={16} /></div>
                        <div>
                          <p className="text-sm font-bold text-slate-800">Marcação</p>
                          <p className="text-xs text-slate-500">Toque ou clique no card da resposta para selecioná-la.</p>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="pt-8">
                    <button 
                      onClick={startActualQuestions}
                      className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95"
                    >
                      Estou Pronto para Começar
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* 3. MOTOR DE EXECUÇÃO (QUESTÕES) */}
            {examStatus === 'running' && (
              <div className="h-full flex flex-col animate-in fade-in duration-300">
                <div className="p-6 bg-slate-900 text-white flex items-center justify-between shrink-0 shadow-lg relative z-10">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest leading-none mb-1">{selectedExam.type}</span>
                    <h2 className="font-bold text-base md:text-lg line-clamp-1">{selectedExam.title}</h2>
                  </div>
                  <div className="text-right">
                    <span className="text-2xl font-black text-white/30 tabular-nums leading-none">
                      {currentQuestionIdx + 1}/{selectedExam.questions.length}
                    </span>
                  </div>
                </div>

                {/* AREA DE CONTEÚDO SCROLLABLE */}
                <div className="flex-1 overflow-y-auto bg-slate-50/50">
                  <div className="max-w-2xl mx-auto p-6 md:p-12 space-y-10 pb-40">
                    <div className="space-y-4">
                      <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-md uppercase">Questão {currentQuestionIdx + 1}</span>
                      <h3 className="text-lg md:text-xl font-bold text-slate-800 leading-tight">
                        {selectedExam.questions[currentQuestionIdx].text}
                      </h3>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                      {selectedExam.questions[currentQuestionIdx].options.map((opt, oIdx) => (
                        <button 
                          key={oIdx}
                          onClick={() => setUserAnswers({...userAnswers, [currentQuestionIdx]: oIdx})}
                          className={`flex items-center gap-4 p-5 rounded-2xl text-left border-2 transition-all group ${
                            userAnswers[currentQuestionIdx] === oIdx 
                              ? 'border-indigo-600 bg-indigo-50/50 shadow-md ring-1 ring-indigo-200' 
                              : 'border-white hover:border-slate-200 bg-white shadow-sm'
                          }`}
                        >
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-black transition-all shrink-0 ${
                            userAnswers[currentQuestionIdx] === oIdx ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'
                          }`}>
                            {String.fromCharCode(65 + oIdx)}
                          </div>
                          <span className={`text-sm font-semibold leading-tight ${userAnswers[currentQuestionIdx] === oIdx ? 'text-indigo-900 font-bold' : 'text-slate-600'}`}>
                            {opt}
                          </span>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* RODAPÉ DE NAVEGAÇÃO FIXO */}
                <div className="p-6 bg-white border-t border-slate-100 flex items-center justify-between shrink-0 shadow-[0_-4px_20px_rgba(0,0,0,0.05)] relative z-10">
                  <button 
                    disabled={currentQuestionIdx === 0}
                    onClick={() => {
                      setCurrentQuestionIdx(v => v - 1);
                      document.querySelector('.overflow-y-auto')?.scrollTo(0,0);
                    }}
                    className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-50 disabled:opacity-0 transition-all"
                  >
                    <ChevronLeft size={16} /> Anterior
                  </button>

                  {currentQuestionIdx === selectedExam.questions.length - 1 ? (
                    <button 
                      onClick={finishExam}
                      className="bg-indigo-600 text-white px-10 py-3 rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 active:scale-95"
                    >
                      Finalizar Prova
                    </button>
                  ) : (
                    <button 
                      onClick={() => {
                        setCurrentQuestionIdx(v => v + 1);
                        document.querySelector('.overflow-y-auto')?.scrollTo(0,0);
                      }}
                      className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white rounded-xl text-sm font-bold hover:bg-slate-800 transition-all active:scale-95"
                    >
                      Próxima <ChevronRight size={16} />
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* 4. RESULTADO FINAL (SUCESSO) */}
            {examStatus === 'result' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in-95 duration-500">
                <div className={`w-24 h-24 rounded-full flex items-center justify-center mb-6 shadow-2xl ${
                  finalScore >= selectedExam.passingGrade ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                }`}>
                  <Trophy size={48} />
                </div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 italic tracking-tight">
                  {finalScore >= selectedExam.passingGrade ? 'Excelente Desempenho!' : 'Bom Esforço!'}
                </h2>
                <p className="text-slate-500 text-sm mb-8 font-medium">Sua nota nesta avaliação foi de:</p>
                <div className="text-7xl font-black text-slate-900 mb-10 tabular-nums">
                  {finalScore}<span className="text-3xl text-slate-300">%</span>
                </div>
                <div className="flex flex-col gap-3 w-full max-w-xs">
                  <button 
                    onClick={() => {setExamStatus('idle'); setSelectedExam(null);}}
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95"
                  >
                    Voltar ao Portal Acadêmico
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* MODAL DE CRIAÇÃO / EDIÇÃO DE PROVA */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-900">{editingExamId ? 'Editar Matriz Acadêmica' : 'Configurar Nova Avaliação'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Título da Prova</label>
                  <input required value={examTitle} onChange={e => setExamTitle(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Curso Vinculado</label>
                  <select required value={examCourseId} onChange={e => setExamCourseId(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                    <option value="">Selecione o Curso...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Tipo de Teste</label>
                  <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                    <option value="activity">Atividade Livre (3 tentativas)</option>
                    <option value="evaluation">Avaliação Oficial (1 tentativa)</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Nota de Corte (%)</label>
                  <input type="number" value={passingGrade} onChange={e => setPassingGrade(parseInt(e.target.value))} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
              </div>

              <div className="space-y-4 pt-4">
                <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Banco de Questões ({questions.length})</h4>
                  <button type="button" onClick={addQuestion} className="text-indigo-600 text-xs font-black hover:underline uppercase tracking-tighter">+ Adicionar Pergunta</button>
                </div>

                {questions.map((q, idx) => (
                  <div key={idx} className="p-5 border border-slate-100 rounded-2xl bg-slate-50/50 space-y-4 relative group hover:border-indigo-200 transition-all">
                    <button 
                      type="button"
                      onClick={() => setQuestions(questions.filter((_, i) => i !== idx))}
                      className="absolute top-3 right-3 p-1.5 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <X size={16} />
                    </button>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-indigo-500 uppercase">Enunciado</label>
                      <textarea 
                        rows={2}
                        placeholder={`Digite a pergunta ${idx + 1}...`}
                        className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-bold transition-all resize-none"
                        value={q.text}
                        onChange={e => {
                          const updated = [...questions];
                          updated[idx].text = e.target.value;
                          setQuestions(updated);
                        }}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Alternativas (Marque a correta)</label>
                      {q.options.map((opt, oIdx) => (
                        <div key={oIdx} className="flex items-center gap-3">
                          <input 
                            type="radio" 
                            name={`correct-ans-${idx}`}
                            checked={q.correctOptionIndex === oIdx} 
                            onChange={() => {
                              const updated = [...questions];
                              updated[idx].correctOptionIndex = oIdx;
                              setQuestions(updated);
                            }} 
                            className="w-4 h-4 text-indigo-600 focus:ring-indigo-500"
                          />
                          <input 
                            placeholder={`Opção ${String.fromCharCode(65 + oIdx)}`}
                            className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none focus:border-indigo-400 transition-all"
                            value={opt}
                            onChange={e => {
                              const updated = [...questions];
                              updated[idx].options[oIdx] = e.target.value;
                              setQuestions(updated);
                            }}
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 active:scale-[0.98]">
                {editingExamId ? 'Atualizar Avaliação' : 'Publicar na Plataforma'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson 
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  MousePointer2,
  ListChecks,
  Download,
  FileText,
  ExternalLink,
  Video,
  Radio,
  MessageSquare,
  Users,
  TrendingUp,
  BarChart3,
  Calendar,
  PlayCircle
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // Existing Exam State
  const [exams, setExams] = useState<Exam[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExamId, setEditingExamId] = useState<string | null>(null);

  // Existing Exam Engine State
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);
  const [attemptError, setAttemptError] = useState<string | null>(null);
  const [attemptInfo, setAttemptInfo] = useState({ current: 0, max: 0 });

  // Existing Exam Form State
  const [examTitle, setExamTitle] = useState('');
  const [examCourseId, setExamCourseId] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [questions, setQuestions] = useState<Question[]>([]);

  // NEW: Diary State
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [selectedCourseForDiary, setSelectedCourseForDiary] = useState<string>(courses[0]?.id || '');

  // NEW: Additional States for other Tabs
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [completedLessons, setCompletedLessons] = useState<CompletedLesson[]>([]);

  // 1. Existing Snapshot for Exams
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Exam));
      setExams(fetched);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // 2. NEW: Snapshot for Diary Data (Only if activeSub is diario or other related tabs)
  useEffect(() => {
    // We load enrollments/results/students for diary, reports, and attendance
    if (['diario', 'relatorio', 'frequencia', 'feedback'].includes(activeSub)) {
      const unsubEnroll = onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      });

      const unsubResults = onSnapshot(collection(db, 'exam_results'), (snap) => {
        setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
      });

      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();

      return () => {
        unsubEnroll();
        unsubResults();
      };
    }
  }, [activeSub]);

  // 3. NEW: Specific Snapshots for Materials, Feedbacks, Lives, CompletedLessons
  useEffect(() => {
    const unsubscribes: (() => void)[] = [];

    if (activeSub === 'materiais') {
      const q = query(collection(db, 'materials'), orderBy('createdAt', 'desc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }

    if (activeSub === 'feedback') {
      const q = query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }

    if (activeSub === 'live') {
      const q = query(collection(db, 'lives'), orderBy('date', 'asc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setLives(snap.docs.map(d => ({ id: d.id, ...d.data() } as LiveSession)));
      }));
    }

    // Carregar Completed Lessons também para Relatórios
    if (activeSub === 'frequencia' || activeSub === 'relatorio') {
      const q = query(collection(db, 'completed_lessons'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setCompletedLessons(snap.docs.map(d => ({ id: d.id, ...d.data() } as CompletedLesson)));
      }));
    }

    return () => {
      unsubscribes.forEach(unsub => unsub());
    };
  }, [activeSub]);

  // 3. NEW: Diary Data Calculation Logic
  const diaryData = useMemo(() => {
    if (!selectedCourseForDiary) return [];

    // Filter enrollments for the selected course
    const courseEnrollments = enrollments.filter(e => e.courseId === selectedCourseForDiary);

    return courseEnrollments.map(enroll => {
      const student = allStudents.find(s => s.uid === enroll.userId);
      const studentName = student?.displayName || 'Aluno Desconhecido';

      // Get all results for this student in this course
      const studentResults = examResults.filter(r => {
        // Find exam for this result to check courseId
        const exam = exams.find(e => e.id === r.examId);
        return r.userId === enroll.userId && exam?.courseId === selectedCourseForDiary;
      });

      // Calculate averages
      const activities = studentResults.filter(r => {
        const exam = exams.find(e => e.id === r.examId);
        return exam?.type === 'activity';
      });
      const evaluations = studentResults.filter(r => {
        const exam = exams.find(e => e.id === r.examId);
        return exam?.type === 'evaluation';
      });

      const avgActivity = activities.length > 0 
        ? activities.reduce((acc, curr) => acc + curr.score, 0) / activities.length 
        : 0;

      const avgEvaluation = evaluations.length > 0
        ? evaluations.reduce((acc, curr) => acc + curr.score, 0) / evaluations.length
        : 0;

      const finalAverage = (avgActivity + avgEvaluation) / 2;
      const status = finalAverage >= 70 ? 'Aprovado' : 'Em Recuperação';

      return {
        studentName,
        progress: enroll.progress || 0,
        avgActivity: parseFloat(avgActivity.toFixed(1)),
        avgEvaluation: parseFloat(avgEvaluation.toFixed(1)),
        finalAverage: parseFloat(finalAverage.toFixed(1)),
        status
      };
    });
  }, [enrollments, examResults, allStudents, exams, selectedCourseForDiary]);

  // Calculations for Reports (Updated to match requirements)
  const reportStats = useMemo(() => {
    const totalStudents = allStudents.length;
    const totalCompletedLessons = completedLessons.length;
    const allScores = examResults.map(r => r.score);
    const avgPerformance = allScores.length > 0 
      ? (allScores.reduce((a, b) => a + b, 0) / allScores.length).toFixed(1) 
      : '0.0';
    return { totalStudents, totalCompletedLessons, avgPerformance };
  }, [allStudents, completedLessons, examResults]);


  // --- EXISTING HANDLERS (DO NOT TOUCH) ---
  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (questions.length === 0) return;

    const payload = {
      title: examTitle,
      courseId: examCourseId,
      type: examType,
      passingGrade: passingGrade,
      questions: questions,
      updatedAt: serverTimestamp(),
      authorId: user.uid
    };

    try {
      if (editingExamId) {
        await updateDoc(doc(db, 'exams', editingExamId), payload);
      } else {
        await addDoc(collection(db, 'exams'), {
          ...payload,
          createdAt: serverTimestamp()
        });
      }
      setIsModalOpen(false);
      resetExamForm();
    } catch (err) {
      console.error("Erro ao salvar exame:", err);
    }
  };

  const resetExamForm = () => {
    setExamTitle('');
    setExamCourseId('');
    setExamType('activity');
    setPassingGrade(70);
    setQuestions([]);
    setEditingExamId(null);
  };

  const handleEditExam = (exam: Exam) => {
    setEditingExamId(exam.id);
    setExamTitle(exam.title);
    setExamCourseId(exam.courseId);
    setExamType(exam.type);
    setPassingGrade(exam.passingGrade);
    setQuestions(exam.questions);
    setIsModalOpen(true);
  };

  const handleDeleteExam = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir esta avaliação permanentemente?")) {
      try {
        await deleteDoc(doc(db, 'exams', id));
      } catch (err) {
        console.error("Erro ao deletar exame:", err);
      }
    }
  };

  const addQuestion = () => {
    const newQ: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: '',
      options: ['', '', '', ''],
      correctOptionIndex: 0
    };
    setQuestions([...questions, newQ]);
  };

  const startExamFlow = async (exam: Exam) => {
    setAttemptError(null);
    const isPrivilegedUser = user.role === 'diretor' || user.role === 'professor';
    const q = query(
      collection(db, 'exam_results'), 
      where('userId', '==', user.uid),
      where('examId', '==', exam.id)
    );
    const attemptDocs = await getDocs(q);
    const maxAttempts = exam.type === 'evaluation' ? 1 : 3;

    if (!isPrivilegedUser && attemptDocs.size >= maxAttempts) {
      setAttemptError(`Limite de ${maxAttempts} tentativa(s) atingido.`);
      return;
    }

    setAttemptInfo({ 
      current: isPrivilegedUser ? 0 : attemptDocs.size + 1, 
      max: isPrivilegedUser ? 999 : maxAttempts 
    });

    setSelectedExam(exam);
    setUserAnswers({});
    setCurrentQuestionIdx(0);
    setExamStatus('briefing');
  };

  const finishExam = async () => {
    if (!selectedExam) return;
    let correctOnes = 0;
    selectedExam.questions.forEach((q, idx) => {
      if (userAnswers[idx] === q.correctOptionIndex) {
        correctOnes++;
      }
    });
    const score = Math.round((correctOnes / selectedExam.questions.length) * 100);
    setFinalScore(score);
    try {
      await addDoc(collection(db, 'exam_results'), {
        userId: user.uid,
        userName: user.displayName,
        userRole: user.role,
        examId: selectedExam.id,
        score,
        passed: score >= selectedExam.passingGrade,
        attempt: attemptInfo.current,
        completedAt: serverTimestamp()
      });
      setExamStatus('result');
    } catch (err) {
      console.error("Erro ao salvar resultado:", err);
    }
  };

  const startActualQuestions = () => {
    setCurrentQuestionIdx(0);
