            )}
            {examStatus === 'result' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in-95 duration-500">
                <div className={`w-24 h-24 rounded-full flex items-center justify-center mb-6 shadow-2xl ${finalScore >= selectedExam.passingGrade ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'}`}><Trophy size={48} /></div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 italic tracking-tight">{finalScore >= selectedExam.passingGrade ? 'Excelente!' : 'Bom Esforço!'}</h2>
                <p className="text-slate-500 text-sm mb-8 font-medium">Sua nota:</p>
                <div className="text-7xl font-black text-slate-900 mb-10 tabular-nums">{finalScore}%</div>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="w-full max-w-xs bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95 transition-all">Voltar</button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* EXAM MODAL FORM (Untouched) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-900">{editingExamId ? 'Editar' : 'Nova'} Avaliação</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <input required placeholder="Título" value={examTitle} onChange={e => setExamTitle(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <select required value={examCourseId} onChange={e => setExamCourseId(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none">
                  <option value="">Curso...</option>
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none">
                  <option value="activity">Atividade</option><option value="evaluation">Avaliação</option>
                </select>
                <input type="number" value={passingGrade} onChange={e => setPassingGrade(parseInt(e.target.value))} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
              </div>
              <button type="button" onClick={() => setQuestions([...questions, { id: Math.random().toString(36).substr(2, 9), text: '', options: ['', '', '', ''], correctOptionIndex: 0 }])} className="text-indigo-600 text-xs font-black uppercase tracking-tighter hover:underline">+ Adicionar Pergunta</button>
              {questions.map((q, idx) => (
                <div key={idx} className="p-5 border border-slate-100 rounded-2xl bg-slate-50/50 space-y-4 relative group">
                  <button type="button" onClick={() => setQuestions(questions.filter((_, i) => i !== idx))} className="absolute top-3 right-3 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><X size={16} /></button>
                  <textarea rows={2} placeholder={`Pergunta ${idx + 1}`} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold outline-none" value={q.text} onChange={e => { const updated = [...questions]; updated[idx].text = e.target.value; setQuestions(updated); }} />
                  <div className="space-y-2">
                    {q.options.map((opt, oIdx) => (
                      <div key={oIdx} className="flex items-center gap-3">
                        <input type="radio" name={`correct-${idx}`} checked={q.correctOptionIndex === oIdx} onChange={() => { const updated = [...questions]; updated[idx].correctOptionIndex = oIdx; setQuestions(updated); }} />
                        <input placeholder={`Opção ${oIdx + 1}`} className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none" value={opt} onChange={e => { const updated = [...questions]; updated[idx].options[oIdx] = e.target.value; setQuestions(updated); }} />
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Salvar Avaliação</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson 
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  MousePointer2,
  ListChecks,
  Download,
  FileText,
  ExternalLink,
  Video,
  Radio,
  MessageSquare,
  Users,
  TrendingUp,
  BarChart3,
  Calendar,
  PlayCircle,
  ThumbsUp,
  Lightbulb,
  Frown,
  Star,
  // Fix: Added missing MessageCircle icon
  MessageCircle
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // States
  const [exams, setExams] = useState<Exam[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExamId, setEditingExamId] = useState<string | null>(null);
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);
  const [attemptError, setAttemptError] = useState<string | null>(null);
  const [attemptInfo, setAttemptInfo] = useState({ current: 0, max: 0 });

  const [examTitle, setExamTitle] = useState('');
  const [examCourseId, setExamCourseId] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [questions, setQuestions] = useState<Question[]>([]);

  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [selectedCourseForDiary, setSelectedCourseForDiary] = useState<string>(courses[0]?.id || '');

  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [completedLessons, setCompletedLessons] = useState<CompletedLesson[]>([]);

  // Snapshots
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Exam));
      setExams(fetched);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (['diario', 'relatorio', 'frequencia', 'feedback'].includes(activeSub)) {
      onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      });

      onSnapshot(collection(db, 'exam_results'), (snap) => {
        setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
      });

      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();
    }
  }, [activeSub]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }
    if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }
    if (activeSub === 'live') {
      unsubscribes.push(onSnapshot(query(collection(db, 'lives'), orderBy('date', 'asc')), (snap) => {
        setLives(snap.docs.map(d => ({ id: d.id, ...d.data() } as LiveSession)));
      }));
    }
    if (activeSub === 'frequencia' || activeSub === 'relatorio') {
      unsubscribes.push(onSnapshot(collection(db, 'completed_lessons'), (snap) => {
        setCompletedLessons(snap.docs.map(d => ({ id: d.id, ...d.data() } as CompletedLesson)));
      }));
    }
    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub]);

  // Feedback Metrics
  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avgRating: 0, elogios: 0, sugestoes: 0, reclamacoes: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + curr.rating, 0) / feedbacks.length;
    return {
      avgRating: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      reclamacoes: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const diaryData = useMemo(() => {
    if (!selectedCourseForDiary) return [];
    const courseEnrollments = enrollments.filter(e => e.courseId === selectedCourseForDiary);
    return courseEnrollments.map(enroll => {
      const student = allStudents.find(s => s.uid === enroll.userId);
      const studentResults = examResults.filter(r => {
        const exam = exams.find(e => e.id === r.examId);
        return r.userId === enroll.userId && exam?.courseId === selectedCourseForDiary;
      });
      const activities = studentResults.filter(r => exams.find(e => e.id === r.examId)?.type === 'activity');
      const evaluations = studentResults.filter(r => exams.find(e => e.id === r.examId)?.type === 'evaluation');
      const avgActivity = activities.length > 0 ? activities.reduce((acc, curr) => acc + curr.score, 0) / activities.length : 0;
      const avgEvaluation = evaluations.length > 0 ? evaluations.reduce((acc, curr) => acc + curr.score, 0) / evaluations.length : 0;
      const finalAverage = (avgActivity + avgEvaluation) / 2;
      return {
        studentName: student?.displayName || 'Aluno Desconhecido',
        progress: enroll.progress || 0,
        avgActivity: parseFloat(avgActivity.toFixed(1)),
        avgEvaluation: parseFloat(avgEvaluation.toFixed(1)),
        finalAverage: parseFloat(finalAverage.toFixed(1)),
        status: finalAverage >= 70 ? 'Aprovado' : 'Em Recuperação'
      };
    });
  }, [enrollments, examResults, allStudents, exams, selectedCourseForDiary]);

  const reportStats = useMemo(() => {
    const totalStudents = enrollments.length;
    const totalCompletedLessons = completedLessons.length;
    const allScores = examResults.map(r => r.score);
    const avgPerformance = allScores.length > 0 ? (allScores.reduce((a, b) => a + b, 0) / allScores.length).toFixed(1) : '0.0';
    return { totalStudents, totalCompletedLessons, avgPerformance };
  }, [enrollments, completedLessons, examResults]);

  // Handlers
  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (questions.length === 0) return;
    const payload = { title: examTitle, courseId: examCourseId, type: examType, passingGrade: passingGrade, questions, updatedAt: serverTimestamp(), authorId: user.uid };
    try {
      if (editingExamId) await updateDoc(doc(db, 'exams', editingExamId), payload);
      else await addDoc(collection(db, 'exams'), { ...payload, createdAt: serverTimestamp() });
      setIsModalOpen(false);
      resetExamForm();
    } catch (err) { console.error(err); }
  };

  const resetExamForm = () => {
    setExamTitle(''); setExamCourseId(''); setExamType('activity'); setPassingGrade(70); setQuestions([]); setEditingExamId(null);
  };

  const startExamFlow = async (exam: Exam) => {
    setAttemptError(null);
    const isPrivilegedUser = user.role === 'diretor' || user.role === 'professor';
    const q = query(collection(db, 'exam_results'), where('userId', '==', user.uid), where('examId', '==', exam.id));
    const attemptDocs = await getDocs(q);
    const maxAttempts = exam.type === 'evaluation' ? 1 : 3;
    if (!isPrivilegedUser && attemptDocs.size >= maxAttempts) {
      setAttemptError(`Limite de ${maxAttempts} tentativa(s) atingido.`);
      return;
    }
    setAttemptInfo({ current: isPrivilegedUser ? 0 : attemptDocs.size + 1, max: isPrivilegedUser ? 999 : maxAttempts });
    setSelectedExam(exam); setUserAnswers({}); setCurrentQuestionIdx(0); setExamStatus('briefing');
  };

  const finishExam = async () => {
    if (!selectedExam) return;
    let correctOnes = 0;
    selectedExam.questions.forEach((q, idx) => { if (userAnswers[idx] === q.correctOptionIndex) correctOnes++; });
    const score = Math.round((correctOnes / selectedExam.questions.length) * 100);
    setFinalScore(score);
    try {
      await addDoc(collection(db, 'exam_results'), { userId: user.uid, userName: user.displayName, userRole: user.role, examId: selectedExam.id, score, passed: score >= selectedExam.passingGrade, attempt: attemptInfo.current, completedAt: serverTimestamp() });
      setExamStatus('result');
    } catch (err) { console.error(err); }
  };

  const deleteMaterial = async (id: string) => { if (confirm("Excluir material?")) await deleteDoc(doc(db, 'materials', id)); };

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* CASE: AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">Avaliações e Atividades</h2>
              <p className="text-xs text-slate-500">Gestão do conhecimento e progresso discente.</p>
            </div>
            <button 
              onClick={() => { resetExamForm(); setIsModalOpen(true); }}
              className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
            >
              <Plus size={16} /> Nova Avaliação
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(exam => (
              <div key={exam.id} className="bg-white border border-slate-200 p-5 rounded-2xl hover:border-indigo-200 transition-all group relative overflow-hidden">
                <div className="flex justify-between items-start mb-4">
                  <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider ${
                    exam.type === 'evaluation' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'
                  }`}>
                    {exam.type === 'evaluation' ? 'Avaliação Oficial' : 'Atividade'}
                  </span>
                  <div className="flex items-center gap-1">
                    <button onClick={() => { setEditingExamId(exam.id); setExamTitle(exam.title); setExamCourseId(exam.courseId); setExamType(exam.type); setPassingGrade(exam.passingGrade); setQuestions(exam.questions); setIsModalOpen(true); }} className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><Pencil size={14} /></button>
                    <button onClick={() => { if (confirm("Excluir?")) deleteDoc(doc(db, 'exams', exam.id)); }} className="p-1.5 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"><Trash2 size={14} /></button>
                  </div>
                </div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{exam.title}</h3>
                <p className="text-[10px] text-slate-400 font-bold mb-6">VINCULADO: {courses.find(c => c.id === exam.courseId)?.nome || 'Sem Categoria'}</p>
                <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                  <div className="flex items-center gap-4 text-[10px] text-slate-400 font-bold uppercase">
                    <span className="flex items-center gap-1"><Clock size={12} /> {exam.questions.length} Qs</span>
                    <span className="flex items-center gap-1 text-indigo-500"><ShieldCheck size={12} /> {exam.passingGrade}%</span>
                  </div>
                  <button onClick={() => startExamFlow(exam)} className="bg-slate-900 text-white px-4 py-1.5 rounded-lg text-[11px] font-bold hover:bg-slate-800 shadow-sm">Testar Prova</button>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {/* CASE: DIÁRIO */}
      {activeSub === 'diario' && (
        <div className="space-y-6">
          <Header title="Diário de Classe" desc="Pauta eletrônica de notas e progresso acadêmico." />
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <div className="p-4 border-b bg-slate-50 flex items-center justify-between">
              <select value={selectedCourseForDiary} onChange={e => setSelectedCourseForDiary(e.target.value)} className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button className="flex items-center gap-2 text-xs font-bold text-slate-600 hover:text-indigo-600"><Download size={14} /> Exportar</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse text-xs">
                <thead className="bg-slate-50/80 font-black text-slate-500 uppercase tracking-widest border-b border-slate-100">
                  <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Progresso</th><th className="px-6 py-4">Atividades</th><th className="px-6 py-4">Provas</th><th className="px-6 py-4">Média Final</th><th className="px-6 py-4">Status</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {diaryData.map((d, i) => (
                    <tr key={i} className="hover:bg-slate-50/50">
                      <td className="px-6 py-4 font-bold text-slate-900">{d.studentName}</td>
                      <td className="px-6 py-4 font-medium text-slate-600">{d.progress}%</td>
                      <td className="px-6 py-4 font-bold text-slate-600">{d.avgActivity}</td>
                      <td className="px-6 py-4 font-bold text-slate-600">{d.avgEvaluation}</td>
                      <td className="px-6 py-4 font-black text-slate-900">{d.finalAverage}</td>
                      <td className={`px-6 py-4 font-black uppercase tracking-widest ${d.status === 'Aprovado' ? 'text-emerald-600' : 'text-amber-500'}`}>{d.status}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* CASE: MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="animate-in slide-in-from-right-4 duration-300">
          <div className="flex justify-between items-center mb-6">
             <Header title="Biblioteca de Materiais" desc="Arquivos e links de apoio." />
             <button className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {materials.map(m => (
              <div key={m.id} className="bg-slate-800 border border-slate-700 p-6 rounded-2xl relative group">
                <button onClick={() => deleteMaterial(m.id)} className="absolute top-3 right-3 text-slate-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16} /></button>
                <div className="w-12 h-12 rounded-xl flex items-center justify-center mb-4 bg-slate-700 text-indigo-400"><FileText size={24} /></div>
                <h4 className="font-bold text-white text-sm mb-1">{m.title}</h4>
                <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-4">{m.type}</p>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full block text-center py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-500 transition-all">Acessar Arquivo</a>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* CASE: FREQUENCIA */}
      {activeSub === 'frequencia' && (
        <div className="animate-in slide-in-from-right-4 duration-300">
          <Header title="Controle de Frequência" desc="Acompanhamento detalhado da participação." />
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
             <table className="w-full text-left text-xs">
                <thead className="bg-slate-50 font-black text-slate-500 uppercase tracking-widest border-b border-slate-100">
                   <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Aulas Concluídas</th><th className="px-6 py-4">% de Presença</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                   {enrollments.map((e, i) => {
                     const student = allStudents.find(s => s.uid === e.userId);
                     return (
                       <tr key={i} className="hover:bg-slate-50/50">
                          <td className="px-6 py-4 font-bold text-slate-900">{student?.displayName || 'Aluno'}</td>
                          <td className="px-6 py-4 text-slate-600">{Math.round(e.progress / 5)} lições</td>
                          <td className="px-6 py-4"><div className="flex items-center gap-2"><div className="w-20 h-1.5 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-emerald-500" style={{ width: `${e.progress}%` }}></div></div><span className="font-bold text-slate-900">{e.progress}%</span></div></td>
                       </tr>
                     );
                   })}
                </tbody>
             </table>
          </div>
        </div>
      )}

      {/* CASE: RELATÓRIO */}
      {activeSub === 'relatorio' && (
        <div className="animate-in slide-in-from-right-4 duration-300">
           <Header title="Relatórios Gerenciais" desc="Visão panorâmica dos indicadores da escola." />
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
