                 <button className="bg-white text-indigo-600 px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest">Definir Link</button>
              </div>
              <div className="lg:col-span-2 space-y-4">
                 <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Histórico</h3>
                 {lives.map(live => (
                    <div key={live.id} className="bg-white p-4 rounded-xl border border-slate-200 flex items-center justify-between">
                       <div className="flex items-center gap-4"><div className="bg-indigo-50 p-3 rounded-lg text-indigo-600"><Video size={20}/></div><h4 className="font-bold text-slate-900 text-sm">{live.title}</h4></div>
                       <button className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg">Acessar</button>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* CASE: FEEDBACK 360 DASHBOARD */}
      {activeSub === 'feedback' && (
        <div className="animate-in slide-in-from-right-4 duration-300 space-y-6">
           <Header title="Feedback 360°" desc="Dashboard de satisfação e manifestações dos alunos." />

           {/* Dashboard Summary Cards */}
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div className="bg-slate-900 p-5 rounded-2xl text-white flex items-center justify-between border border-slate-800 shadow-xl">
                 <div>
                    <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-1">Média NPS</p>
                    <h2 className="text-2xl font-black">{feedbackStats.avgRating} <span className="text-xs text-slate-500">/ 5.0</span></h2>
                 </div>
                 <div className="p-3 bg-white/10 rounded-xl text-amber-400"><Star size={20} fill="currentColor" /></div>
              </div>
              <div className="bg-white p-5 rounded-2xl border border-emerald-100 flex items-center justify-between group hover:shadow-lg transition-all">
                 <div>
                    <p className="text-[10px] font-bold text-emerald-500 uppercase tracking-widest mb-1">Elogios</p>
                    <h2 className="text-2xl font-black text-emerald-900">{feedbackStats.elogios}</h2>
                 </div>
                 <div className="p-3 bg-emerald-50 rounded-xl text-emerald-600 group-hover:scale-110 transition-transform"><ThumbsUp size={20} /></div>
              </div>
              <div className="bg-white p-5 rounded-2xl border border-indigo-100 flex items-center justify-between group hover:shadow-lg transition-all">
                 <div>
                    <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-1">Sugestões</p>
                    <h2 className="text-2xl font-black text-indigo-900">{feedbackStats.sugestoes}</h2>
                 </div>
                 <div className="p-3 bg-indigo-50 rounded-xl text-indigo-600 group-hover:scale-110 transition-transform"><Lightbulb size={20} /></div>
              </div>
              <div className="bg-white p-5 rounded-2xl border border-rose-100 flex items-center justify-between group hover:shadow-lg transition-all">
                 <div>
                    <p className="text-[10px] font-bold text-rose-500 uppercase tracking-widest mb-1">Reclamações</p>
                    <h2 className="text-2xl font-black text-rose-900">{feedbackStats.reclamacoes}</h2>
                 </div>
                 <div className="p-3 bg-rose-50 rounded-xl text-rose-600 group-hover:scale-110 transition-transform"><Frown size={20} /></div>
              </div>
           </div>

           {/* Feedback Wall */}
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {feedbacks.map(f => (
                 <div key={f.id} className={`p-5 rounded-2xl border bg-white transition-all shadow-sm flex flex-col justify-between h-56 ${
                   f.type === 'elogio' ? 'border-emerald-100 hover:border-emerald-300' :
                   f.type === 'sugestao' ? 'border-indigo-100 hover:border-indigo-300' :
                   'border-rose-100 hover:border-rose-300'
                 }`}>
                    <div>
                       <div className="flex items-center justify-between mb-3">
                          <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                            f.type === 'elogio' ? 'bg-emerald-50 text-emerald-600' :
                            f.type === 'sugestao' ? 'bg-indigo-50 text-indigo-600' :
                            'bg-rose-50 text-rose-600'
                          }`}>
                            {f.type} • {f.category}
                          </span>
                          <div className="flex gap-0.5 text-amber-400">
                             {[...Array(5)].map((_, i) => <Star key={i} size={10} fill={i < f.rating ? "currentColor" : "none"} className={i < f.rating ? "text-amber-400" : "text-slate-200"} />)}
                          </div>
                       </div>
                       <p className="text-sm text-slate-700 font-medium leading-relaxed italic line-clamp-4">"{f.comment}"</p>
                    </div>
                    <div className="pt-4 border-t border-slate-100 flex items-center gap-3">
