                </div>
                <button onClick={() => setExamStatus('tutorial')} className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-bold text-sm hover:bg-emerald-700 transition-all flex items-center gap-2">Avançar <ChevronRight size={18} /></button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="text-xs text-slate-400 font-bold hover:text-slate-600">Voltar para o portal</button>
