                             </div>
                          </div>
                          <button className="p-2 text-slate-300 hover:text-indigo-600 transition-colors" title="Responder Aluno">
                             <MessageCircle size={14} />
                          </button>
                       </div>
                    </div>
                 ))}
                 {feedbacks.length === 0 && (
                    <div className="col-span-full py-24 text-center bg-slate-50 rounded-[40px] border-2 border-dashed border-slate-200">
                       <MessageSquare size={60} className="mx-auto text-slate-200 mb-6" />
                       <h3 className="text-lg font-black text-slate-400">Silêncio no Dashboard</h3>
                       <p className="text-sm text-slate-400 mt-1 max-w-xs mx-auto">Seus alunos ainda não enviaram feedbacks. Incentive a participação para obter inteligência acadêmica.</p>
                    </div>
                 )}
              </div>
           </div>
        </div>
      )}

      {/* MODAL & EXAM ENGINE (Shared - Untouched logic) */}
      {selectedExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[400] bg-slate-50 flex items-center justify-center p-0 md:p-6">
          <div className="bg-white w-full max-w-4xl h-full md:h-[90vh] md:rounded-3xl shadow-2xl border border-slate-200 flex flex-col relative overflow-hidden">
            {examStatus === 'briefing' && (
              <div className="flex-1 flex flex-col items-center justify-center p-10 text-center space-y-8 animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center animate-pulse"><Sparkles size={40} /></div>
                <div className="max-w-xl space-y-4">
                  <h2 className="text-2xl font-black text-slate-900 italic tracking-tight">Respire fundo...</h2>
                  <p className="text-slate-600 text-base leading-relaxed">Prepare-se para consolidar o seu conhecimento com tranquilidade.</p>
                </div>
                <button onClick={() => setExamStatus('tutorial')} className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-bold text-sm hover:bg-emerald-700 transition-all flex items-center gap-2">Avançar <ChevronRight size={18} /></button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="text-xs text-slate-400 font-bold hover:text-slate-600">Voltar para o portal</button>
              </div>
            )}
            {examStatus === 'tutorial' && (
              <div className="flex-1 flex flex-col p-8 md:p-12 overflow-y-auto">
                <div className="max-w-2xl mx-auto w-full space-y-8 pb-10">
                  <div className="flex items-center gap-3 text-indigo-600 mb-2"><Info size={24} /><h2 className="text-xl font-black uppercase tracking-tight">Instruções</h2></div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100"><h3 className="font-bold text-slate-900 mb-1">{selectedExam.title}</h3><p className="text-xs text-slate-500">{selectedExam.questions.length} Questões</p></div>
                    <div className="bg-indigo-50 p-5 rounded-2xl border border-indigo-100"><p className="text-sm font-bold text-indigo-900">Tentativa {attemptInfo.current}</p></div>
                  </div>
                  <button onClick={() => setExamStatus('running')} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95 transition-all">Estou Pronto</button>
                </div>
              </div>
            )}
            {examStatus === 'running' && (
              <div className="h-full flex flex-col">
                <div className="p-6 bg-slate-900 text-white flex items-center justify-between shrink-0"><h2 className="font-bold text-base md:text-lg">{selectedExam.title}</h2><span className="text-2xl font-black text-white/30">{currentQuestionIdx + 1}/{selectedExam.questions.length}</span></div>
                <div className="flex-1 overflow-y-auto bg-slate-50/50">
                  <div className="max-w-2xl mx-auto p-6 md:p-12 space-y-10 pb-40">
                    <h3 className="text-lg md:text-xl font-bold text-slate-800 leading-tight">{selectedExam.questions[currentQuestionIdx].text}</h3>
                    <div className="grid grid-cols-1 gap-3">
                      {selectedExam.questions[currentQuestionIdx].options.map((opt, oIdx) => (
                        <button key={oIdx} onClick={() => setUserAnswers({...userAnswers, [currentQuestionIdx]: oIdx})} className={`flex items-center gap-4 p-5 rounded-2xl text-left border-2 transition-all ${userAnswers[currentQuestionIdx] === oIdx ? 'border-indigo-600 bg-indigo-50/50' : 'border-white bg-white shadow-sm'}`}>
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-black ${userAnswers[currentQuestionIdx] === oIdx ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>{String.fromCharCode(65 + oIdx)}</div>
                          <span className={`text-sm font-semibold ${userAnswers[currentQuestionIdx] === oIdx ? 'text-indigo-900 font-bold' : 'text-slate-600'}`}>{opt}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="p-6 bg-white border-t border-slate-100 flex items-center justify-between shrink-0">
                  <button disabled={currentQuestionIdx === 0} onClick={() => setCurrentQuestionIdx(v => v - 1)} className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-bold text-slate-500 disabled:opacity-0 transition-all"><ChevronLeft size={16} /> Anterior</button>
                  {currentQuestionIdx === selectedExam.questions.length - 1 ? <button onClick={finishExam} className="bg-indigo-600 text-white px-10 py-3 rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all shadow-xl active:scale-95">Finalizar Prova</button> : <button onClick={() => setCurrentQuestionIdx(v => v + 1)} className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white rounded-xl text-sm font-bold active:scale-95 transition-all">Próxima <ChevronRight size={16} /></button>}
                </div>
              </div>
            )}
            {examStatus === 'result' && (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in-95 duration-500">
                <div className={`w-24 h-24 rounded-full flex items-center justify-center mb-6 shadow-2xl ${finalScore >= selectedExam.passingGrade ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'}`}><Trophy size={48} /></div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 italic tracking-tight">{finalScore >= selectedExam.passingGrade ? 'Excelente!' : 'Bom Esforço!'}</h2>
                <p className="text-slate-500 text-sm mb-8 font-medium">Sua nota:</p>
                <div className="text-7xl font-black text-slate-900 mb-10 tabular-nums">{finalScore}%</div>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="w-full max-w-xs bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95 transition-all">Voltar</button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* EXAM MODAL FORM (Untouched) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-900">{editingExamId ? 'Editar' : 'Nova'} Avaliação</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <input required placeholder="Título" value={examTitle} onChange={e => setExamTitle(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <select required value={examCourseId} onChange={e => setExamCourseId(e.target.value)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none">
                  <option value="">Curso...</option>
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none">
                  <option value="activity">Atividade</option><option value="evaluation">Avaliação</option>
                </select>
                <input type="number" value={passingGrade} onChange={e => setPassingGrade(parseInt(e.target.value))} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
              </div>
              <button type="button" onClick={() => setQuestions([...questions, { id: Math.random().toString(36).substr(2, 9), text: '', options: ['', '', '', ''], correctOptionIndex: 0 }])} className="text-indigo-600 text-xs font-black uppercase tracking-tighter hover:underline">+ Adicionar Pergunta</button>
              {questions.map((q, idx) => (
                <div key={idx} className="p-5 border border-slate-100 rounded-2xl bg-slate-50/50 space-y-4 relative group">
                  <button type="button" onClick={() => setQuestions(questions.filter((_, i) => i !== idx))} className="absolute top-3 right-3 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><X size={16} /></button>
                  <textarea rows={2} placeholder={`Pergunta ${idx + 1}`} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold outline-none" value={q.text} onChange={e => { const updated = [...questions]; updated[idx].text = e.target.value; setQuestions(updated); }} />
                  <div className="space-y-2">
                    {q.options.map((opt, oIdx) => (
                      <div key={oIdx} className="flex items-center gap-3">
                        <input type="radio" name={`correct-${idx}`} checked={q.correctOptionIndex === oIdx} onChange={() => { const updated = [...questions]; updated[idx].correctOptionIndex = oIdx; setQuestions(updated); }} />
                        <input placeholder={`Opção ${oIdx + 1}`} className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none" value={opt} onChange={e => { const updated = [...questions]; updated[idx].options[oIdx] = e.target.value; setQuestions(updated); }} />
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Salvar Avaliação</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  doc, 
  serverTimestamp 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  User as UserIcon, 
  FileText, 
  Image as ImageIcon,
  Trash2,
  Pencil
} from 'lucide-react';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

type ModalTab = 'geral' | 'docente' | 'midias';

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [activeTab, setActiveTab] = useState<ModalTab>('geral');

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tema: '',
    categoria: '',
    nivelDificuldade: 'Iniciante' as Course['nivelDificuldade'],
    capaUrl: '',
    status: 'rascunho' as Course['status'],
    professorResponsavel: user.displayName || '',
    biografiaDocente: '',
    fotoDocenteUrl: '',
    materialApoioUrl: ''
  });

  // 1. LISTAGEM EM TEMPO REAL
  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    }, (error) => {
      console.error("Erro na sincronização em tempo real:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  // 2. SALVAMENTO NO FIRESTORE
  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coursePayload = {
        ...formData,
        professorId: user.uid,
        inscritos: editingCourse ? editingCourse.inscritos : 0,
        createdAt: editingCourse ? editingCourse.createdAt : serverTimestamp(),
      };

      if (editingCourse) {
        const courseRef = doc(db, 'cursos', editingCourse.id);
        await updateDoc(courseRef, coursePayload);
      } else {
        await addDoc(collection(db, 'cursos'), coursePayload);
      }

      setIsModalOpen(false);
      setEditingCourse(null);
      resetForm();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    }
  };

  const resetForm = () => {
    setFormData({
      nome: '',
      descricao: '',
      tema: '',
      categoria: '',
      nivelDificuldade: 'Iniciante',
      capaUrl: '',
      status: 'rascunho',
      professorResponsavel: user.displayName || '',
      biografiaDocente: '',
      fotoDocenteUrl: '',
      materialApoioUrl: ''
    });
    setActiveTab('geral');
  };

  const openEditModal = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      nome: course.nome,
      descricao: course.descricao || '',
      tema: course.tema || '',
      categoria: course.categoria,
      nivelDificuldade: course.nivelDificuldade,
      capaUrl: course.capaUrl,
      status: course.status,
      professorResponsavel: course.professorResponsavel,
      biografiaDocente: course.biografiaDocente || '',
      fotoDocenteUrl: course.fotoDocenteUrl || '',
      materialApoioUrl: course.materialApoioUrl || ''
    });
    setActiveTab('geral');
    setIsModalOpen(true);
  };

  // CORREÇÃO: Encaminha para o SchoolManagement se a aba não for 'cursos' ou 'modulos'
  if (activeSubView !== 'cursos' && activeSubView !== 'modulos') {
    return <SchoolManagement user={user} courses={myCourses} activeSub={activeSubView} />;
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Portal do Professor</h1>
          <p className="text-slate-500 text-sm">Olá, {user.displayName}. Gerencie seu conteúdo acadêmico aqui.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setEditingCourse(null); setIsModalOpen(true); }}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-sm"
        >
          <Plus size={18} />
          Criar Novo Conteúdo
        </button>
      </header>

      {/* Alerta de Contexto */}
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex gap-3 items-start">
        <Info className="text-indigo-600 mt-0.5 shrink-0" size={18} />
        <div>
          <p className="text-sm font-semibold text-indigo-900 leading-none mb-1">Sincronização Ativa</p>
          <p className="text-xs text-indigo-700">Seus cursos estão sendo listados em tempo real do Firestore para seu ID: {user.uid}.</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Pesquisar nos meus cursos..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
          <button className="flex items-center gap-2 text-slate-600 px-3 py-1.5 border border-slate-200 rounded-lg text-xs font-semibold hover:bg-slate-50">
            <Filter size={14} />
            Filtrar por Status
          </button>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
          </div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 p-4">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                className="border border-slate-100 p-4 rounded-xl hover:shadow-md transition-all cursor-pointer group bg-slate-50/50 relative"
                onClick={() => openEditModal(course)}
              >
                <div className="flex justify-between items-start mb-3">
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                    course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'
                  }`}>
                    {course.status}
                  </span>
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); openEditModal(course); }}
                      className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"
                    >
                      <Pencil size={14} />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); if (confirm('Excluir?')) deleteDoc(doc(db, 'cursos', course.id)); }}
                      className="p-1.5 text-slate-300 hover:text-red-600 hover:bg-white rounded-lg transition-all"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>

                {course.capaUrl && (
                  <div className="w-full h-32 mb-3 overflow-hidden rounded-lg bg-slate-200">
                    <img src={course.capaUrl} alt={course.nome} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  </div>
                )}

                <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-1">{course.nome}</h3>
                <div className="flex gap-2 mb-2">
                   <span className="text-[9px] bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.categoria}</span>
                   <span className="text-[9px] bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded font-bold uppercase">{course.nivelDificuldade}</span>
                </div>
                <p className="text-xs text-slate-500 line-clamp-2 mb-4 h-8">{course.descricao || 'Sem descrição cadastrada.'}</p>
                <div className="flex items-center justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider pt-3 border-t border-slate-100">
                  <span>{course.inscritos} Alunos</span>
                  <button className="text-indigo-600 hover:underline">Ver Detalhes</button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-12 opacity-50">
            <div className="bg-slate-100 p-4 rounded-full mb-4 text-slate-400">
              <BookOpen size={40} />
            </div>
            <p className="text-slate-600 font-bold text-sm">Nenhum curso sob sua gestão</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden">
            <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900">{editingCourse ? 'Editar Matriz' : 'Nova Matriz'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-lg">
                <X size={20} className="text-slate-500" />
              </button>
            </div>
            <div className="flex border-b border-slate-100 px-6 bg-slate-50/50">
              {(['geral', 'docente', 'midias'] as ModalTab[]).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-4 py-3 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${
                    activeTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'
                  }`}
                >
                  {tab}
                </button>
              ))}
            </div>
            <form onSubmit={handleSaveCourse} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
              {activeTab === 'geral' && (
                <div className="space-y-4">
                  <input required value={formData.nome} onChange={(e) => setFormData({...formData, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" placeholder="Nome do Curso" />
                  <div className="grid grid-cols-2 gap-4">
                    <select required value={formData.categoria} onChange={(e) => setFormData({...formData, categoria: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm">
                      <option value="">Categoria...</option>
                      <option value="Básico">Básico</option><option value="Doutrina">Doutrina</option>
                    </select>
                    <select value={formData.nivelDificuldade} onChange={(e) => setFormData({...formData, nivelDificuldade: e.target.value as any})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm">
                      <option value="Iniciante">Iniciante</option><option value="Intermediário">Intermediário</option>
                    </select>
                  </div>
                  <textarea rows={4} value={formData.descricao} onChange={(e) => setFormData({...formData, descricao: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm resize-none" placeholder="Descrição..."></textarea>
                </div>
              )}
              {activeTab === 'docente' && (
                <div className="space-y-4">
                  <input required value={formData.professorResponsavel} onChange={(e) => setFormData({...formData, professorResponsavel: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" placeholder="Nome do Professor" />
                  <textarea rows={4} value={formData.biografiaDocente} onChange={(e) => setFormData({...formData, biografiaDocente: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm resize-none" placeholder="Biografia..."></textarea>
                </div>
              )}
              {activeTab === 'midias' && (
                <div className="space-y-4">
                  <input required type="url" value={formData.capaUrl} onChange={(e) => setFormData({...formData, capaUrl: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" placeholder="URL da Capa" />
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold">
                    <option value="rascunho">Rascunho</option><option value="ativo">Ativo</option>
                  </select>
                </div>
              )}
              <div className="pt-6 flex gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-3 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold uppercase">Cancelar</button>
                <button type="submit" className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl text-xs font-bold uppercase shadow-lg">Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

