  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson,
  Module,
  Lesson
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
