  Settings,
  MoreVertical,
  GripVertical
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // States
  const [exams, setExams] = useState<Exam[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExamId, setEditingExamId] = useState<string | null>(null);
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);
  const [attemptError, setAttemptError] = useState<string | null>(null);
  const [attemptInfo, setAttemptInfo] = useState({ current: 0, max: 0 });

  const [examTitle, setExamTitle] = useState('');
  const [examCourseId, setExamCourseId] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [questions, setQuestions] = useState<Question[]>([]);

  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [selectedCourseForDiary, setSelectedCourseForDiary] = useState<string>(courses[0]?.id || '');

  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [completedLessons, setCompletedLessons] = useState<CompletedLesson[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // States para Módulos e Aulas
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');

  // Snapshots
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Exam));
      setExams(fetched);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (['diario', 'relatorio', 'frequencia', 'feedback'].includes(activeSub)) {
      onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      });
      onSnapshot(collection(db, 'exam_results'), (snap) => {
        setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
      });
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();
    }
  }, [activeSub]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }
    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules), orderBy('order', 'asc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      }));
    }
    if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }
    if (activeSub === 'live') {
      unsubscribes.push(onSnapshot(query(collection(db, 'lives'), orderBy('date', 'asc')), (snap) => {
        setLives(snap.docs.map(d => ({ id: d.id, ...d.data() } as LiveSession)));
      }));
    }
    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules]);

  // Handlers para Módulos e Aulas
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle('');
    setIsModuleModalOpen(false);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;

    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle,
      videoUrl: lessonVideoUrl,
      description: lessonDesc,
      order: mod.lessons.length + 1
    };

    const updatedLessons = [...mod.lessons, newLesson];
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: updatedLessons });

    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc('');
    setIsLessonModalOpen(false);
  };

  const deleteLesson = async (moduleId: string, lessonId: string) => {
    const mod = modules.find(m => m.id === moduleId);
    if (!mod) return;
    const updated = mod.lessons.filter(l => l.id !== lessonId);
    await updateDoc(doc(db, 'modulos', moduleId), { lessons: updated });
  };

  // Feedback Metrics
  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avgRating: 0, elogios: 0, sugestoes: 0, reclamacoes: 0, platformRating: 0, lessonRating: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + curr.rating, 0) / feedbacks.length;
    const platformFeedbacks = feedbacks.filter(f => f.category === 'plataforma');
    const lessonFeedbacks = feedbacks.filter(f => f.category === 'aula');
    return {
      avgRating: avg.toFixed(1),
      platformRating: (platformFeedbacks.reduce((a, b) => a + b.rating, 0) / (platformFeedbacks.length || 1)).toFixed(1),
      lessonRating: (lessonFeedbacks.reduce((a, b) => a + b.rating, 0) / (lessonFeedbacks.length || 1)).toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      reclamacoes: feedbacks.filter(f => f.type === 'reclamacao').length,
