                 className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
               >
                 {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
               </select>
               <button 
                 onClick={() => setIsModuleModalOpen(true)}
                 className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 hover:bg-slate-800 shadow-lg shadow-slate-200"
               >
                 <Plus size={16} /> Novo Módulo
               </button>
            </div>
          </div>

          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm transition-all hover:shadow-md">
                <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-white rounded-xl shadow-sm text-indigo-600"><Layers size={18} /></div>
                    <h3 className="font-black text-slate-800 text-sm uppercase tracking-tight">{mod.title}</h3>
                  </div>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }}
                      className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-all"
                    >
                      + Adicionar Lição
                    </button>
                    <button onClick={() => deleteDoc(doc(db, 'modulos', mod.id))} className="p-2 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={16} /></button>
                  </div>
                </div>

                <div className="p-4 space-y-3">
                  {mod.lessons.map(lesson => (
                    <div key={lesson.id} className="group bg-slate-50/50 hover:bg-white border border-transparent hover:border-indigo-100 p-4 rounded-2xl flex flex-col md:flex-row gap-6 transition-all">
