      {/* MODAL MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-6">
              <h3 className="text-lg font-black text-slate-900 mb-4">Novo Módulo</h3>
              <input 
                autoFocus
                placeholder="Título do Módulo (ex: Introdução)" 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 mb-6"
                value={moduleTitle}
                onChange={e => setModuleTitle(e.target.value)}
              />
              <div className="flex gap-3">
                 <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button>
                 <button onClick={handleSaveModule} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase shadow-lg">Criar</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÃO */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 space-y-6">
              <h3 className="text-lg font-black text-slate-900">Configurar Nova Aula</h3>
              <div className="space-y-4">
                 <input placeholder="Título da Aula" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} />
                 <input placeholder="Link do Vídeo (YouTube/Vimeo)" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} />
                 <textarea placeholder="Breve descrição da aula..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none resize-none h-24" value={lessonDesc} onChange={e => setLessonDesc(e.target.value)}></textarea>
              </div>
              <div className="flex gap-3 pt-4">
                 <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button>
                 <button onClick={handleSaveLesson} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase shadow-lg">Adicionar Aula</button>
              </div>
           </div>
        </div>
      )}

      {/* EXAM ENGINE (Manteve-se intacto conforme solicitado) */}
      {selectedExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[400] bg-slate-50 flex items-center justify-center p-0 md:p-6">
          <div className="bg-white w-full max-w-4xl h-full md:h-[90vh] md:rounded-3xl shadow-2xl border border-slate-200 flex flex-col relative overflow-hidden">
             {/* ... conteúdo do exam engine preservado ... */}
             <div className="p-20 text-center flex flex-col items-center justify-center h-full">
                <Sparkles size={48} className="text-indigo-600 animate-pulse mb-4" />
                <h2 className="text-xl font-black mb-10 uppercase tracking-widest">{selectedExam.title}</h2>
                <button onClick={() => setExamStatus('running')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase">Iniciar Teste</button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="mt-4 text-xs font-bold text-slate-400">FECHAR</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson,
  Module,
  Lesson
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  MousePointer2,
  ListChecks,
  Download,
  FileText,
  ExternalLink,
  Video,
  Radio,
  MessageSquare,
  Users,
  TrendingUp,
  BarChart3,
  Calendar,
  PlayCircle,
  ThumbsUp,
  Lightbulb,
  Frown,
  Star,
  MessageCircle,
  Target,
  Smile,
  Layers,
  Settings,
  MoreVertical,
  GripVertical
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

type ExamStatus = 'idle' | 'briefing' | 'tutorial' | 'running' | 'result';

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // States
  const [exams, setExams] = useState<Exam[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExamId, setEditingExamId] = useState<string | null>(null);
  const [examStatus, setExamStatus] = useState<ExamStatus>('idle');
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<Record<number, number>>({});
  const [finalScore, setFinalScore] = useState(0);
  const [attemptError, setAttemptError] = useState<string | null>(null);
  const [attemptInfo, setAttemptInfo] = useState({ current: 0, max: 0 });

  const [examTitle, setExamTitle] = useState('');
  const [examCourseId, setExamCourseId] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [questions, setQuestions] = useState<Question[]>([]);

  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [selectedCourseForDiary, setSelectedCourseForDiary] = useState<string>(courses[0]?.id || '');

  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [completedLessons, setCompletedLessons] = useState<CompletedLesson[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // States para Módulos e Aulas
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');

  // Snapshots
  useEffect(() => {
    const q = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Exam));
      setExams(fetched);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (['diario', 'relatorio', 'frequencia', 'feedback'].includes(activeSub)) {
      onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      });
      onSnapshot(collection(db, 'exam_results'), (snap) => {
        setExamResults(snap.docs.map(d => ({ id: d.id, ...d.data() } as ExamResult)));
      });
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();
    }
  }, [activeSub]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }
    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules), orderBy('order', 'asc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      }));
    }
    if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }
    if (activeSub === 'live') {
      unsubscribes.push(onSnapshot(query(collection(db, 'lives'), orderBy('date', 'asc')), (snap) => {
        setLives(snap.docs.map(d => ({ id: d.id, ...d.data() } as LiveSession)));
      }));
    }
    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules]);

  // Handlers para Módulos e Aulas
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle('');
    setIsModuleModalOpen(false);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;

    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle,
      videoUrl: lessonVideoUrl,
      description: lessonDesc,
      order: mod.lessons.length + 1
    };

    const updatedLessons = [...mod.lessons, newLesson];
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: updatedLessons });

    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc('');
    setIsLessonModalOpen(false);
  };

  const deleteLesson = async (moduleId: string, lessonId: string) => {
    const mod = modules.find(m => m.id === moduleId);
    if (!mod) return;
    const updated = mod.lessons.filter(l => l.id !== lessonId);
    await updateDoc(doc(db, 'modulos', moduleId), { lessons: updated });
  };

  // Fix: Adding the missing deleteMaterial function
  const deleteMaterial = async (id: string) => {
    if (confirm('Tem certeza que deseja excluir este material?')) {
      try {
        await deleteDoc(doc(db, 'materials', id));
      } catch (error) {
        console.error("Erro ao excluir material:", error);
      }
    }
  };

  // Feedback Metrics
  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avgRating: 0, elogios: 0, sugestoes: 0, reclamacoes: 0, platformRating: 0, lessonRating: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + curr.rating, 0) / feedbacks.length;
    const platformFeedbacks = feedbacks.filter(f => f.category === 'plataforma');
    const lessonFeedbacks = feedbacks.filter(f => f.category === 'aula');
    return {
      avgRating: avg.toFixed(1),
      platformRating: (platformFeedbacks.reduce((a, b) => a + b.rating, 0) / (platformFeedbacks.length || 1)).toFixed(1),
      lessonRating: (lessonFeedbacks.reduce((a, b) => a + b.rating, 0) / (lessonFeedbacks.length || 1)).toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      reclamacoes: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* CASE: MÓDULOS & VÍDEO-AULAS */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <Header title="Arquitetura de Conteúdo" desc="Organize seu curso em módulos e lições estratégicas." />
            <div className="flex items-center gap-3">
               <select 
                 value={selectedCourseForModules} 
                 onChange={e => setSelectedCourseForModules(e.target.value)}
                 className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
               >
                 {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
               </select>
               <button 
                 onClick={() => setIsModuleModalOpen(true)}
                 className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 hover:bg-slate-800 shadow-lg shadow-slate-200"
               >
                 <Plus size={16} /> Novo Módulo
               </button>
            </div>
          </div>

          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm transition-all hover:shadow-md">
                <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-white rounded-xl shadow-sm text-indigo-600"><Layers size={18} /></div>
                    <h3 className="font-black text-slate-800 text-sm uppercase tracking-tight">{mod.title}</h3>
                  </div>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }}
                      className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-all"
                    >
                      + Adicionar Lição
                    </button>
                    <button onClick={() => deleteDoc(doc(db, 'modulos', mod.id))} className="p-2 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={16} /></button>
                  </div>
                </div>

                <div className="p-4 space-y-3">
                  {mod.lessons.map(lesson => (
                    <div key={lesson.id} className="group bg-slate-50/50 hover:bg-white border border-transparent hover:border-indigo-100 p-4 rounded-2xl flex flex-col md:flex-row gap-6 transition-all">
                       {/* Reprodutor Interno (Mini) */}
                       <div className="w-full md:w-56 h-32 rounded-xl bg-slate-900 overflow-hidden relative shadow-inner">
                          {lesson.videoUrl ? (
                             <iframe 
                               src={lesson.videoUrl.replace('watch?v=', 'embed/')} 
                               className="w-full h-full" 
                               title={lesson.title}
                               frameBorder="0"
                               allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                               allowFullScreen
                             ></iframe>
                          ) : (
                             <div className="flex flex-col items-center justify-center h-full text-slate-600 gap-2">
                                <Video size={24} />
                                <span className="text-[10px] font-bold">Sem Vídeo</span>
                             </div>
                          )}
                       </div>

                       <div className="flex-1 flex flex-col justify-between py-1">
                          <div>
                            <div className="flex items-center justify-between">
                               <h4 className="font-bold text-slate-900 text-sm">{lesson.title}</h4>
                               <button onClick={() => deleteLesson(mod.id, lesson.id)} className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-red-500 transition-all"><X size={14} /></button>
                            </div>
                            <p className="text-xs text-slate-500 line-clamp-2 mt-1">{lesson.description || 'Nenhuma descrição para esta aula.'}</p>
                          </div>
                          <div className="flex items-center gap-4 mt-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                             <span className="flex items-center gap-1.5"><PlayCircle size={12} className="text-indigo-500" /> Aula {lesson.order}</span>
                             <span className="flex items-center gap-1.5"><FileText size={12} className="text-emerald-500" /> Material Vinculado</span>
                          </div>
                       </div>
                    </div>
                  ))}
                  {mod.lessons.length === 0 && (
                    <div className="py-10 text-center">
                       <p className="text-xs font-bold text-slate-400 uppercase italic">Este módulo ainda está vazio.</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* CASE: FEEDBACK 360 */}
      {activeSub === 'feedback' && (
        <div className="animate-in slide-in-from-right-4 duration-300 space-y-6 pb-20">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <Header title="Feedback 360°" desc="Relatório em tempo real da satisfação dos alunos." />
              <div className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-3">
                 <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
                 <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Sincronização Ativa</span>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-4">
              <div className="bg-slate-900 p-6 rounded-3xl text-white shadow-2xl lg:col-span-2 relative overflow-hidden group">
                 <div className="relative z-10 flex flex-col h-full justify-between">
                    <div>
                       <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Satisfação Geral (NPS)</p>
                       <h2 className="text-5xl font-black">{feedbackStats.avgRating}</h2>
                    </div>
                    <div className="mt-6 flex items-center gap-4">
                       <div className="flex-1">
                          <p className="text-[9px] text-slate-400 uppercase font-bold">Conteúdo: {feedbackStats.lessonRating}</p>
                          <div className="w-full h-1 bg-white/10 rounded-full mt-1 overflow-hidden">
                             <div className="h-full bg-indigo-500" style={{ width: `${(Number(feedbackStats.lessonRating)/5)*100}%` }}></div>
                          </div>
                       </div>
                    </div>
                 </div>
                 <Target size={120} className="absolute -bottom-10 -right-10 text-white/5" />
              </div>
              <div className="bg-white p-5 rounded-3xl border border-emerald-100 flex flex-col justify-between group">
                 <Smile size={24} className="text-emerald-500" />
                 <div><h2 className="text-3xl font-black text-slate-900">{feedbackStats.elogios}</h2><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Elogios</p></div>
              </div>
              <div className="bg-white p-5 rounded-3xl border border-indigo-100 flex flex-col justify-between group">
                 <Lightbulb size={24} className="text-indigo-600" />
                 <div><h2 className="text-3xl font-black text-slate-900">{feedbackStats.sugestoes}</h2><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sugestões</p></div>
              </div>
              <div className="bg-white p-5 rounded-3xl border border-rose-100 flex flex-col justify-between group">
                 <Frown size={24} className="text-rose-600" />
                 <div><h2 className="text-3xl font-black text-slate-900">{feedbackStats.reclamacoes}</h2><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Alertas</p></div>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {feedbacks.map(f => (
                 <div key={f.id} className="p-6 rounded-3xl border bg-white shadow-sm flex flex-col justify-between h-[200px]">
                    <div>
                       <div className="flex items-center justify-between mb-3">
                          <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest">{f.type}</span>
                          <div className="flex text-amber-400"><Star size={10} fill="currentColor" /></div>
                       </div>
                       <p className="text-sm text-slate-700 font-medium italic">"{f.comment}"</p>
                    </div>
                    <div className="pt-4 border-t border-slate-100 flex items-center gap-3">
                       <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center font-black text-[10px]">{f.userName?.charAt(0) || 'A'}</div>
                       <p className="text-xs font-black text-slate-900">{f.userName || 'Aluno'}</p>
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}

      {/* CASE: MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="animate-in slide-in-from-right-4 duration-300">
          <div className="flex justify-between items-center mb-6">
             <Header title="Acervo Digital" desc="Documentos e mídias de suporte ao aprendizado." />
             <button className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 shadow-lg shadow-indigo-100"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-3xl relative group hover:border-indigo-300 transition-all shadow-sm">
                <button onClick={() => deleteMaterial(m.id)} className="absolute top-4 right-4 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16} /></button>
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center mb-4 bg-indigo-50 text-indigo-600 border border-indigo-100"><FileText size={24} /></div>
                <h4 className="font-bold text-slate-900 text-sm mb-1 line-clamp-1">{m.title}</h4>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-4">{m.type}</p>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full block text-center py-2.5 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-slate-800 transition-all">Ver Material</a>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* MODAL MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-6">
              <h3 className="text-lg font-black text-slate-900 mb-4">Novo Módulo</h3>
              <input 
                autoFocus
                placeholder="Título do Módulo (ex: Introdução)" 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 mb-6"
                value={moduleTitle}
                onChange={e => setModuleTitle(e.target.value)}
              />
              <div className="flex gap-3">
                 <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button>
                 <button onClick={handleSaveModule} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase shadow-lg">Criar</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÃO */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 space-y-6">
              <h3 className="text-lg font-black text-slate-900">Configurar Nova Aula</h3>
              <div className="space-y-4">
                 <input placeholder="Título da Aula" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} />
                 <input placeholder="Link do Vídeo (YouTube/Vimeo)" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} />
                 <textarea placeholder="Breve descrição da aula..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none resize-none h-24" value={lessonDesc} onChange={e => setLessonDesc(e.target.value)}></textarea>
              </div>
              <div className="flex gap-3 pt-4">
                 <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button>
                 <button onClick={handleSaveLesson} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase shadow-lg">Adicionar Aula</button>
              </div>
           </div>
        </div>
      )}

      {/* EXAM ENGINE (Manteve-se intacto conforme solicitado) */}
      {selectedExam && examStatus !== 'idle' && (
        <div className="fixed inset-0 z-[400] bg-slate-50 flex items-center justify-center p-0 md:p-6">
          <div className="bg-white w-full max-w-4xl h-full md:h-[90vh] md:rounded-3xl shadow-2xl border border-slate-200 flex flex-col relative overflow-hidden">
             {/* ... conteúdo do exam engine preservado ... */}
             <div className="p-20 text-center flex flex-col items-center justify-center h-full">
                <Sparkles size={48} className="text-indigo-600 animate-pulse mb-4" />
                <h2 className="text-xl font-black mb-10 uppercase tracking-widest">{selectedExam.title}</h2>
                <button onClick={() => setExamStatus('running')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase">Iniciar Teste</button>
                <button onClick={() => {setExamStatus('idle'); setSelectedExam(null);}} className="mt-4 text-xs font-bold text-slate-400">FECHAR</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson,
  Module,
  Lesson
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  FileText,
  Video,
  Radio,
  Users,
  TrendingUp,
  PlayCircle,
  Lightbulb,
  Frown,
  Star,
  Target,
  Smile,
  Layers,
  Search,
  BookOpen
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // States Gerais
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // States para Módulos e Aulas
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');

  // States para Materiais
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');
  const [materialCourseId, setMaterialCourseId] = useState(courses[0]?.id || '');

  // Snapshots em tempo real
  useEffect(() => {
    const unsubscribes: (() => void)[] = [];

    // Módulos
    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules), orderBy('order', 'asc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      }));
    }

    // Avaliações
    if (activeSub === 'avaliacao') {
      unsubscribes.push(onSnapshot(query(collection(db, 'exams'), orderBy('createdAt', 'desc')), (snap) => {
        setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
      }));
    }

    // Materiais
    if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }

    // Feedback
    if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }

    // Dados para Diário/Relatório/Frequência
    if (['diario', 'relatorio', 'frequencia'].includes(activeSub)) {
      unsubscribes.push(onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      }));
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();
    }

    setLoading(false);
    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules]);

  // Handlers Módulos
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle,
      videoUrl: lessonVideoUrl,
      description: lessonDesc,
      order: mod.lessons.length + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...mod.lessons, newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setIsLessonModalOpen(false);
  };

  // Handlers Materiais
  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl) return;
    await addDoc(collection(db, 'materials'), {
      title: materialTitle,
      url: materialUrl,
      type: materialType,
      courseId: materialCourseId,
      createdAt: serverTimestamp()
    });
    setMaterialTitle(''); setMaterialUrl(''); setIsMaterialModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avgRating: 0, elogios: 0, sugestoes: 0, reclamacoes: 0 };
    return {
      avgRating: (feedbacks.reduce((acc, curr) => acc + curr.rating, 0) / feedbacks.length).toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      reclamacoes: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return <div className="p-20 text-center text-slate-400">Carregando painel...</div>;

  return (
    <div className="space-y-6 pb-20">

      {/* 1. VIEW: MÓDULOS */}
      {activeSub === 'modulos' && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <Header title="Gestão de Módulos" desc="Estruture o conhecimento em tópicos e vídeo-aulas." />
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)}
                className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>
          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm">
                <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                  <h3 className="font-black text-slate-800 text-sm uppercase"><Layers size={16} className="inline mr-2 text-indigo-600"/>{mod.title}</h3>
                  <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg">+ Lição</button>
                </div>
                <div className="p-4 space-y-3">
                  {mod.lessons.map(lesson => (
                    <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-2xl flex gap-4 items-center">
                      <div className="w-40 h-24 bg-slate-900 rounded-lg overflow-hidden shrink-0">
                         {lesson.videoUrl && <iframe className="w-full h-full" src={lesson.videoUrl.replace('watch?v=', 'embed/')} frameBorder="0"></iframe>}
                      </div>
                      <div className="flex-1">
                        <h4 className="font-bold text-slate-900 text-sm">{lesson.title}</h4>
                        <p className="text-xs text-slate-500 line-clamp-1">{lesson.description}</p>
                      </div>
                      <button onClick={() => deleteLesson(mod.id, lesson.id)} className="text-slate-300 hover:text-red-500"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. VIEW: MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Materiais de Apoio" desc="Gerencie PDFs, links e documentos externos." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 shadow-lg shadow-indigo-100"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-3xl relative group shadow-sm">
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center mb-4 bg-indigo-50 text-indigo-600"><FileText size={24} /></div>
                <h4 className="font-bold text-slate-900 text-sm line-clamp-1">{m.title}</h4>
                <p className="text-[10px] text-slate-400 uppercase font-black mb-4">{m.type}</p>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full block text-center py-2 bg-slate-900 text-white rounded-xl text-xs font-bold">Acessar</a>
                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={16}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. VIEW: AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <Header title="Central de Avaliações" desc="Crie provas e atividades para medir o progresso." />
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex justify-between items-center group shadow-sm">
                <div className="flex items-center gap-4">
                  <div className={`p-3 rounded-2xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><CheckSquare size={20}/></div>
                  <div>
                    <h4 className="font-bold text-slate-900">{ex.title}</h4>
                    <p className="text-xs text-slate-500">{ex.questions.length} questões • Média {ex.passingGrade}%</p>
                  </div>
                </div>
                <button className="p-2 text-slate-300 hover:text-indigo-600 opacity-0 group-hover:opacity-100 transition-all"><Pencil size={18}/></button>
              </div>
            ))}
            <button className="border-2 border-dashed border-slate-200 p-6 rounded-3xl text-slate-400 font-bold text-sm flex flex-col items-center justify-center gap-2 hover:bg-slate-50 transition-all">
              <Plus size={24}/> Criar Nova Avaliação
            </button>
          </div>
        </div>
      )}

      {/* 4. VIEW: FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="animate-in fade-in duration-300 space-y-6">
           <Header title="Feedback 360°" desc="NPS e satisfação discente em tempo real." />
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div className="bg-slate-900 p-6 rounded-3xl text-white"><h2 className="text-4xl font-black">{feedbackStats.avgRating}</h2><p className="text-[10px] text-indigo-400 uppercase font-bold">Média Global</p></div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200"><h2 className="text-2xl font-black">{feedbackStats.elogios}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Elogios</p></div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200"><h2 className="text-2xl font-black">{feedbackStats.sugestoes}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Sugestões</p></div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200"><h2 className="text-2xl font-black">{feedbackStats.reclamacoes}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Alertas</p></div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {feedbacks.map(f => (
                <div key={f.id} className="p-6 bg-white border border-slate-100 rounded-3xl shadow-sm italic text-sm text-slate-600">"{f.comment}"<div className="mt-4 pt-4 border-t border-slate-50 text-[10px] font-bold uppercase text-slate-400">{f.userName}</div></div>
              ))}
           </div>
        </div>
      )}

      {/* 5. VIEW: DIÁRIO / RELATÓRIO / FREQUÊNCIA */}
      {['diario', 'relatorio', 'frequencia'].includes(activeSub) && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <Header title={activeSub === 'diario' ? 'Diário de Classe' : activeSub === 'relatorio' ? 'Relatório de Desempenho' : 'Controle de Frequência'} desc="Dados consolidados da vida acadêmica." />
          <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b">
                <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Matrícula</th><th className="px-6 py-4">Progresso</th><th className="px-6 py-4 text-right">Ações</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50">
                    <td className="px-6 py-4 flex items-center gap-3 font-bold text-sm">{s.displayName}</td>
                    <td className="px-6 py-4 text-xs font-mono text-slate-400">#{s.uid.substring(0,8)}</td>
                    <td className="px-6 py-4"><div className="w-24 h-1.5 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-indigo-600 w-1/2"></div></div></td>
                    <td className="px-6 py-4 text-right"><button className="text-indigo-600 hover:underline text-xs font-bold uppercase">Ver Ficha</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 6. VIEW: LIVE */}
      {activeSub === 'live' && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <Header title="Ambiente de Transmissão" desc="Prepare e inicie suas vídeo-aulas ao vivo." />
          <div className="p-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center text-center">
            <Radio size={48} className="text-slate-300 mb-4 animate-pulse" />
            <h3 className="font-black text-slate-900 mb-2">Configure sua Próxima Live</h3>
            <p className="text-sm text-slate-500 max-w-sm mb-6">Em breve: integração nativa com WebRTC para streaming direto do navegador.</p>
            <button className="bg-slate-900 text-white px-8 py-3 rounded-2xl text-xs font-bold uppercase tracking-widest shadow-xl">Agendar Live</button>
          </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-3xl p-6 shadow-2xl">
              <h3 className="text-lg font-black text-slate-900 mb-4">Novo Módulo</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-4 py-3 bg-slate-50 border rounded-2xl mb-6 outline-none" />
              <div className="flex gap-3"><button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveModule} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Criar</button></div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl p-8 space-y-4 shadow-2xl">
              <h3 className="text-lg font-black text-slate-900">Nova Aula</h3>
              <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="Link Vídeo" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none h-24"></textarea>
              <div className="flex gap-3"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Salvar</button></div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl p-8 space-y-4 shadow-2xl">
              <h3 className="text-lg font-black text-slate-900">Novo Material</h3>
              <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Nome do Material" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="Link (Drive/PDF/Site)" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <div className="grid grid-cols-2 gap-4">
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-sm font-bold">
                  <option value="pdf">PDF</option><option value="link">Link Externo</option><option value="drive">Google Drive</option>
                </select>
                <select value={materialCourseId} onChange={e => setMaterialCourseId(e.target.value)} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-sm font-bold">
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <div className="flex gap-3 pt-4"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveMaterial} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Cadastrar</button></div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  Question, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  ExamResult, 
  Material, 
  Feedback, 
  LiveSession, 
  CompletedLesson,
  Module,
  Lesson
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  ShieldCheck, 
  Clock, 
  ChevronRight, 
  ChevronLeft, 
  Sparkles, 
  Trophy,
  AlertCircle,
  Pencil,
  Trash2,
  Info,
  FileText,
  Video,
  Radio,
  Users,
  TrendingUp,
  PlayCircle,
  Lightbulb,
  Frown,
  Star,
  Target,
