  Layers,
  Search,
  BookOpen
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  // States Gerais
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [lives, setLives] = useState<LiveSession[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // States para Módulos e Aulas
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');

  // States para Materiais
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');
  const [materialCourseId, setMaterialCourseId] = useState(courses[0]?.id || '');

  // Snapshots em tempo real
  useEffect(() => {
    const unsubscribes: (() => void)[] = [];

    // Módulos
    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules), orderBy('order', 'asc'));
      unsubscribes.push(onSnapshot(q, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      }));
    }

    // Avaliações
    if (activeSub === 'avaliacao') {
      unsubscribes.push(onSnapshot(query(collection(db, 'exams'), orderBy('createdAt', 'desc')), (snap) => {
        setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
      }));
    }

    // Materiais
    if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
      }));
    }

    // Feedback
    if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
      }));
    }

    // Dados para Diário/Relatório/Frequência
    if (['diario', 'relatorio', 'frequencia'].includes(activeSub)) {
      unsubscribes.push(onSnapshot(collection(db, 'inscricoes'), (snap) => {
        setEnrollments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Enrollment)));
      }));
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      };
      fetchStudents();
    }

    setLoading(false);
    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules]);

  // Handlers Módulos
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle,
      videoUrl: lessonVideoUrl,
      description: lessonDesc,
      order: mod.lessons.length + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...mod.lessons, newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setIsLessonModalOpen(false);
  };

  // Fixed missing deleteLesson function
  const deleteLesson = async (moduleId: string, lessonId: string) => {
    if (!confirm('Deseja realmente excluir esta lição?')) return;

    const mod = modules.find(m => m.id === moduleId);
    if (!mod) return;

    const updatedLessons = mod.lessons.filter(l => l.id !== lessonId);
    try {
      await updateDoc(doc(db, 'modulos', moduleId), { lessons: updatedLessons });
    } catch (error) {
      console.error("Erro ao excluir lição:", error);
