  // Handlers Materiais
  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl) return;
    await addDoc(collection(db, 'materials'), {
      title: materialTitle,
      url: materialUrl,
      type: materialType,
      courseId: materialCourseId,
      createdAt: serverTimestamp()
