  if (loading) return <div className="p-20 text-center text-slate-400">Carregando painel...</div>;

  return (
    <div className="space-y-6 pb-20">

      {/* 1. VIEW: MÓDULOS */}
      {activeSub === 'modulos' && (
        <div className="animate-in fade-in duration-300 space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <Header title="Gestão de Módulos" desc="Estruture o conhecimento em tópicos e vídeo-aulas." />
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
