                className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
