          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-3xl relative group shadow-sm">
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center mb-4 bg-indigo-50 text-indigo-600"><FileText size={24} /></div>
