              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-4 py-3 bg-slate-50 border rounded-2xl mb-6 outline-none" />
              <div className="flex gap-3"><button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveModule} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Criar</button></div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl p-8 space-y-4 shadow-2xl">
              <h3 className="text-lg font-black text-slate-900">Nova Aula</h3>
              <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="Link Vídeo" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none h-24"></textarea>
              <div className="flex gap-3"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Salvar</button></div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-3xl p-8 space-y-4 shadow-2xl">
              <h3 className="text-lg font-black text-slate-900">Novo Material</h3>
              <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Nome do Material" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="Link (Drive/PDF/Site)" className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" />
              <div className="grid grid-cols-2 gap-4">
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-sm font-bold">
                  <option value="pdf">PDF</option><option value="link">Link Externo</option><option value="drive">Google Drive</option>
                </select>
                <select value={materialCourseId} onChange={e => setMaterialCourseId(e.target.value)} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-sm font-bold">
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <div className="flex gap-3 pt-4"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-xs font-bold uppercase">Cancelar</button><button onClick={handleSaveMaterial} className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-bold uppercase">Cadastrar</button></div>
           </div>
        </div>
      )}

    </div>
  );
};

