                  <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Aula" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Vídeo</label>
                  <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="Link do YouTube, Vimeo ou Drive" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
                </div>

                <div className="space-y-1">
