                        onChange={e => setLessonMaterialUrl(e.target.value)} 
                        placeholder="Ou cole um link direto do Drive/PDF" 
                        className={`w-full pl-10 pr-5 py-4 bg-slate-50 border rounded-2xl outline-none focus:ring-2 focus:ring-emerald-500 text-sm ${selectedMaterialId ? 'opacity-50 cursor-not-allowed' : ''}`} 
                      />
