import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  doc, 
  serverTimestamp,
  getDocs,
  writeBatch
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import { 
  Search, 
  BookOpen, 
  Plus, 
  X, 
  Trash2,
  Pencil
} from 'lucide-react';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

type ModalTab = 'geral' | 'docente' | 'midias';

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [activeTab, setActiveTab] = useState<ModalTab>('geral');

  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tema: '',
    categoria: '',
    nivelDificuldade: 'Iniciante' as Course['nivelDificuldade'],
    capaUrl: '',
    status: 'rascunho' as Course['status'],
    professorResponsavel: user.displayName || '',
    biografiaDocente: '',
    fotoDocenteUrl: '',
    materialApoioUrl: ''
  });

  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm('ATENÇÃO: Deletar este curso removerá permanentemente todos os módulos e lições associados. Confirmar?')) return;

    try {
      // 1. Deleta o curso
      await deleteDoc(doc(db, 'cursos', courseId));

      // 2. Busca e deleta módulos associados (Exclusão em Cascata Manual)
      const q = query(collection(db, 'modulos'), where('courseId', '==', courseId));
      const modSnap = await getDocs(q);

      const batch = writeBatch(db);
      modSnap.forEach((mDoc) => {
        batch.delete(mDoc.ref);
      });
      await batch.commit();

    } catch (error) {
      console.error("Erro ao deletar curso em cascata:", error);
    }
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coursePayload = {
        ...formData,
        professorId: user.uid,
        inscritos: editingCourse ? editingCourse.inscritos : 0,
        createdAt: editingCourse ? editingCourse.createdAt : serverTimestamp(),
      };

      if (editingCourse) {
        await updateDoc(doc(db, 'cursos', editingCourse.id), coursePayload);
      } else {
        await addDoc(collection(db, 'cursos'), coursePayload);
      }
      setIsModalOpen(false);
      resetForm();
    } catch (error) { console.error(error); }
  };

  const resetForm = () => {
    setFormData({
      nome: '', descricao: '', tema: '', categoria: '', nivelDificuldade: 'Iniciante',
      capaUrl: '', status: 'rascunho', professorResponsavel: user.displayName || '',
      biografiaDocente: '', fotoDocenteUrl: '', materialApoioUrl: ''
    });
    setEditingCourse(null);
  };

  const openEditModal = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      nome: course.nome, descricao: course.descricao || '', tema: course.tema || '',
      categoria: course.categoria, nivelDificuldade: course.nivelDificuldade,
      capaUrl: course.capaUrl, status: course.status, professorResponsavel: course.professorResponsavel,
      biografiaDocente: course.biografiaDocente || '', fotoDocenteUrl: course.fotoDocenteUrl || '',
      materialApoioUrl: course.materialApoioUrl || ''
    });
    setIsModalOpen(true);
  };

  if (activeSubView !== 'cursos') {
    return <SchoolManagement user={user} courses={myCourses} activeSub={activeSubView} />;
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Portal do Professor</h1>
          <p className="text-slate-500 text-sm">Gerencie seu conteúdo acadêmico e turmas.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsModalOpen(true); }}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all"
        >
          <Plus size={18} />
          Novo Curso
        </button>
      </header>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px]">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="Pesquisar..." className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-lg text-xs outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
        </div>

        {loading ? (
          <div className="p-20 text-center"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto"></div></div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 p-4">
            {myCourses.map(course => (
              <div key={course.id} onClick={() => openEditModal(course)} className="border border-slate-100 p-4 rounded-xl hover:shadow-md transition-all cursor-pointer bg-slate-50/50 group relative">
                <div className="flex justify-between items-start mb-3">
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>{course.status}</span>
                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => { e.stopPropagation(); openEditModal(course); }} className="p-1.5 bg-white rounded-lg text-indigo-600 shadow-sm"><Pencil size={14}/></button>
                    <button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="p-1.5 bg-white rounded-lg text-red-600 shadow-sm"><Trash2 size={14}/></button>
                  </div>
                </div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{course.nome}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{course.descricao || 'Sem descrição.'}</p>
                <div className="mt-4 pt-3 border-t border-slate-100 flex justify-between text-[10px] font-bold text-slate-400 uppercase">
                  <span>{course.inscritos} Alunos</span>
                  <span className="text-indigo-600">Editar Matriz</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-6 py-4 bg-slate-50 border-b flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900">{editingCourse ? 'Editar Curso' : 'Novo Curso'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
            </div>
            <div className="flex border-b bg-slate-50/50 px-6">
              {(['geral', 'docente', 'midias'] as ModalTab[]).map((tab) => (
                <button key={tab} onClick={() => setActiveTab(tab)} className={`px-4 py-3 text-[10px] font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>{tab}</button>
              ))}
            </div>
            <form onSubmit={handleSaveCourse} className="p-6 space-y-4 max-h-[60vh] overflow-y-auto text-sm">
              {activeTab === 'geral' && (
                <div className="space-y-4">
                  <input required value={formData.nome} onChange={(e) => setFormData({...formData, nome: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" placeholder="Nome do Curso" />
                  <textarea rows={3} value={formData.descricao} onChange={(e) => setFormData({...formData, descricao: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none resize-none" placeholder="Descrição curta..."></textarea>
                  <div className="grid grid-cols-2 gap-4">
                    <select value={formData.categoria} onChange={(e) => setFormData({...formData, categoria: e.target.value})} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-xs font-bold uppercase">
                      <option value="Básico">Teologia Básica</option>
                      <option value="Doutrina">Doutrina Cristã</option>
                      <option value="História">História da Igreja</option>
                    </select>
                    <select value={formData.nivelDificuldade} onChange={(e) => setFormData({...formData, nivelDificuldade: e.target.value as any})} className="px-4 py-3 bg-slate-50 border rounded-2xl outline-none text-xs font-bold uppercase">
                      <option value="Iniciante">Iniciante</option>
                      <option value="Intermediário">Intermediário</option>
                      <option value="Avançado">Avançado</option>
                    </select>
                  </div>
                </div>
              )}
              {activeTab === 'docente' && (
                <div className="space-y-4">
                  <input value={formData.professorResponsavel} onChange={(e) => setFormData({...formData, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" placeholder="Nome do Professor" />
                  <textarea rows={4} value={formData.biografiaDocente} onChange={(e) => setFormData({...formData, biografiaDocente: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none resize-none" placeholder="Breve currículo do docente..."></textarea>
                </div>
              )}
              {activeTab === 'midias' && (
                <div className="space-y-4">
                  <input type="url" value={formData.capaUrl} onChange={(e) => setFormData({...formData, capaUrl: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none" placeholder="URL da Imagem de Capa" />
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl outline-none font-bold uppercase">
                    <option value="rascunho">Rascunho</option>
                    <option value="ativo">Publicado</option>
                  </select>
                </div>
              )}
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg shadow-indigo-100">Salvar Alterações</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

