interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');
  const [materialCourseId, setMaterialCourseId] = useState(courses[0]?.id || '');

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    // Snapshot de Materiais para o seletor de aulas
    const qMat = query(collection(db, 'materials'), where('courseId', '==', selectedCourseForModules));
    unsubscribes.push(onSnapshot(qMat, (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'avaliacao') {
      unsubscribes.push(onSnapshot(query(collection(db, 'exams'), orderBy('createdAt', 'desc')), (snap) => {
        setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia'].includes(activeSub)) {
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchStudents();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules]);

  // Handlers
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!confirm('Excluir este módulo e todas as aulas?')) return;
    await deleteDoc(doc(db, 'modulos', moduleId));
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc,
      materialUrl: finalMaterialUrl, order: (mod.lessons?.length || 0) + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...(mod.lessons || []), newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); setSelectedMaterialId(''); setIsLessonModalOpen(false);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl) return;
    await addDoc(collection(db, 'materials'), {
      title: materialTitle, url: materialUrl, type: materialType,
      courseId: materialCourseId, createdAt: serverTimestamp()
    });
    setMaterialTitle(''); setMaterialUrl(''); setIsMaterialModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return <div className="p-20 text-center"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div><p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sincronizando...</p></div>;

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MÓDULOS */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <Header title="Gestão de Conteúdo" desc="Organize aulas em módulos e prepare seus vídeos." />
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-white border rounded-xl px-4 py-2 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>
          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm">
                <div className="bg-slate-50 px-6 py-4 border-b flex items-center justify-between">
                  <h3 className="font-black text-slate-800 text-xs uppercase flex items-center gap-2"><Layers size={14} className="text-indigo-600"/>{mod.title}</h3>
                  <div className="flex gap-2">
                    <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg">+ Lição</button>
                    <button onClick={() => handleDeleteModule(mod.id)} className="text-slate-300 hover:text-red-500 p-1"><Trash2 size={16}/></button>
                  </div>
                </div>
                <div className="p-4 space-y-3">
                  {(mod.lessons || []).map(lesson => (
                    <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-2xl flex gap-4 items-center group">
                      <div className="w-40 h-24 bg-slate-900 rounded-lg overflow-hidden shrink-0 shadow-inner">
                         {lesson.videoUrl && <iframe className="w-full h-full opacity-80" src={lesson.videoUrl.includes('youtube.com') ? lesson.videoUrl.replace('watch?v=', 'embed/') : lesson.videoUrl} frameBorder="0"></iframe>}
                      </div>
                      <div className="flex-1">
                        <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">{lesson.title} {lesson.materialUrl && <FileText size={12} className="text-emerald-500"/>}</h4>
                        <p className="text-[10px] text-slate-500 line-clamp-2 mt-1">{lesson.description}</p>
                      </div>
                      <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Acervo Digital" desc="Documentos de apoio para download." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 shadow-lg shadow-indigo-100"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-3xl relative group shadow-sm hover:border-indigo-200 transition-all">
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center mb-4 bg-indigo-50 text-indigo-600"><FileText size={24} /></div>
                <h4 className="font-bold text-slate-900 text-sm line-clamp-1">{m.title}</h4>
                <p className="text-[10px] text-slate-400 uppercase font-black mb-4 tracking-widest">{m.type}</p>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full block text-center py-2.5 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-slate-800 transition-all">Ver Documento</a>
                <button onClick={async () => { if(confirm('Remover material?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={16}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <Header title="Provas e Atividades" desc="Gerencie as avaliações dos cursos." />
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex justify-between items-center group shadow-sm">
                <div className="flex items-center gap-4">
                  <div className="p-3 rounded-2xl bg-amber-50 text-amber-600"><CheckSquare size={20}/></div>
                  <div>
                    <h4 className="font-bold text-slate-900">{ex.title}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">{ex.questions.length} Questões</p>
                  </div>
                </div>
                <button className="p-2 text-slate-300 hover:text-indigo-600"><ChevronRight size={20}/></button>
              </div>
            ))}
            <button className="border-2 border-dashed border-slate-200 p-8 rounded-3xl text-slate-400 font-bold text-sm flex flex-col items-center justify-center gap-2 hover:bg-slate-50 transition-all">
              <Plus size={32} />
              <span>Criar Novo Exame</span>
            </button>
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-6">
           <Header title="Análise de Satisfação" desc="Comentários e notas dos alunos." />
           <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div className="bg-slate-900 p-6 rounded-3xl text-white">
                <h2 className="text-4xl font-black">{feedbackStats.avg}</h2>
                <p className="text-[10px] text-indigo-400 uppercase font-black">Média NPS</p>
              </div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                <div><h2 className="text-2xl font-black text-slate-900">{feedbackStats.elogios}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Elogios</p></div>
                <Smile className="text-emerald-500" />
              </div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                <div><h2 className="text-2xl font-black text-slate-900">{feedbackStats.sugestoes}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Sugestões</p></div>
                <Lightbulb className="text-indigo-500" />
              </div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                <div><h2 className="text-2xl font-black text-slate-900">{feedbackStats.alertas}</h2><p className="text-[10px] text-slate-400 uppercase font-bold">Alertas</p></div>
                <Frown className="text-rose-500" />
              </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {feedbacks.map(f => (
                <div key={f.id} className="p-6 bg-white border border-slate-100 rounded-3xl shadow-sm">
                  <p className="text-sm text-slate-600 italic">"{f.comment}"</p>
                  <div className="mt-4 flex items-center gap-2">
                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center font-bold text-[10px]">{f.userName?.charAt(0)}</div>
                    <span className="text-xs font-bold text-slate-900">{f.userName}</span>
                  </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* 5. TABELAS (DIÁRIO / RELATÓRIO / FREQUÊNCIA) */}
      {['diario', 'relatorio', 'frequencia'].includes(activeSub) && (
        <div className="space-y-6">
          <Header 
            title={activeSub === 'diario' ? 'Diário de Classe' : activeSub === 'relatorio' ? 'Relatório Pedagógico' : 'Controle de Frequência'} 
            desc="Listagem detalhada dos estudantes matriculados." 
          />
          <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                <tr>
                  <th className="px-8 py-5">Estudante</th>
                  <th className="px-8 py-5">Matrícula</th>
                  <th className="px-8 py-5">Desempenho</th>
                  <th className="px-8 py-5 text-right">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-8 py-5 flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-black text-xs">{s.displayName.charAt(0)}</div>
                      <span className="font-bold text-slate-900 text-sm">{s.displayName}</span>
                    </td>
                    <td className="px-8 py-5 text-xs font-mono text-slate-400">ID-{s.uid.substring(0,6).toUpperCase()}</td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-3">
                        <div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-indigo-600 rounded-full w-[70%]" />
                        </div>
                        <span className="text-[10px] font-black text-slate-500">70%</span>
                      </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-full text-[9px] font-black uppercase">Regular</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 6. LIVE */}
      {activeSub === 'live' && (
        <div className="space-y-6">
          <Header title="Transmissão ao Vivo" desc="Realize aulas síncronas agora." />
          <div className="p-24 bg-white border-2 border-dashed border-slate-200 rounded-[3rem] flex flex-col items-center text-center">
            <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6">
              <Radio size={40} className="text-indigo-600 animate-pulse" />
            </div>
            <h3 className="font-black text-slate-900 text-xl mb-3 uppercase">Iniciar Nova Sala Virtual</h3>
            <p className="text-sm text-slate-500 max-w-sm mb-8">Conecte-se com seus alunos em tempo real via streaming.</p>
            <button className="bg-slate-900 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest">Configurar Transmissão</button>
          </div>
        </div>
      )}

      {/* MODAIS (MANTIDOS) */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
              <h3 className="text-lg font-black text-slate-900 mb-6 uppercase tracking-tight">Criar Módulo</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl mb-8 outline-none focus:ring-2 focus:ring-indigo-600 font-medium" />
              <div className="flex gap-3">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveModule} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg shadow-indigo-100">Criar</button>
              </div>
           </div>
        </div>
      )}

      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 space-y-5 shadow-2xl animate-in zoom-in-95 duration-200 overflow-y-auto max-h-[90vh]">
              <h3 className="text-xl font-black text-slate-900 uppercase">Configurar Aula</h3>
              <div className="space-y-4">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Aula" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="Link do Vídeo" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
                <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-xs font-bold uppercase">
                  <option value="">Anexar do Acervo...</option>
                  {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                </select>
                <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou link manual de apoio" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-sm" />
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição..." className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none h-24 resize-none text-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">Salvar Aula</button>
              </div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 space-y-5 shadow-2xl animate-in zoom-in-95 duration-200">
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Novo Material</h3>
              <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do arquivo" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-sm" />
              <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="Link do Drive/PDF" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-sm" />
              <div className="grid grid-cols-2 gap-4">
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-[10px] font-black uppercase">
                  <option value="pdf">PDF</option><option value="link">Site</option><option value="drive">Drive</option>
                </select>
                <select value={materialCourseId} onChange={e => setMaterialCourseId(e.target.value)} className="px-5 py-4 bg-slate-50 border rounded-2xl outline-none text-[10px] font-black uppercase">
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">Cadastrar</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Enrollment, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  Link as LinkIcon,
  ExternalLink,
  BookOpen,
  TrendingUp,
  Users,
  Award,
  MoreVertical,
  Edit3,
  Search
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string; // Prop opcional para quando vem de "Editar Matriz"
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');
  const [materialCourseId, setMaterialCourseId] = useState(courses[0]?.id || '');

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const qMat = query(collection(db, 'materials'), where('courseId', '==', selectedCourseForModules));
    unsubscribes.push(onSnapshot(qMat, (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'avaliacao') {
      const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
      unsubscribes.push(onSnapshot(qEx, (snap) => {
        setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia'].includes(activeSub)) {
      const fetchStudents = async () => {
        const q = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snap = await getDocs(q);
        setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchStudents();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules, user.uid]);

  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle) return;
    await addDoc(collection(db, 'exams'), {
      title: examTitle,
      courseId: selectedCourseForModules,
      type: examType,
      passingGrade: passingGrade,
      questions: [],
      authorId: user.uid,
      createdAt: serverTimestamp()
    });
    setExamTitle(''); setIsExamModalOpen(false);
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!confirm('Excluir este módulo e todas as aulas?')) return;
    await deleteDoc(doc(db, 'modulos', moduleId));
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc,
      materialUrl: finalMaterialUrl, order: (mod.lessons?.length || 0) + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...(mod.lessons || []), newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); setSelectedMaterialId(''); setIsLessonModalOpen(false);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl) return;
    await addDoc(collection(db, 'materials'), {
      title: materialTitle, url: materialUrl, type: materialType,
      courseId: materialCourseId, createdAt: serverTimestamp()
    });
    setMaterialTitle(''); setMaterialUrl(''); setIsMaterialModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return (
    <div className="p-20 text-center">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Organizando Estrutura...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MÓDULOS (MATRIZ CURRICULAR) */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Matriz Curricular</h2>
              <p className="text-xs text-slate-500 font-medium">Defina a jornada de aprendizado para o curso selecionado.</p>
            </div>
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)} 
                className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[2.5rem] overflow-hidden transition-all hover:border-indigo-100">
                <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm">
                      <Layers size={18} />
                    </div>
                    <div>
                      <h3 className="font-black text-slate-800 text-xs uppercase tracking-wider">{mod.title}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Lições Disponíveis</p>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-4 py-2 rounded-xl shadow-md shadow-indigo-100 hover:scale-105 transition-all">Adicionar Aula</button>
                    <button onClick={() => handleDeleteModule(mod.id)} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                  </div>
                </div>
                <div className="p-6 grid grid-cols-1 gap-3">
                  {(mod.lessons || []).map((lesson, idx) => (
                    <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-3xl flex gap-5 items-center group border border-transparent hover:border-indigo-100 hover:bg-white transition-all">
                      <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover:text-indigo-600 transition-colors">
                        {idx + 1}
                      </div>
                      <div className="flex-1">
                        <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">
                          {lesson.title} 
                          {lesson.materialUrl && <FileText size={12} className="text-emerald-500" title="Material de Apoio Incluso" />}
                        </h4>
                        <div className="flex items-center gap-3 mt-1">
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">ID: {lesson.id}</span>
                          {lesson.videoUrl && <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter flex items-center gap-1"><Radio size={10}/> Vídeo Ativo</span>}
                        </div>
                      </div>
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button className="p-2 text-slate-400 hover:text-indigo-600"><Edit3 size={16}/></button>
                        <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                      </div>
                    </div>
                  ))}
                  {(!mod.lessons || mod.lessons.length === 0) && (
                    <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-3xl">
                      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Nenhuma lição vinculada a este módulo.</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Acervo Digital" desc="Documentos de apoio para download e estudo." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] relative group shadow-sm hover:border-indigo-300 hover:shadow-xl hover:shadow-indigo-50 transition-all">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-5 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}>
                  <FileText size={28} />
                </div>
                <h4 className="font-black text-slate-900 text-sm leading-tight mb-2">{m.title}</h4>
                <div className="flex items-center gap-2 mb-6">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-2 py-1 bg-slate-50 rounded-lg">{m.type}</span>
                </div>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all">
                  <ExternalLink size={14}/> Acessar Arquivo
                </a>
                <button onClick={async () => { if(confirm('Remover material?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO (REDESIGN COMPLETO) */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200">
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Provas & Atividades</h2>
              <p className="text-xs text-slate-500 font-medium">Crie avaliações complexas para testar o conhecimento.</p>
            </div>
            <button onClick={() => setIsExamModalOpen(true)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-600 transition-all">
              <Plus size={18} /> Novo Exame
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-3xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}>
                    <Award size={24} />
                  </div>
                  <div className="text-right">
                    <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">Passagem</span>
                    <span className="text-xl font-black text-slate-900">{ex.passingGrade}%</span>
                  </div>
                </div>
                <h4 className="font-black text-slate-900 text-lg mb-2">{ex.title}</h4>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-6">{ex.questions?.length || 0} Questões Cadastradas</p>

                <div className="flex gap-3">
                  <button className="flex-1 py-3 bg-slate-50 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-50 hover:text-indigo-600 transition-all">Configurar Perguntas</button>
                  <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-3 bg-slate-50 text-slate-300 rounded-xl hover:text-red-500"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK (RESTAURAÇÃO DO VISUAL PREMIUM) */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <Header title="Mural de Feedback" desc="Sua reputação acadêmica e impressões dos alunos." />

           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-200 relative overflow-hidden">
                <div className="relative z-10">
                  <h2 className="text-5xl font-black mb-1">{feedbackStats.avg}</h2>
                  <p className="text-[10px] text-indigo-100 uppercase font-black tracking-[0.2em]">NPS Acadêmico</p>
                </div>
                <Target size={120} className="absolute -bottom-6 -right-6 text-white/10 rotate-12" />
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Elogios</span>
                  <Smile className="text-emerald-500" />
                </div>
                <h3 className="text-3xl font-black text-slate-900">{feedbackStats.elogios}</h3>
                <div className="w-full h-1 bg-emerald-50 rounded-full mt-4 overflow-hidden"><div className="h-full bg-emerald-500 w-full" /></div>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sugestões</span>
                  <Lightbulb className="text-indigo-500" />
                </div>
                <h3 className="text-3xl font-black text-slate-900">{feedbackStats.sugestoes}</h3>
                <div className="w-full h-1 bg-indigo-50 rounded-full mt-4 overflow-hidden"><div className="h-full bg-indigo-500 w-full" /></div>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Alertas</span>
                  <Frown className="text-rose-500" />
                </div>
                <h3 className="text-3xl font-black text-slate-900">{feedbackStats.alertas}</h3>
                <div className="w-full h-1 bg-rose-50 rounded-full mt-4 overflow-hidden"><div className="h-full bg-rose-500 w-full" /></div>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] shadow-sm flex flex-col justify-between hover:shadow-xl transition-all border-l-4 border-l-indigo-600">
                  <div className="flex text-amber-400 mb-6"><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/></div>
                  <p className="text-sm text-slate-600 italic font-medium leading-relaxed">"{f.comment}"</p>
                  <div className="mt-8 flex items-center gap-4 border-t pt-6">
                    <div className="w-10 h-10 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-[10px] text-slate-400 uppercase">{f.userName?.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{f.userName}</p>
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Aluno Verificado</p>
                    </div>
                  </div>
                </div>
              ))}
              {feedbacks.length === 0 && (
                <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
                   <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">Sem feedbacks registrados no momento.</p>
                </div>
              )}
           </div>
        </div>
      )}

      {/* 5. TABELAS - DIÁRIO / FREQUÊNCIA / RELATÓRIO */}
      {['diario', 'relatorio', 'frequencia'].includes(activeSub) && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-200">
            <Header 
              title={activeSub === 'diario' ? 'Diário Digital' : activeSub === 'relatorio' ? 'Relatório Pedagógico' : 'Gestão de Frequência'} 
              desc="Controle total sobre a evolução dos discentes em tempo real." 
            />
            <div className="flex gap-2">
              <div className="bg-slate-900 text-white px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><Users size={16}/> {allStudents.length} Alunos</div>
            </div>
          </div>
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-2xl shadow-slate-200/50">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                <tr>
                  <th className="px-10 py-6">Estudante</th>
                  <th className="px-10 py-6">ID Matrícula</th>
                  <th className="px-10 py-6">Média Progresso</th>
                  <th className="px-10 py-6 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-10 py-6 flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">{s.displayName.charAt(0)}</div>
                      <span className="font-black text-slate-900 text-sm tracking-tighter uppercase">{s.displayName}</span>
                    </td>
                    <td className="px-10 py-6 text-xs font-mono text-slate-400 uppercase tracking-widest">{s.uid.substring(0,8)}</td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-40 h-2 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-indigo-600 rounded-full w-[85%]" />
                        </div>
                        <span className="text-[10px] font-black text-slate-900">85%</span>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-right">
                      <button className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 hover:border-indigo-100 shadow-sm transition-all"><ChevronRight size={18}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 6. LIVE */}
      {activeSub === 'live' && (
        <div className="space-y-6">
          <Header title="Sala de Transmissão" desc="Inicie sua aula ao vivo para toda a comunidade escolar." />
          <div className="p-32 bg-white border-2 border-dashed border-slate-200 rounded-[4rem] flex flex-col items-center text-center group hover:border-indigo-400 transition-all">
            <div className="w-24 h-24 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mb-8 group-hover:scale-110 transition-transform">
              <Radio size={48} className="text-indigo-600 animate-pulse" />
            </div>
            <h3 className="font-black text-slate-900 text-2xl mb-4 uppercase tracking-tighter">Preparado para entrar ao vivo?</h3>
            <p className="text-sm text-slate-500 max-w-sm mb-10 font-medium">Conecte sua câmera e microfone. Seus alunos receberão uma notificação instantânea assim que você começar.</p>
            <button className="bg-slate-900 text-white px-12 py-5 rounded-[2rem] text-xs font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all hover:bg-indigo-600">Abrir Estúdio Digital</button>
          </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 duration-200">
              <h3 className="text-xl font-black text-slate-900 mb-8 uppercase tracking-tighter">Novo Módulo Acadêmico</h3>
              <div className="space-y-6">
                <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Ex: Teologia do Antigo Testamento" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold text-sm" />
                <div className="flex gap-4">
                  <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                  <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Criar Módulo</button>
                </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL EXAMES */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 duration-200">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Configurar Exame</h3>
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Título do Exame</label>
                  <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Ex: Prova Final de Hermenêutica" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold text-sm" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Tipo</label>
                    <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="activity">Atividade Livre</option>
                      <option value="evaluation">Prova Avaliativa</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Nota de Corte (%)</label>
                    <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-black text-sm" />
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100">Criar Base da Prova</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 duration-200 overflow-y-auto max-h-[90vh]">
              <div className="text-center">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Configurar Nova Aula</h3>
                <p className="text-xs text-slate-400 font-medium">Aulas dinâmicas geram maior engajamento.</p>
              </div>

              <div className="space-y-5">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título Impactante da Lição" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold text-sm" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo (YouTube / Vimeo / Drive)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold text-sm" />

                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 block">Vincular Material de Apoio</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-3">
                    <option value="">Buscar no Acervo Pedagógico...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                  <div className="relative">
                    <LinkIcon size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou cole um link direto" className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold disabled:opacity-50" />
                  </div>
                </div>

                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="O que o aluno aprenderá nesta lição?" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none h-32 resize-none font-medium text-sm"></textarea>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Salvar Aula na Matriz</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 duration-200">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Novo Item no Acervo</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Nome do Documento / Apostila" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold text-sm" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo no Google Drive ou PDF" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold text-sm" />
                <div className="grid grid-cols-2 gap-4">
                  <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                    <option value="pdf">Arquivo PDF</option>
                    <option value="link">Link Externo</option>
                    <option value="drive">Google Drive</option>
                  </select>
                  <select value={materialCourseId} onChange={e => setMaterialCourseId(e.target.value)} className="px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Voltar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all">Cadastrar no Acervo</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  doc, 
  serverTimestamp,
  getDocs,
  writeBatch
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, User, ProfessorSubView } from '../types';
import { 
  Search, 
  BookOpen, 
  Plus, 
  X, 
  Trash2,
  Pencil,
  LayoutGrid
} from 'lucide-react';
import SchoolManagement from '../SchoolManagement';

interface ProfessorViewProps {
  user: User;
  activeSubView?: ProfessorSubView;
}

type ModalTab = 'geral' | 'docente' | 'midias';

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSubView = 'cursos' }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [activeTab, setActiveTab] = useState<ModalTab>('geral');
  const [internalSubView, setInternalSubView] = useState<ProfessorSubView>(activeSubView);
  const [selectedMatrizId, setSelectedMatrizId] = useState<string | undefined>(undefined);

  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tema: '',
    categoria: '',
    nivelDificuldade: 'Iniciante' as Course['nivelDificuldade'],
    capaUrl: '',
    status: 'rascunho' as Course['status'],
    professorResponsavel: user.displayName || '',
    biografiaDocente: '',
    fotoDocenteUrl: '',
    materialApoioUrl: ''
  });

  useEffect(() => {
    setInternalSubView(activeSubView);
  }, [activeSubView]);

  useEffect(() => {
    const q = query(
      collection(db, 'cursos'), 
      where('professorId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user.uid]);

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm('ATENÇÃO: Deletar este curso removerá permanentemente todos os módulos e lições associados. Confirmar?')) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      const q = query(collection(db, 'modulos'), where('courseId', '==', courseId));
      const modSnap = await getDocs(q);
      const batch = writeBatch(db);
      modSnap.forEach((mDoc) => batch.delete(mDoc.ref));
      await batch.commit();
    } catch (error) { console.error(error); }
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coursePayload = {
        ...formData,
        professorId: user.uid,
        inscritos: editingCourse ? editingCourse.inscritos : 0,
        createdAt: editingCourse ? editingCourse.createdAt : serverTimestamp(),
      };
      if (editingCourse) {
        await updateDoc(doc(db, 'cursos', editingCourse.id), coursePayload);
      } else {
        await addDoc(collection(db, 'cursos'), coursePayload);
      }
      setIsModalOpen(false);
      resetForm();
    } catch (error) { console.error(error); }
  };

  const resetForm = () => {
    setFormData({
      nome: '', descricao: '', tema: '', categoria: '', nivelDificuldade: 'Iniciante',
      capaUrl: '', status: 'rascunho', professorResponsavel: user.displayName || '',
      biografiaDocente: '', fotoDocenteUrl: '', materialApoioUrl: ''
    });
    setEditingCourse(null);
  };

  const openEditModal = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      nome: course.nome, descricao: course.descricao || '', tema: course.tema || '',
      categoria: course.categoria, nivelDificuldade: course.nivelDificuldade,
      capaUrl: course.capaUrl, status: course.status, professorResponsavel: course.professorResponsavel,
      biografiaDocente: course.biografiaDocente || '', fotoDocenteUrl: course.fotoDocenteUrl || '',
      materialApoioUrl: course.materialApoioUrl || ''
    });
    setIsModalOpen(true);
  };

  const navigateToMatriz = (courseId: string) => {
    setSelectedMatrizId(courseId);
    setInternalSubView('modulos');
  };

  if (internalSubView !== 'cursos') {
    return (
      <SchoolManagement 
        user={user} 
        courses={myCourses} 
        activeSub={internalSubView} 
        selectedCourseId={selectedMatrizId} 
      />
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Meus Cursos</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão de catálogo acadêmico e publicações.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsModalOpen(true); }}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-[0.15em] hover:bg-indigo-700 shadow-2xl shadow-indigo-100 transition-all active:scale-95"
        >
          <Plus size={18} strokeWidth={3} />
          Criar Nova Disciplina
        </button>
      </header>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm min-h-[500px] overflow-hidden">
        <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="Localizar curso..." className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
          </div>
        </div>

        {loading ? (
          <div className="p-32 text-center flex flex-col items-center gap-4">
            <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sincronizando Banco de Dados...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 p-8">
            {myCourses.map(course => (
              <div key={course.id} className="group relative flex flex-col bg-slate-50/30 border border-slate-100 rounded-[2.5rem] hover:bg-white hover:shadow-2xl hover:border-indigo-100 transition-all duration-300 p-6">
                <div className="flex justify-between items-start mb-6">
                  <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>
                    {course.status}
                  </div>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => openEditModal(course)} className="p-2.5 bg-white border border-slate-100 rounded-xl text-indigo-600 shadow-sm hover:scale-110 transition-all"><Pencil size={14}/></button>
                    <button onClick={() => handleDeleteCourse(course.id)} className="p-2.5 bg-white border border-slate-100 rounded-xl text-red-600 shadow-sm hover:scale-110 transition-all"><Trash2 size={14}/></button>
                  </div>
                </div>

                <div className="mb-8">
                  <h3 className="font-black text-slate-900 text-lg leading-tight uppercase tracking-tighter mb-2 group-hover:text-indigo-600 transition-colors">{course.nome}</h3>
                  <p className="text-xs text-slate-500 font-medium line-clamp-2 leading-relaxed">{course.descricao || 'Nenhuma descrição detalhada disponível para este curso.'}</p>
                </div>

                <div className="mt-auto space-y-4">
                  <div className="flex items-center justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest bg-white/50 p-4 rounded-2xl border border-slate-100">
                    <div className="flex items-center gap-2">
                       <LayoutGrid size={14} className="text-indigo-400" />
                       {course.inscritos} Alunos
                    </div>
                    <span className="text-indigo-600">{course.categoria}</span>
                  </div>

                  <button 
                    onClick={() => navigateToMatriz(course.id)}
                    className="w-full py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.15em] hover:bg-indigo-600 transition-all group-hover:shadow-xl group-hover:shadow-indigo-100"
                  >
                    Editar Matriz Curricular
                  </button>
                </div>
              </div>
            ))}
            {myCourses.length === 0 && (
              <div className="col-span-full py-20 text-center border-2 border-dashed border-slate-100 rounded-[3rem]">
                 <BookOpen size={48} className="mx-auto text-slate-200 mb-4" />
                 <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">Nenhum curso cadastrado no momento.</p>
              </div>
            )}
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-8 py-6 bg-slate-50 border-b flex items-center justify-between">
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">{editingCourse ? 'Configurações do Curso' : 'Novo Curso Acadêmico'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
            </div>
            <div className="flex border-b bg-slate-50/50 px-8">
              {(['geral', 'docente', 'midias'] as ModalTab[]).map((tab) => (
                <button 
                  key={tab} 
                  onClick={() => setActiveTab(tab)} 
                  className={`px-6 py-4 text-[10px] font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}
                >
                  {tab}
                </button>
              ))}
            </div>
            <form onSubmit={handleSaveCourse} className="p-8 space-y-6 max-h-[60vh] overflow-y-auto">
              {activeTab === 'geral' && (
                <div className="space-y-6">
                  <input required value={formData.nome} onChange={(e) => setFormData({...formData, nome: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Nome da Disciplina" />
                  <textarea rows={3} value={formData.descricao} onChange={(e) => setFormData({...formData, descricao: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 resize-none font-medium" placeholder="Objetivos pedagógicos..."></textarea>
                  <div className="grid grid-cols-2 gap-4">
                    <select value={formData.categoria} onChange={(e) => setFormData({...formData, categoria: e.target.value})} className="px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="Básico">Teologia Básica</option>
                      <option value="Doutrina">Doutrina Cristã</option>
                      <option value="História">História da Igreja</option>
                    </select>
                    <select value={formData.nivelDificuldade} onChange={(e) => setFormData({...formData, nivelDificuldade: e.target.value as any})} className="px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="Iniciante">Iniciante</option>
                      <option value="Intermediário">Intermediário</option>
                      <option value="Avançado">Avançado</option>
                    </select>
                  </div>
                </div>
              )}
              {activeTab === 'docente' && (
                <div className="space-y-6">
                  <input value={formData.professorResponsavel} onChange={(e) => setFormData({...formData, professorResponsavel: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="Nome do Titular" />
                  <textarea rows={4} value={formData.biografiaDocente} onChange={(e) => setFormData({...formData, biografiaDocente: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 resize-none font-medium" placeholder="Currículo acadêmico do professor..."></textarea>
                </div>
              )}
              {activeTab === 'midias' && (
                <div className="space-y-6">
                  <input type="url" value={formData.capaUrl} onChange={(e) => setFormData({...formData, capaUrl: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" placeholder="URL da Capa do Curso" />
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none font-black uppercase text-[10px]">
                    <option value="rascunho">Modo Rascunho</option>
                    <option value="ativo">Publicar Curso</option>
                  </select>
                </div>
              )}
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100">Confirmar Dados</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string;
  role: UserRole;
  photoURL?: string;
}

export interface Lesson {
  id: string;
  title: string;
  description?: string;
  videoUrl: string;
  materialUrl?: string;
  order: number;
}

export interface Module {
  id: string;
  courseId: string;
  title: string;
  order: number;
  lessons: Lesson[];
}

export interface Course {
  id: string;
  nome: string;
  descricao?: string;
  tema: string;
  categoria: string;
  nivelDificuldade: 'Iniciante' | 'Intermediário' | 'Avançado';
  professorResponsavel: string;
  professorId: string;
  capaUrl: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
  biografiaDocente?: string;
  fotoDocenteUrl?: string;
  materialApoioUrl?: string;
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

export interface Exam {
  id: string;
  title: string;
  courseId: string;
  moduleId: string; // Novo campo obrigatório para vínculo
  type: 'activity' | 'evaluation';
  passingGrade: number;
  questions: Question[];
  createdAt: any;
  authorId?: string;
  updatedAt?: any;
}

export interface ExamResult {
  id?: string;
  userId: string;
  examId: string;
  score: number;
  passed: boolean;
  attempt: number;
  completedAt: any;
  userRole?: string;
  userName?: string;
}

export interface Enrollment {
  id: string;
  userId: string;
  courseId: string;
  progress: number;
  enrolledAt: any;
}

export interface Material {
  id: string;
  courseId: string;
  lessonId?: string; 
  title: string;
  type: 'pdf' | 'video' | 'link' | 'drive';
  url: string;
  createdAt: any;
}

export interface Feedback {
  id: string;
  userId: string;
  courseId: string;
  rating: number;
  comment: string;
  category: 'aula' | 'plataforma' | 'docente';
  type: 'elogio' | 'sugestao' | 'reclamacao';
  createdAt: any;
  userName?: string;
}

export interface LiveSession {
  id: string;
  title: string;
  date: any;
  link: string;
  status: 'scheduled' | 'live' | 'ended';
  courseId?: string;
}

export interface CompletedLesson {
  id: string;
  userId: string;
  courseId: string;
  lessonId: string;
  completedAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  Link as LinkIcon,
  ExternalLink,
  Users,
  Award,
  Edit3,
  BookOpen
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    // Snapshot global de exames para carregar perguntas e vínculos
    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia', 'avaliacao'].includes(activeSub)) {
      const fetchExtra = async () => {
        const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapS = await getDocs(qS);
        setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchExtra();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules, user.uid]);

  // Handlers
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam) {
      alert("Por favor, preencha o título e selecione um módulo para a prova.");
      return;
    }
    await addDoc(collection(db, 'exams'), {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      questions: [],
      authorId: user.uid,
      createdAt: serverTimestamp()
    });
    setExamTitle(''); setSelectedModuleForExam(''); setIsExamModalOpen(false);
  };

  const handleAddQuestion = async () => {
    if (!currentExam || !qText || qOptions.some(o => !o)) return;
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: qText,
      options: qOptions,
      correctOptionIndex: qCorrect
    };
    const updatedQuestions = [...(currentExam.questions || []), newQuestion];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: updatedQuestions });
    setQText(''); setQOptions(['', '', '', '']); setQCorrect(0);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc,
      materialUrl: finalMaterialUrl, order: (mod.lessons?.length || 0) + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...(mod.lessons || []), newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); setSelectedMaterialId(''); setIsLessonModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return (
    <div className="p-20 text-center">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Carregando Matriz Acadêmica...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MATRIZ CURRICULAR (MÓDULOS + EXAMES INJETADOS) */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Matriz Curricular</h2>
              <p className="text-xs text-slate-500 font-medium">Módulos, aulas e avaliações finais de cada etapa.</p>
            </div>
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)} 
                className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[2.5rem] overflow-hidden transition-all hover:border-indigo-100">
                  <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm">
                        <Layers size={18} />
                      </div>
                      <div>
                        <h3 className="font-black text-slate-800 text-xs uppercase tracking-wider">{mod.title}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Aulas + {moduleExams.length} Provas</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-4 py-2 rounded-xl shadow-md shadow-indigo-100 hover:scale-105 transition-all">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir este módulo e todo o seu conteúdo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-6 grid grid-cols-1 gap-3">
                    {/* Aulas do Módulo */}
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-3xl flex gap-5 items-center group border border-transparent hover:border-indigo-100 hover:bg-white transition-all">
                        <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover:text-indigo-600 transition-colors">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">{lesson.title} {lesson.materialUrl && <FileText size={12} className="text-emerald-500" />}</h4>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none mt-1">Aula em Vídeo</p>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}

                    {/* Exames do Módulo (Injetados no Final) */}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/50 p-5 rounded-3xl flex gap-5 items-center border border-amber-100 mt-2">
                        <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center text-amber-600"><CheckSquare size={18} /></div>
                        <div className="flex-1">
                          <h4 className="font-black text-amber-900 text-sm uppercase tracking-tighter">Avaliação Final: {ex.title}</h4>
                          <p className="text-[9px] font-black text-amber-600 uppercase tracking-widest leading-none mt-1">Checkpoint do Módulo • Corte {ex.passingGrade}%</p>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-4 py-2 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg shadow-amber-100">Editar Perguntas</button>
                      </div>
                    ))}

                    {(!mod.lessons || mod.lessons.length === 0) && (
                      <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-3xl"><p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Vazio.</p></div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Acervo Digital" desc="Documentos de apoio para download e estudo." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] relative group shadow-sm hover:border-indigo-300 transition-all">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-5 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}><FileText size={28} /></div>
                <h4 className="font-black text-slate-900 text-sm leading-tight mb-2">{m.title}</h4>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar Arquivo</a>
                <button onClick={async () => { if(confirm('Remover material?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO (GERENCIAMENTO GERAL) */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <Header title="Banco de Provas" desc="Visualize e crie exames vinculados aos módulos." />
            <button onClick={() => setIsExamModalOpen(true)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-600 transition-all"><Plus size={18} /> Criar Prova</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-3xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Award size={24} /></div>
                  <div className="text-right"><span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">Passagem</span><span className="text-xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-lg mb-2">{ex.title}</h4>
                <div className="flex items-center gap-2 mb-6">
                   <span className="text-[9px] font-black text-indigo-500 uppercase px-2 py-1 bg-indigo-50 rounded-lg">Módulo ID: {ex.moduleId.substring(0,6)}</span>
                </div>
                <div className="flex gap-3">
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-slate-200">Gerenciar {ex.questions?.length || 0} Questões</button>
                  <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-4 bg-slate-50 text-slate-300 rounded-xl hover:text-red-500 transition-colors"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <Header title="Mural de Feedback" desc="Sua reputação acadêmica e impressões dos alunos." />
           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <h2 className="text-5xl font-black mb-1">{feedbackStats.avg}</h2>
                <p className="text-[10px] text-indigo-100 uppercase font-black tracking-[0.2em]">NPS Acadêmico</p>
                <Target size={120} className="absolute -bottom-6 -right-6 text-white/10 rotate-12" />
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Smile className="text-emerald-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.elogios}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Elogios</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Lightbulb className="text-indigo-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.sugestoes}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sugestões</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Frown className="text-rose-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.alertas}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Alertas</p>
              </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] shadow-sm flex flex-col justify-between border-l-4 border-l-indigo-600 hover:shadow-xl transition-all">
                  <div className="flex text-amber-400 mb-6"><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/></div>
                  <p className="text-sm text-slate-600 italic font-medium leading-relaxed">"{f.comment}"</p>
                  <div className="mt-8 flex items-center gap-4 border-t pt-6">
                    <div className="w-10 h-10 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-[10px] text-slate-400 uppercase">{f.userName?.charAt(0)}</div>
                    <div><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{f.userName}</p><p className="text-[9px] font-bold text-slate-400 uppercase">Aluno Verificado</p></div>
                  </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* 5. TABELAS */}
      {['diario', 'relatorio', 'frequencia'].includes(activeSub) && (
        <div className="space-y-6">
          <div className="flex items-center justify-between bg-white p-8 rounded-[2.5rem] border border-slate-200">
            <Header title={activeSub === 'diario' ? 'Diário Digital' : 'Relatório Pedagógico'} desc="Listagem total de alunos." />
            <div className="bg-slate-900 text-white px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><Users size={16}/> {allStudents.length} Alunos</div>
          </div>
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-2xl shadow-slate-200/50">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                <tr><th className="px-10 py-6">Estudante</th><th className="px-10 py-6">Matrícula</th><th className="px-10 py-6">Progresso</th><th className="px-10 py-6 text-right">Ações</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-10 py-6 flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs">{s.displayName.charAt(0)}</div><span className="font-black text-slate-900 text-sm tracking-tighter uppercase">{s.displayName}</span></td>
                    <td className="px-10 py-6 text-xs font-mono text-slate-400 uppercase">{s.uid.substring(0,8)}</td>
                    <td className="px-10 py-6"><div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-indigo-600 w-[70%]" /></div></td>
                    <td className="px-10 py-6 text-right"><button className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 transition-all"><ChevronRight size={18}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 6. LIVE */}
      {activeSub === 'live' && (
        <div className="space-y-6">
          <Header title="Sala de Transmissão" desc="Inicie sua aula ao vivo para toda a comunidade escolar." />
          <div className="p-32 bg-white border-2 border-dashed border-slate-200 rounded-[4rem] flex flex-col items-center text-center group hover:border-indigo-400 transition-all">
            <div className="w-24 h-24 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mb-8 group-hover:scale-110 transition-transform"><Radio size={48} className="text-indigo-600 animate-pulse" /></div>
            <h3 className="font-black text-slate-900 text-2xl mb-4 uppercase tracking-tighter">Preparado para entrar ao vivo?</h3>
            <button className="bg-slate-900 text-white px-12 py-5 rounded-[2rem] text-xs font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all hover:bg-indigo-600">Abrir Estúdio Digital</button>
          </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-xl font-black text-slate-900 mb-8 uppercase tracking-tighter">Novo Módulo Acadêmico</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold mb-6" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Módulo</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL EXAMES (VÍNCULO OBRIGATÓRIO) */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-6 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Nova Avaliação</h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Título da Prova</label>
                  <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Ex: Prova Final" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Vincular ao Módulo</label>
                  <select value={selectedModuleForExam} onChange={e => setSelectedModuleForExam(e.target.value)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                    <option value="">Selecione o Módulo de Destino...</option>
                    {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Tipo</label>
                    <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="activity">Atividade Livre</option><option value="evaluation">Prova Avaliativa</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Nota de Corte (%)</label>
                    <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-black" />
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Base da Prova</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE PERGUNTAS (FUNCIONAL) */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-8 border-b pb-6">
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Questões: {currentExam.title}</h3>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{currentExam.questions?.length || 0} Itens Registrados</p>
                 </div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-slate-200"><X size={20}/></button>
              </div>

              <div className="space-y-6 mb-10 bg-slate-50 p-8 rounded-[2rem] border border-slate-100">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Enunciado da Questão</label>
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Qual o significado original de..." className="w-full px-5 py-4 border-none rounded-xl outline-none bg-white font-bold text-sm h-24 resize-none" />
                 </div>
                 <div className="grid grid-cols-1 gap-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Opções de Resposta</label>
                    {qOptions.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3">
                         <div onClick={() => setQCorrect(i)} className={`w-10 h-10 rounded-xl flex items-center justify-center cursor-pointer transition-all font-black text-xs ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>
                            {String.fromCharCode(65 + i)}
                         </div>
                         <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-4 py-3 bg-white border-none rounded-xl outline-none text-xs font-bold" />
                      </div>
                    ))}
                 </div>
                 <button onClick={handleAddQuestion} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all">+ Adicionar Pergunta ao Banco</button>
              </div>

              <div className="space-y-3">
                 <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Questões Salvas</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-5 bg-white border border-slate-100 rounded-2xl flex justify-between items-center group hover:border-indigo-200 transition-all">
                      <div className="flex-1">
                        <p className="text-xs font-black text-slate-900 leading-tight uppercase tracking-tighter mb-2">{idx + 1}. {q.text}</p>
                        <div className="flex gap-2">
                          <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded-lg">Correta: {String.fromCharCode(65 + q.correctOptionIndex)}</span>
                        </div>
                      </div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-2 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Configurar Nova Aula</h3>
              <div className="space-y-5">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Lição" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo (YouTube / Vimeo / Drive)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 block">Material de Apoio</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-3">
                    <option value="">Buscar no Acervo...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                  <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou cole um link direto" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold disabled:opacity-50" />
                </div>
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none h-32 resize-none font-medium text-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Salvar Aula</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Novo Item no Acervo</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Drive / PDF" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase"><option value="pdf">PDF</option><option value="link">Link Externo</option><option value="drive">Google Drive</option></select>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Voltar</button>
                <button onClick={() => { handleSaveMaterial(); setIsMaterialModalOpen(false); }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Cadastrar</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  Link as LinkIcon,
  ExternalLink,
  Users,
  Award,
  Edit3,
  BookOpen
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || courses[0]?.id || '');
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    // Snapshot global de exames para carregar perguntas e vínculos
    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (activeSub === 'modulos') {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia', 'avaliacao'].includes(activeSub)) {
      const fetchExtra = async () => {
        const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapS = await getDocs(qS);
        setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchExtra();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules, user.uid]);

  // Handlers
  const handleSaveModule = async () => {
    if (!moduleTitle) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam) {
      alert("Por favor, preencha o título e selecione um módulo para a prova.");
      return;
    }
    await addDoc(collection(db, 'exams'), {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      questions: [],
      authorId: user.uid,
      createdAt: serverTimestamp()
    });
    setExamTitle(''); setSelectedModuleForExam(''); setIsExamModalOpen(false);
  };

  const handleAddQuestion = async () => {
    if (!currentExam || !qText || qOptions.some(o => !o)) return;
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: qText,
      options: qOptions,
      correctOptionIndex: qCorrect
    };
    const updatedQuestions = [...(currentExam.questions || []), newQuestion];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: updatedQuestions });
    setQText(''); setQOptions(['', '', '', '']); setQCorrect(0);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc,
      materialUrl: finalMaterialUrl, order: (mod.lessons?.length || 0) + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...(mod.lessons || []), newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); setSelectedMaterialId(''); setIsLessonModalOpen(false);
  };

  // Fix: Added handleSaveMaterial function
  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl) return;
    try {
      await addDoc(collection(db, 'materials'), {
        courseId: selectedCourseForModules,
        title: materialTitle,
        url: materialUrl,
        type: materialType,
        createdAt: serverTimestamp()
      });
      setMaterialTitle('');
      setMaterialUrl('');
      setIsMaterialModalOpen(false);
    } catch (error) {
      console.error("Erro ao salvar material:", error);
    }
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return (
    <div className="p-20 text-center">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Carregando Matriz Acadêmica...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MATRIZ CURRICULAR (MÓDULOS + EXAMES INJETADOS) */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Matriz Curricular</h2>
              <p className="text-xs text-slate-500 font-medium">Módulos, aulas e avaliações finais de cada etapa.</p>
            </div>
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)} 
                className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[2.5rem] overflow-hidden transition-all hover:border-indigo-100">
                  <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm">
                        <Layers size={18} />
                      </div>
                      <div>
                        <h3 className="font-black text-slate-800 text-xs uppercase tracking-wider">{mod.title}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Aulas + {moduleExams.length} Provas</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-4 py-2 rounded-xl shadow-md shadow-indigo-100 hover:scale-105 transition-all">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir este módulo e todo o seu conteúdo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-6 grid grid-cols-1 gap-3">
                    {/* Aulas do Módulo */}
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-3xl flex gap-5 items-center group border border-transparent hover:border-indigo-100 hover:bg-white transition-all">
                        <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover:text-indigo-600 transition-colors">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">{lesson.title} {lesson.materialUrl && <FileText size={12} className="text-emerald-500" />}</h4>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none mt-1">Aula em Vídeo</p>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}

                    {/* Exames do Módulo (Injetados no Final) */}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/50 p-5 rounded-3xl flex gap-5 items-center border border-amber-100 mt-2">
                        <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center text-amber-600"><CheckSquare size={18} /></div>
                        <div className="flex-1">
                          <h4 className="font-black text-amber-900 text-sm uppercase tracking-tighter">Avaliação Final: {ex.title}</h4>
                          <p className="text-[9px] font-black text-amber-600 uppercase tracking-widest leading-none mt-1">Checkpoint do Módulo • Corte {ex.passingGrade}%</p>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-4 py-2 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg shadow-amber-100">Editar Perguntas</button>
                      </div>
                    ))}

                    {(!mod.lessons || mod.lessons.length === 0) && (
                      <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-3xl"><p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Vazio.</p></div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Acervo Digital" desc="Documentos de apoio para download e estudo." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] relative group shadow-sm hover:border-indigo-300 transition-all">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-5 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}><FileText size={28} /></div>
                <h4 className="font-black text-slate-900 text-sm leading-tight mb-2">{m.title}</h4>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar Arquivo</a>
                <button onClick={async () => { if(confirm('Remover material?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO (GERENCIAMENTO GERAL) */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <Header title="Banco de Provas" desc="Visualize e crie exames vinculados aos módulos." />
            <button onClick={() => setIsExamModalOpen(true)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-600 transition-all"><Plus size={18} /> Criar Prova</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-3xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Award size={24} /></div>
                  <div className="text-right"><span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">Passagem</span><span className="text-xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-lg mb-2">{ex.title}</h4>
                <div className="flex items-center gap-2 mb-6">
                   <span className="text-[9px] font-black text-indigo-500 uppercase px-2 py-1 bg-indigo-50 rounded-lg">Módulo ID: {ex.moduleId.substring(0,6)}</span>
                </div>
                <div className="flex gap-3">
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-slate-200">Gerenciar {ex.questions?.length || 0} Questões</button>
                  <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-4 bg-slate-50 text-slate-300 rounded-xl hover:text-red-500 transition-colors"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <Header title="Mural de Feedback" desc="Sua reputação acadêmica e impressões dos alunos." />
           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <h2 className="text-5xl font-black mb-1">{feedbackStats.avg}</h2>
                <p className="text-[10px] text-indigo-100 uppercase font-black tracking-[0.2em]">NPS Acadêmico</p>
                <Target size={120} className="absolute -bottom-6 -right-6 text-white/10 rotate-12" />
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Smile className="text-emerald-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.elogios}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Elogios</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Lightbulb className="text-indigo-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.sugestoes}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sugestões</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Frown className="text-rose-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.alertas}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Alertas</p>
              </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] shadow-sm flex flex-col justify-between border-l-4 border-l-indigo-600 hover:shadow-xl transition-all">
                  <div className="flex text-amber-400 mb-6"><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/></div>
                  <p className="text-sm text-slate-600 italic font-medium leading-relaxed">"{f.comment}"</p>
                  <div className="mt-8 flex items-center gap-4 border-t pt-6">
                    <div className="w-10 h-10 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-[10px] text-slate-400 uppercase">{f.userName?.charAt(0)}</div>
                    <div><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{f.userName}</p><p className="text-[9px] font-bold text-slate-400 uppercase">Aluno Verificado</p></div>
                  </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* 5. TABELAS */}
      {['diario', 'relatorio', 'frequencia'].includes(activeSub) && (
        <div className="space-y-6">
          <div className="flex items-center justify-between bg-white p-8 rounded-[2.5rem] border border-slate-200">
            <Header title={activeSub === 'diario' ? 'Diário Digital' : 'Relatório Pedagógico'} desc="Listagem total de alunos." />
            <div className="bg-slate-900 text-white px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><Users size={16}/> {allStudents.length} Alunos</div>
          </div>
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-2xl shadow-slate-200/50">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                <tr><th className="px-10 py-6">Estudante</th><th className="px-10 py-6">Matrícula</th><th className="px-10 py-6">Progresso</th><th className="px-10 py-6 text-right">Ações</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-10 py-6 flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs">{s.displayName.charAt(0)}</div><span className="font-black text-slate-900 text-sm tracking-tighter uppercase">{s.displayName}</span></td>
                    <td className="px-10 py-6 text-xs font-mono text-slate-400 uppercase">{s.uid.substring(0,8)}</td>
                    <td className="px-10 py-6"><div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-indigo-600 w-[70%]" /></div></td>
                    <td className="px-10 py-6 text-right"><button className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 transition-all"><ChevronRight size={18}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 6. LIVE */}
      {activeSub === 'live' && (
        <div className="space-y-6">
          <Header title="Sala de Transmissão" desc="Inicie sua aula ao vivo para toda a comunidade escolar." />
          <div className="p-32 bg-white border-2 border-dashed border-slate-200 rounded-[4rem] flex flex-col items-center text-center group hover:border-indigo-400 transition-all">
            <div className="w-24 h-24 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mb-8 group-hover:scale-110 transition-transform"><Radio size={48} className="text-indigo-600 animate-pulse" /></div>
            <h3 className="font-black text-slate-900 text-2xl mb-4 uppercase tracking-tighter">Preparado para entrar ao vivo?</h3>
            <button className="bg-slate-900 text-white px-12 py-5 rounded-[2rem] text-xs font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all hover:bg-indigo-600">Abrir Estúdio Digital</button>
          </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-xl font-black text-slate-900 mb-8 uppercase tracking-tighter">Novo Módulo Acadêmico</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold mb-6" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Módulo</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL EXAMES (VÍNCULO OBRIGATÓRIO) */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-6 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Nova Avaliação</h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Título da Prova</label>
                  <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Ex: Prova Final" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Vincular ao Módulo</label>
                  <select value={selectedModuleForExam} onChange={e => setSelectedModuleForExam(e.target.value)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                    <option value="">Selecione o Módulo de Destino...</option>
                    {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Tipo</label>
                    <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="activity">Atividade Livre</option><option value="evaluation">Prova Avaliativa</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Nota de Corte (%)</label>
                    <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-black" />
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Base da Prova</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE PERGUNTAS (FUNCIONAL) */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-8 border-b pb-6">
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Questões: {currentExam.title}</h3>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{currentExam.questions?.length || 0} Itens Registrados</p>
                 </div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-slate-200"><X size={20}/></button>
              </div>

              <div className="space-y-6 mb-10 bg-slate-50 p-8 rounded-[2rem] border border-slate-100">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Enunciado da Questão</label>
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Qual o significado original de..." className="w-full px-5 py-4 border-none rounded-xl outline-none bg-white font-bold text-sm h-24 resize-none" />
                 </div>
                 <div className="grid grid-cols-1 gap-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Opções de Resposta</label>
                    {qOptions.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3">
                         <div onClick={() => setQCorrect(i)} className={`w-10 h-10 rounded-xl flex items-center justify-center cursor-pointer transition-all font-black text-xs ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>
                            {String.fromCharCode(65 + i)}
                         </div>
                         <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-4 py-3 bg-white border-none rounded-xl outline-none text-xs font-bold" />
                      </div>
                    ))}
                 </div>
                 <button onClick={handleAddQuestion} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all">+ Adicionar Pergunta ao Banco</button>
              </div>

              <div className="space-y-3">
                 <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Questões Salvas</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-5 bg-white border border-slate-100 rounded-2xl flex justify-between items-center group hover:border-indigo-200 transition-all">
                      <div className="flex-1">
                        <p className="text-xs font-black text-slate-900 leading-tight uppercase tracking-tighter mb-2">{idx + 1}. {q.text}</p>
                        <div className="flex gap-2">
                          <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded-lg">Correta: {String.fromCharCode(65 + q.correctOptionIndex)}</span>
                        </div>
                      </div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-2 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Configurar Nova Aula</h3>
              <div className="space-y-5">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Lição" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo (YouTube / Vimeo / Drive)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 block">Material de Apoio</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-3">
                    <option value="">Buscar no Acervo...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                  <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou cole um link direto" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold disabled:opacity-50" />
                </div>
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none h-32 resize-none font-medium text-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Salvar Aula</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Novo Item no Acervo</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Drive / PDF" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase"><option value="pdf">PDF</option><option value="link">Link Externo</option><option value="drive">Google Drive</option></select>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Voltar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Cadastrar</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  Link as LinkIcon,
  ExternalLink,
  Users,
  Award,
  Edit3,
  BookOpen
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    // Snapshot global de exames para carregar perguntas e vínculos
    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (activeSub === 'modulos' && selectedCourseForModules) {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia', 'avaliacao'].includes(activeSub)) {
      const fetchExtra = async () => {
        const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapS = await getDocs(qS);
        setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchExtra();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules, user.uid]);

  // Handlers
  const handleSaveModule = async () => {
    if (!moduleTitle || !selectedCourseForModules) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam || !selectedCourseForModules) {
      alert("Por favor, preencha o título e selecione um módulo para a prova.");
      return;
    }
    await addDoc(collection(db, 'exams'), {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      questions: [],
      authorId: user.uid,
      createdAt: serverTimestamp()
    });
    setExamTitle(''); setSelectedModuleForExam(''); setIsExamModalOpen(false);
  };

  const handleAddQuestion = async () => {
    if (!currentExam || !qText || qOptions.some(o => !o)) return;
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: qText,
      options: qOptions,
      correctOptionIndex: qCorrect
    };
    const updatedQuestions = [...(currentExam.questions || []), newQuestion];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: updatedQuestions });
    setQText(''); setQOptions(['', '', '', '']); setQCorrect(0);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const newLesson: Lesson = {
      id: Math.random().toString(36).substr(2, 9),
      title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc,
      materialUrl: finalMaterialUrl, order: (mod.lessons?.length || 0) + 1
    };
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: [...(mod.lessons || []), newLesson] });
    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); setSelectedMaterialId(''); setIsLessonModalOpen(false);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl || !selectedCourseForModules) return;
    try {
      await addDoc(collection(db, 'materials'), {
        courseId: selectedCourseForModules,
        title: materialTitle,
        url: materialUrl,
        type: materialType,
        createdAt: serverTimestamp()
      });
      setMaterialTitle('');
      setMaterialUrl('');
      setIsMaterialModalOpen(false);
    } catch (error) {
      console.error("Erro ao salvar material:", error);
    }
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc }: { title: string, desc: string }) => (
    <div className="mb-6">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h1>
      <p className="text-sm text-slate-500">{desc}</p>
    </div>
  );

  if (loading) return (
    <div className="p-20 text-center">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Carregando Matriz Acadêmica...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Matriz Curricular</h2>
              <p className="text-xs text-slate-500 font-medium">Módulos, aulas e avaliações finais de cada etapa.</p>
            </div>
            <div className="flex items-center gap-3">
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)} 
                className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[2.5rem] overflow-hidden transition-all hover:border-indigo-100">
                  <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm">
                        <Layers size={18} />
                      </div>
                      <div>
                        <h3 className="font-black text-slate-800 text-xs uppercase tracking-wider">{mod.title}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Aulas + {moduleExams.length} Provas</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-4 py-2 rounded-xl shadow-md shadow-indigo-100 hover:scale-105 transition-all">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir este módulo e todo o seu conteúdo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-6 grid grid-cols-1 gap-3">
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-slate-50/50 p-4 rounded-3xl flex gap-5 items-center group border border-transparent hover:border-indigo-100 hover:bg-white transition-all">
                        <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover:text-indigo-600 transition-colors">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">{lesson.title} {lesson.materialUrl && <FileText size={12} className="text-emerald-500" />}</h4>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none mt-1">Aula em Vídeo</p>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}

                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/50 p-5 rounded-3xl flex gap-5 items-center border border-amber-100 mt-2">
                        <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center text-amber-600"><CheckSquare size={18} /></div>
                        <div className="flex-1">
                          <h4 className="font-black text-amber-900 text-sm uppercase tracking-tighter">Avaliação Final: {ex.title}</h4>
                          <p className="text-[9px] font-black text-amber-600 uppercase tracking-widest leading-none mt-1">Checkpoint do Módulo • Corte {ex.passingGrade}%</p>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-4 py-2 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg shadow-amber-100 transition-transform active:scale-95">Editar Perguntas</button>
                      </div>
                    ))}

                    {(!mod.lessons || mod.lessons.length === 0) && (
                      <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-3xl"><p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Vazio.</p></div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <Header title="Acervo Digital" desc="Documentos de apoio para download e estudo." />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {materials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] relative group shadow-sm hover:border-indigo-300 transition-all">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-5 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}><FileText size={28} /></div>
                <h4 className="font-black text-slate-900 text-sm leading-tight mb-2">{m.title}</h4>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar Arquivo</a>
                <button onClick={async () => { if(confirm('Remover material?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
            <Header title="Banco de Provas" desc="Visualize e crie exames vinculados aos módulos." />
            <button onClick={() => setIsExamModalOpen(true)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-600 transition-all"><Plus size={18} /> Criar Prova</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.map(ex => (
              <div key={ex.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-3xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Award size={24} /></div>
                  <div className="text-right"><span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">Passagem</span><span className="text-xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-lg mb-2">{ex.title}</h4>
                <div className="flex items-center gap-2 mb-6">
                   <span className="text-[9px] font-black text-indigo-500 uppercase px-2 py-1 bg-indigo-50 rounded-lg">Módulo: {ex.moduleId ? ex.moduleId.substring(0,8) : 'N/A'}</span>
                </div>
                <div className="flex gap-3">
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-slate-200 hover:bg-indigo-600 transition-colors">Gerenciar {ex.questions?.length || 0} Questões</button>
                  <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-4 bg-slate-50 text-slate-300 rounded-xl hover:text-red-500 transition-colors"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <Header title="Mural de Feedback" desc="Sua reputação acadêmica e impressões dos alunos." />
           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <h2 className="text-5xl font-black mb-1">{feedbackStats.avg}</h2>
                <p className="text-[10px] text-indigo-100 uppercase font-black tracking-[0.2em]">NPS Acadêmico</p>
                <Target size={120} className="absolute -bottom-6 -right-6 text-white/10 rotate-12" />
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
                <Smile className="text-emerald-500 mb-4" /><h3 className="text-3xl font-black text-slate-900">{feedbackStats.elogios}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Elogios</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between">
