          </div>
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-2xl shadow-slate-200/50">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                <tr><th className="px-10 py-6">Estudante</th><th className="px-10 py-6">Matrícula</th><th className="px-10 py-6">Progresso</th><th className="px-10 py-6 text-right">Ações</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-10 py-6 flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs">{(s.displayName || 'U').charAt(0)}</div><span className="font-black text-slate-900 text-sm tracking-tighter uppercase">{s.displayName}</span></td>
                    <td className="px-10 py-6 text-xs font-mono text-slate-400 uppercase">{s.uid ? s.uid.substring(0,8) : 'N/A'}</td>
                    <td className="px-10 py-6"><div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-indigo-600 w-[70%]" /></div></td>
                    <td className="px-10 py-6 text-right"><button className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 transition-all"><ChevronRight size={18}/></button></td>
                  </tr>
                ))}
