                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Nota de Corte (%)</label>
                    <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-black" />
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Base da Prova</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE PERGUNTAS */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-8 border-b pb-6">
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Questões: {currentExam.title}</h3>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{currentExam.questions?.length || 0} Itens Registrados</p>
                 </div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X size={20}/></button>
              </div>

              <div className="space-y-6 mb-10 bg-slate-50 p-8 rounded-[2rem] border border-slate-100">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Enunciado da Questão</label>
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Enunciado da pergunta..." className="w-full px-5 py-4 border-none rounded-xl outline-none bg-white font-bold text-sm h-24 resize-none" />
                 </div>
                 <div className="grid grid-cols-1 gap-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Opções de Resposta</label>
                    {qOptions.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3">
                         <div onClick={() => setQCorrect(i)} className={`w-10 h-10 rounded-xl flex items-center justify-center cursor-pointer transition-all font-black text-xs ${qCorrect === i ? 'bg-emerald-500 text-white border-none shadow-md' : 'bg-white border-2 border-slate-100 text-slate-300 hover:border-indigo-200'}`}>
                            {String.fromCharCode(65 + i)}
                         </div>
                         <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-4 py-3 bg-white border-none rounded-xl outline-none text-xs font-bold focus:ring-1 focus:ring-indigo-100 transition-all" />
                      </div>
                    ))}
                 </div>
                 <button onClick={handleAddQuestion} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all">+ Adicionar Pergunta</button>
              </div>

              <div className="space-y-3">
                 <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Questões Salvas</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-5 bg-white border border-slate-100 rounded-2xl flex justify-between items-center group hover:border-indigo-200 transition-all">
                      <div className="flex-1">
                        <p className="text-xs font-black text-slate-900 leading-tight uppercase tracking-tighter mb-2">{idx + 1}. {q.text}</p>
                        <div className="flex gap-2">
                          <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded-lg">Correta: {String.fromCharCode(65 + q.correctOptionIndex)}</span>
                        </div>
                      </div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-2 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Configurar Nova Aula</h3>
              <div className="space-y-5">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Lição" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 block">Material de Apoio</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-3">
                    <option value="">Buscar no Acervo...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                  <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou cole um link direto" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold disabled:opacity-50" />
                </div>
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="Descrição..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none h-32 resize-none font-medium text-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Salvar Aula</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Novo Item no Acervo</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Drive / PDF" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase"><option value="pdf">PDF</option><option value="link">Link Externo</option><option value="drive">Google Drive</option></select>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Voltar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-transform active:scale-95">Cadastrar</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  Link as LinkIcon,
  ExternalLink,
  Users,
  Award,
  Edit3,
  BookOpen,
  Eye,
  Calendar,
  ClipboardList,
  BarChart3,
  PlayCircle
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State (Edit/Create)
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  // Preview States
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (activeSub === 'modulos' && selectedCourseForModules) {
      const q = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(q, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
        setLoading(false);
      }));
    } else if (activeSub === 'materiais') {
      unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
        setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
        setLoading(false);
      }));
    } else if (activeSub === 'feedback') {
      unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
        setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
        setLoading(false);
      }));
    } else if (['diario', 'relatorio', 'frequencia', 'avaliacao'].includes(activeSub)) {
      const fetchExtra = async () => {
        const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapS = await getDocs(qS);
        setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
        setLoading(false);
      };
      fetchExtra();
    } else {
      setLoading(false);
    }

    return () => unsubscribes.forEach(unsub => unsub());
  }, [activeSub, selectedCourseForModules, user.uid]);

  // Handlers Pedagógicos
  const handleSaveModule = async () => {
    if (!moduleTitle || !selectedCourseForModules) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam || !selectedCourseForModules) {
      alert("Por favor, preencha o título e selecione um módulo para a prova.");
      return;
    }
    const examData = {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      authorId: user.uid,
      updatedAt: serverTimestamp()
    };

    if (currentExam) {
      await updateDoc(doc(db, 'exams', currentExam.id), examData);
    } else {
      await addDoc(collection(db, 'exams'), { ...examData, questions: [], createdAt: serverTimestamp() });
    }

    setExamTitle(''); setSelectedModuleForExam(''); setIsExamModalOpen(false); setCurrentExam(null);
  };

  const handleEditExam = (ex: Exam) => {
    setCurrentExam(ex);
    setExamTitle(ex.title);
    setExamType(ex.type);
    setPassingGrade(ex.passingGrade);
    setSelectedModuleForExam(ex.moduleId);
    setIsExamModalOpen(true);
  };

  const handleAddQuestion = async () => {
    if (!currentExam || !qText || qOptions.some(o => !o)) return;
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: qText,
      options: qOptions,
      correctOptionIndex: qCorrect
    };
    const updatedQuestions = [...(currentExam.questions || []), newQuestion];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: updatedQuestions });
    setQText(''); setQOptions(['', '', '', '']); setQCorrect(0);
    // Refresh local state if needed (snapshot handles it)
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;

    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }

    const lessonData: Lesson = {
      id: editingLessonId || Math.random().toString(36).substr(2, 9),
      title: lessonTitle, 
      videoUrl: lessonVideoUrl, 
      description: lessonDesc,
      materialUrl: finalMaterialUrl, 
      order: editingLessonId ? (mod.lessons.find(l => l.id === editingLessonId)?.order || 1) : (mod.lessons?.length || 0) + 1
    };

    let updatedLessons;
    if (editingLessonId) {
      updatedLessons = mod.lessons.map(l => l.id === editingLessonId ? lessonData : l);
    } else {
      updatedLessons = [...(mod.lessons || []), lessonData];
    }

    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: updatedLessons });

    setLessonTitle(''); setLessonVideoUrl(''); setLessonDesc(''); setLessonMaterialUrl(''); 
    setSelectedMaterialId(''); setEditingLessonId(null); setIsLessonModalOpen(false);
  };

  const handleEditLesson = (modId: string, lesson: Lesson) => {
    setCurrentModuleId(modId);
    setEditingLessonId(lesson.id);
    setLessonTitle(lesson.title);
    setLessonVideoUrl(lesson.videoUrl);
    setLessonDesc(lesson.description || '');
    setLessonMaterialUrl(lesson.materialUrl || '');
    setIsLessonModalOpen(true);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl || !selectedCourseForModules) return;
    try {
      await addDoc(collection(db, 'materials'), {
        courseId: selectedCourseForModules,
        title: materialTitle,
        url: materialUrl,
        type: materialType,
        createdAt: serverTimestamp()
      });
      setMaterialTitle(''); setMaterialUrl(''); setIsMaterialModalOpen(false);
    } catch (error) { console.error(error); }
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">{title}</h1>
        <p className="text-sm text-slate-500 font-medium">{desc}</p>
      </div>
    </div>
  );

  if (isPreviewMode) {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-950 flex flex-col text-white animate-in fade-in duration-300">
        <div className="p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 px-3 py-1 rounded text-[10px] font-black uppercase">Modo Preview Professor</div>
            <h2 className="text-sm font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</h2>
          </div>
          <button onClick={() => setIsPreviewMode(false)} className="px-6 py-2 bg-white text-slate-900 rounded-xl text-xs font-black uppercase hover:bg-slate-200 transition-all">Sair do Preview</button>
        </div>
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          <div className="flex-1 bg-black flex items-center justify-center p-8">
             <div className="aspect-video w-full max-w-4xl bg-slate-900 rounded-3xl flex flex-col items-center justify-center border border-white/5">
                <PlayCircle size={80} className="text-white/20 mb-4" />
                <p className="text-xs font-bold uppercase tracking-[0.2em] text-white/40">O Player do Aluno será renderizado aqui</p>
             </div>
          </div>
          <div className="w-full md:w-80 border-l border-white/10 bg-slate-900/50 p-6 overflow-y-auto">
             <h3 className="text-[10px] font-black uppercase text-white/40 tracking-widest mb-6">Conteúdo Programático</h3>
             <div className="space-y-4">
               {modules.map(mod => (
                 <div key={mod.id} className="space-y-2">
                   <p className="text-xs font-black text-white uppercase">{mod.title}</p>
                   {(mod.lessons || []).map(l => (
                     <div key={l.id} className="p-3 bg-white/5 rounded-xl text-[10px] font-medium border border-transparent hover:border-indigo-500 cursor-pointer">
                       {l.title}
                     </div>
                   ))}
                   {exams.filter(e => e.moduleId === mod.id).map(e => (
                     <div key={e.id} className="p-3 bg-amber-500/10 rounded-xl text-[10px] font-black text-amber-500 uppercase border border-amber-500/20">
                       {e.title}
                     </div>
                   ))}
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="p-20 text-center">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto mb-4"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sincronizando Sistema Pedagógico...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <Header title="Matriz de Ensino" desc="Hierarquia completa de módulos, lições e avaliações." icon={<Layers size={24} />} />
            <div className="flex items-center gap-3">
              <button onClick={() => setIsPreviewMode(true)} className="px-5 py-3 bg-slate-100 text-slate-600 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-slate-200 transition-all"><Eye size={16}/> Preview</button>
              <select 
                value={selectedCourseForModules} 
                onChange={e => setSelectedCourseForModules(e.target.value)} 
                className="bg-slate-50 border-none rounded-2xl px-5 py-3 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden transition-all hover:border-indigo-100 group">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm"><Layers size={20} /></div>
                      <div>
                        <h3 className="font-black text-slate-800 text-sm uppercase tracking-wider">{mod.title}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Lições • {moduleExams.length} Avaliações</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-5 py-2.5 rounded-xl shadow-lg shadow-indigo-100 hover:scale-105 transition-all">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-8 grid grid-cols-1 gap-4">
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-slate-50/50 p-5 rounded-[2rem] flex gap-6 items-center border border-transparent hover:border-indigo-100 hover:bg-white transition-all group/lesson">
                        <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover/lesson:text-indigo-600 transition-colors">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-bold text-slate-900 text-sm flex items-center gap-2">{lesson.title}</h4>
                          <div className="flex gap-2 mt-1">
                             <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded">ID: {lesson.id.substring(0,6)}</span>
                             {lesson.materialUrl && <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded">Material Pronto</span>}
                          </div>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover/lesson:opacity-100 transition-opacity">
                          <button onClick={() => handleEditLesson(mod.id, lesson)} className="p-2.5 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 hover:border-indigo-100 transition-all"><Edit3 size={16}/></button>
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2.5 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-red-500 transition-all"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}

                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/40 p-6 rounded-[2rem] flex gap-6 items-center border border-amber-100/50 group/exam">
                        <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center text-amber-600"><CheckSquare size={20} /></div>
                        <div className="flex-1">
                          <h4 className="font-black text-amber-900 text-xs uppercase tracking-tighter">Avaliação: {ex.title}</h4>
                          <p className="text-[9px] font-black text-amber-600 uppercase tracking-widest mt-1">Checkpoint Acadêmico • Mínimo {ex.passingGrade}%</p>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/exam:opacity-100 transition-all">
                           <button onClick={() => handleEditExam(ex)} className="p-2.5 bg-white border border-amber-100 rounded-xl text-amber-600 hover:bg-amber-50 transition-all"><Edit3 size={16}/></button>
                           <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-5 py-2.5 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg shadow-amber-100 transition-transform active:scale-95">Editar Questões</button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* DIÁRIO DE CLASSE (PROFESSOR REAL) */}
      {activeSub === 'diario' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-center justify-between">
            <Header title="Diário Digital" desc="Observações pedagógicas e controle de evolução individual." icon={<Calendar size={24} />} />
            <div className="flex gap-2">
               <button className="px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest">Lançar Nova Nota</button>
            </div>
          </div>
          <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-sm">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                 <tr><th className="px-10 py-6">Estudante</th><th className="px-10 py-6">Último Acesso</th><th className="px-10 py-6">Notas</th><th className="px-10 py-6">Observações</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {allStudents.map(s => (
                   <tr key={s.uid} className="hover:bg-slate-50/50 transition-colors">
                     <td className="px-10 py-6">
                        <div className="flex items-center gap-4">
                           <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs">{(s.displayName || 'U').charAt(0)}</div>
                           <span className="font-black text-slate-900 text-sm tracking-tighter uppercase">{s.displayName}</span>
                        </div>
                     </td>
                     <td className="px-10 py-6 text-xs font-mono text-slate-400 uppercase tracking-widest">Há 2 dias</td>
                     <td className="px-10 py-6">
                        <div className="flex gap-1">
                           {[8.5, 9.0, 7.5].map((n, i) => <span key={i} className="px-2 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[10px] font-black">{n}</span>)}
                        </div>
                     </td>
                     <td className="px-10 py-6"><input placeholder="Escreva um feedback..." className="bg-transparent border-b border-slate-100 text-xs py-1 w-full focus:border-indigo-500 outline-none" /></td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        </div>
      )}

      {/* FREQUÊNCIA NOMINAL */}
      {activeSub === 'frequencia' && (
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-center justify-between">
              <Header title="Lista de Presença" desc="Controle de visualização das aulas e engajamento." icon={<ClipboardList size={24} />} />
              <div className="px-5 py-3 bg-emerald-50 text-emerald-600 rounded-2xl text-[10px] font-black uppercase">Chamada de Hoje: {new Date().toLocaleDateString()}</div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allStudents.map(s => (
                <div key={s.uid} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex items-center justify-between shadow-sm hover:border-indigo-200 transition-all">
                   <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-slate-400">{(s.displayName || 'U').charAt(0)}</div>
                      <span className="font-black text-slate-900 text-xs uppercase tracking-tighter">{s.displayName}</span>
                   </div>
                   <div className="flex gap-2">
                      <button className="w-8 h-8 rounded-full bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center justify-center text-[10px] font-black">P</button>
                      <button className="w-8 h-8 rounded-full bg-rose-50 text-rose-300 border border-rose-100 flex items-center justify-center text-[10px] font-black">F</button>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* FEEDBACK - MURAL DINÂMICO */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm">
             <div className="flex flex-col md:flex-row gap-8 justify-between">
                <div>
                   <h1 className="text-4xl font-black text-slate-900 tracking-tighter uppercase mb-2">Mural Pedagógico</h1>
                   <p className="text-slate-500 font-medium">Veja o que seus alunos estão falando sobre as lições.</p>
                </div>
                <div className="flex items-center gap-6">
                   <div className="text-center">
                      <p className="text-5xl font-black text-indigo-600">{feedbackStats.avg}</p>
                      <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mt-1">Score Geral</p>
                   </div>
                   <div className="h-12 w-px bg-slate-100"></div>
                   <div className="space-y-1">
                      <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.elogios} Elogios</p></div>
                      <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.sugestoes} Sugestões</p></div>
                      <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-rose-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.alertas} Alertas</p></div>
                   </div>
                </div>
             </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group hover:border-indigo-100 transition-all">
                  <div className={`absolute top-0 right-0 w-2 h-full ${f.type === 'elogio' ? 'bg-emerald-500' : f.type === 'sugestao' ? 'bg-indigo-500' : 'bg-rose-500'}`} />
                  <div className="flex items-center justify-between mb-6">
                     <div className="flex text-amber-400"><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/></div>
                     <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{new Date().toLocaleDateString()}</span>
                  </div>
                  <p className="text-sm font-medium text-slate-700 leading-relaxed mb-8 italic">"{f.comment}"</p>
                  <div className="flex items-center gap-4">
                     <div className="w-10 h-10 rounded-2xl bg-slate-50 flex items-center justify-center font-black text-slate-400 text-xs">{(f.userName || 'U').charAt(0)}</div>
                     <div><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{f.userName || 'Aluno'}</p><p className="text-[9px] font-bold text-indigo-500 uppercase tracking-widest">{f.category || 'Aula'}</p></div>
                  </div>
                </div>
              ))}
              {feedbacks.length === 0 && <div className="col-span-full py-32 text-center text-slate-300 font-black uppercase text-xs tracking-widest border-4 border-dashed rounded-[4rem]">Aguardando feedbacks discentes...</div>}
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES (CREATE & EDIT) */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center">
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">{editingLessonId ? 'Editar Lição' : 'Criar Nova Lição'}</h3>
                 <button onClick={() => setIsLessonModalOpen(false)} className="p-3 bg-slate-50 rounded-full hover:bg-slate-200"><X size={20} /></button>
              </div>
              <div className="space-y-5">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Lição" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo (Youtube/Vimeo/Drive)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 block">Material de Apoio Digital</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-3">
                    <option value="">Buscar no Acervo Acadêmico...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                  <input disabled={!!selectedMaterialId} value={lessonMaterialUrl} onChange={e => setLessonMaterialUrl(e.target.value)} placeholder="Ou cole um link externo direto" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold disabled:opacity-50" />
                </div>
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="O que será ensinado nesta aula?" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none h-32 resize-none font-medium text-sm leading-relaxed"></textarea>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => { setIsLessonModalOpen(false); setEditingLessonId(null); }} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">{editingLessonId ? 'Atualizar Lição' : 'Publicar Lição'}</button>
              </div>
           </div>
        </div>
