      {/* MODAL EXAMES (CREATE & EDIT) */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-6 shadow-2xl animate-in zoom-in-95">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">{currentExam ? 'Editar Avaliação' : 'Nova Avaliação'}</h3>
                 <button onClick={() => { setIsExamModalOpen(false); setCurrentExam(null); }} className="p-3 bg-slate-50 rounded-full"><X size={20} /></button>
              </div>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Título da Prova</label>
                  <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Ex: Exame de Conclusão de Módulo" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Vincular ao Módulo</label>
                  <select value={selectedModuleForExam} onChange={e => setSelectedModuleForExam(e.target.value)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                    <option value="">Selecione o checkpoint do módulo...</option>
                    {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Tipo</label>
                    <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                      <option value="activity">Atividade Livre</option><option value="evaluation">Prova Avaliativa</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Nota de Corte (%)</label>
                    <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-black" />
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => { setIsExamModalOpen(false); setCurrentExam(null); }} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">{currentExam ? 'Salvar Alterações' : 'Criar Base da Prova'}</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE QUESTÕES (BANCO DE DADOS) */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-3xl rounded-[3.5rem] p-12 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-10 border-b pb-8">
                 <div className="flex items-center gap-5">
                    <div className="p-4 bg-amber-50 text-amber-600 rounded-2xl"><ClipboardList size={24} /></div>
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Editor de Questões</h3>
                      <p className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Prova: {currentExam.title}</p>
                    </div>
                 </div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-4 bg-slate-50 rounded-full hover:bg-slate-200 transition-colors"><X size={24}/></button>
              </div>

              <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 mb-12">
                 <div className="space-y-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Enunciado da Pergunta</label>
                       <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Escreva a pergunta acadêmica aqui..." className="w-full px-6 py-5 border-none rounded-2xl outline-none bg-white font-bold text-sm h-32 resize-none shadow-sm" />
                    </div>
                    <div className="grid grid-cols-1 gap-3">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Opções de Resposta (Marque a Correta)</label>
                       {qOptions.map((opt, i) => (
                         <div key={i} className="flex items-center gap-4 group">
                            <div onClick={() => setQCorrect(i)} className={`w-12 h-12 rounded-2xl flex items-center justify-center cursor-pointer transition-all font-black text-sm shadow-sm ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300 group-hover:border-indigo-200'}`}>
                               {String.fromCharCode(65 + i)}
                            </div>
                            <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-6 py-4 bg-white border-none rounded-2xl outline-none text-xs font-bold focus:ring-2 focus:ring-indigo-100 transition-all shadow-sm" />
                         </div>
                       ))}
                    </div>
                    <button onClick={handleAddQuestion} className="w-full py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-700 transition-all active:scale-95">+ Adicionar ao Banco de Dados da Prova</button>
                 </div>
              </div>

              <div className="space-y-4">
                 <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1 mb-6">Lista de Questões ({currentExam.questions?.length || 0})</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-6 bg-white border border-slate-100 rounded-[2rem] flex justify-between items-center group hover:border-indigo-200 transition-all shadow-sm">
                      <div className="flex-1 pr-6">
                        <div className="flex items-center gap-3 mb-2">
                           <span className="w-6 h-6 rounded-lg bg-slate-900 text-white flex items-center justify-center text-[10px] font-black">{idx + 1}</span>
                           <p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{q.text}</p>
                        </div>
                        <div className="flex gap-2">
                          <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-3 py-1 rounded-full">Gabarito: {String.fromCharCode(65 + q.correctOptionIndex)}</span>
                          <span className="text-[9px] font-black text-slate-400 uppercase bg-slate-50 px-3 py-1 rounded-full">{q.options.length} Opções</span>
                        </div>
                      </div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-3 bg-slate-50 text-slate-200 hover:text-red-500 rounded-xl transition-all"><Trash2 size={18}/></button>
                   </div>
                 ))}
                 {(!currentExam.questions || currentExam.questions.length === 0) && <div className="p-12 text-center text-[10px] font-black uppercase text-slate-300 tracking-widest border-2 border-dashed rounded-[2.5rem]">O banco de questões está vazio.</div>}
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter text-center">Novo Documento Pedagógico</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Material (Apostila / PDF / Link)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo (Google Drive / PDF Link)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase">
                   <option value="pdf">Arquivo PDF</option>
                   <option value="link">Link de Referência</option>
                   <option value="drive">Arquivo Google Drive</option>
                </select>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Cadastrar no Acervo</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-xl font-black text-slate-900 mb-8 uppercase tracking-tighter">Novo Módulo de Ensino</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título (Ex: Introdução ao Antigo Testamento)" className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold mb-6" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700">Criar Módulo</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy
} from 'firebase/firestore';
import { db } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  Smile,
  Lightbulb,
  Frown,
  Target,
  ChevronRight,
  ExternalLink,
  Users,
  Award,
  Edit3,
  Eye,
  Calendar,
  ClipboardList,
  PlayCircle,
  Search,
  TrendingUp,
  Tv
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  // Preview States
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    // Snapshot global de exames
    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    // Carregamento de módulos
    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
      }));
    }

    // Carregamento de materiais
    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    // Carregamento de feedbacks
    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    // Carregamento de alunos
    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // Handlers Pedagógicos
  const handleSaveModule = async () => {
    if (!moduleTitle || !selectedCourseForModules) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam || !selectedCourseForModules) {
      alert("Selecione título e módulo.");
      return;
    }
    const examData = {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      authorId: user.uid,
      updatedAt: serverTimestamp()
    };
    if (currentExam) {
      await updateDoc(doc(db, 'exams', currentExam.id), examData);
    } else {
      await addDoc(collection(db, 'exams'), { ...examData, questions: [], createdAt: serverTimestamp() });
    }
    setIsExamModalOpen(false); setCurrentExam(null);
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;

    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }

    const lessonData: Lesson = {
      id: editingLessonId || Math.random().toString(36).substr(2, 9),
      title: lessonTitle, 
      videoUrl: lessonVideoUrl, 
      description: lessonDesc,
      materialUrl: finalMaterialUrl, 
      order: editingLessonId ? (mod.lessons.find(l => l.id === editingLessonId)?.order || 1) : (mod.lessons?.length || 0) + 1
    };

    const updatedLessons = editingLessonId 
      ? mod.lessons.map(l => l.id === editingLessonId ? lessonData : l)
      : [...(mod.lessons || []), lessonData];

    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: updatedLessons });
    setIsLessonModalOpen(false); setEditingLessonId(null);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl || !selectedCourseForModules) return;
    await addDoc(collection(db, 'materials'), {
      courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp()
    });
    setIsMaterialModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const filteredMaterials = useMemo(() => {
    return materials.filter(m => m.courseId === selectedCourseForModules);
  }, [materials, selectedCourseForModules]);

  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">{title}</h1>
        <p className="text-sm text-slate-500 font-medium">{desc}</p>
      </div>
    </div>
  );

  if (isPreviewMode) {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-950 flex flex-col text-white animate-in fade-in duration-300">
        <div className="p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 px-3 py-1 rounded text-[10px] font-black uppercase">Modo Preview Professor</div>
            <h2 className="text-sm font-bold uppercase">{courses.find(c => c.id === selectedCourseForModules)?.nome}</h2>
          </div>
          <button onClick={() => setIsPreviewMode(false)} className="px-6 py-2 bg-white text-slate-900 rounded-xl text-xs font-black uppercase hover:bg-slate-200 transition-all">Sair do Preview</button>
        </div>
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          <div className="flex-1 bg-black flex items-center justify-center p-8">
             <div className="aspect-video w-full max-w-4xl bg-slate-900 rounded-3xl flex flex-col items-center justify-center border border-white/5 shadow-2xl">
                <PlayCircle size={80} className="text-white/20 mb-4" />
                <p className="text-xs font-bold uppercase tracking-[0.2em] text-white/40">Visualização do Player Acadêmico</p>
             </div>
          </div>
          <div className="w-full md:w-80 border-l border-white/10 bg-slate-900/50 p-6 overflow-y-auto">
             <h3 className="text-[10px] font-black uppercase text-white/40 tracking-widest mb-6 italic">Conteúdo Programático</h3>
             <div className="space-y-4">
               {modules.map(mod => (
                 <div key={mod.id} className="space-y-2">
                   <p className="text-xs font-black text-white uppercase border-b border-white/5 pb-1">{mod.title}</p>
                   {(mod.lessons || []).map(l => <div key={l.id} className="p-3 bg-white/5 rounded-xl text-[10px] font-medium hover:bg-white/10 cursor-pointer">{l.title}</div>)}
                   {exams.filter(e => e.moduleId === mod.id).map(e => <div key={e.id} className="p-3 bg-amber-500/10 rounded-xl text-[10px] font-black text-amber-500 uppercase border border-amber-500/20">{e.title}</div>)}
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="p-20 text-center flex flex-col items-center gap-4">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sincronizando Banco de Dados Acadêmico...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <Header title="Matriz de Ensino" desc="Hierarquia completa de módulos, lições e avaliações." icon={<Layers size={24} />} />
            <div className="flex items-center gap-3">
              <button onClick={() => setIsPreviewMode(true)} className="px-5 py-3 bg-slate-100 text-slate-600 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-slate-200 transition-all"><Eye size={16}/> Preview</button>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-5 py-3 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden group">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm"><Layers size={20} /></div>
                      <div><h3 className="font-black text-slate-800 text-sm uppercase">{mod.title}</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Lições • {moduleExams.length} Avaliações</p></div>
                    </div>
                    <div className="flex gap-2">
