                <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Título da Prova" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none focus:ring-2 focus:ring-indigo-600 font-bold shadow-sm" />
                <select value={selectedModuleForExam} onChange={e => setSelectedModuleForExam(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none text-[10px] font-black uppercase shadow-sm">
                    <option value="">Vincular ao checkpoint do módulo...</option>
                    {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                </select>
                <div className="grid grid-cols-2 gap-4">
                  <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase shadow-sm"><option value="activity">Atividade</option><option value="evaluation">Prova</option></select>
                  <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none font-black shadow-sm" />
                </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">{currentExam ? 'Atualizar' : 'Criar'}</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE QUESTÕES */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] p-12 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-12 border-b pb-8">
                 <div className="flex items-center gap-6"><div className="p-5 bg-amber-50 text-amber-600 rounded-3xl shadow-sm"><ClipboardList size={28} /></div><div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Editor de Questões</h3><p className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Exame Acadêmico: {currentExam.title}</p></div></div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-5 bg-slate-50 rounded-full hover:bg-slate-200 transition-colors"><X size={24}/></button>
              </div>
              <div className="bg-slate-50 p-12 rounded-[3.5rem] border border-slate-100 mb-12 shadow-sm">
                 <div className="space-y-8">
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Enunciado da pergunta acadêmica..." className="w-full px-8 py-6 border-none rounded-[1.5rem] outline-none bg-white font-bold text-sm h-36 resize-none shadow-sm" />
                    <div className="grid grid-cols-1 gap-4">
                       {qOptions.map((opt, i) => (
                         <div key={i} className="flex items-center gap-5">
                            <div onClick={() => setQCorrect(i)} className={`w-14 h-14 rounded-2xl flex items-center justify-center cursor-pointer transition-all font-black text-sm shadow-sm ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>{String.fromCharCode(65 + i)}</div>
                            <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-8 py-4 bg-white border-none rounded-2xl outline-none text-xs font-bold shadow-sm" />
                         </div>
                       ))}
                    </div>
                    <button onClick={handleAddQuestion} className="w-full py-6 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 transition-all">+ Adicionar ao Banco de Dados</button>
                 </div>
              </div>
              <div className="space-y-5">
                 <h4 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em] mb-8">Questões Registradas ({currentExam.questions?.length || 0})</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] flex justify-between items-center group shadow-sm hover:border-indigo-100 transition-all">
                      <div className="flex-1 pr-8"><div className="flex items-center gap-4 mb-3"><span className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center text-xs font-black">{idx + 1}</span><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{q.text}</p></div><span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-4 py-1 rounded-full shadow-sm">Gabarito: {String.fromCharCode(65 + q.correctOptionIndex)}</span></div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-4 bg-slate-50 text-slate-200 hover:text-red-500 rounded-2xl transition-all shadow-sm"><Trash2 size={20}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter text-center">Adicionar Recurso</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none text-[10px] font-black uppercase shadow-sm">
                   <option value="pdf">PDF</option><option value="link">Link</option><option value="drive">Drive</option>
                </select>
