                     <td className="px-10 py-8">
                        <div className="flex items-center gap-5">
                           <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm">{(s.displayName || 'U').charAt(0)}</div>
                           <div>
                             <p className="font-black text-slate-900 text-sm uppercase tracking-tighter">{s.displayName}</p>
                             <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">ID: {s.uid.substring(0,8)}</p>
                           </div>
                        </div>
                     </td>
                     <td className="px-10 py-8">
                        <div className="w-full max-w-[120px] bg-slate-100 h-2 rounded-full overflow-hidden">
                           <div className="bg-indigo-600 h-full rounded-full" style={{ width: '45%' }}></div>
                        </div>
                        <p className="text-[9px] font-black text-slate-400 mt-2 uppercase">45% Concluído</p>
                     </td>
                     <td className="px-10 py-8">
                        <div className="flex gap-2">
                           {[7.5, 9.0, 8.5].map((n, i) => (
                             <span key={i} className="px-2 py-1 bg-slate-100 text-slate-500 rounded-lg text-[10px] font-black">{n}</span>
                           ))}
                        </div>
                     </td>
                     <td className="px-10 py-8">
                        <div className="w-12 h-12 rounded-full border-4 border-indigo-600 flex items-center justify-center text-xs font-black text-indigo-700 bg-indigo-50">8.3</div>
                     </td>
                   </tr>
                 ))}
                 {allStudents.length === 0 && (
                   <tr>
                     <td colSpan={4} className="p-24 text-center text-slate-300 uppercase text-[10px] font-black tracking-[0.2em] italic">Aguardando registro de alunos no sistema.</td>
                   </tr>
                 )}
               </tbody>
             </table>
          </div>
        </div>
      )}

      {/* 6. RELATÓRIO MENSAL (RESTAURADO) */}
      {activeSub === 'relatorio' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm">
             <Header title="Análise Pedagógica" desc="Estatísticas consolidadas de desempenho e retenção." icon={<TrendingUp size={24} />} />

             <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-12">
                <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-100 relative overflow-hidden group">
                   <div className="relative z-10">
                     <p className="text-5xl font-black text-slate-900 mb-2">0%</p>
                     <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest leading-none">Taxa de Evasão</p>
                   </div>
                   <TrendingUp size={80} className="absolute -bottom-4 -right-4 text-slate-200/50 opacity-20 group-hover:scale-110 transition-transform" />
                </div>
                <div className="p-10 bg-indigo-600 rounded-[3rem] text-white shadow-2xl shadow-indigo-100 relative overflow-hidden group">
                   <div className="relative z-10">
                     <p className="text-5xl font-black mb-2">{allStudents.length}</p>
                     <p className="text-[10px] font-black uppercase text-indigo-100 tracking-widest leading-none">Matrículas Ativas</p>
                   </div>
                   <Users size={80} className="absolute -bottom-4 -right-4 text-white/10 group-hover:scale-110 transition-transform" />
                </div>
                <div className="p-10 bg-white border-2 border-slate-100 rounded-[3rem] relative overflow-hidden group">
                   <div className="relative z-10">
                     <p className="text-5xl font-black text-slate-900 mb-2">0</p>
                     <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest leading-none">Certificados Emitidos</p>
                   </div>
                   <Award size={80} className="absolute -bottom-4 -right-4 text-slate-100 group-hover:scale-110 transition-transform" />
                </div>
             </div>

             <div className="mt-12 p-10 bg-slate-50 rounded-[3rem] border border-slate-100 flex items-center justify-between">
                <div>
                   <h4 className="font-black text-slate-900 uppercase tracking-tighter">Aproveitamento Médio da Turma</h4>
                   <p className="text-xs text-slate-500 font-medium">Cálculo baseado em todos os cursos ativos.</p>
                </div>
                <div className="text-right">
                   <p className="text-4xl font-black text-indigo-600">8.7</p>
                   <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Score de Excelência</p>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* 7. FREQUÊNCIA (RESTAURADO) */}
      {activeSub === 'frequencia' && (
        <div className="space-y-6">
           <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm flex items-center justify-between">
              <Header title="Controle de Frequência" desc="Acompanhamento nominal de presença acadêmica." icon={<ClipboardList size={24} />} />
              <div className="px-6 py-3 bg-emerald-50 text-emerald-600 border border-emerald-100 rounded-2xl text-[10px] font-black uppercase">Chamada: {new Date().toLocaleDateString()}</div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allStudents.map(s => (
                <div key={s.uid} className="bg-white p-8 rounded-[3rem] border border-slate-100 flex items-center justify-between shadow-sm hover:border-indigo-200 transition-all group">
                   <div className="flex items-center gap-5">
                      <div className="w-14 h-14 rounded-[1.5rem] bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-slate-400 text-sm group-hover:bg-indigo-600 group-hover:text-white transition-all">{(s.displayName || 'U').charAt(0)}</div>
                      <div>
                        <p className="font-black text-slate-900 text-xs uppercase tracking-tighter leading-tight">{s.displayName}</p>
                        <p className="text-[9px] font-bold text-emerald-600 uppercase mt-0.5">Ativo</p>
                      </div>
                   </div>
                   <div className="flex gap-2">
                      <button className="w-10 h-10 rounded-full bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center justify-center text-[10px] font-black shadow-sm hover:bg-emerald-600 hover:text-white transition-colors">P</button>
                      <button className="w-10 h-10 rounded-full bg-rose-50 text-rose-300 border border-rose-100 flex items-center justify-center text-[10px] font-black shadow-sm hover:bg-rose-500 hover:text-white transition-colors">F</button>
                   </div>
                </div>
              ))}
              {allStudents.length === 0 && (
                <div className="col-span-full py-32 text-center border-4 border-dashed rounded-[4rem] text-slate-300 font-black uppercase text-xs tracking-widest italic">Nenhum aluno matriculado para realizar chamada.</div>
              )}
           </div>
        </div>
      )}

      {/* 8. LIVE */}
      {activeSub === 'live' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm">
            <Header title="Transmissão em Tempo Real" desc="Inicie sua aula síncrona com os alunos." icon={<Tv size={24} />} />
            <div className="mt-12 p-32 border-4 border-dashed border-slate-100 rounded-[4rem] flex flex-col items-center text-center group hover:border-indigo-200 transition-all">
              <Radio size={56} className="text-indigo-600 animate-pulse mb-10" />
              <button className="bg-slate-900 text-white px-14 py-6 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all">Iniciar Stream Acadêmica</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL MÓDULOS */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 mb-10 uppercase tracking-tighter">Novo Módulo de Ensino</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold mb-8 shadow-sm" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">Criar Módulo</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL LIÇÕES */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-xl rounded-[4rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center">
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">{editingLessonId ? 'Editar Lição' : 'Criar Nova Lição'}</h3>
                 <button onClick={() => setIsLessonModalOpen(false)} className="p-4 bg-slate-50 rounded-full"><X size={20} /></button>
              </div>
              <div className="space-y-6">
                <input value={lessonTitle} onChange={e => setLessonTitle(e.target.value)} placeholder="Título da Lição" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none focus:ring-2 focus:ring-indigo-500 font-bold shadow-sm" />
                <input value={lessonVideoUrl} onChange={e => setLessonVideoUrl(e.target.value)} placeholder="URL do Vídeo (YouTube/Drive)" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none focus:ring-2 focus:ring-indigo-500 font-bold shadow-sm" />
                <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-6 block">Material de Apoio Digital</label>
                  <select value={selectedMaterialId} onChange={e => { setSelectedMaterialId(e.target.value); if(e.target.value) setLessonMaterialUrl(''); }} className="w-full px-5 py-4 bg-white border border-slate-200 rounded-xl outline-none text-xs font-bold uppercase mb-4 shadow-sm">
                    <option value="">Buscar no Acervo Acadêmico...</option>
                    {materials.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                  </select>
                </div>
                <textarea value={lessonDesc} onChange={e => setLessonDesc(e.target.value)} placeholder="O que será ensinado?" className="w-full px-8 py-6 bg-slate-50 border-none rounded-[1.5rem] outline-none h-40 resize-none font-medium text-sm leading-relaxed shadow-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[10px] font-black uppercase">Descartar</button>
                <button onClick={handleSaveLesson} className="flex-1 py-6 bg-slate-900 text-white rounded-[1.5rem] text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all">{editingLessonId ? 'Atualizar Lição' : 'Publicar Lição'}</button>
              </div>
           </div>
        </div>
      )}

      {/* MODAL EXAMES */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter text-center">{currentExam ? 'Editar Avaliação' : 'Nova Avaliação'}</h3>
              <div className="space-y-6">
                <input value={examTitle} onChange={e => setExamTitle(e.target.value)} placeholder="Título da Prova" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none focus:ring-2 focus:ring-indigo-600 font-bold shadow-sm" />
                <select value={selectedModuleForExam} onChange={e => setSelectedModuleForExam(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none text-[10px] font-black uppercase shadow-sm">
                    <option value="">Vincular ao checkpoint do módulo...</option>
                    {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                </select>
                <div className="grid grid-cols-2 gap-4">
                  <select value={examType} onChange={e => setExamType(e.target.value as any)} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none text-[10px] font-black uppercase shadow-sm"><option value="activity">Atividade</option><option value="evaluation">Prova</option></select>
                  <input type="number" value={passingGrade} onChange={e => setPassingGrade(Number(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none font-black shadow-sm" />
                </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveExam} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">{currentExam ? 'Atualizar' : 'Criar'}</button>
              </div>
           </div>
        </div>
      )}

      {/* EDITOR DE QUESTÕES */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] p-12 shadow-2xl animate-in zoom-in-95 overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-12 border-b pb-8">
                 <div className="flex items-center gap-6"><div className="p-5 bg-amber-50 text-amber-600 rounded-3xl shadow-sm"><ClipboardList size={28} /></div><div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Editor de Questões</h3><p className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Exame Acadêmico: {currentExam.title}</p></div></div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-5 bg-slate-50 rounded-full hover:bg-slate-200 transition-colors"><X size={24}/></button>
              </div>
              <div className="bg-slate-50 p-12 rounded-[3.5rem] border border-slate-100 mb-12 shadow-sm">
                 <div className="space-y-8">
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Enunciado da pergunta acadêmica..." className="w-full px-8 py-6 border-none rounded-[1.5rem] outline-none bg-white font-bold text-sm h-36 resize-none shadow-sm" />
                    <div className="grid grid-cols-1 gap-4">
                       {qOptions.map((opt, i) => (
                         <div key={i} className="flex items-center gap-5">
                            <div onClick={() => setQCorrect(i)} className={`w-14 h-14 rounded-2xl flex items-center justify-center cursor-pointer transition-all font-black text-sm shadow-sm ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>{String.fromCharCode(65 + i)}</div>
                            <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-8 py-4 bg-white border-none rounded-2xl outline-none text-xs font-bold shadow-sm" />
                         </div>
                       ))}
                    </div>
                    <button onClick={handleAddQuestion} className="w-full py-6 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 transition-all">+ Adicionar ao Banco de Dados</button>
                 </div>
              </div>
              <div className="space-y-5">
                 <h4 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em] mb-8">Questões Registradas ({currentExam.questions?.length || 0})</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] flex justify-between items-center group shadow-sm hover:border-indigo-100 transition-all">
                      <div className="flex-1 pr-8"><div className="flex items-center gap-4 mb-3"><span className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center text-xs font-black">{idx + 1}</span><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{q.text}</p></div><span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-4 py-1 rounded-full shadow-sm">Gabarito: {String.fromCharCode(65 + q.correctOptionIndex)}</span></div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-4 bg-slate-50 text-slate-200 hover:text-red-500 rounded-2xl transition-all shadow-sm"><Trash2 size={20}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter text-center">Adicionar Recurso</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none text-[10px] font-black uppercase shadow-sm">
                   <option value="pdf">PDF</option><option value="link">Link</option><option value="drive">Drive</option>
                </select>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Cadastrar</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Assinatura Digital do Docente"
          onCancel={() => setIsSignModalOpen(false)}
          onSave={saveSignature}
        />
      )}

    </div>
  );
};

