  Eye,
  Calendar,
  ClipboardList,
  PlayCircle,
  TrendingUp,
  Tv,
  PenTool,
  // Added missing Users import
  Users
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);

  // Assinatura State
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);

  // Modulos & Matriz State
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');

  // Lesson State
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');

  // Perguntas State
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  // Preview States
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    if (selectedCourseId) setSelectedCourseForModules(selectedCourseId);
  }, [selectedCourseId]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const fetchSignature = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) {
          setUserSignature(userDoc.data().signatureUrl || null);
        }
      }
    };
    fetchSignature();

    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        const fetchedModules = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setModules(fetchedModules.sort((a, b) => (a.order || 0) - (b.order || 0)));
      }));
    }

    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  const saveSignature = async (base64: string) => {
    if (auth.currentUser) {
      await updateDoc(doc(db, 'users', auth.currentUser.uid), {
        signatureUrl: base64
      });
      setUserSignature(base64);
      setIsSignModalOpen(false);
    }
  };

  const handleSaveModule = async () => {
    if (!moduleTitle || !selectedCourseForModules) return;
    await addDoc(collection(db, 'modulos'), {
      courseId: selectedCourseForModules,
      title: moduleTitle,
      order: modules.length + 1,
      lessons: [],
      createdAt: serverTimestamp()
    });
    setModuleTitle(''); setIsModuleModalOpen(false);
  };

  const handleSaveExam = async () => {
    if (!examTitle || !selectedModuleForExam || !selectedCourseForModules) {
      alert("Selecione título e módulo.");
      return;
    }
    const examData = {
      title: examTitle,
      courseId: selectedCourseForModules,
      moduleId: selectedModuleForExam,
      type: examType,
      passingGrade: passingGrade,
      authorId: user.uid,
      updatedAt: serverTimestamp()
    };
    if (currentExam) {
      await updateDoc(doc(db, 'exams', currentExam.id), examData);
    } else {
      await addDoc(collection(db, 'exams'), { ...examData, questions: [], createdAt: serverTimestamp() });
    }
    setIsExamModalOpen(false); setCurrentExam(null);
  };

  const handleAddQuestion = async () => {
    if (!currentExam || !qText || qOptions.some(o => !o.trim())) {
      alert("Preencha o enunciado e todas as alternativas.");
      return;
    }
    const newQuestion: Question = {
      id: Math.random().toString(36).substr(2, 9),
      text: qText,
      options: [...qOptions],
      correctOptionIndex: qCorrect
    };
    const updatedQuestions = [...(currentExam.questions || []), newQuestion];
    try {
      await updateDoc(doc(db, 'exams', currentExam.id), {
        questions: updatedQuestions,
        updatedAt: serverTimestamp()
      });
      setQText('');
      setQOptions(['', '', '', '']);
      setQCorrect(0);
    } catch (error) {
      console.error("Erro ao adicionar questão:", error);
    }
  };

  const handleSaveLesson = async () => {
    if (!lessonTitle || !currentModuleId) return;
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    let finalMaterialUrl = lessonMaterialUrl;
    if (selectedMaterialId) {
      const mat = materials.find(m => m.id === selectedMaterialId);
      if (mat) finalMaterialUrl = mat.url;
    }
    const lessonData: Lesson = {
      id: editingLessonId || Math.random().toString(36).substr(2, 9),
      title: lessonTitle, 
      videoUrl: lessonVideoUrl, 
      description: lessonDesc,
      materialUrl: finalMaterialUrl, 
      order: editingLessonId ? (mod.lessons.find(l => l.id === editingLessonId)?.order || 1) : (mod.lessons?.length || 0) + 1
    };
    const updatedLessons = editingLessonId 
      ? mod.lessons.map(l => l.id === editingLessonId ? lessonData : l)
      : [...(mod.lessons || []), lessonData];
    await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: updatedLessons });
    setIsLessonModalOpen(false); setEditingLessonId(null);
  };

  const handleSaveMaterial = async () => {
    if (!materialTitle || !materialUrl || !selectedCourseForModules) return;
    await addDoc(collection(db, 'materials'), {
      courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp()
    });
    setIsMaterialModalOpen(false);
  };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return {
      avg: avg.toFixed(1),
      elogios: feedbacks.filter(f => f.type === 'elogio').length,
      sugestoes: feedbacks.filter(f => f.type === 'sugestao').length,
      alertas: feedbacks.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks]);

  const filteredMaterials = useMemo(() => {
    return materials.filter(m => m.courseId === selectedCourseForModules);
  }, [materials, selectedCourseForModules]);

  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">{title}</h1>
        <p className="text-sm text-slate-500 font-medium">{desc}</p>
      </div>
    </div>
  );

  if (isPreviewMode) {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-950 flex flex-col text-white animate-in fade-in duration-300">
        <div className="p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 px-3 py-1 rounded text-[10px] font-black uppercase">Modo Preview Professor</div>
            <h2 className="text-sm font-bold uppercase">{courses.find(c => c.id === selectedCourseForModules)?.nome}</h2>
          </div>
          <button onClick={() => setIsPreviewMode(false)} className="px-6 py-2 bg-white text-slate-900 rounded-xl text-xs font-black uppercase hover:bg-slate-200 transition-all">Sair do Preview</button>
        </div>
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          <div className="flex-1 bg-black flex items-center justify-center p-8">
             <div className="aspect-video w-full max-w-4xl bg-slate-900 rounded-3xl flex flex-col items-center justify-center border border-white/5 shadow-2xl">
                <PlayCircle size={80} className="text-white/20 mb-4" />
                <p className="text-xs font-bold uppercase tracking-[0.2em] text-white/40">Visualização do Player Acadêmico</p>
             </div>
          </div>
          <div className="w-full md:w-80 border-l border-white/10 bg-slate-900/50 p-6 overflow-y-auto">
             <h3 className="text-[10px] font-black uppercase text-white/40 tracking-widest mb-6 italic">Conteúdo Programático</h3>
             <div className="space-y-4">
               {modules.map(mod => (
                 <div key={mod.id} className="space-y-2">
                   <p className="text-xs font-black text-white uppercase border-b border-white/5 pb-1">{mod.title}</p>
                   {(mod.lessons || []).map(l => <div key={l.id} className="p-3 bg-white/5 rounded-xl text-[10px] font-medium hover:bg-white/10 cursor-pointer">{l.title}</div>)}
                   {exams.filter(e => e.moduleId === mod.id).map(e => <div key={e.id} className="p-3 bg-amber-500/10 rounded-xl text-[10px] font-black text-amber-500 uppercase border border-amber-500/20">{e.title}</div>)}
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="p-20 text-center flex flex-col items-center gap-4">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mx-auto"></div>
      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sincronizando Banco de Dados Acadêmico...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">

      {/* 1. MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <Header title="Matriz de Ensino" desc="Hierarquia completa de módulos, lições e avaliações." icon={<Layers size={24} />} />

            <div className="flex items-center gap-6">
               {userSignature ? (
                 <div className="flex items-center gap-4">
                    <img src={userSignature} alt="Assinatura" className="h-8 grayscale object-contain" />
                    <button onClick={() => setIsSignModalOpen(true)} className="p-2 bg-white rounded-lg border text-indigo-600 hover:bg-indigo-50"><Edit3 size={14}/></button>
                 </div>
               ) : (
                 <button onClick={() => setIsSignModalOpen(true)} className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 border-2 border-indigo-100 px-4 py-2 rounded-xl hover:bg-indigo-50 transition-all">
                    <PenTool size={14}/> Assinar para Certificados
                 </button>
               )}
               <div className="h-10 w-px bg-slate-200"></div>
               <div className="flex items-center gap-3">
                <button onClick={() => setIsPreviewMode(true)} className="px-5 py-3 bg-slate-100 text-slate-600 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-slate-200 transition-all"><Eye size={16}/> Preview</button>
                <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-5 py-3 text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"><Plus size={16} /> Novo Módulo</button>
              </div>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden group">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm"><Layers size={20} /></div>
                      <div><h3 className="font-black text-slate-800 text-sm uppercase">{mod.title}</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{mod.lessons?.length || 0} Lições • {moduleExams.length} Avaliações</p></div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setIsLessonModalOpen(true); }} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-5 py-2.5 rounded-xl shadow-lg hover:scale-105 transition-all">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-8 grid grid-cols-1 gap-4">
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-slate-50/50 p-5 rounded-[2rem] flex gap-6 items-center border border-transparent hover:border-indigo-100 hover:bg-white transition-all group/lesson">
                        <div className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center font-black text-slate-400 text-xs group-hover/lesson:text-indigo-600 transition-colors">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-bold text-slate-900 text-sm">{lesson.title}</h4>
                          <div className="flex gap-2 mt-1">
                             <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded">Aula #{idx+1}</span>
                             {lesson.materialUrl && <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded">Anexo Disponível</span>}
                          </div>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover/lesson:opacity-100 transition-opacity">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(lesson.id); setLessonTitle(lesson.title); setLessonVideoUrl(lesson.videoUrl); setLessonDesc(lesson.description || ''); setIsLessonModalOpen(true); }} className="p-2.5 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 transition-all"><Edit3 size={16}/></button>
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(l => l.id !== lesson.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); } }} className="p-2.5 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-red-500 transition-all"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/40 p-6 rounded-[2rem] flex gap-6 items-center border border-amber-100/50 group/exam">
                        <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center text-amber-600"><CheckSquare size={20} /></div>
                        <div className="flex-1">
                          <h4 className="font-black text-amber-900 text-xs uppercase">Avaliação Final: {ex.title}</h4>
                          <p className="text-[9px] font-black text-amber-600 uppercase mt-1">Checkpoint Acadêmico • Corte {ex.passingGrade}%</p>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/exam:opacity-100 transition-all">
                           <button onClick={() => { setCurrentExam(ex); setExamTitle(ex.title); setExamType(ex.type); setPassingGrade(ex.passingGrade); setSelectedModuleForExam(ex.moduleId); setIsExamModalOpen(true); }} className="p-2.5 bg-white border border-amber-100 rounded-xl text-amber-600 hover:bg-amber-50 transition-all"><Edit3 size={16}/></button>
                           <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-5 py-2.5 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg transition-transform active:scale-95">Editar Questões</button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <Header title="Acervo Acadêmico" desc="Repositório de documentos e mídias de apoio." icon={<FileText size={24} />} />
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-5 py-3 text-xs font-black uppercase">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100"><Plus size={18}/> Novo Material</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {filteredMaterials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-8 rounded-[2.5rem] relative group shadow-sm hover:border-indigo-300 transition-all">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-6 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}><FileText size={32} /></div>
                <h4 className="font-black text-slate-900 text-sm leading-tight mb-4 uppercase tracking-tighter">{m.title}</h4>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar Arquivo</a>
                <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-8 right-8 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={20}/></button>
              </div>
            ))}
            {filteredMaterials.length === 0 && <div className="col-span-full py-24 text-center border-4 border-dashed rounded-[3rem] text-slate-300 font-black uppercase text-xs tracking-widest italic">Acervo vazio para este curso.</div>}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <Header title="Gestão de Exames" desc="Controle central de provas e atividades vinculadas." icon={<CheckSquare size={24} />} />
            <button onClick={() => { setCurrentExam(null); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-8 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-indigo-600 transition-all"><Plus size={18} /> Criar Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
              <div key={ex.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-8">
                  <div className={`p-5 rounded-3xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Award size={28} /></div>
                  <div className="text-right"><span className="text-[10px] font-black uppercase text-slate-400 tracking-widest block mb-1">Corte Acadêmico</span><span className="text-3xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-lg mb-3 uppercase tracking-tighter">{ex.title}</h4>
                <div className="flex gap-4">
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-colors">Configurar {ex.questions?.length || 0} Questões</button>
                  <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-5 bg-slate-50 text-slate-300 rounded-2xl hover:text-red-500 transition-colors"><Trash2 size={20}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm">
             <div className="flex flex-col md:flex-row gap-8 justify-between">
                <div><h1 className="text-4xl font-black text-slate-900 tracking-tighter uppercase mb-2">Mural Pedagógico</h1><p className="text-slate-500 font-medium italic">Sua reputação acadêmica e impressões discentes.</p></div>
                <div className="flex items-center gap-8">
                   <div className="text-center"><p className="text-6xl font-black text-indigo-600">{feedbackStats.avg}</p><p className="text-[10px] font-black uppercase text-slate-400 mt-1">NPS Geral</p></div>
                   <div className="h-16 w-px bg-slate-100 hidden md:block"></div>
                   <div className="space-y-1">
                      <div className="flex items-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-emerald-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.elogios} Elogios</p></div>
                      <div className="flex items-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.sugestoes} Sugestões</p></div>
                      <div className="flex items-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-rose-500"></div><p className="text-[10px] font-black uppercase text-slate-600">{feedbackStats.alertas} Alertas</p></div>
                   </div>
                </div>
             </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group hover:border-indigo-100 transition-all">
                  <div className={`absolute top-0 right-0 w-2.5 h-full ${f.type === 'elogio' ? 'bg-emerald-500' : f.type === 'sugestao' ? 'bg-indigo-500' : 'bg-rose-500'}`} />
                  <p className="text-sm font-medium text-slate-700 leading-relaxed mb-10 italic">"{f.comment}"</p>
                  <div className="flex items-center gap-4 border-t pt-8 border-slate-50">
                     <div className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center font-black text-slate-400 text-sm">{(f.userName || 'U').charAt(0)}</div>
                     <div><p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{f.userName || 'Aluno'}</p><p className="text-[10px] font-bold text-indigo-500 uppercase">{f.category || 'Curso'}</p></div>
                  </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* 5. DIÁRIO DE CLASSE (RESTAURADO) */}
      {activeSub === 'diario' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm flex items-center justify-between">
            <Header title="Diário Acadêmico" desc="Controle automático de aproveitamento e evolução individual." icon={<Calendar size={24} />} />
            <div className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest">{allStudents.length} Estudantes Inscritos</div>
          </div>
          <div className="bg-white rounded-[3.5rem] border border-slate-100 overflow-hidden shadow-sm">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b tracking-widest">
                 <tr>
                   <th className="px-10 py-8">Estudante</th>
                   <th className="px-10 py-8">Progresso</th>
                   <th className="px-10 py-8">Notas de Atividades</th>
                   <th className="px-10 py-8">Média Final</th>
