    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // LIVE CORE LOGIC
  const startLive = async () => {
    try {
      const userStream = await navigator.mediaDevices.getUserMedia({ 
        video: { width: { ideal: 1920 }, height: { ideal: 1080 }, facingMode: facingMode }, 
        audio: true 
      });
      setStream(userStream);
      if (videoRef.current) videoRef.current.srcObject = userStream;
      setIsLiveActive(true);
    } catch (err) {
      alert("Permissão de mídia negada.");
    }
  };

  const stopLive = () => {
    stream?.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsLiveActive(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (stream) {
      const track = stream.getAudioTracks()[0];
      track.enabled = !track.enabled;
      setMicActive(track.enabled);
    }
  };

  const toggleVideo = () => {
    if (stream) {
      const track = stream.getVideoTracks()[0];
      track.enabled = !track.enabled;
      setVideoActive(track.enabled);
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screenStream;
      setScreenShareActive(true);
      screenStream.getVideoTracks()[0].onended = () => {
        if (videoRef.current && stream) videoRef.current.srcObject = stream;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const flipCamera = async () => {
    const newMode = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(newMode);
    if (isLiveActive) {
      stream?.getTracks().forEach(t => t.stop());
      const newStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: newMode }, 
        audio: true 
      });
      setStream(newStream);
      if (videoRef.current) videoRef.current.srcObject = newStream;
    }
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages([...chatMessages, {
      user: user.displayName,
      text: chatMessage,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
    }]);
    setChatMessage('');
  };

  // AGENDAMENTO LOGIC
  const handleScheduleClass = async () => {
    if (!newClass.title || !newClass.date || !newClass.courseId) return;
    const schedRef = await addDoc(collection(db, 'scheduledClasses'), {
      ...newClass,
      professorId: user.uid,
      status: 'scheduled',
      createdAt: serverTimestamp()
    });

    // Notify Students
    const studentQuery = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const studentSnap = await getDocs(studentQuery);
    studentSnap.forEach(async (student) => {
      await addDoc(collection(db, 'notifications'), {
        userId: student.id,
        title: `Aula Agendada: ${newClass.title}`,
        message: `O professor ${user.displayName} agendou uma nova aula ao vivo para ${new Date(newClass.date).toLocaleString()}.`,
        date: newClass.date,
        type: 'class_scheduled',
        read: false,
        archived: false,
        calendarData: { title: newClass.title, start: newClass.date }
      });
    });

    setIsScheduleModalOpen(false);
    setNewClass({ title: '', description: '', date: '', courseId: '' });
  };

  // RENDERING HELPERS
  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase leading-none">{title}</h1>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">{desc}</p>
      </div>
    </div>
  );

  // Common UI handlers (signature, module, material, etc) logic truncated for brevity
  const saveSignature = async (b64: string) => { if(auth.currentUser) { await updateDoc(doc(db, 'users', auth.currentUser.uid), { signatureUrl: b64 }); setUserSignature(b64); setIsSignModalOpen(false); }};
  const handleSaveModule = async () => { if(!moduleTitle) return; await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); setModuleTitle(''); setIsModuleModalOpen(false); };
  const handleSaveLesson = async () => { if(!lessonTitle || !currentModuleId) return; const mod = modules.find(m => m.id === currentModuleId); if(!mod) return; const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? {...l, title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc} : l) : [...(mod.lessons||[]), {id: Math.random().toString(36).substr(2,9), title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc, order: (mod.lessons?.length||0)+1}]; await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: up }); setIsLessonModalOpen(false); setEditingLessonId(null); };
  const handleSaveExam = async () => { const payload = { title: examTitle, courseId: selectedCourseForModules, moduleId: selectedModuleForExam, type: examType, passingGrade, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); setCurrentExam(null); };
  const handleSaveMaterial = async () => { if(!materialTitle || !materialUrl) return; await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); };

  if (loading) return (
    <div className="h-full flex flex-col items-center justify-center p-20 gap-4 text-center">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div>
      <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Sincronizando Ecossistema Pedagógico...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500 h-full">

      {/* 1. CURRICULUM MANAGEMENT */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm">
            <Header title="Matriz de Ensino" desc="Arquitetura de conteúdo e progresso acadêmico." icon={<Layers size={24} />} />
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 flex items-center gap-2 hover:bg-indigo-700 transition-all"><Plus size={16}/> Novo Módulo</button>
            </div>
          </div>
          {/* Modules List logic here... */}
          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[2.5rem] overflow-hidden">
                <div className="p-8 bg-slate-50 border-b flex items-center justify-between">
                   <div className="flex items-center gap-4">
                      <div className="p-3 bg-white rounded-xl shadow-sm text-indigo-500"><Layers size={20}/></div>
                      <h3 className="font-black text-slate-800 uppercase text-xs tracking-widest">{mod.title}</h3>
                   </div>
                   <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setIsLessonModalOpen(true); }} className="px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:scale-105 transition-all">Adicionar Aula</button>
                </div>
                <div className="p-8 grid grid-cols-1 gap-3">
                   {(mod.lessons || []).map((l, i) => (
                     <div key={l.id} className="p-5 bg-slate-50/50 border border-transparent hover:border-indigo-100 hover:bg-white rounded-2xl flex items-center justify-between group transition-all">
                        <div className="flex items-center gap-4">
                           <span className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover:text-indigo-600 group-hover:border-indigo-500 transition-all">{i+1}</span>
                           <span className="font-bold text-slate-800 text-sm">{l.title}</span>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                           <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonTitle(l.title); setLessonVideoUrl(l.videoUrl); setLessonDesc(l.description||''); setIsLessonModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600"><Edit3 size={16}/></button>
                           <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), {lessons: up}); }}} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 8. LIVE STUDIO (MEET STYLE) */}
      {activeSub === 'live' && (
        <div className="h-full flex flex-col space-y-6">
          {!isLiveActive ? (
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
               {/* Transmissão Imediata */}
               <div className="bg-white p-12 rounded-[4rem] border border-slate-200 shadow-sm text-center flex flex-col items-center justify-center animate-in zoom-in-95 h-full">
                  <div className="w-24 h-24 bg-rose-50 rounded-full flex items-center justify-center mb-8 shadow-inner animate-pulse">
                     <Radio size={48} className="text-rose-600" />
                  </div>
                  <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-4 italic">Estúdio ao Vivo</h2>
                  <p className="text-slate-400 max-w-sm mb-12 font-medium uppercase text-[10px] tracking-widest leading-relaxed">Conecte-se instantaneamente com seus alunos agora mesmo.</p>
                  <button onClick={startLive} className="bg-slate-900 text-white px-12 py-6 rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-rose-600 transition-all active:scale-95 flex items-center gap-3">
                    <Tv size={20}/> Abrir Sala Virtual
                  </button>
               </div>

               {/* Agendamentos */}
               <div className="bg-white p-12 rounded-[4rem] border border-slate-200 shadow-sm flex flex-col h-full overflow-hidden">
                  <div className="flex items-center justify-between mb-8">
                     <div className="flex items-center gap-3">
                        <div className="p-3 bg-amber-50 text-amber-600 rounded-2xl"><Calendar size={20}/></div>
                        <h3 className="font-black text-slate-900 uppercase text-xs tracking-tighter">Agenda Acadêmica</h3>
                     </div>
                     <button onClick={() => setIsScheduleModalOpen(true)} className="p-3 bg-slate-900 text-white rounded-2xl hover:bg-indigo-600 transition-all"><Plus size={20}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto space-y-4 pr-2">
                     {scheduledClasses.map(s => (
                       <div key={s.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl group hover:border-indigo-200 hover:bg-white transition-all">
                          <div className="flex justify-between items-start">
                             <div className="flex flex-col">
                                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.15em] mb-1">{new Date(s.date).toLocaleString()}</span>
                                <span className="font-black text-slate-900 uppercase text-sm leading-tight tracking-tight">{s.title}</span>
                             </div>
                             <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                                <button onClick={async () => { if(confirm('Excluir agendamento?')) await deleteDoc(doc(db, 'scheduledClasses', s.id)); }} className="p-2 text-slate-300 hover:text-rose-500"><Trash2 size={16}/></button>
                             </div>
                          </div>
                       </div>
                     ))}
                     {scheduledClasses.length === 0 && (
                       <div className="flex flex-col items-center justify-center py-20 text-slate-300 font-black uppercase text-[10px] tracking-widest italic">Nenhuma aula programada.</div>
                     )}
                  </div>
               </div>
            </div>
          ) : (
            <div className="fixed inset-0 z-[500] bg-[#1a1a1a] flex flex-col text-white animate-in fade-in duration-500 overflow-hidden">
              {/* Overlay Top: Status */}
              <div className="absolute top-0 left-0 right-0 z-50 p-6 flex items-center justify-between bg-gradient-to-b from-black/80 to-transparent pointer-events-none">
                 <div className="flex items-center gap-4 pointer-events-auto">
                    <div className="bg-rose-600 px-4 py-2 rounded-full flex items-center gap-2 shadow-2xl">
                       <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
                       <span className="text-[10px] font-black uppercase tracking-[0.2em]">AO VIVO</span>
                    </div>
                    <div className="bg-black/50 backdrop-blur-md px-5 py-2 rounded-full border border-white/10 flex items-center gap-3">
                       <Users size={14} className="text-white/60"/>
                       <span className="text-[10px] font-black uppercase tracking-widest">{allStudents.length} Alunos</span>
                    </div>
                 </div>
                 <div className="flex items-center gap-4 pointer-events-auto">
                    <div className="bg-black/40 backdrop-blur-md px-6 py-3 rounded-[2rem] border border-white/5 text-[10px] font-black uppercase tracking-[0.2em] shadow-2xl">
                       Estúdio: {user.displayName}
                    </div>
                 </div>
              </div>

              {/* Main Area: Stream & Side Chat */}
              <div className="flex-1 flex overflow-hidden">
                 <div className="flex-1 relative flex items-center justify-center p-4 lg:p-12">
                    <div className={`w-full h-full max-w-[1920px] max-h-[1080px] aspect-video bg-slate-900 rounded-[3rem] overflow-hidden shadow-[0_40px_100px_rgba(0,0,0,0.8)] border border-white/5 relative group transition-all duration-700 ${isChatOpen ? 'lg:mr-8' : ''}`}>
                       <video 
                         ref={videoRef} 
                         autoPlay 
                         playsInline 
                         muted 
                         className={`w-full h-full object-cover transition-all duration-700 ${videoActive ? 'scale-100 opacity-100' : 'scale-110 opacity-0'} ${activeBackground === 'blur' ? 'blur-md' : ''}`}
                       />

                       {!videoActive && (
                         <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#0a0a0a] animate-in fade-in">
                           <div className="w-40 h-40 rounded-full bg-indigo-600 flex items-center justify-center text-5xl font-black border-[10px] border-white/5 shadow-2xl">
                             {user.displayName.charAt(0)}
                           </div>
                           <p className="mt-10 text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Câmera em Stand-by</p>
                         </div>
                       )}

                       {/* Controls Overlay (Bottom) */}
                       <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-[#0a0a0a]/80 backdrop-blur-3xl px-8 py-5 rounded-[2.5rem] border border-white/10 opacity-0 group-hover:opacity-100 transition-all shadow-2xl scale-95 group-hover:scale-100">
                          <button onClick={toggleMic} className={`p-4 rounded-2xl transition-all ${micActive ? 'bg-white/5 hover:bg-white/10' : 'bg-rose-600 hover:bg-rose-700 shadow-lg shadow-rose-900/50'}`}>
                             {micActive ? <Mic size={20}/> : <MicOff size={20}/>}
                          </button>
                          <button onClick={toggleVideo} className={`p-4 rounded-2xl transition-all ${videoActive ? 'bg-white/5 hover:bg-white/10' : 'bg-rose-600 hover:bg-rose-700 shadow-lg shadow-rose-900/50'}`}>
                             {videoActive ? <Video size={20}/> : <VideoOff size={20}/>}
                          </button>
                          <div className="w-px h-8 bg-white/10 mx-2"></div>
                          <button onClick={startScreenShare} className={`p-4 rounded-2xl transition-all ${screenShareActive ? 'bg-indigo-600' : 'bg-white/5 hover:bg-white/10'}`}>
                             <Monitor size={20}/>
                          </button>
                          <button onClick={flipCamera} className="p-4 rounded-2xl bg-white/5 hover:bg-white/10">
                             <RefreshCw size={20}/>
                          </button>
                          <div className="w-px h-8 bg-white/10 mx-2"></div>
                          <button onClick={stopLive} className="px-8 py-4 bg-rose-600 hover:bg-rose-700 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl flex items-center gap-3">
                             <PhoneOff size={16}/> Encerrar
                          </button>
                       </div>

                       {/* Effects Side Bar */}
                       <div className="absolute right-8 top-1/2 -translate-y-1/2 flex flex-col gap-4 opacity-0 group-hover:opacity-100 transition-all">
                          <button 
                            onClick={() => setActiveBackground(activeBackground === 'blur' ? 'none' : 'blur')}
                            className={`p-4 rounded-2xl border transition-all ${activeBackground === 'blur' ? 'bg-indigo-600 border-indigo-500 shadow-lg shadow-indigo-900' : 'bg-black/60 border-white/5 hover:bg-black/80'}`}
                          >
                            <Sparkles size={20}/>
                          </button>
                          <button onClick={() => setIsChatOpen(!isChatOpen)} className={`p-4 rounded-2xl border transition-all ${isChatOpen ? 'bg-indigo-600 border-indigo-500' : 'bg-black/60 border-white/5'}`}>
                            <MessageSquare size={20}/>
                          </button>
                       </div>
                    </div>
                 </div>

                 {/* Side Chat Panel */}
                 {isChatOpen && (
                   <div className="w-full lg:w-96 bg-[#0f0f0f] border-l border-white/5 flex flex-col animate-in slide-in-from-right duration-500 h-full">
                      <div className="p-8 border-b border-white/5 flex items-center justify-between">
                         <h4 className="text-[11px] font-black uppercase tracking-widest">Chat em Tempo Real</h4>
                         <button onClick={() => setIsChatOpen(false)} className="text-white/40 hover:text-white"><X size={18}/></button>
                      </div>
                      <div className="flex-1 overflow-y-auto p-8 space-y-6">
                         {chatMessages.map((msg, i) => (
                           <div key={i} className="animate-in fade-in slide-in-from-bottom-2">
                              <div className="flex items-center gap-2 mb-1">
                                 <span className="text-[10px] font-black uppercase text-indigo-400">{msg.user}</span>
                                 <span className="text-[8px] font-bold text-white/20 uppercase">{msg.time}</span>
                              </div>
                              <p className="text-xs font-medium text-white/60 leading-relaxed bg-white/5 p-4 rounded-2xl">{msg.text}</p>
                           </div>
                         ))}
                         {chatMessages.length === 0 && (
                           <div className="h-full flex flex-col items-center justify-center text-center p-10 opacity-20">
                              <MessageSquare size={48} className="mb-4" />
                              <p className="text-[10px] font-black uppercase tracking-widest leading-loose italic">Aguardando interações discentes...</p>
                           </div>
                         )}
                      </div>
                      <div className="p-8 bg-black/40 border-t border-white/5">
                         <div className="relative">
                            <input 
                              value={chatMessage} 
                              onChange={e => setChatMessage(e.target.value)} 
                              onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                              placeholder="Fale com a turma..." 
                              className="w-full bg-white/5 border-none rounded-2xl px-6 py-4 text-xs font-bold focus:ring-2 focus:ring-indigo-600 outline-none" 
                            />
                            <button onClick={handleSendMessage} className="absolute right-2 top-1/2 -translate-y-1/2 p-3 text-indigo-500 hover:text-indigo-400"><Send size={18}/></button>
                         </div>
                      </div>
                   </div>
                 )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* MODAL AGENDAMENTO */}
      {isScheduleModalOpen && (
        <div className="fixed inset-0 z-[600] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-12 shadow-2xl animate-in zoom-in-95 overflow-hidden">
              <div className="flex items-center gap-6 mb-12">
                 <div className="p-5 bg-amber-50 text-amber-600 rounded-[2rem] shadow-sm"><Bell size={32} /></div>
                 <div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Programar Aula</h3><p className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic">Notificação automática aos alunos</p></div>
              </div>
              <div className="space-y-6">
                 <input value={newClass.title} onChange={e => setNewClass({...newClass, title: e.target.value})} placeholder="Título da Aula Virtual..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none focus:ring-2 focus:ring-indigo-600 font-bold shadow-sm" />
                 <select value={newClass.courseId} onChange={e => setNewClass({...newClass, courseId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] text-[10px] font-black uppercase shadow-sm">
                    <option value="">Vincular a uma Disciplina...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                 </select>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Data e Hora do Evento</label>
                    <input type="datetime-local" value={newClass.date} onChange={e => setNewClass({...newClass, date: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-bold shadow-sm" />
                 </div>
                 <textarea value={newClass.description} onChange={e => setNewClass({...newClass, description: e.target.value})} placeholder="Objetivos pedagógicos desta transmissão..." className="w-full px-8 py-6 bg-slate-50 border-none rounded-[1.5rem] outline-none h-32 resize-none font-medium text-sm leading-relaxed shadow-sm"></textarea>
              </div>
              <div className="flex gap-4 pt-10">
                 <button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase">Cancelar</button>
                 <button onClick={handleScheduleClass} className="flex-1 py-6 bg-slate-900 text-white rounded-3xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.2em]">Confirmar e Notificar</button>
              </div>
           </div>
        </div>
      )}

      {/* OTHER MODALS (SignaturePad, ModuleModal, etc) remains but with refreshed aesthetics */}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital Institucional" onCancel={() => setIsSignModalOpen(false)} onSave={saveSignature} />}

      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-md rounded-[3.5rem] p-10 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-2xl font-black text-slate-900 mb-10 uppercase tracking-tighter">Novo Módulo Acadêmico</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-600 font-bold mb-8 shadow-sm" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Descartar</button>
                <button onClick={handleSaveModule} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700">Criar Agora</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string;
  role: UserRole;
  photoURL?: string;
  signatureUrl?: string;
}

export interface ScheduledClass {
  id: string;
  courseId: string;
  professorId: string;
  title: string;
  description: string;
  date: any;
  status: 'scheduled' | 'live' | 'finished';
  createdAt: any;
}

export interface Notification {
  id: string;
  userId: string;
  title: string;
  message: string;
  date: any;
  type: 'class_scheduled' | 'system';
  read: boolean;
  archived: boolean;
  calendarData?: any;
}

export interface Lesson {
  id: string;
  title: string;
  description?: string;
  videoUrl: string;
  materialUrl?: string;
  order: number;
}

export interface Module {
  id: string;
  courseId: string;
  title: string;
  order: number;
  lessons: Lesson[];
}

export interface Course {
  id: string;
  nome: string;
  descricao?: string;
  tema: string;
  categoria: string;
  nivelDificuldade: 'Iniciante' | 'Intermediário' | 'Avançado';
  professorResponsavel: string;
  professorId: string;
  capaUrl: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
  // Added missing properties identified in views/ProfessorView.tsx
  biografiaDocente?: string;
  fotoDocenteUrl?: string;
  materialApoioUrl?: string;
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctOption: number;
}

export interface Exam {
  id: string;
  title: string;
  courseId: string;
  moduleId: string;
  type: 'activity' | 'evaluation';
  passingGrade: number;
  questions: Question[];
  authorId?: string;
}

export interface Material {
  id: string;
  courseId: string;
  title: string;
  type: 'pdf' | 'video' | 'link' | 'drive';
  url: string;
}

export interface Feedback {
  id: string;
  userId: string;
  courseId: string;
  rating: number;
  comment: string;
  type: 'elogio' | 'sugestao' | 'reclamacao';
  userName?: string;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy,
  getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question,
  ScheduledClass
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  ExternalLink,
  Award,
  Edit3,
  Eye,
  Calendar,
  ClipboardList,
  PlayCircle,
  TrendingUp,
  Tv,
  PenTool,
  Users,
  Mic,
  MicOff,
  Video,
  VideoOff,
  Monitor,
  PhoneOff,
  MoreVertical,
  MessageSquare,
  Sparkles,
  RefreshCw,
  Send,
  Bell
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [stream, setStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [activeBackground, setActiveBackground] = useState<'none' | 'blur' | 'office'>('none');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);

  // Agendamento State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [newClass, setNewClass] = useState({ title: '', description: '', date: '', courseId: '' });

  // Outros States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const fetchSignature = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) setUserSignature(userDoc.data().signatureUrl || null);
      }
    };
    fetchSignature();

    const qSched = query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid), orderBy('date', 'asc'));
    unsubscribes.push(onSnapshot(qSched, (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // LIVE LOGIC
  const startLive = async () => {
    try {
      const userStream = await navigator.mediaDevices.getUserMedia({ 
        video: { width: { ideal: 1920 }, height: { ideal: 1080 }, facingMode: facingMode }, 
        audio: true 
      });
      setStream(userStream);
      if (videoRef.current) videoRef.current.srcObject = userStream;
      setIsLiveActive(true);
    } catch (err) { alert("Permissão de mídia negada."); }
  };
  const stopLive = () => { stream?.getTracks().forEach(t => t.stop()); setStream(null); setIsLiveActive(false); setScreenShareActive(false); };
  const toggleMic = () => { if (stream) { const track = stream.getAudioTracks()[0]; track.enabled = !track.enabled; setMicActive(track.enabled); } };
  const toggleVideo = () => { if (stream) { const track = stream.getVideoTracks()[0]; track.enabled = !track.enabled; setVideoActive(track.enabled); } };
  const startScreenShare = async () => { try { const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true }); if (videoRef.current) videoRef.current.srcObject = screenStream; setScreenShareActive(true); screenStream.getVideoTracks()[0].onended = () => { if (videoRef.current && stream) videoRef.current.srcObject = stream; setScreenShareActive(false); }; } catch (err) { console.error(err); } };
  const flipCamera = async () => { const newMode = facingMode === 'user' ? 'environment' : 'user'; setFacingMode(newMode); if (isLiveActive) { stream?.getTracks().forEach(t => t.stop()); const newStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: newMode }, audio: true }); setStream(newStream); if (videoRef.current) videoRef.current.srcObject = newStream; } };
  const handleSendMessage = () => { if (!chatMessage.trim()) return; setChatMessages([...chatMessages, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) }]); setChatMessage(''); };

  // AGENDAMENTO
  const handleScheduleClass = async () => {
    if (!newClass.title || !newClass.date || !newClass.courseId) return;
    await addDoc(collection(db, 'scheduledClasses'), { ...newClass, professorId: user.uid, status: 'scheduled', createdAt: serverTimestamp() });
    const studentQuery = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const studentSnap = await getDocs(studentQuery);
    studentSnap.forEach(async (student) => {
      await addDoc(collection(db, 'notifications'), { userId: student.id, title: `Aula Agendada: ${newClass.title}`, message: `Nova aula programada para ${new Date(newClass.date).toLocaleString()}.`, date: newClass.date, type: 'class_scheduled', read: false, archived: false });
    });
    setIsScheduleModalOpen(false);
    setNewClass({ title: '', description: '', date: '', courseId: '' });
  };

  // HANDLERS GERAIS
  const saveSignature = async (b64: string) => { if(auth.currentUser) { await updateDoc(doc(db, 'users', auth.currentUser.uid), { signatureUrl: b64 }); setUserSignature(b64); setIsSignModalOpen(false); }};
  const handleSaveModule = async () => { if(!moduleTitle) return; await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); setModuleTitle(''); setIsModuleModalOpen(false); };
  const handleSaveLesson = async () => { if(!lessonTitle || !currentModuleId) return; const mod = modules.find(m => m.id === currentModuleId); if(!mod) return; const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? {...l, title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc} : l) : [...(mod.lessons||[]), {id: Math.random().toString(36).substr(2,9), title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc, order: (mod.lessons?.length||0)+1}]; await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: up }); setIsLessonModalOpen(false); setEditingLessonId(null); };
  const handleSaveExam = async () => { const payload = { title: examTitle, courseId: selectedCourseForModules, moduleId: selectedModuleForExam, type: examType, passingGrade, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); setCurrentExam(null); };
  const handleSaveMaterial = async () => { if(!materialTitle || !materialUrl) return; await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); };

  const feedbackStats = useMemo(() => {
    if (feedbacks.length === 0) return { avg: "0", elogios: 0, sugestoes: 0, alertas: 0 };
    const avg = feedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / feedbacks.length;
    return { avg: avg.toFixed(1), elogios: feedbacks.filter(f => f.type === 'elogio').length, sugestoes: feedbacks.filter(f => f.type === 'sugestao').length, alertas: feedbacks.filter(f => f.type === 'reclamacao').length };
  }, [feedbacks]);

  const filteredMaterials = useMemo(() => materials.filter(m => m.courseId === selectedCourseForModules), [materials, selectedCourseForModules]);

  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase leading-none">{title}</h1>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">{desc}</p>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500 h-full">

      {/* 1. MÓDULOS E LIÇÕES */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm">
            <Header title="Matriz de Ensino" desc="Hierarquia de conteúdo e lições acadêmicas." icon={<Layers size={24} />} />
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 flex items-center gap-2 hover:bg-indigo-700 transition-all"><Plus size={16}/> Novo Módulo</button>
            </div>
          </div>
          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[2.5rem] overflow-hidden">
                <div className="p-8 bg-slate-50 border-b flex items-center justify-between">
                   <div className="flex items-center gap-4">
                      <div className="p-3 bg-white rounded-xl shadow-sm text-indigo-500"><Layers size={20}/></div>
                      <h3 className="font-black text-slate-800 uppercase text-xs tracking-widest">{mod.title}</h3>
                   </div>
                   <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setIsLessonModalOpen(true); }} className="px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:scale-105 transition-all">Adicionar Aula</button>
                </div>
                <div className="p-8 grid grid-cols-1 gap-3">
                   {(mod.lessons || []).map((l, i) => (
                     <div key={l.id} className="p-5 bg-slate-50/50 border border-transparent hover:border-indigo-100 hover:bg-white rounded-2xl flex items-center justify-between group transition-all">
                        <div className="flex items-center gap-4">
                           <span className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover:text-indigo-600 group-hover:border-indigo-500 transition-all">{i+1}</span>
                           <span className="font-bold text-slate-800 text-sm">{l.title}</span>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                           <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonTitle(l.title); setLessonVideoUrl(l.videoUrl); setLessonDesc(l.description||''); setIsLessonModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600"><Edit3 size={16}/></button>
                           <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), {lessons: up}); }}} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16}/></button>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm">
            <Header title="Acervo Acadêmico" desc="Repositório de mídias e documentos de apoio." icon={<FileText size={24} />} />
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 flex items-center gap-2 hover:bg-indigo-700 transition-all"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {filteredMaterials.map(m => (
              <div key={m.id} className="bg-white border border-slate-200 p-8 rounded-[2.5rem] relative group shadow-sm hover:border-indigo-300 transition-all">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-6 ${m.type === 'pdf' ? 'bg-rose-50 text-rose-500' : 'bg-indigo-50 text-indigo-500'}`}><FileText size={28} /></div>
                <h4 className="font-black text-slate-900 text-xs leading-tight mb-4 uppercase tracking-tighter">{m.title}</h4>
                <a href={m.url} target="_blank" rel="noreferrer" className="w-full flex items-center justify-center gap-2 py-4 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar Arquivo</a>
                <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'materials', m.id)) }} className="absolute top-8 right-8 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm">
            <Header title="Gestão de Exames" desc="Controle de provas e atividades avaliativas." icon={<CheckSquare size={24} />} />
            <button onClick={() => { setCurrentExam(null); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all shadow-xl shadow-indigo-100"><Plus size={18} /> Criar Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
              <div key={ex.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm relative group hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-8">
                  <div className={`p-4 rounded-2xl ${ex.type === 'evaluation' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Award size={24} /></div>
                  <div className="text-right"><span className="text-[10px] font-black uppercase text-slate-400 tracking-widest block mb-1">Corte</span><span className="text-2xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-sm mb-3 uppercase tracking-tighter">{ex.title}</h4>
                <div className="flex gap-4">
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-colors">Configurar Questões</button>
                  <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'exams', ex.id)) }} className="p-4 bg-slate-50 text-slate-300 rounded-xl hover:text-red-500 transition-colors"><Trash2 size={18}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK */}
      {activeSub === 'feedback' && (
        <div className="space-y-8">
           <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm">
             <div className="flex flex-col md:flex-row gap-8 justify-between items-center">
                <div><h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase mb-2">Mural Pedagógico</h1><p className="text-slate-500 font-medium italic">Reputação e impressões discentes.</p></div>
