              <div className="bg-slate-50 p-12 rounded-[3.5rem] border border-slate-100 mb-12 shadow-sm">
                 <div className="space-y-8">
                    <textarea value={qText} onChange={e => setQText(e.target.value)} placeholder="Enunciado da pergunta..." className="w-full px-8 py-6 border-none rounded-[1.5rem] bg-white font-bold text-sm h-36 shadow-sm" />
                    <div className="grid grid-cols-1 gap-4">
                       {qOptions.map((opt, i) => (
                         <div key={i} className="flex items-center gap-5">
                            <div onClick={() => setQCorrect(i)} className={`w-14 h-14 rounded-2xl flex items-center justify-center cursor-pointer transition-all font-black text-sm shadow-sm ${qCorrect === i ? 'bg-emerald-500 text-white border-none' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>{String.fromCharCode(65 + i)}</div>
                            <input value={opt} onChange={e => { const copy = [...qOptions]; copy[i] = e.target.value; setQOptions(copy); }} placeholder={`Alternativa ${String.fromCharCode(65 + i)}...`} className="flex-1 px-8 py-4 bg-white border-none rounded-2xl outline-none text-xs font-bold shadow-sm" />
                         </div>
                       ))}
                    </div>
                    <button onClick={async () => { if (!currentExam || !qText || qOptions.some(o => !o.trim())) return; const newQuestion: Question = { id: Math.random().toString(36).substr(2, 9), text: qText, options: [...qOptions], correctOption: qCorrect }; const updatedQuestions = [...(currentExam.questions || []), newQuestion]; await updateDoc(doc(db, 'exams', currentExam.id), { questions: updatedQuestions }); setQText(''); setQOptions(['','','','']); }} className="w-full py-6 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700">Adicionar Questão</button>
                 </div>
              </div>
              <div className="space-y-5">
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] flex justify-between items-center shadow-sm">
                      <div className="flex-1 pr-8"><p className="text-xs font-black text-slate-900 uppercase tracking-tighter mb-2">{idx + 1}. {q.text}</p><span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-4 py-1 rounded-full">Correta: {String.fromCharCode(65 + q.correctOption)}</span></div>
                      <button onClick={async () => { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); }} className="p-4 text-slate-200 hover:text-red-500 transition-all"><Trash2 size={20}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter text-center">Adicionar Recurso</h3>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo" className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-sm" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] text-[10px] font-black uppercase shadow-sm"><option value="pdf">PDF</option><option value="link">Link</option><option value="drive">Drive</option></select>
              </div>
              <div className="flex gap-4 pt-6"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button><button onClick={handleSaveMaterial} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Cadastrar</button></div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Digital Institucional" onCancel={() => setIsSignModalOpen(false)} onSave={saveSignature} />}

    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy,
  getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question,
  ScheduledClass
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  ExternalLink,
  Award,
  Edit3,
  Eye,
  Calendar,
  ClipboardList,
  PlayCircle,
  TrendingUp,
  Tv,
  PenTool,
  Users,
  Mic,
  MicOff,
  Video,
  VideoOff,
  Monitor,
  PhoneOff,
  MoreVertical,
  MessageSquare,
  Sparkles,
  RefreshCw,
  Send,
  Bell,
  Heart,
  Smile,
  ThumbsUp,
  Clapperboard,
  UserX,
  Volume2,
  VolumeX,
  ShieldCheck
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [stream, setStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [activeBackground, setActiveBackground] = useState<'none' | 'blur' | 'office'>('none');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [isParticipantsOpen, setIsParticipantsOpen] = useState(false);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string}[]>([]);

  // Modais de Pós-Aula
  const [showSatisfactionSurvey, setShowSatisfactionSurvey] = useState(false);

  // Agendamento State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [newClass, setNewClass] = useState({ title: '', description: '', date: '', courseId: '' });

  // Matriz & Assinatura States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  // Preview Mode
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const fetchSignature = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) setUserSignature(userDoc.data().signatureUrl || null);
      }
    };
    fetchSignature();

    const qSched = query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid), orderBy('date', 'asc'));
    unsubscribes.push(onSnapshot(qSched, (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // LIVE LOGIC
  const startLive = async () => {
    try {
      const userStream = await navigator.mediaDevices.getUserMedia({ 
        video: { width: { ideal: 1920 }, height: { ideal: 1080 }, facingMode: facingMode }, 
        audio: true 
      });
      setStream(userStream);
      if (videoRef.current) videoRef.current.srcObject = userStream;
      setIsLiveActive(true);
    } catch (err) { alert("Câmera ou Microfone não detectados."); }
  };

  const stopLive = () => {
    stream?.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsLiveActive(false);
    setScreenShareActive(false);
    setShowSatisfactionSurvey(true);
  };

  const toggleMic = () => { if (stream) { const track = stream.getAudioTracks()[0]; track.enabled = !track.enabled; setMicActive(track.enabled); } };
  const toggleVideo = () => { if (stream) { const track = stream.getVideoTracks()[0]; track.enabled = !track.enabled; setVideoActive(track.enabled); } };

  const addReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 4000);
  };

  const flipCamera = async () => {
    const newMode = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(newMode);
    if (isLiveActive) {
      stream?.getTracks().forEach(t => t.stop());
      const newStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: newMode }, audio: true });
      setStream(newStream);
      if (videoRef.current) videoRef.current.srcObject = newStream;
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screenStream;
      setScreenShareActive(true);
      screenStream.getVideoTracks()[0].onended = () => {
        if (videoRef.current && stream) videoRef.current.srcObject = stream;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  // HANDLERS GERAIS
  const saveSignature = async (b64: string) => { if(auth.currentUser) { await updateDoc(doc(db, 'users', auth.currentUser.uid), { signatureUrl: b64 }); setUserSignature(b64); setIsSignModalOpen(false); }};
  const handleSaveModule = async () => { if(!moduleTitle) return; await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); setModuleTitle(''); setIsModuleModalOpen(false); };
  const handleSaveLesson = async () => { if(!lessonTitle || !currentModuleId) return; const mod = modules.find(m => m.id === currentModuleId); if(!mod) return; const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? {...l, title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc} : l) : [...(mod.lessons||[]), {id: Math.random().toString(36).substr(2,9), title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc, order: (mod.lessons?.length||0)+1}]; await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: up }); setIsLessonModalOpen(false); setEditingLessonId(null); };
  const handleSaveExam = async () => { const payload = { title: examTitle, courseId: selectedCourseForModules, moduleId: selectedModuleForExam, type: examType, passingGrade, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); setCurrentExam(null); };
  const handleSaveMaterial = async () => { if(!materialTitle || !materialUrl) return; await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); };

  const Header = ({ title, desc, icon }: { title: string, desc: string, icon?: React.ReactNode }) => (
    <div className="flex items-center gap-4 mb-6">
      {icon && <div className="p-3 bg-white border border-slate-200 rounded-2xl text-indigo-600 shadow-sm">{icon}</div>}
      <div>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase leading-none">{title}</h1>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">{desc}</p>
      </div>
    </div>
  );

  if (isPreviewMode) {
    return (
      <div className="fixed inset-0 z-[600] bg-slate-950 flex flex-col text-white animate-in fade-in duration-300">
        <div className="p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 px-3 py-1 rounded text-[10px] font-black uppercase">Modo Preview Professor</div>
            <h2 className="text-sm font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</h2>
          </div>
          <button onClick={() => setIsPreviewMode(false)} className="px-6 py-2 bg-white text-slate-900 rounded-xl text-xs font-black uppercase hover:bg-slate-200 transition-all">Sair do Preview</button>
        </div>
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
          <div className="flex-1 bg-black flex items-center justify-center p-8">
             <div className="aspect-video w-full max-w-4xl bg-slate-900 rounded-3xl flex flex-col items-center justify-center border border-white/5 shadow-2xl">
                <PlayCircle size={80} className="text-white/20 mb-4" />
                <p className="text-xs font-bold uppercase tracking-[0.2em] text-white/40 italic">Interface do Aluno Simulada</p>
             </div>
          </div>
          <div className="w-full lg:w-96 border-l border-white/10 bg-slate-900/50 p-8 overflow-y-auto">
             <h3 className="text-[10px] font-black uppercase text-white/40 tracking-[0.3em] mb-8">Trilha Acadêmica</h3>
             <div className="space-y-6">
               {modules.map(mod => (
                 <div key={mod.id} className="space-y-3">
                   <p className="text-[11px] font-black text-white uppercase border-b border-white/10 pb-2 flex justify-between items-center">
                    {mod.title}
                    <Layers size={12} className="text-white/20"/>
                   </p>
                   {(mod.lessons || []).map(l => <div key={l.id} className="p-4 bg-white/5 rounded-2xl text-[10px] font-bold text-white/60 hover:bg-white/10 cursor-pointer transition-all uppercase tracking-tight">{l.title}</div>)}
                   {exams.filter(e => e.moduleId === mod.id).map(e => <div key={e.id} className="p-4 bg-amber-500/10 rounded-2xl text-[10px] font-black text-amber-500 uppercase border border-amber-500/20 shadow-lg shadow-amber-900/20">AVALIAÇÃO: {e.title}</div>)}
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="h-full flex flex-col items-center justify-center p-20 gap-4 text-center">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div>
      <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Sincronizando Ecossistema Pedagógico...</p>
    </div>
  );

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500 h-full">

      {/* 1. MÓDULOS E LIÇÕES - RESTAURADA COM EXAMES */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[3.5rem] border border-slate-200 shadow-sm">
            <Header title="Matriz Curricular" desc="Hierarquia completa de lições e checkpoints acadêmicos." icon={<Layers size={24} />} />

            <div className="flex items-center gap-6">
               {userSignature ? (
                 <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-2xl border border-slate-100">
                    <img src={userSignature} alt="Assinatura" className="h-8 grayscale object-contain" />
                    <button onClick={() => setIsSignModalOpen(true)} className="p-2 bg-white rounded-xl border text-indigo-600 hover:bg-indigo-50 transition-colors shadow-sm"><Edit3 size={14}/></button>
                 </div>
               ) : (
                 <button onClick={() => setIsSignModalOpen(true)} className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 border-2 border-indigo-100 px-5 py-3 rounded-2xl hover:bg-indigo-50 transition-all shadow-sm">
                    <PenTool size={14}/> Assinar para Certificados
                 </button>
               )}
               <div className="h-10 w-px bg-slate-200"></div>
               <div className="flex items-center gap-3">
                <button onClick={() => setIsPreviewMode(true)} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 hover:bg-slate-200 transition-all shadow-sm"><Eye size={16}/> Preview</button>
                <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm">
                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all tracking-widest"><Plus size={16} /> Novo Módulo</button>
              </div>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[3.5rem] overflow-hidden shadow-sm hover:border-indigo-100 transition-all group">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm transition-transform group-hover:scale-110"><Layers size={20} /></div>
                      <div>
                        <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest italic">{mod.title}</h3>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-1">{mod.lessons?.length || 0} Lições • {moduleExams.length} Avaliações</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setIsLessonModalOpen(true); }} className="text-[9px] font-black uppercase bg-indigo-600 text-white px-6 py-3 rounded-xl shadow-lg hover:scale-105 transition-all tracking-widest">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-8 grid grid-cols-1 gap-4 bg-gradient-to-b from-white to-slate-50/20">
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-white p-5 rounded-[2rem] flex gap-6 items-center border border-slate-100 hover:border-indigo-100 hover:shadow-xl hover:shadow-indigo-500/5 transition-all group/lesson">
                        <div className="w-10 h-10 rounded-full bg-slate-50 border border-slate-100 flex items-center justify-center font-black text-slate-400 text-[10px] group-hover/lesson:bg-indigo-600 group-hover/lesson:text-white group-hover/lesson:border-none transition-all">{idx + 1}</div>
                        <div className="flex-1">
                          <h4 className="font-black text-slate-900 text-xs uppercase tracking-tight italic">{lesson.title}</h4>
                          <div className="flex gap-2 mt-1">
                             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded">Aula #{idx+1}</span>
