                    {(currentExam.questions || []).map((q, idx) => (
                      <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] flex justify-between items-center shadow-sm hover:shadow-xl hover:border-indigo-100 transition-all group">
                         <div className="flex-1 pr-10">
                            <div className="flex items-center gap-4 mb-3">
                               <span className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center text-[10px] font-black italic">{idx + 1}</span>
                               <p className="text-xs font-black text-slate-900 uppercase tracking-tighter leading-tight italic">{q.text}</p>
                            </div>
                            <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-4 py-1.5 rounded-full border border-emerald-100 shadow-sm">Gabarito: {String.fromCharCode(65 + q.correctOption)}</span>
                         </div>
                         <button onClick={async () => { if(confirm('Excluir esta questão?')) { const up = currentExam.questions.filter(item => item.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); } }} className="p-5 bg-slate-50 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all shadow-sm border border-slate-100"><Trash2 size={24}/></button>
                      </div>
                    ))}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL MATERIAIS */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-12 space-y-8 shadow-2xl animate-in zoom-in-95 overflow-hidden">
              <div className="text-center">
                 <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6 text-indigo-600 shadow-inner"><FileText size={40}/></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic">Adicionar Recurso</h3>
                 <p className="text-xs text-slate-400 font-medium mb-10 italic">Disponibilize arquivos PDF ou links externos.</p>
              </div>
              <div className="space-y-6">
                <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-inner" />
                <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold shadow-inner" />
                <select value={materialType} onChange={e => setMaterialType(e.target.value as any)} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] text-[10px] font-black uppercase shadow-inner"><option value="pdf">Documento PDF</option><option value="link">Link Externo</option><option value="drive">Pasta no Cloud</option></select>
              </div>
              <div className="flex gap-4 pt-10">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={handleSaveMaterial} className="flex-1 py-6 bg-indigo-600 text-white rounded-3xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all tracking-widest">Cadastrar Material</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default SchoolManagement;

