  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [stream, setStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [activeBackground, setActiveBackground] = useState<'none' | 'blur' | 'office'>('none');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [isParticipantsOpen, setIsParticipantsOpen] = useState(false);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string}[]>([]);

  // Modais de Pós-Aula
