  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses && courses.length > 0 ? courses[0].id : ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [moduleTitle, setModuleTitle] = useState('');
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonVideoUrl, setLessonVideoUrl] = useState('');
  const [lessonDesc, setLessonDesc] = useState('');
  const [lessonMaterialUrl, setLessonMaterialUrl] = useState('');
  const [selectedMaterialId, setSelectedMaterialId] = useState('');

  // Avaliação State
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [examTitle, setExamTitle] = useState('');
  const [examType, setExamType] = useState<'activity' | 'evaluation'>('activity');
  const [passingGrade, setPassingGrade] = useState(70);
  const [selectedModuleForExam, setSelectedModuleForExam] = useState('');
  const [qText, setQText] = useState('');
  const [qOptions, setQOptions] = useState(['', '', '', '']);
  const [qCorrect, setQCorrect] = useState(0);

  // Materiais State
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [materialType, setMaterialType] = useState<'pdf' | 'link' | 'drive'>('pdf');

  // Preview Mode
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  // Fix: Missing filteredMaterials variable
  const filteredMaterials = useMemo(() => {
    return materials.filter(m => m.courseId === selectedCourseForModules);
  }, [materials, selectedCourseForModules]);

  // Fix: Missing feedbackStats variable
  const feedbackStats = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const avg = relevant.length > 0 ? (relevant.reduce((acc, f) => acc + f.rating, 0) / relevant.length).toFixed(1) : '0.0';
    return {
      avg,
      elogios: relevant.filter(f => f.type === 'elogio').length,
      sugestoes: relevant.filter(f => f.type === 'sugestao').length,
      alertas: relevant.filter(f => f.type === 'reclamacao').length,
    };
  }, [feedbacks, selectedCourseForModules]);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const fetchSignature = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) setUserSignature(userDoc.data().signatureUrl || null);
      }
    };
    fetchSignature();

    const qSched = query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid), orderBy('date', 'asc'));
    unsubscribes.push(onSnapshot(qSched, (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    const qEx = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qEx, (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(query(collection(db, 'materials'), orderBy('createdAt', 'desc')), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'feedbacks'), orderBy('createdAt', 'desc')), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    const fetchStudents = async () => {
      const qS = query(collection(db, 'users'), where('role', '==', 'aluno'));
      const snapS = await getDocs(qS);
      setAllStudents(snapS.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    };
    fetchStudents();

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // LIVE LOGIC
  const startLive = async () => {
    try {
      const userStream = await navigator.mediaDevices.getUserMedia({ 
        video: { width: { ideal: 1920 }, height: { ideal: 1080 }, facingMode: facingMode }, 
        audio: true 
      });
      setStream(userStream);
      if (videoRef.current) videoRef.current.srcObject = userStream;
      setIsLiveActive(true);
    } catch (err) { alert("Câmera ou Microfone não detectados."); }
  };

  const stopLive = () => {
    stream?.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsLiveActive(false);
    setScreenShareActive(false);
    setShowSatisfactionSurvey(true);
  };

  const toggleMic = () => { if (stream) { const track = stream.getAudioTracks()[0]; track.enabled = !track.enabled; setMicActive(track.enabled); } };
  const toggleVideo = () => { if (stream) { const track = stream.getVideoTracks()[0]; track.enabled = !track.enabled; setVideoActive(track.enabled); } };

  const addReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 4000);
  };

  const flipCamera = async () => {
    const newMode = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(newMode);
    if (isLiveActive) {
      stream?.getTracks().forEach(t => t.stop());
      const newStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: newMode }, audio: true });
      setStream(newStream);
      if (videoRef.current) videoRef.current.srcObject = newStream;
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screenStream;
      setScreenShareActive(true);
      screenStream.getVideoTracks()[0].onended = () => {
        if (videoRef.current && stream) videoRef.current.srcObject = stream;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  // Fix: Missing handleSendMessage function
  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    const newMessage = {
      user: user.displayName,
      text: chatMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChatMessages(prev => [...prev, newMessage]);
    setChatMessage('');
  };

  // HANDLERS GERAIS
  const saveSignature = async (b64: string) => { if(auth.currentUser) { await updateDoc(doc(db, 'users', auth.currentUser.uid), { signatureUrl: b64 }); setUserSignature(b64); setIsSignModalOpen(false); }};
  const handleSaveModule = async () => { if(!moduleTitle) return; await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); setModuleTitle(''); setIsModuleModalOpen(false); };
  const handleSaveLesson = async () => { if(!lessonTitle || !currentModuleId) return; const mod = modules.find(m => m.id === currentModuleId); if(!mod) return; const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? {...l, title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc} : l) : [...(mod.lessons||[]), {id: Math.random().toString(36).substr(2,9), title: lessonTitle, videoUrl: lessonVideoUrl, description: lessonDesc, order: (mod.lessons?.length||0)+1}]; await updateDoc(doc(db, 'modulos', currentModuleId), { lessons: up }); setIsLessonModalOpen(false); setEditingLessonId(null); };
  const handleSaveExam = async () => { const payload = { title: examTitle, courseId: selectedCourseForModules, moduleId: selectedModuleForExam, type: examType, passingGrade, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); setCurrentExam(null); };
  const handleSaveMaterial = async () => { if(!materialTitle || !materialUrl) return; await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: materialType, createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); };

  // Fix: Missing handleScheduleClass function
  const handleScheduleClass = async () => {
    if (!newClass.title || !newClass.date || !newClass.courseId) return;
    await addDoc(collection(db, 'scheduledClasses'), {
      ...newClass,
      professorId: user.uid,
