             </div>
          </div>
          <div className="w-full lg:w-96 border-l border-white/10 bg-slate-900/50 p-8 overflow-y-auto">
             <h3 className="text-[10px] font-black uppercase text-white/40 tracking-[0.3em] mb-8">Trilha Acadêmica</h3>
             <div className="space-y-6">
               {modules.map(mod => (
