                    <Layers size={12} className="text-white/20"/>
                   </p>
                   {(mod.lessons || []).map(l => <div key={l.id} className="p-4 bg-white/5 rounded-2xl text-[10px] font-bold text-white/60 hover:bg-white/10 cursor-pointer transition-all uppercase tracking-tight">{l.title}</div>)}
                   {exams.filter(e => e.moduleId === mod.id).map(e => <div key={e.id} className="p-4 bg-amber-500/10 rounded-2xl text-[10px] font-black text-amber-500 uppercase border border-amber-500/20 shadow-lg shadow-amber-900/20">AVALIAÇÃO: {e.title}</div>)}
                 </div>
