                  {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all tracking-widest"><Plus size={16} /> Novo Módulo</button>
              </div>
            </div>
          </div>

          <div className="space-y-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[3.5rem] overflow-hidden shadow-sm hover:border-indigo-100 transition-all group">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm transition-transform group-hover:scale-110"><Layers size={20} /></div>
