                        <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest italic">{mod.title}</h3>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-1">{mod.lessons?.length || 0} Lições • {moduleExams.length} Avaliações</p>
                      </div>
