                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setIsLessonModalOpen(true); }} className="text-[9px] font-black uppercase bg-indigo-600 text-white px-6 py-3 rounded-xl shadow-lg hover:scale-105 transition-all tracking-widest">Adicionar Aula</button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="text-slate-300 hover:text-red-500 p-2 transition-colors"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-8 grid grid-cols-1 gap-4 bg-gradient-to-b from-white to-slate-50/20">
                    {(mod.lessons || []).map((lesson, idx) => (
                      <div key={lesson.id} className="bg-white p-5 rounded-[2rem] flex gap-6 items-center border border-slate-100 hover:border-indigo-100 hover:shadow-xl hover:shadow-indigo-500/5 transition-all group/lesson">
