  query, 
  onSnapshot, 
  addDoc, 
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp, 
  where,
  getDocs,
  orderBy,
  getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, 
  User, 
  Course, 
  ProfessorSubView, 
  Material, 
  Feedback, 
  Module,
  Lesson,
  Question,
  ScheduledClass
} from './types';
import { 
  CheckSquare, 
  Plus, 
  X, 
  Trash2,
  FileText,
  Radio,
  Layers,
  Star,
  ExternalLink,
  Award,
  Edit3,
  Eye,
  Calendar,
  ClipboardList,
  PlayCircle,
  TrendingUp,
  Tv,
  PenTool,
  Users,
  Mic,
  MicOff,
  Video,
  VideoOff,
  Monitor,
  PhoneOff,
  MoreVertical,
  MessageSquare,
  Sparkles,
  RefreshCw,
  Send,
  Bell,
  Heart,
  Smile,
  ThumbsUp,
  Clapperboard,
  UserX,
  Volume2,
  VolumeX,
  ShieldCheck,
  Settings,
  Presentation,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
