                 </div>
                 <div className="flex items-center justify-between p-6 bg-slate-50 rounded-3xl border border-slate-100">
                    <span className="text-[11px] font-black uppercase text-slate-700 tracking-widest">Chat somente leitura</span>
                    <button className="w-14 h-8 bg-slate-300 rounded-full relative"><div className="absolute left-1 top-1 w-6 h-6 bg-white rounded-full shadow-md"></div></button>
                 </div>
                 <div className="flex items-center justify-between p-6 bg-slate-50 rounded-3xl border border-slate-100">
                    <span className="text-[11px] font-black uppercase text-slate-700 tracking-widest">Permitir Reações</span>
                    <button className="w-14 h-8 bg-indigo-600 rounded-full relative"><div className="absolute right-1 top-1 w-6 h-6 bg-white rounded-full shadow-md"></div></button>
