              </div>
              <button onClick={() => setIsLiveSettingsOpen(false)} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all">Salvar Preferências</button>
