    setIsLessonModalOpen(false);
  };

  const handleSaveExam = async () => {
    const payload = { 
      title: examTitle, 
      courseId: selectedCourseForModules, 
      moduleId: selectedModuleForExam, 
      type: examType, 
      passingGrade, 
      authorId: user.uid, 
      questions: currentExam?.questions || [], 
      createdAt: serverTimestamp() 
