    else await addDoc(collection(db, 'exams'), payload);
    setIsExamModalOpen(false); setCurrentExam(null);
  };

  const handleSaveQuestion = async () => {
    if(!currentExam || !qText) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: qText, options: qOptions, correctOption: qCorrect };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
