      {isExamModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-12 space-y-8 shadow-2xl">
              <div className="flex items-center gap-6">
                 <div className="p-5 bg-amber-50 text-amber-600 rounded-3xl shadow-sm"><Award size={32} /></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic">Configurar Avaliação</h3>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Título do Exame</label>
                    <input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Final de Teologia..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-bold shadow-inner" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Vincular a Módulo</label>
                    <select value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase shadow-inner">
                       <option value="">Nenhum Módulo Selecionado</option>
                       {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                    </select>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Tipo</label>
                       <select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase shadow-inner"><option value="activity">Atividade</option><option value="evaluation">Prova</option></select>
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Corte %</label>
                       <input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-black shadow-inner" />
                    </div>
                 </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={async () => {
                  const payload = { ...examForm, courseId: selectedCourseForModules, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() };
                  if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload);
                  else await addDoc(collection(db, 'exams'), payload);
                  setIsExamModalOpen(false);
                }} className="flex-1 py-6 bg-indigo-600 text-white rounded-3xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Salvar Exame</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, Image as ImageIcon
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [showDeviceMenu, setShowDeviceMenu] = useState<'audio' | 'video' | null>(null);

  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);

  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'green'>('none');

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [isTestExamOpen, setIsTestExamOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Data Fetching
  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    const qExams = query(collection(db, 'exams'), where('authorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qExams, (snap) => setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam))));

    const qSched = query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid));
    unsubscribes.push(onSnapshot(qSched, (snap) => setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass))));

    if (selectedCourseForModules) {
      const qMod = query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules));
      unsubscribes.push(onSnapshot(qMod, (snap) => setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0))));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material))));
    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback))));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const docRef = doc(db, 'users', user.uid);
      const d = await getDoc(docRef);
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // Live Handlers
  const startLive = async (vId?: string, aId?: string) => {
    try {
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
      const constraints = {
        video: vId ? { deviceId: { exact: vId } } : true,
        audio: aId ? { deviceId: { exact: aId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setIsLiveActive(true);
    } catch (err) { alert("Erro ao acessar mídia."); }
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const audioTrack = streamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setMicActive(audioTrack.enabled);
      }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const videoTrack = streamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setVideoActive(videoTrack.enabled);
      }
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screenStream;
      setScreenShareActive(true);
      screenStream.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error("Erro ao compartilhar tela:", err); }
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    const newMessage = {
      user: user.displayName || 'Professor',
      text: chatMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setChatMessages(prev => [...prev, newMessage]);
    setChatMessage('');
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    const left = Math.random() * 80 + 10;
    setActiveReactions(prev => [...prev, { id, emoji, left }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  // Academic Handlers
  const handleSaveLesson = async () => {
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const newLesson = { id: editingLessonId || Math.random().toString(36).substr(2,9), ...lessonForm, order: mod.lessons.length + 1 };
    const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? newLesson : l) : [...mod.lessons, newLesson];
    await updateDoc(doc(db, 'modulos', mod.id), { lessons: up });
    setIsLessonModalOpen(false);
  };

  const handleSaveQuestion = async () => {
    if (!currentExam) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
    // Update local state for immediate feedback
    setCurrentExam({ ...currentExam, questions: up });
  };

  const stats = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const avg = relevant.length > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / relevant.length).toFixed(1) : '0.0';
    return { avg, elogios: relevant.filter(f => f.type === 'elogio').length, alertas: relevant.filter(f => f.type === 'reclamacao').length };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      {/* 1. MÓDULOS & LIÇÕES COMPLETO */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl"><Layers size={24}/></div>
              <div><h1 className="text-xl font-black uppercase tracking-tight italic">Matriz Curricular</h1><p className="text-xs text-slate-400 font-bold uppercase">Gestão de Trilhas Acadêmicas</p></div>
            </div>
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3.5 rounded-xl text-[10px] font-black uppercase shadow-lg flex items-center gap-2"><Plus size={16}/> Novo Módulo</button>
            </div>
          </div>
          <div className="space-y-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[2.5rem] overflow-hidden group shadow-sm">
                <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                  <h3 className="font-black text-slate-800 text-xs uppercase italic">{mod.title}</h3>
                  <div className="flex gap-2">
                    <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-4 py-2.5 bg-indigo-600 text-white text-[9px] font-black uppercase rounded-lg shadow-md hover:scale-105 transition-all">Add Aula</button>
                    <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={18}/></button>
                  </div>
                </div>
                <div className="p-6 space-y-3">
                  {mod.lessons.map((l, i) => (
                    <div key={l.id} className="bg-white p-4 rounded-2xl flex items-center justify-between border border-slate-100 hover:border-indigo-100 transition-all group/l">
                      <div className="flex items-center gap-4">
                        <span className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all">{i+1}</span>
                        <div>
                          <h4 className="font-black text-slate-900 text-[11px] uppercase italic">{l.title}</h4>
                          {l.materialUrl && <span className="text-[8px] font-black text-indigo-500 uppercase flex items-center gap-1 mt-0.5"><FileText size={10}/> Material Vinculado</span>}
                        </div>
                      </div>
                      <div className="flex gap-2 opacity-0 group-hover/l:opacity-100 transition-all">
                        <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit3 size={16}/></button>
                        <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><FileText size={24}/></div>
              <div><h1 className="text-xl font-black uppercase italic">Acervo Digital</h1><p className="text-xs text-slate-400 font-bold uppercase">Repositório de Recursos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3.5 rounded-xl text-[10px] font-black uppercase shadow-lg flex items-center gap-2"><Plus size={16}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 relative group hover:shadow-xl transition-all">
                <FileText size={40} className="text-indigo-500 mb-4" />
                <h4 className="font-black text-slate-900 text-xs uppercase italic mb-4">{m.title}</h4>
                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-2 py-4 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all"><ExternalLink size={14}/> Acessar</a>
                <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-red-500 transition-all"><Trash2 size={20}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÕES COMPLETO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-amber-50 text-amber-600 rounded-2xl"><CheckSquare size={24}/></div>
              <div><h1 className="text-xl font-black uppercase italic">Centro de Exames</h1><p className="text-xs text-slate-400 font-bold uppercase">Avaliação de Desempenho</p></div>
            </div>
            <button onClick={() => { setCurrentExam(null); setExamForm({title:'', moduleId:'', type:'activity', passingGrade:70}); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-6 py-3.5 rounded-xl text-[10px] font-black uppercase shadow-lg flex items-center gap-2"><Plus size={16}/> Criar Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
              <div key={ex.id} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 group relative hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-8">
                  <Award size={40} className={ex.type === 'evaluation' ? 'text-amber-500' : 'text-emerald-500'} />
                  <div className="text-right"><span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Média Corte</span><span className="text-3xl font-black text-slate-900">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-sm uppercase italic mb-6 leading-tight">{ex.title}</h4>
                <div className="flex gap-2">
                  <button onClick={() => { setCurrentExam(ex); setExamForm({title:ex.title, moduleId:ex.moduleId, type:ex.type, passingGrade:ex.passingGrade}); setIsExamModalOpen(true); }} className="flex-1 py-4 bg-slate-50 text-slate-600 rounded-xl text-[9px] font-black uppercase border border-slate-200 hover:bg-indigo-50 transition-all">Configurar</button>
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-indigo-600">Questões ({ex.questions?.length||0})</button>
                  <button onClick={() => { setCurrentExam(ex); setIsTestExamOpen(true); }} className="p-4 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><Play size={18}/></button>
                </div>
                <button onClick={async () => { if(confirm('Excluir exame?')) await deleteDoc(doc(db, 'exams', ex.id)); }} className="absolute top-10 right-10 text-slate-100 hover:text-red-500 transition-all"><Trash2 size={24}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK RESTAURADO */}
      {activeSub === 'feedback' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl"><MessageSquare size={24}/></div>
              <div><h1 className="text-xl font-black uppercase italic">Mural Discente</h1><p className="text-xs text-slate-400 font-bold uppercase">Feedback e Satisfação</p></div>
            </div>
            <div className="flex items-center gap-8">
              <div className="text-center"><p className="text-3xl font-black text-indigo-600 leading-none">{stats.avg}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-1">Média NPS</p></div>
              <div className="text-center"><p className="text-3xl font-black text-emerald-600 leading-none">{stats.elogios}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-1">Elogios</p></div>
              <div className="text-center"><p className="text-3xl font-black text-rose-600 leading-none">{stats.alertas}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-1">Críticas</p></div>
            </div>
          </div>
