                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2.5rem] flex items-center justify-between group shadow-sm hover:border-indigo-100 transition-all">
                      <div className="flex items-center gap-5">
                         <span className="w-10 h-10 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xs italic">{idx+1}</span>
                         <div>
                            <p className="text-xs font-black uppercase italic text-slate-900 leading-tight pr-10">{q.text}</p>
                            <span className="text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-3 py-1 rounded-full mt-2 inline-block">Gabarito: {String.fromCharCode(65+q.correctOption)}</span>
                         </div>
                      </div>
                      <button onClick={async () => { if(confirm('Remover questão?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-4 text-slate-100 hover:text-red-500 transition-all"><Trash2 size={22}/></button>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* PREVIEW DO ALUNO (ESTILIZADO) */}
      {isTestExamOpen && currentExam && (
        <div className="fixed inset-0 z-[800] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-4 animate-in fade-in">
           <div className="bg-white w-full max-w-4xl h-[85vh] rounded-[4.5rem] p-20 flex flex-col shadow-2xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-full -mr-32 -mt-32 opacity-50 blur-3xl"></div>

              <div className="flex justify-between items-center mb-16 relative z-10">
                 <div className="flex items-center gap-8">
                    <div className="p-6 bg-indigo-50 text-indigo-600 rounded-[2rem] shadow-sm"><Eye size={40}/></div>
                    <div>
                      <h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic">Preview do Aluno</h3>
