                 <button onClick={() => setIsTestExamOpen(false)} className="p-4 bg-slate-50 rounded-full hover:bg-slate-200"><X size={24}/></button>
              </div>

              {/* MENSAGEM INICIAL DE PREPARAÇÃO */}
              <div className="bg-amber-50 p-10 rounded-[2.5rem] border border-amber-100 flex gap-8 items-center mb-16 relative z-10 shadow-sm">
                 <ShieldAlert size={60} className="text-amber-500 flex-shrink-0 animate-bounce-slow" />
                 <div>
                    <h5 className="font-black text-amber-900 uppercase text-xs tracking-tight italic mb-2">Instruções Pré-Exame</h5>
                    <p className="text-[11px] font-medium text-amber-700 leading-relaxed italic">"Certifique-se de estar em um ambiente calmo e sem interrupções. Esta prova tem caráter oficial e o cronômetro será ativado assim que o aluno iniciar. Revise suas questões antes de concluir."</p>
                 </div>
              </div>

              <div className="flex-1 overflow-y-auto space-y-16 pr-6 custom-scrollbar relative z-10">
                 {currentExam.questions.map((q, idx) => (
                   <div key={q.id} className="space-y-8">
                      <h4 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{idx+1}. {q.text}</h4>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                         {q.options.map((opt, i) => (
                           <div key={i} className={`p-8 rounded-[2rem] border-2 flex items-center gap-6 transition-all cursor-pointer relative ${q.correctOption === i ? 'border-emerald-500 bg-emerald-50/50' : 'border-slate-100 bg-slate-50 hover:border-indigo-200'}`}>
