                 {currentExam.questions.length === 0 && <div className="p-32 text-center text-slate-200 font-black uppercase italic tracking-[0.5em]">Nenhuma Questão para Preview</div>}
              </div>

              <div className="mt-16 flex justify-center">
                 <button onClick={() => setIsTestExamOpen(false)} className="px-20 py-8 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all active:scale-95 italic">Finalizar Teste de Fluxo</button>
