              <div className="w-16 h-16 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-8 text-indigo-600 shadow-inner"><Layers size={32}/></div>
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-10 italic">Novo Módulo Acadêmico</h3>
              <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl outline-none font-bold mb-10 shadow-inner" />
              <div className="flex gap-4">
                <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={() => { if(moduleTitle) { addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); setModuleTitle(''); setIsModuleModalOpen(false); }}} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl">Criar Módulo</button>
