              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-10 italic">Adicionar Recurso</h3>
              <div className="space-y-6 mb-10">
                 <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Documento..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-bold shadow-inner" />
                 <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-bold shadow-inner" />
              </div>
              <div className="flex gap-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={() => { if(materialTitle && materialUrl) { addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-6 bg-indigo-600 text-white rounded-3xl text-[10px] font-black uppercase shadow-xl">Salvar</button>
              </div>
           </div>
        </div>
      )}

      {/* EXAM MODAL AVANÇADO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-12 space-y-8 shadow-2xl">
              <div className="flex items-center gap-6">
                 <div className="p-5 bg-amber-50 text-amber-600 rounded-3xl shadow-sm"><Award size={32} /></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic">Configurar Avaliação</h3>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Título do Exame</label>
                    <input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Final de Teologia..." className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-bold shadow-inner" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Vincular a Módulo</label>
                    <select value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase shadow-inner">
                       <option value="">Nenhum Módulo Selecionado</option>
                       {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                    </select>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Tipo</label>
                       <select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase shadow-inner"><option value="activity">Atividade</option><option value="evaluation">Prova</option></select>
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Corte %</label>
                       <input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-black shadow-inner" />
                    </div>
                 </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase">Cancelar</button>
                <button onClick={async () => {
                  const payload = { ...examForm, courseId: selectedCourseForModules, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() };
                  if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload);
                  else await addDoc(collection(db, 'exams'), payload);
                  setIsExamModalOpen(false);
                }} className="flex-1 py-6 bg-indigo-600 text-white rounded-3xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Salvar Exame</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, Image as ImageIcon,
  CheckCircle2, AlertTriangle, Info
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'green'>('none');

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [isTestExamOpen, setIsTestExamOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Test Simulation State
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(query(collection(db, 'exams'), where('authorId', '==', user.uid)), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // Handlers
  const startLive = async (vId?: string, aId?: string) => {
    try {
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
      const constraints = {
        video: vId ? { deviceId: { exact: vId } } : true,
        audio: aId ? { deviceId: { exact: aId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setIsLiveActive(true);
    } catch (err) { alert("Erro ao acessar mídia."); }
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  const handleSaveLesson = async () => {
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const lesson = { id: editingLessonId || Math.random().toString(36).substr(2,9), ...lessonForm, order: mod.lessons.length + 1 };
    const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? lesson : l) : [...mod.lessons, lesson];
    await updateDoc(doc(db, 'modulos', mod.id), { lessons: up });
    setIsLessonModalOpen(false);
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setCurrentExam({ ...currentExam, questions: up });
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const stats = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const avg = relevant.length > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / relevant.length).toFixed(1) : '0.0';
    return { avg, elogios: relevant.filter(f => f.type === 'elogio').length, alertas: relevant.filter(f => f.type === 'reclamacao').length, sugestoes: relevant.filter(f => f.type === 'sugestao').length };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      {/* 1. MÓDULOS & MATRIZ */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl"><Layers size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Controle de Fluxo Pedagógico</p></div>
            </div>
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-10 py-5 rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><Plus size={18}/> Adicionar Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[3.5rem] overflow-hidden group shadow-sm">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="w-10 h-10 bg-indigo-100 text-indigo-700 rounded-xl flex items-center justify-center font-black text-xs">{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-xs uppercase italic tracking-widest">{mod.title}</h3>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-6 py-3 bg-indigo-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg hover:scale-105 transition-all">Add Lição</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all"><Edit3 size={18}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-3 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-10 space-y-4">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-5 rounded-[2.5rem] flex items-center justify-between border border-slate-100 hover:border-indigo-100 hover:bg-indigo-50/10 transition-all group/l">
                        <div className="flex items-center gap-5">
                          <span className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 text-xs uppercase italic">{l.title}</h4>
                            <div className="flex gap-3 mt-1">
                              {l.videoUrl && <span className="text-[8px] font-black text-rose-500 uppercase flex items-center gap-1"><PlayCircle size={10}/> Vídeo Ativo</span>}
                              {l.materialUrl && <span className="text-[8px] font-black text-indigo-500 uppercase flex items-center gap-1"><FileText size={10}/> Material Base</span>}
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/l:opacity-100 transition-all">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-3 text-indigo-600 hover:bg-indigo-50 rounded-xl"><Edit3 size={18}/></button>
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-3 text-red-500 hover:bg-red-50 rounded-xl"><Trash2 size={18}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/50 p-6 rounded-[2.5rem] flex items-center justify-between border border-amber-100 shadow-sm">
                        <div className="flex items-center gap-5">
                          <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl"><CheckSquare size={20}/></div>
                          <div><h4 className="font-black text-amber-900 text-xs uppercase">Avaliação: {ex.title}</h4><span className="text-[9px] font-black text-amber-600/50 uppercase italic tracking-widest">{ex.questions?.length||0} Questões Cadastradas</span></div>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-6 py-3 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg hover:bg-amber-700 transition-all">Editar Exame</button>
                        </div>
                      </div>
                    ))}
                    {mod.lessons.length === 0 && moduleExams.length === 0 && <p className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic tracking-widest">Nenhum conteúdo vinculado a este módulo.</p>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl"><FileText size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Acervo Pedagógico</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Arquivos e Documentos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-10 py-5 rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all flex items-center gap-2"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 relative group hover:shadow-2xl transition-all text-center">
                <FileText size={56} className="text-indigo-500 mx-auto mb-6" />
                <h4 className="font-black text-slate-900 text-xs uppercase italic mb-6 leading-tight">{m.title}</h4>
                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all shadow-lg"><ExternalLink size={16}/> Acessar Recurso</a>
                <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-8 right-8 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-red-500 transition-all"><Trash2 size={24}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 3. AVALIAÇÕES */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-amber-50 text-amber-600 rounded-3xl"><CheckSquare size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Banco de Exames</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Atividades e Provas</p></div>
            </div>
            <button onClick={() => { setCurrentExam(null); setExamForm({title:'', moduleId:'', type:'activity', passingGrade:70}); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-10 py-5 rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-600 transition-all flex items-center gap-2"><Plus size={18}/> Criar Novo Exame</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
              <div key={ex.id} className="bg-white p-12 rounded-[4rem] border border-slate-100 group relative hover:shadow-2xl transition-all">
                <div className="flex justify-between items-start mb-10">
                  <Award size={48} className={ex.type === 'evaluation' ? 'text-amber-500' : 'text-emerald-500'} />
                  <div className="text-right"><span className="text-[10px] font-black uppercase text-slate-400 block mb-1 tracking-widest">Nota Corte</span><span className="text-4xl font-black text-slate-900 leading-none">{ex.passingGrade}%</span></div>
                </div>
                <h4 className="font-black text-slate-900 text-sm uppercase italic mb-8 leading-snug">{ex.title}</h4>
                <div className="flex gap-4">
                  <button onClick={() => { setCurrentExam(ex); setExamForm({title:ex.title, moduleId:ex.moduleId, type:ex.type, passingGrade:ex.passingGrade}); setIsExamModalOpen(true); }} className="flex-1 py-5 bg-slate-50 text-slate-600 rounded-2xl text-[10px] font-black uppercase border border-slate-200 hover:bg-indigo-50 transition-all">Configurar</button>
                  <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-600">Questões ({ex.questions?.length||0})</button>
                  <button onClick={() => { setCurrentExam(ex); setTestStarted(false); setIsTestExamOpen(true); }} className="p-5 bg-indigo-50 text-indigo-600 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all shadow-lg active:scale-95"><PlayCircle size={22}/></button>
                </div>
                <button onClick={async () => { if(confirm('Excluir exame?')) await deleteDoc(doc(db, 'exams', ex.id)); }} className="absolute top-10 right-10 text-slate-100 hover:text-red-500 transition-all"><Trash2 size={24}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. FEEDBACK REDESIGN PREMIUM */}
      {activeSub === 'feedback' && (
        <div className="space-y-6">
          <div className="bg-white p-12 rounded-[4.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-8">
            <div className="flex items-center gap-6">
              <div className="p-5 bg-indigo-600 text-white rounded-[2rem] shadow-xl shadow-indigo-100"><MessageSquare size={32}/></div>
              <div><h1 className="text-3xl font-black uppercase italic tracking-tighter">Mural Discente</h1><p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mt-1">Análise de Satisfação em Tempo Real</p></div>
            </div>
            <div className="flex items-center gap-10 bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
              <div className="text-center px-4 border-r border-slate-200"><p className="text-4xl font-black text-indigo-600 leading-none">{stats.avg}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-2 tracking-widest">Score NPS</p></div>
              <div className="text-center px-4 border-r border-slate-200"><p className="text-4xl font-black text-emerald-600 leading-none">{stats.elogios}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-2 tracking-widest">Elogios</p></div>
              <div className="text-center px-4"><p className="text-4xl font-black text-rose-600 leading-none">{stats.alertas}</p><p className="text-[8px] font-black uppercase text-slate-400 mt-2 tracking-widest">Alertas</p></div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {feedbacks.filter(f => f.courseId === selectedCourseForModules).map(f => (
              <div key={f.id} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-24 h-24 bg-slate-50 rounded-full -mr-12 -mt-12 opacity-50 group-hover:scale-150 transition-all duration-700"></div>
                <div className="flex gap-1 mb-6 relative z-10">
                  {[1,2,3,4,5].map(n => <Star key={n} size={14} className={n <= (f.rating||0) ? 'fill-amber-400 text-amber-400' : 'text-slate-100'} />)}
                </div>
                <p className="text-xs font-medium text-slate-600 italic leading-relaxed mb-8 relative z-10">"{f.comment}"</p>
                <div className="flex items-center gap-4 border-t pt-6 relative z-10">
                  <div className="w-10 h-10 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xs">{(f.userName||'U').charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-[10px] font-black uppercase italic text-slate-900 leading-none">{f.userName||'Estudante'}</span><span className="text-[8px] font-bold text-slate-400 uppercase mt-1">Matriculado em {selectedCourseForModules.substring(0,8)}</span></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 5, 6, 7. DIÁRIO / RELATÓRIO / FREQUÊNCIA */}
      {(['diario', 'relatorio', 'frequencia'] as ProfessorSubView[]).includes(activeSub) && (
        <div className="space-y-6 h-full">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex items-center gap-6">
            <div className="p-4 bg-slate-900 text-white rounded-3xl">
              {activeSub === 'diario' ? <Calendar size={32}/> : activeSub === 'relatorio' ? <TrendingUp size={32}/> : <Users size={32}/>}
            </div>
            <div>
              <h1 className="text-2xl font-black uppercase italic tracking-tighter">{activeSub === 'diario' ? 'Diário Acadêmico' : activeSub === 'relatorio' ? 'Métricas Mensais' : 'Fluxo de Presença'}</h1>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Sincronização Cloud Ativa</p>
            </div>
          </div>
          <div className="bg-white rounded-[4rem] border border-slate-100 overflow-hidden shadow-sm flex-1">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 tracking-[0.3em] border-b">
                <tr><th className="px-12 py-8">Discente</th><th className="px-12 py-8">Situação</th><th className="px-12 py-8">Engajamento</th><th className="px-12 py-8">Resultado</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-indigo-50/20 transition-all cursor-default">
                    <td className="px-12 py-6 flex items-center gap-5"><div className="w-12 h-12 rounded-[1.25rem] bg-indigo-600 text-white flex items-center justify-center font-black text-xs shadow-lg">{s.displayName.charAt(0)}</div><span className="text-sm font-black uppercase italic text-slate-900 tracking-tighter">{s.displayName}</span></td>
                    <td className="px-12 py-6"><span className="px-4 py-1.5 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase rounded-xl border border-emerald-100">Ativo</span></td>
                    <td className="px-12 py-6 font-black text-sm text-slate-600">96.4%</td>
                    <td className="px-12 py-6"><span className="px-5 py-2.5 bg-white text-indigo-700 text-[11px] font-black uppercase rounded-2xl border border-slate-200 shadow-sm">Grade 9.2</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
            {allStudents.length === 0 && <div className="p-32 text-center text-[10px] font-black text-slate-300 uppercase italic tracking-[0.5em]">Sem registros cadastrados no sistema.</div>}
          </div>
        </div>
      )}

      {/* 8. LIVE STUDIO AVANÇADO */}
      {activeSub === 'live' && (
        <div className="h-full flex flex-col space-y-6">
          {!isLiveActive ? (
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-10 items-center">
               <div className="bg-white p-16 rounded-[5rem] border border-slate-200 shadow-sm text-center flex flex-col items-center justify-center relative overflow-hidden group h-full">
                  <div className="w-32 h-32 bg-rose-50 rounded-[3.5rem] flex items-center justify-center mb-10 animate-pulse"><Radio size={64} className="text-rose-600" /></div>
                  <h2 className="text-5xl font-black text-slate-900 uppercase tracking-tighter mb-4 italic">Broadcast Pro</h2>
                  <p className="text-slate-400 max-w-sm mb-12 font-medium uppercase text-xs tracking-widest leading-relaxed">Conecte-se instantaneamente com sua audiência discente via streaming nativo.</p>
                  <button onClick={() => startLive()} className="bg-slate-900 text-white px-20 py-8 rounded-[3rem] text-xs font-black uppercase shadow-2xl hover:bg-rose-600 transition-all active:scale-95 flex items-center gap-4 tracking-widest"><Tv size={24}/> Abrir Studio de Aula</button>
               </div>
               <div className="bg-white p-12 rounded-[5rem] border border-slate-200 shadow-sm flex flex-col h-full overflow-hidden">
                  <div className="flex items-center justify-between mb-12">
                     <div className="flex items-center gap-5"><div className="p-5 bg-amber-50 text-amber-600 rounded-[2rem]"><Calendar size={32}/></div><h3 className="font-black text-slate-900 uppercase text-sm italic tracking-widest">Cronograma de Aulas</h3></div>
                     <button onClick={() => setIsScheduleModalOpen(true)} className="p-5 bg-slate-900 text-white rounded-[1.5rem] hover:bg-indigo-600 shadow-xl transition-all"><Plus size={32}/></button>
                  </div>
                  <div className="flex-1 overflow-y-auto space-y-5 pr-2 custom-scrollbar">
                     {scheduledClasses.map(s => (
                       <div key={s.id} className="p-8 bg-slate-50 border border-slate-100 rounded-[2.5rem] flex justify-between items-center group hover:bg-white hover:shadow-xl transition-all duration-500">
                          <div><span className="text-[10px] font-black text-indigo-600 uppercase block mb-2 tracking-widest">{new Date(s.date).toLocaleString()}</span><span className="font-black text-slate-900 uppercase text-sm italic leading-none">{s.title}</span></div>
                          <button onClick={async () => { if(confirm('Remover agendamento?')) await deleteDoc(doc(db, 'scheduledClasses', s.id)); }} className="p-4 text-slate-200 hover:text-rose-600 bg-white rounded-xl shadow-sm"><Trash2 size={20}/></button>
                       </div>
                     ))}
                  </div>
               </div>
            </div>
          ) : (
            <div className="fixed inset-0 z-[600] bg-black flex flex-col text-white animate-in fade-in overflow-hidden">
              <div className="absolute top-0 left-0 right-0 z-[700] p-8 flex items-center justify-between pointer-events-none">
                 <div className="flex items-center gap-6 pointer-events-auto">
                    <div className="bg-rose-600 px-8 py-4 rounded-full flex items-center gap-4 shadow-2xl border border-rose-500/20">
                       <div className="w-3 h-3 bg-white rounded-full animate-ping"></div>
                       <span className="text-xs font-black uppercase tracking-[0.3em]">AO VIVO</span>
                    </div>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className="bg-zinc-900/90 backdrop-blur-3xl px-8 py-4 rounded-full border border-white/10 flex items-center gap-4 hover:bg-indigo-600 transition-all shadow-xl">
                       <Users size={18}/><span className="text-xs font-black uppercase">{allStudents.length} Conectados</span>
                    </button>
                 </div>
                 <div className="flex items-center gap-4 pointer-events-auto">
                    <div className="bg-indigo-600 px-8 py-4 rounded-[2rem] text-xs font-black uppercase flex items-center gap-4 shadow-2xl">
                       <ShieldCheck size={20}/> PROFESSOR: {user.displayName}
                    </div>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className="p-5 bg-zinc-900/90 backdrop-blur-3xl rounded-full hover:bg-white/10 transition-all shadow-xl"><Settings size={24}/></button>
                 </div>
              </div>

              <div className="flex-1 flex overflow-hidden">
                 <div className="flex-1 relative flex items-center justify-center p-8 lg:p-16">
                    <div className="absolute inset-0 pointer-events-none z-[650] overflow-hidden">
                       {activeReactions.map(r => (
                         <div key={r.id} className="absolute bottom-32 text-8xl animate-bounce-up opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
                       ))}
                    </div>

                    <div className={`w-full h-full max-w-[1920px] aspect-video bg-zinc-900 rounded-[5rem] overflow-hidden border border-white/10 relative group transition-all duration-700 shadow-[0_50px_150px_rgba(0,0,0,1)] ${activePanel !== 'none' ? 'lg:mr-10 scale-[0.97]' : ''}`}>
                       {isPresentationMode ? (
                         <div className="w-full h-full bg-white flex flex-col items-center justify-center text-zinc-900 relative animate-in zoom-in-95">
                            <Presentation size={160} className="text-indigo-600 mb-10 opacity-10" />
                            <h2 className="text-5xl font-black uppercase italic tracking-tighter">EXIBIÇÃO DE SLIDE {presentationSlide}</h2>
                            <p className="text-zinc-400 font-black text-sm uppercase mt-4 tracking-widest">Material Acadêmico de Apoio</p>
                            <div className="absolute inset-x-20 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                               <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-10 bg-zinc-100 rounded-full text-zinc-600 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto active:scale-90"><ChevronLeft size={48}/></button>
                               <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-10 bg-zinc-100 rounded-full text-zinc-600 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto active:scale-90"><ChevronRight size={48}/></button>
                            </div>
                         </div>
                       ) : (
                         <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-all ${videoActive ? 'opacity-100' : 'opacity-0'} ${virtualBg === 'blur' ? 'blur-3xl' : ''}`} />
                       )}

                       {/* CONTROLES DE STUDIO */}
