                          <div className="w-px h-12 bg-white/10 mx-2"></div>
                          <div className="flex gap-2 bg-black/50 p-3 rounded-3xl border border-white/5">
                             {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-3 hover:bg-white/10 rounded-2xl transition-all text-2xl active:scale-125">{e}</button>)}
                          </div>

                          <div className="w-px h-12 bg-white/10 mx-2"></div>
                          <button onClick={stopLive} className="px-12 py-7 bg-rose-600 hover:bg-rose-700 rounded-[2.5rem] text-xs font-black uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center gap-4"><PhoneOff size={24}/> Encerrar Aula</button>
                       </div>

                       <div className="absolute right-12 top-1/2 -translate-y-1/2 flex flex-col gap-6 opacity-0 group-hover:opacity-100 transition-all">
                          <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-6 rounded-3xl border transition-all shadow-2xl ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/60 border-white/5 hover:bg-white/10'}`}><MessageSquare size={32}/></button>
                          <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-6 rounded-3xl border transition-all shadow-2xl ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/60 border-white/5 hover:bg-white/10'}`}><Users size={32}/></button>
                       </div>
                    </div>
                 </div>

                 {activePanel !== 'none' && (
                   <div className="w-[450px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right duration-500 h-full shadow-[0_0_150px_rgba(0,0,0,1)] relative z-[750]">
                      <div className="p-12 border-b border-white/5 flex items-center justify-between">
                         <h4 className="text-sm font-black uppercase tracking-[0.3em] italic">{activePanel === 'chat' ? 'Chat da Turma' : activePanel === 'participants' ? 'Moderação Discente' : 'Opções de Broadcast'}</h4>
                         <button onClick={() => setActivePanel('none')} className="p-4 bg-white/5 rounded-full hover:bg-white/10"><X size={24}/></button>
                      </div>
                      <div className="flex-1 overflow-y-auto p-10 space-y-6 custom-scrollbar">
                         {activePanel === 'chat' ? (
                           chatMessages.map((m, i) => (
                             <div key={i} className="animate-in fade-in slide-in-from-bottom-3">
                                <div className="flex items-center gap-3 mb-2"><span className="text-xs font-black text-indigo-400 uppercase italic">{m.user}</span><span className="text-[10px] text-white/20 font-bold">{m.time}</span></div>
                                <p className="text-sm font-medium text-white/70 bg-white/5 p-6 rounded-[2rem] border border-white/5 italic leading-relaxed">"{m.text}"</p>
                             </div>
                           ))
                         ) : activePanel === 'participants' ? (
                           allStudents.map(s => (
                             <div key={s.uid} className="p-6 bg-white/5 rounded-[2.5rem] border border-white/5 flex items-center justify-between group/u hover:bg-white/10 transition-all">
                                <div className="flex items-center gap-5">
                                   <div className="w-12 h-12 rounded-2xl bg-zinc-800 flex items-center justify-center font-black text-sm">{(s.displayName||'U').charAt(0)}</div>
                                   <span className="text-sm font-black uppercase italic text-white/80">{s.displayName}</span>
                                </div>
                                <div className="flex gap-2 opacity-0 group-hover/u:opacity-100 transition-all">
                                   <button className="p-4 bg-white/5 hover:bg-rose-600 rounded-2xl"><VolumeX size={16}/></button>
                                   <button className="p-4 bg-white/5 hover:bg-rose-600 rounded-2xl"><UserX size={16}/></button>
                                </div>
                             </div>
                           ))
                         ) : (
                           <div className="space-y-10">
                              <div className="space-y-5">
                                 <h5 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 italic">Input de Mídia</h5>
                                 <select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLive(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600">
                                    <option value="">Câmera Principal...</option>
                                    {devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}
                                 </select>
                                 <select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLive(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600">
                                    <option value="">Microfone Principal...</option>
                                    {devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}
                                 </select>
                              </div>
                              <div className="space-y-5">
                                 <h5 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 italic">Background Virtual</h5>
                                 <div className="grid grid-cols-2 gap-4">
                                    {['Original', 'Desfoque', 'Estúdio', 'Green'].map(bg => (
                                      <button key={bg} onClick={() => setVirtualBg(bg.toLowerCase() as any)} className={`p-5 rounded-[1.5rem] border text-[10px] font-black uppercase transition-all flex items-center gap-3 ${virtualBg === bg.toLowerCase() ? 'bg-indigo-600 border-indigo-400' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
                                         {bg === 'Original' ? <Video size={14}/> : <Sparkles size={14}/>} {bg}
                                      </button>
                                    ))}
                                 </div>
                              </div>
                           </div>
                         )}
                      </div>
                      {activePanel === 'chat' && (
                        <div className="p-12 border-t border-white/5 bg-[#050505]">
                           <div className="relative">
                              <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Mensagem para a turma..." className="w-full bg-white/5 border-none rounded-[2rem] px-8 py-6 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" />
                              <button onClick={handleSendMessage} className="absolute right-4 top-1/2 -translate-y-1/2 p-4 text-indigo-500 hover:text-indigo-400 transition-all"><Send size={28}/></button>
                           </div>
                        </div>
                      )}
                   </div>
                 )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* -------------------- MODAIS -------------------- */}

      {/* PPTX UPLOAD & START */}
      {showPptUpload && (
        <div className="fixed inset-0 z-[850] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-xl rounded-[5rem] p-16 text-center shadow-[0_50px_100px_rgba(0,0,0,0.5)] animate-in zoom-in-95">
              <div className="w-24 h-24 bg-indigo-50 rounded-[3rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Presentation size={48}/></div>
              <h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic mb-4">Gerenciador de Slides</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-12 italic">Carregue o Material Didático da Transmissão</p>

              <div onClick={() => fileInputRef.current?.click()} className="border-4 border-dashed border-slate-100 rounded-[4rem] p-20 mb-12 hover:border-indigo-400 hover:bg-indigo-50/20 transition-all cursor-pointer group">
                 <Upload size={64} className="text-slate-200 mx-auto mb-6 group-hover:text-indigo-600 group-hover:scale-110 transition-all" />
                 <span className="text-[11px] font-black uppercase text-slate-300 group-hover:text-indigo-900 transition-colors tracking-widest">Selecionar Documento PowerPoint / PDF</span>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { /* Simulation */ } }} />
              </div>

              <div className="flex gap-5">
                 <button onClick={() => setShowPptUpload(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[10px] font-black uppercase tracking-widest italic">Cancelar</button>
                 <button onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 tracking-[0.3em] italic">Iniciar Apresentação</button>
              </div>
           </div>
        </div>
      )}

      {/* QUESTION EDITOR AVANÇADO (CRUD DE QUESTÕES) */}
      {isQuestionEditorOpen && currentExam && (
        <div className="fixed inset-0 z-[800] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[5rem] p-20 flex flex-col shadow-2xl relative">
              <div className="flex justify-between items-center mb-12 border-b border-slate-100 pb-10">
                 <div>
                    <h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic">Banco de Questões</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Configurando: {currentExam.title}</p>
                 </div>
                 <button onClick={() => setIsQuestionEditorOpen(false)} className="p-6 bg-slate-50 rounded-full hover:bg-slate-200 transition-all"><X size={32}/></button>
              </div>

              <div className="bg-slate-50 p-12 rounded-[4rem] border border-slate-100 mb-12 space-y-10 shadow-inner overflow-y-auto max-h-[50%] custom-scrollbar">
                 <div className="space-y-3">
                    <label className="text-[11px] font-black uppercase text-slate-400 tracking-widest italic ml-1">Enunciado Pedagógico</label>
                    <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Escreva o enunciado da questão aqui..." className="w-full px-10 py-8 bg-white border-none rounded-[2rem] h-32 font-bold shadow-sm outline-none focus:ring-2 focus:ring-indigo-600 resize-none"></textarea>
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-4 group">
                         <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-14 h-14 rounded-2xl font-black text-sm transition-all shadow-md ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border-2 border-slate-100 text-slate-300 hover:border-indigo-400'}`}>{String.fromCharCode(65+i)}</button>
                         <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Alternativa ${String.fromCharCode(65+i)}...`} className="flex-1 px-8 py-5 bg-white border-none rounded-2xl text-xs font-bold shadow-sm outline-none focus:ring-2 focus:ring-indigo-600" />
                      </div>
                    ))}
                 </div>
                 <button onClick={handleSaveQuestion} className="w-full py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.3em] italic shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Anexar Questão ao Banco</button>
              </div>

              <div className="flex-1 overflow-y-auto space-y-6 pr-6 custom-scrollbar">
                 <h4 className="text-[10px] font-black uppercase text-slate-300 tracking-[0.4em] mb-6 italic border-b pb-4">Itens Acadêmicos Vinculados ({currentExam.questions?.length || 0})</h4>
                 {(currentExam.questions || []).map((q, idx) => (
                   <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[3rem] flex items-start justify-between group shadow-sm hover:border-indigo-200 hover:shadow-xl transition-all">
                      <div className="flex items-start gap-8">
                         <span className="w-12 h-12 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-sm italic shadow-lg mt-1">{idx+1}</span>
                         <div>
                            <p className="text-sm font-black uppercase italic text-slate-900 leading-tight pr-10">{q.text}</p>
                            <div className="flex flex-wrap gap-2 mt-4">
                               {q.options.map((opt, oi) => (
                                 <span key={oi} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase italic border ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                                    {String.fromCharCode(65+oi)}: {opt.substring(0, 20)}...
                                 </span>
                               ))}
                            </div>
                         </div>
                      </div>
                      <button onClick={async () => { if(confirm('Excluir esta questão permanentemente?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-5 text-slate-100 hover:text-red-500 hover:bg-rose-50 rounded-2xl transition-all"><Trash2 size={24}/></button>
                   </div>
                 ))}
                 {currentExam.questions?.length === 0 && <div className="py-20 text-center text-slate-200 font-black uppercase text-xs italic tracking-[0.5em]">Sem questões para exibição.</div>}
              </div>
           </div>
        </div>
      )}

      {/* SIMULADOR DE EXAME (ESTILO ALUNO) */}
      {isTestExamOpen && currentExam && (
        <div className="fixed inset-0 z-[900] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[5rem] p-24 flex flex-col shadow-[0_50px_150px_rgba(0,0,0,0.8)] relative overflow-hidden">
              <div className="absolute top-0 right-0 w-80 h-80 bg-indigo-50 rounded-full -mr-40 -mt-40 opacity-50 blur-[100px]"></div>

              <div className="flex justify-between items-center mb-20 relative z-10">
                 <div className="flex items-center gap-10">
                    <div className="p-8 bg-indigo-600 text-white rounded-[2.5rem] shadow-2xl shadow-indigo-100"><Eye size={48}/></div>
                    <div>
                      <h3 className="text-5xl font-black text-slate-900 uppercase tracking-tighter italic">Simulador Discente</h3>
                      <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Validação Acadêmica: {currentExam.title}</p>
                    </div>
                 </div>
                 <button onClick={() => { setIsTestExamOpen(false); setTestStarted(false); }} className="p-6 bg-slate-50 rounded-full hover:bg-rose-50 hover:text-rose-600 transition-all shadow-sm"><X size={32}/></button>
              </div>

              {!testStarted ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center relative z-10 animate-in zoom-in-95">
                   <div className="w-24 h-24 bg-amber-50 rounded-[2.5rem] flex items-center justify-center mb-10 text-amber-500 shadow-inner"><Info size={48} /></div>
                   <h4 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic mb-6">Pronto para Iniciar?</h4>
                   <div className="max-w-xl space-y-6 mb-16 text-slate-500 font-medium italic leading-relaxed">
                      <p className="flex items-center gap-4 bg-slate-50 p-6 rounded-[2rem] border border-slate-100"><ShieldAlert size={24} className="text-amber-500 flex-shrink-0" /> Certifique-se de estar em um ambiente silencioso e sem interrupções externas.</p>
                      <p className="flex items-center gap-4 bg-slate-50 p-6 rounded-[2rem] border border-slate-100"><Clock size={24} className="text-indigo-500 flex-shrink-0" /> Esta avaliação cronometra seu progresso para garantir a integridade pedagógica.</p>
                      <p className="flex items-center gap-4 bg-slate-50 p-6 rounded-[2rem] border border-slate-100"><CheckCircle2 size={24} className="text-emerald-500 flex-shrink-0" /> Leia cada enunciado com atenção redobrada antes de confirmar sua resposta.</p>
                   </div>
                   <button onClick={() => { setTestStarted(true); setCurrentTestAnswers({}); }} className="px-24 py-10 bg-slate-900 text-white rounded-[3rem] text-sm font-black uppercase tracking-[0.4em] italic shadow-[0_30px_60px_rgba(0,0,0,0.3)] hover:bg-indigo-600 transition-all active:scale-95">Iniciar Simulação Agora</button>
                </div>
              ) : (
                <div className="flex-1 flex flex-col overflow-hidden relative z-10">
                   <div className="flex-1 overflow-y-auto space-y-24 pr-10 custom-scrollbar pb-20">
                      {currentExam.questions.map((q, idx) => (
                        <div key={q.id} className="space-y-10 animate-in fade-in slide-in-from-bottom-10">
                           <div className="flex items-center gap-6">
                              <span className="text-5xl font-black text-indigo-100 italic">#{idx+1}</span>
                              <h4 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{q.text}</h4>
                           </div>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                              {q.options.map((opt, i) => (
                                <div 
                                  key={i} 
                                  onClick={() => setCurrentTestAnswers(prev => ({...prev, [q.id]: i}))}
                                  className={`p-10 rounded-[3rem] border-2 flex items-center gap-8 transition-all cursor-pointer relative group ${currentTestAnswers[q.id] === i ? 'border-indigo-600 bg-indigo-50/50 shadow-2xl' : 'border-slate-100 bg-slate-50 hover:border-indigo-200'}`}
                                >
                                   {currentTestAnswers[q.id] === i && <div className="absolute -top-4 -right-4 bg-indigo-600 text-white p-3 rounded-full shadow-2xl animate-in zoom-in-50"><CheckCircle2 size={20}/></div>}
                                   <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-sm shadow-inner ${currentTestAnswers[q.id] === i ? 'bg-indigo-600 text-white' : 'bg-white border text-slate-300'}`}>{String.fromCharCode(65+i)}</div>
                                   <span className={`text-lg font-bold italic tracking-tight ${currentTestAnswers[q.id] === i ? 'text-indigo-900' : 'text-slate-600'}`}>{opt}</span>
                                </div>
                              ))}
                           </div>
                        </div>
                      ))}
                      {currentExam.questions.length === 0 && <div className="p-40 text-center text-slate-200 font-black uppercase text-xs italic tracking-[0.5em]">Exame vazio no banco de dados.</div>}
                   </div>

                   <div className="mt-auto pt-10 border-t border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-xl">
                      <div className="flex items-center gap-4 bg-slate-50 px-8 py-5 rounded-[2rem] border border-slate-200">
                         <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                         <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic">Status: {Object.keys(currentTestAnswers).length} de {currentExam.questions.length} Respondidas</span>
                      </div>
                      <button onClick={() => { setIsTestExamOpen(false); setTestStarted(false); }} className="px-20 py-8 bg-slate-900 text-white rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.5em] shadow-2xl hover:bg-emerald-600 transition-all active:scale-95 italic">Finalizar e Corrigir</button>
                   </div>
                </div>
              )}
           </div>
        </div>
      )}

      {/* MODAL MÓDULO (RESTAURADO & FUNCIONAL) */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[650] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[4rem] p-16 text-center shadow-2xl">
              <div className="w-20 h-20 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Layers size={40}/></div>
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-12 italic">{currentModuleId ? 'Editar Módulo' : 'Novo Módulo'}</h3>
              <div className="space-y-2 text-left mb-10">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Identificação Acadêmica</label>
                 <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] outline-none font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="flex gap-4">
                <button onClick={() => { setIsModuleModalOpen(false); setModuleTitle(''); setCurrentModuleId(null); }} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[2rem] text-[11px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={async () => { 
                   if(!moduleTitle) return;
                   if(currentModuleId) {
                      await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle });
                   } else {
                      await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() });
                   }
                   setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(false); 
                }} className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-[11px] font-black uppercase shadow-xl tracking-[0.2em] italic">Confirmar</button>
              </div>
           </div>
        </div>
      )}

      {/* LIÇÃO MODAL AVANÇADO */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
          <div className="bg-white w-full max-w-xl rounded-[4rem] p-16 space-y-10 shadow-2xl overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{editingLessonId ? 'Editar Aula Master' : 'Criar Aula Master'}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Configuração Detalhada de Conteúdo</p></div>
            <div className="space-y-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título do Encontro</label>
                 <input value={lessonForm.title} onChange={e => setLessonForm({...lessonForm, title: e.target.value})} placeholder="Ex: Hermenêutica I - Introdução..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Vídeo Streaming (Vimeo/YT)</label>
                 <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link do player de vídeo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Material de Apoio Digital</label>
                 <select value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner outline-none focus:ring-2 focus:ring-indigo-600">
                    <option value="">Vincular Arquivo Existente...</option>
                    {materials.filter(m => m.courseId === selectedCourseForModules).map(m => <option key={m.id} value={m.url}>{m.title}</option>)}
                 </select>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Descrição Pedagógica</label>
                 <textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Tópicos que serão abordados..." className="w-full px-10 py-8 bg-slate-50 border-none rounded-[2.5rem] h-40 font-medium text-sm shadow-inner resize-none outline-none focus:ring-2 focus:ring-indigo-600"></textarea>
              </div>
            </div>
            <div className="flex gap-4 pt-6">
              <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
              <button onClick={handleSaveLesson} className="flex-1 py-7 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.3em] italic">Publicar Conteúdo</button>
            </div>
          </div>
        </div>
      )}

      {/* EXAM MODAL AVANÇADO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-16 space-y-10 shadow-2xl">
              <div className="flex items-center gap-6">
                 <div className="p-6 bg-amber-50 text-amber-600 rounded-[2rem] shadow-sm shadow-amber-200/50"><Award size={40} /></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Configurar Exame</h3>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título da Atividade</label>
                    <input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Geral do Módulo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Módulo Referente</label>
                    <select value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner">
                       <option value="">Vincular a Módulo...</option>
                       {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                    </select>
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Tipo</label>
                       <select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-8 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner"><option value="activity">Teste Base</option><option value="evaluation">Prova Final</option></select>
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Média %</label>
                       <input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-8 py-6 bg-slate-50 border-none rounded-[2rem] font-black shadow-inner" />
                    </div>
                 </div>
              </div>
              <div className="flex gap-4 pt-10">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={async () => {
                  const payload = { ...examForm, courseId: selectedCourseForModules, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() };
                  if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload);
                  else await addDoc(collection(db, 'exams'), payload);
                  setIsExamModalOpen(false);
                }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all tracking-widest italic">Gravar Configurações</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Coleta de Assinatura Acadêmica" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'green'>('none');

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isQuestionEditorOpen, setIsQuestionEditorOpen] = useState(false);
  const [isTestExamOpen, setIsTestExamOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Test Simulation State
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(query(collection(db, 'exams'), where('authorId', '==', user.uid)), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  // Handlers
  const startLive = async (vId?: string, aId?: string) => {
    try {
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
      const constraints = {
        video: vId ? { deviceId: { exact: vId } } : true,
        audio: aId ? { deviceId: { exact: aId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setIsLiveActive(true);
    } catch (err) { alert("Erro ao acessar mídia."); }
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  const handleSaveLesson = async () => {
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const lesson = { id: editingLessonId || Math.random().toString(36).substr(2,9), ...lessonForm, order: mod.lessons.length + 1 };
    const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? lesson : l) : [...mod.lessons, lesson];
    await updateDoc(doc(db, 'modulos', mod.id), { lessons: up });
    setIsLessonModalOpen(false);
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setCurrentExam({ ...currentExam, questions: up });
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const stats = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const avg = relevant.length > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / relevant.length).toFixed(1) : '0.0';
    return { avg, elogios: relevant.filter(f => f.type === 'elogio').length, alertas: relevant.filter(f => f.type === 'reclamacao').length, sugestoes: relevant.filter(f => f.type === 'sugestao').length };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      {/* 1. MÓDULOS & MATRIZ */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl"><Layers size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Controle de Fluxo Pedagógico</p></div>
            </div>
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => setIsModuleModalOpen(true)} className="bg-indigo-600 text-white px-10 py-5 rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><Plus size={18}/> Adicionar Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[3.5rem] overflow-hidden group shadow-sm">
                  <div className="bg-slate-50/50 px-10 py-6 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="w-10 h-10 bg-indigo-100 text-indigo-700 rounded-xl flex items-center justify-center font-black text-xs">{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-xs uppercase italic tracking-widest">{mod.title}</h3>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-6 py-3 bg-indigo-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg hover:scale-105 transition-all">Add Lição</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all"><Edit3 size={18}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-3 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                    </div>
                  </div>
                  <div className="p-10 space-y-4">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-5 rounded-[2.5rem] flex items-center justify-between border border-slate-100 hover:border-indigo-100 hover:bg-indigo-50/10 transition-all group/l">
                        <div className="flex items-center gap-5">
                          <span className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 text-xs uppercase italic">{l.title}</h4>
                            <div className="flex gap-3 mt-1">
                              {l.videoUrl && <span className="text-[8px] font-black text-rose-500 uppercase flex items-center gap-1"><PlayCircle size={10}/> Vídeo Ativo</span>}
                              {l.materialUrl && <span className="text-[8px] font-black text-indigo-500 uppercase flex items-center gap-1"><FileText size={10}/> Material Base</span>}
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/l:opacity-100 transition-all">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-3 text-indigo-600 hover:bg-indigo-50 rounded-xl"><Edit3 size={18}/></button>
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-3 text-red-500 hover:bg-red-50 rounded-xl"><Trash2 size={18}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/50 p-6 rounded-[2.5rem] flex items-center justify-between border border-amber-100 shadow-sm">
                        <div className="flex items-center gap-5">
                          <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl"><CheckSquare size={20}/></div>
                          <div><h4 className="font-black text-amber-900 text-xs uppercase">Avaliação: {ex.title}</h4><span className="text-[9px] font-black text-amber-600/50 uppercase italic tracking-widest">{ex.questions?.length||0} Questões Cadastradas</span></div>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => { setCurrentExam(ex); setIsQuestionEditorOpen(true); }} className="px-6 py-3 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-lg hover:bg-amber-700 transition-all">Editar Exame</button>
                        </div>
                      </div>
                    ))}
                    {mod.lessons.length === 0 && moduleExams.length === 0 && <p className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic tracking-widest">Nenhum conteúdo vinculado a este módulo.</p>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 2. MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6">
          <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl"><FileText size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Acervo Pedagógico</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Arquivos e Documentos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-indigo-600 text-white px-10 py-5 rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all flex items-center gap-2"><Plus size={18}/> Novo Material</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 relative group hover:shadow-2xl transition-all text-center">
