      )}

      {/* -------------------- MODAIS MASTER -------------------- */}

      {/* PPTX UPLOAD */}
      {showPptUpload && (
        <div className="fixed inset-0 z-[850] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-xl rounded-[5rem] p-16 text-center shadow-2xl animate-in zoom-in-95">
