              <h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic mb-4">Apresentar Documento</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-12 italic">Seleção de Material PPTX/PDF</p>

              <div onClick={() => fileInputRef.current?.click()} className="border-4 border-dashed border-slate-100 rounded-[4rem] p-20 mb-12 hover:border-indigo-400 hover:bg-indigo-50/20 transition-all cursor-pointer group">
                 <Upload size={64} className="text-slate-200 mx-auto mb-6 group-hover:text-indigo-600 group-hover:scale-110 transition-all" />
                 <span className="text-[11px] font-black uppercase text-slate-300 group-hover:text-indigo-900 tracking-widest leading-none">Carregar PowerPoint ou PDF</span>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { /* Simulado */ } }} />
              </div>

              <div className="flex gap-5">
                 <button onClick={() => setShowPptUpload(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[10px] font-black uppercase tracking-widest italic">Cancelar</button>
                 <button onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 tracking-[0.3em] italic">Iniciar Exibição</button>
              </div>
           </div>
        </div>
      )}

