        <div className="fixed inset-0 z-[650] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[4rem] p-16 text-center shadow-2xl">
              <div className="w-20 h-20 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Layers size={40}/></div>
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-12 italic">{currentModuleId ? 'Editar Módulo' : 'Novo Módulo'}</h3>
              <div className="space-y-2 text-left mb-10">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título do Módulo</label>
                 <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Ex: Antigo Testamento..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] outline-none font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="flex gap-4">
                <button onClick={() => { setIsModuleModalOpen(false); setModuleTitle(''); setCurrentModuleId(null); }} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[2rem] text-[11px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={async () => { 
                   if(!moduleTitle) return;
                   if(currentModuleId) {
                      await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle });
                   } else {
                      await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() });
                   }
                   setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(false); 
                }} className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-[11px] font-black uppercase shadow-xl tracking-[0.2em] italic">Confirmar</button>
