              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Streaming Video Link</label>
                 <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link YouTube/Vimeo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Material de Apoio Digital</label>
                 <select value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner">
                    <option value="">Nenhum Material...</option>
                    {materials.filter(m => m.courseId === selectedCourseForModules).map(m => <option key={m.id} value={m.url}>{m.title}</option>)}
