                            onClick={() => setCurrentTestAnswers(prev => ({...prev, [q.id]: i}))}
                            className={`p-10 rounded-[3.5rem] border-2 flex items-center gap-8 transition-all cursor-pointer relative group ${currentTestAnswers[q.id] === i ? 'border-indigo-500 bg-indigo-600/20 shadow-[0_0_100px_rgba(79,70,229,0.3)]' : 'border-white/5 bg-white/5 hover:bg-white/10'}`}
