                             {currentTestAnswers[q.id] === i && <div className="absolute top-1/2 -translate-y-1/2 right-12 bg-indigo-500 text-white p-4 rounded-full shadow-2xl animate-in zoom-in-50"><CheckCircle2 size={32}/></div>}
