                             <span className={`text-xl font-bold italic tracking-tight pr-24 ${currentTestAnswers[q.id] === i ? 'text-white' : 'text-white/60 group-hover:text-white'}`}>{opt}</span>
                          </div>
                        ))}
                     </div>
                  </div>
                ))}

                <div className="pt-40 pb-40 text-center">
                   <div className="inline-block p-10 bg-white/5 backdrop-blur-3xl rounded-[4rem] border border-white/10 shadow-2xl">
                      <p className="text-xs font-black text-slate-400 uppercase tracking-[0.5em] mb-10 italic">Você finalizou todos os itens acadêmicos</p>
                      <button onClick={() => { setFullScreenMode('none'); setTestStarted(false); }} className="px-24 py-10 bg-emerald-600 text-white rounded-[3rem] text-sm font-black uppercase tracking-[0.5em] shadow-2xl hover:bg-emerald-500 transition-all active:scale-95 italic">Finalizar e Registrar Simulação</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {testStarted && (
          <div className="bg-white/5 backdrop-blur-2xl border-t border-white/10 p-8 flex justify-between items-center relative z-20">
             <div className="flex items-center gap-10">
                <div className="flex items-center gap-4">
                   <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_15px_rgba(16,185,129,0.5)]"></div>
                   <span className="text-[11px] font-black uppercase text-white/40 tracking-[0.3em] italic">Simulação Discente em Progresso</span>
                </div>
                <div className="h-10 w-px bg-white/10"></div>
                <div className="flex items-center gap-4">
                   <ListOrdered size={20} className="text-indigo-400" />
                   <span className="text-[11px] font-black uppercase text-white tracking-widest">{Object.keys(currentTestAnswers).length} de {currentExam.questions.length} Respondidas</span>
                </div>
             </div>
