                <span className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">Professor: {user.displayName}</span>
                <div className="w-10 h-10 rounded-xl bg-indigo-600/50 flex items-center justify-center font-black text-xs">{user.displayName.charAt(0)}</div>
