              <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl"><Layers size={32}/></div>
              <div><h1 className="text-2xl font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1><p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Controle de Fluxo Pedagógico</p></div>
            </div>
            <div className="flex items-center gap-3">
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500">
