              <tbody className="divide-y divide-slate-50">
                {allStudents.map(s => (
                  <tr key={s.uid} className="hover:bg-indigo-50/20 transition-all">
                    <td className="px-12 py-6 flex items-center gap-5"><div className="w-12 h-12 rounded-[1.25rem] bg-indigo-600 text-white flex items-center justify-center font-black text-xs shadow-lg">{s.displayName.charAt(0)}</div><span className="text-sm font-black uppercase italic text-slate-900 tracking-tighter">{s.displayName}</span></td>
