                       <span className="text-xs font-black uppercase tracking-[0.3em]">AO VIVO</span>
                    </div>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className="bg-zinc-900/90 backdrop-blur-3xl px-8 py-4 rounded-full border border-white/10 flex items-center gap-4 hover:bg-indigo-600 transition-all">
                       <Users size={18}/><span className="text-xs font-black uppercase">{allStudents.length} Online</span>
                    </button>
                 </div>
                 <div className="flex items-center gap-4 pointer-events-auto">
                    <div className="bg-indigo-600 px-8 py-4 rounded-[2rem] text-xs font-black uppercase flex items-center gap-4 shadow-2xl">
                       <ShieldCheck size={20}/> PROFESSOR: {user.displayName}
                    </div>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className="p-5 bg-zinc-900/90 backdrop-blur-3xl rounded-full hover:bg-white/10 transition-all shadow-xl"><Settings size={24}/></button>
                 </div>
              </div>

              <div className="flex-1 flex overflow-hidden">
                 <div className="flex-1 relative flex items-center justify-center p-8 lg:p-16">
                    <div className="absolute inset-0 pointer-events-none z-[650] overflow-hidden">
                       {activeReactions.map(r => (
                         <div key={r.id} className="absolute bottom-32 text-8xl animate-bounce-up opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
                       ))}
                    </div>

                    <div className={`w-full h-full max-w-[1920px] aspect-video bg-zinc-900 rounded-[5rem] overflow-hidden border border-white/10 relative group transition-all duration-700 shadow-[0_50px_150px_rgba(0,0,0,1)] ${activePanel !== 'none' ? 'lg:mr-10 scale-[0.97]' : ''}`}>
                       {isPresentationMode ? (
                         <div className="w-full h-full bg-white flex flex-col items-center justify-center text-zinc-900 relative animate-in zoom-in-95">
                            <Presentation size={160} className="text-indigo-600 mb-10 opacity-10" />
                            <h2 className="text-5xl font-black uppercase italic tracking-tighter">EXIBIÇÃO DE SLIDE {presentationSlide}</h2>
                            <p className="text-zinc-400 font-black text-sm uppercase mt-4 tracking-widest">Material Acadêmico de Apoio</p>
                            <div className="absolute inset-x-20 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                               <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-10 bg-zinc-100 rounded-full text-zinc-600 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto active:scale-90"><ChevronLeft size={48}/></button>
                               <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-10 bg-zinc-100 rounded-full text-zinc-600 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto active:scale-90"><ChevronRight size={48}/></button>
                            </div>
                         </div>
                       ) : (
                         <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-all ${videoActive ? 'opacity-100' : 'opacity-0'} ${virtualBg === 'blur' ? 'blur-3xl' : ''}`} />
                       )}

                       <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-zinc-950/95 backdrop-blur-3xl px-12 py-7 rounded-[3.5rem] border border-white/10 shadow-[0_40px_100px_rgba(0,0,0,1)] opacity-0 group-hover:opacity-100 transition-all scale-95 group-hover:scale-100">
                          <button onClick={toggleMic} className={`p-6 rounded-3xl transition-all shadow-xl ${micActive ? 'bg-white/5 hover:bg-white/10' : 'bg-rose-600 shadow-rose-900/40'}`}>{micActive ? <Mic size={28}/> : <MicOff size={28}/>}</button>
                          <button onClick={toggleVideo} className={`p-6 rounded-3xl transition-all shadow-xl ${videoActive ? 'bg-white/5 hover:bg-white/10' : 'bg-rose-600 shadow-rose-900/40'}`}>{videoActive ? <Video size={28}/> : <VideoOff size={28}/>}</button>

                          <div className="w-px h-12 bg-white/10 mx-2"></div>

                          <button onClick={startScreenShare} className={`p-6 rounded-3xl transition-all shadow-xl ${screenShareActive ? 'bg-indigo-600' : 'bg-white/5 hover:bg-white/10'}`} title="Desktop Share"><Monitor size={28}/></button>
                          <button onClick={() => setShowPptUpload(true)} className={`p-6 rounded-3xl transition-all shadow-xl ${isPresentationMode ? 'bg-indigo-600' : 'bg-white/5 hover:bg-white/10'}`} title="PPTX Presenter"><Presentation size={28}/></button>

                          <div className="w-px h-12 bg-white/10 mx-2"></div>
                          <div className="flex gap-2 bg-black/50 p-3 rounded-3xl border border-white/5">
                             {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-3 hover:bg-white/10 rounded-2xl transition-all text-2xl active:scale-125">{e}</button>)}
                          </div>

                          <div className="w-px h-12 bg-white/10 mx-2"></div>
                          <button onClick={stopLive} className="px-12 py-7 bg-rose-600 hover:bg-rose-700 rounded-[2.5rem] text-xs font-black uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center gap-4"><PhoneOff size={24}/> Encerrar Aula</button>
                       </div>

                       <div className="absolute right-12 top-1/2 -translate-y-1/2 flex flex-col gap-6 opacity-0 group-hover:opacity-100 transition-all">
                          <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-6 rounded-3xl border transition-all shadow-2xl ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/60 border-white/5 hover:bg-white/10'}`}><MessageSquare size={32}/></button>
                          <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-6 rounded-3xl border transition-all shadow-2xl ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/60 border-white/5 hover:bg-white/10'}`}><Users size={32}/></button>
                       </div>
                    </div>
                 </div>

                 {activePanel !== 'none' && (
                   <div className="w-[450px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right duration-500 h-full shadow-[0_0_150px_rgba(0,0,0,1)] relative z-[750]">
                      <div className="p-12 border-b border-white/5 flex items-center justify-between">
                         <h4 className="text-sm font-black uppercase tracking-[0.3em] italic">{activePanel === 'chat' ? 'Chat da Turma' : activePanel === 'participants' ? 'Moderação Discente' : 'Opções de Studio'}</h4>
                         <button onClick={() => setActivePanel('none')} className="p-4 bg-white/5 rounded-full hover:bg-white/10"><X size={24}/></button>
                      </div>
                      <div className="flex-1 overflow-y-auto p-10 space-y-6 custom-scrollbar">
                         {activePanel === 'chat' ? (
                           chatMessages.map((m, i) => (
                             <div key={i} className="animate-in fade-in slide-in-from-bottom-3">
                                <div className="flex items-center gap-3 mb-2"><span className="text-xs font-black text-indigo-400 uppercase italic">{m.user}</span><span className="text-[10px] text-white/20 font-bold">{m.time}</span></div>
                                <p className="text-sm font-medium text-white/70 bg-white/5 p-6 rounded-[2rem] border border-white/5 italic leading-relaxed">"{m.text}"</p>
                             </div>
                           ))
                         ) : activePanel === 'participants' ? (
                           allStudents.map(s => (
                             <div key={s.uid} className="p-6 bg-white/5 rounded-[2.5rem] border border-white/5 flex items-center justify-between group/u hover:bg-white/10 transition-all">
                                <div className="flex items-center gap-5">
                                   <div className="w-12 h-12 rounded-2xl bg-zinc-800 flex items-center justify-center font-black text-sm">{(s.displayName||'U').charAt(0)}</div>
                                   <span className="text-sm font-black uppercase italic text-white/80">{s.displayName}</span>
                                </div>
                                <div className="flex gap-2 opacity-0 group-hover/u:opacity-100 transition-all">
                                   <button className="p-4 bg-white/5 hover:bg-rose-600 rounded-2xl" title="Mutar"><VolumeX size={16}/></button>
                                   <button className="p-4 bg-white/5 hover:bg-rose-600 rounded-2xl" title="Expulsar"><UserX size={16}/></button>
                                </div>
                             </div>
                           ))
                         ) : (
                           <div className="space-y-10">
                              <div className="space-y-5">
                                 <h5 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 italic">Input de Mídia</h5>
                                 <select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLive(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600">
                                    <option value="">Câmera Master...</option>
                                    {devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}
                                 </select>
                                 <select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLive(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600">
                                    <option value="">Microfone Master...</option>
                                    {devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}
                                 </select>
                              </div>
                           </div>
                         )}
                      </div>
                   </div>
                 )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* MODAIS GERAIS */}
      {showPptUpload && (
        <div className="fixed inset-0 z-[850] bg-slate-950/98 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-xl rounded-[5rem] p-16 text-center shadow-2xl animate-in zoom-in-95">
              <div className="w-24 h-24 bg-indigo-50 rounded-[3rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Presentation size={48}/></div>
              <h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic mb-4">Apresentar Documento</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-12 italic">Seleção de Material PPTX/PDF</p>

              <div onClick={() => fileInputRef.current?.click()} className="border-4 border-dashed border-slate-100 rounded-[4rem] p-20 mb-12 hover:border-indigo-400 hover:bg-indigo-50/20 transition-all cursor-pointer group">
                 <Upload size={64} className="text-slate-200 mx-auto mb-6 group-hover:text-indigo-600 group-hover:scale-110 transition-all" />
                 <span className="text-[11px] font-black uppercase text-slate-300 group-hover:text-indigo-900 tracking-widest leading-none">Carregar PowerPoint ou PDF</span>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { /* Simulado */ } }} />
              </div>

              <div className="flex gap-5">
                 <button onClick={() => setShowPptUpload(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[10px] font-black uppercase tracking-widest italic">Cancelar</button>
                 <button onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 tracking-[0.3em] italic">Iniciar Exibição</button>
              </div>
           </div>
        </div>
      )}

      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[650] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[4rem] p-16 text-center shadow-2xl">
              <div className="w-20 h-20 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Layers size={40}/></div>
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-12 italic">{currentModuleId ? 'Editar Módulo' : 'Novo Módulo'}</h3>
              <div className="space-y-2 text-left mb-10">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título do Módulo</label>
                 <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Ex: Antigo Testamento..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] outline-none font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="flex gap-4">
                <button onClick={() => { setIsModuleModalOpen(false); setModuleTitle(''); setCurrentModuleId(null); }} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[2rem] text-[11px] font-black uppercase tracking-widest">Descartar</button>
                <button onClick={async () => { 
                   if(!moduleTitle) return;
                   if(currentModuleId) {
                      await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle });
                   } else {
                      await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() });
                   }
                   setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(false); 
                }} className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-[11px] font-black uppercase shadow-xl tracking-[0.2em] italic">Confirmar</button>
              </div>
           </div>
        </div>
      )}

      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
          <div className="bg-white w-full max-w-xl rounded-[4rem] p-16 space-y-10 shadow-2xl overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{editingLessonId ? 'Editar Aula Master' : 'Criar Aula Master'}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Configuração Detalhada de Conteúdo</p></div>
            <div className="space-y-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título do Encontro</label>
                 <input value={lessonForm.title} onChange={e => setLessonForm({...lessonForm, title: e.target.value})} placeholder="Título envolvente..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Streaming Video Link</label>
                 <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link YouTube/Vimeo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner focus:ring-2 focus:ring-indigo-600" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Material de Apoio Digital</label>
                 <select value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner">
                    <option value="">Nenhum Material...</option>
                    {materials.filter(m => m.courseId === selectedCourseForModules).map(m => <option key={m.id} value={m.url}>{m.title}</option>)}
                 </select>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Descrição Pedagógica</label>
                 <textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="O que será abordado..." className="w-full px-10 py-8 bg-slate-50 border-none rounded-[2.5rem] h-40 font-medium text-sm shadow-inner resize-none focus:ring-2 focus:ring-indigo-600"></textarea>
              </div>
            </div>
            <div className="flex gap-4 pt-6">
              <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
              <button onClick={handleSaveLesson} className="flex-1 py-7 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.3em] italic">Publicar Aula</button>
            </div>
          </div>
        </div>
      )}

      {isExamModalOpen && (
        <div className="fixed inset-0 z-[650] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-16 space-y-10 shadow-2xl">
              <div className="flex items-center gap-6">
                 <div className="p-6 bg-amber-50 text-amber-600 rounded-[2rem] shadow-sm"><Award size={40} /></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Novo Exame</h3>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título da Atividade</label>
                    <input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Final de Teologia..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Módulo Referente</label>
                    <select value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner">
                       <option value="">Vincular a Módulo...</option>
                       {modules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                    </select>
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Tipo</label>
                       <select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-8 py-6 bg-slate-50 border-none rounded-[2rem] text-[10px] font-black uppercase shadow-inner"><option value="activity">Atividade</option><option value="evaluation">Prova Final</option></select>
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Média %</label>
                       <input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-8 py-6 bg-slate-50 border-none rounded-[2rem] font-black shadow-inner" />
                    </div>
                 </div>
              </div>
              <div className="flex gap-4 pt-10">
                <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={async () => {
                  const payload = { ...examForm, courseId: selectedCourseForModules, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() };
                  if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload);
                  else await addDoc(collection(db, 'exams'), payload);
                  setIsExamModalOpen(false);
                }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-xl hover:bg-indigo-700 tracking-widest italic">Salvar Exame</button>
              </div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[650] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-16 text-center shadow-2xl">
              <div className="w-20 h-20 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-10 text-emerald-600 shadow-inner"><FileText size={40}/></div>
              <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-10 italic">Adicionar Recurso</h3>
              <div className="space-y-6 mb-10 text-left">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Título do Documento</label>
                    <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: Apostila de Teologia..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Link Digital (Drive/PDF)</label>
                    <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Arquivo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
                 </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[2rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
                <button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-[11px] font-black uppercase shadow-xl italic tracking-widest">Gravar</button>
              </div>
           </div>
        </div>
      )}

      {isScheduleModalOpen && (
        <div className="fixed inset-0 z-[650] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[4rem] p-16 shadow-2xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full -mr-16 -mt-16 opacity-50 blur-3xl"></div>
              <div className="flex items-center gap-6 mb-12">
                 <div className="p-6 bg-amber-50 text-amber-600 rounded-[2rem] shadow-inner"><Bell size={40} /></div>
                 <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Agendar Aula</h3>
              </div>
              <div className="space-y-6 mb-12">
                 <input placeholder="Título da Transmissão..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
                 <input type="datetime-local" className="w-full px-10 py-6 bg-slate-50 border-none rounded-[2rem] font-bold shadow-inner" />
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-7 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest">Cancelar</button>
                 <button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-7 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase hover:bg-indigo-600 transition-all shadow-2xl italic">Confirmar</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Master" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

