  useEffect(() => {
    const fetchSignature = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) {
          setUserSignature(userDoc.data().signatureUrl || null);
        }
      }
    };
    fetchSignature();
  }, []);

  const saveSignature = async (base64: string) => {
    if (auth.currentUser) {
      await updateDoc(doc(db, 'users', auth.currentUser.uid), {
        signatureUrl: base64
      });
      setUserSignature(base64);
      setIsSignModalOpen(false);
    }
  };

  const sections = [
    { title: 'Gestão de Equipe', desc: 'Gerencie cargos, permissões e novos colaboradores.', icon: <Users className="text-indigo-600" /> },
    { title: 'Perfil da Escola', desc: 'Dados institucionais, logotipos e contatos.', icon: <Building className="text-slate-600" /> },
    { title: 'Assinaturas Digitais', desc: 'Configurações de certificados e validade jurídica.', icon: <Shield className="text-emerald-600" /> },
    { title: 'Plano e Faturamento', desc: 'Acompanhe sua assinatura do sistema LMS.', icon: <CreditCard className="text-amber-600" /> },
