      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Card de Assinatura Digital */}
        <div className="col-span-full bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
           <div className="flex items-center gap-6">
              <div className="p-5 bg-indigo-50 text-indigo-600 rounded-3xl shadow-sm">
                 <PenTool size={32} />
              </div>
              <div>
                 <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Sua Assinatura Institucional</h3>
                 <p className="text-xs text-slate-500 font-medium">Necessária para emissão automática de certificados válidos.</p>
              </div>
           </div>

           {userSignature ? (
             <div className="flex flex-col items-center gap-3">
               <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                 <img src={userSignature} alt="Assinatura" className="h-12 object-contain grayscale" />
               </div>
               <button onClick={() => setIsSignModalOpen(true)} className="text-[9px] font-black uppercase text-indigo-600 hover:underline">Atualizar Assinatura</button>
             </div>
           ) : (
             <button onClick={() => setIsSignModalOpen(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all shadow-xl shadow-slate-200 flex items-center gap-2">
                <PenTool size={16}/> Coletar Assinatura Agora
             </button>
           )}
