        {sections.map((section, i) => (
          <button 
            key={i}
            className="flex items-center gap-4 p-6 bg-white border border-slate-200 rounded-xl hover:border-indigo-400 hover:shadow-md transition-all text-left group"
          >
            <div className="p-3 bg-slate-50 rounded-xl group-hover:bg-indigo-50 transition-colors">
              {section.icon}
            </div>
            <div className="flex-1">
              <h3 className="font-bold text-slate-900 text-sm">{section.title}</h3>
              <p className="text-slate-500 text-xs mt-0.5">{section.desc}</p>
            </div>
            <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-500" />
          </button>
        ))}
      </div>

      <div className="p-6 bg-slate-100 rounded-xl border border-slate-200 mt-8">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Informações Técnicas</h3>
        <div className="space-y-2 text-xs font-mono text-slate-500">
          <p>Versão do Sistema: 1.0.4-stable</p>
          <p>Database: Google Cloud Firestore / siteigreja-461f6</p>
          <p>Ambiente: Produção</p>
        </div>
      </div>

      {isSignModalOpen && (
        <SignaturePad 
          title="Assinatura do Diretor"
          onCancel={() => setIsSignModalOpen(false)}
          onSave={saveSignature}
        />
      )}
    </div>
  );
};

