            <div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{editingLessonId ? 'Editar Aula Master' : 'Criar Aula Master'}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Configuração Detalhada de Conteúdo</p></div>
            <div className="space-y-6">
