import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, PieChart, Activity, Share2, Image as LucideImage
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live Stream States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais de Formulários
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Test Simulation State
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(query(collection(db, 'exams'), where('authorId', '==', user.uid)), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  // Handlers Live
  const startLive = async (vId?: string, aId?: string) => {
    try {
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
      const constraints = {
        video: vId ? { deviceId: { exact: vId } } : true,
        audio: aId ? { deviceId: { exact: aId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setIsLiveActive(true);
    } catch (err) { alert("Erro ao acessar mídia."); }
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
    setSelectedFileName(null);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  // Handlers Pedagógicos
  const handleSaveLesson = async () => {
    const mod = modules.find(m => m.id === currentModuleId);
    if (!mod) return;
    const lesson = { id: editingLessonId || Math.random().toString(36).substr(2,9), ...lessonForm, order: mod.lessons.length + 1 };
    const up = editingLessonId ? mod.lessons.map(l => l.id === editingLessonId ? lesson : l) : [...mod.lessons, lesson];
    await updateDoc(doc(db, 'modulos', mod.id), { lessons: up });
    setIsLessonModalOpen(false);
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setCurrentExam({ ...currentExam, questions: up });
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < currentExam.questions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180); 
    } else {
      setFullScreenMode('none');
      setTestStarted(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const categories = {
      elogio: relevant.filter(f => f.type === 'elogio').length,
      reclamacao: relevant.filter(f => f.type === 'reclamacao').length,
      sugestao: relevant.filter(f => f.type === 'sugestao').length
    };
    const ratingDistribution = [1, 2, 3, 4, 5].map(star => ({
      star, count: relevant.filter(f => f.rating === star).length
    }));
    return { avg, total, categories, ratingDistribution, relevant };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // VIEW: PREVIEW DO CURSO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-10 py-6 flex items-center justify-between sticky top-0 z-10 shadow-2xl">
          <div className="flex items-center gap-6">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full transition-all"><ArrowLeft size={24}/></button>
            <div>
              <h2 className="text-xl font-black uppercase tracking-tight italic">Ambiente do Aluno</h2>
              <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Curso: {courses.find(c => c.id === selectedCourseForModules)?.nome}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-8 py-3 bg-indigo-600 rounded-2xl text-[10px] font-black uppercase shadow-lg shadow-indigo-900/50 hover:bg-indigo-500">Sair da Simulação</button>
        </header>

        <div className="flex-1 flex overflow-hidden">
          <aside className="w-80 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6 hidden md:block">
            <h3 className="text-[10px] font-black uppercase text-slate-400 mb-6 tracking-widest">Estrutura de Ensino</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-3">
                  <div className="flex items-center gap-2 text-xs font-black uppercase text-indigo-600 italic">
                    <span className="w-6 h-6 rounded bg-indigo-100 flex items-center justify-center text-[10px]">{idx + 1}</span>
                    {m.title}
                  </div>
                  <div className="pl-8 space-y-2">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[11px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer transition-colors group">
                        <PlayCircle size={14} className="text-slate-300 group-hover:text-indigo-600" /> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>

          <main className="flex-1 overflow-y-auto p-12 bg-white">
            <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in duration-700">
              <div className="aspect-video bg-slate-900 rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.1)] flex flex-col items-center justify-center text-white/50 group relative overflow-hidden">
                 <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
                 <Play size={100} className="text-white group-hover:scale-110 transition-transform cursor-pointer relative z-10" />
                 <p className="mt-6 text-xs font-black uppercase tracking-[0.4em] relative z-10 text-white/70 italic">Streaming Master 4K</p>
              </div>

              <div className="space-y-8">
                <div className="flex items-center gap-4">
                   <div className="h-10 w-1 bg-indigo-600 rounded-full"></div>
                   <h1 className="text-5xl font-black text-slate-900 tracking-tighter uppercase italic">Lição Inaugural</h1>
                </div>
                <p className="text-slate-500 leading-relaxed text-xl font-medium italic">Simulação pedagógica concluída. O aluno terá acesso a esta interface limpa e focada para garantir o máximo aproveitamento dos estudos teológicos.</p>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-10">
                   <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-100 flex items-center gap-8 group hover:border-indigo-200 transition-all cursor-pointer">
                      <div className="p-5 bg-white rounded-3xl shadow-sm text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all"><FileText size={40}/></div>
                      <div><h4 className="font-black text-sm uppercase italic">Documentação</h4><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Apostila Completa em PDF</p></div>
                   </div>
                   <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-100 flex items-center gap-8 group hover:border-amber-200 transition-all cursor-pointer">
                      <div className="p-5 bg-white rounded-3xl shadow-sm text-amber-600 group-hover:bg-amber-600 group-hover:text-white transition-all"><Award size={40}/></div>
                      <div><h4 className="font-black text-sm uppercase italic">Avaliação</h4><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Simulado de Conhecimento</p></div>
                   </div>
                </div>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }

  // TELA CHEIA: EDITOR DE QUESTÕES
  if (fullScreenMode === 'question_editor' && currentExam) {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-50 flex flex-col animate-in fade-in overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-10 py-6 flex items-center justify-between sticky top-0 z-10 shadow-sm">
          <div className="flex items-center gap-6">
            <button onClick={() => setFullScreenMode('none')} className="p-3 bg-slate-100 hover:bg-slate-200 rounded-full transition-all"><ArrowLeft size={24}/></button>
            <div>
              <h2 className="text-2xl font-black uppercase tracking-tighter italic leading-none">Editor de Exame: {currentExam.title}</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2 italic">Ref: {currentExam.id.substring(0,8)}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="bg-slate-900 text-white px-10 py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-indigo-600 shadow-xl transition-all tracking-widest">Finalizar Gestão</button>
        </header>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-slate-50/50 p-10">
          <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-5 space-y-8 sticky top-0 h-fit">
              <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-xl shadow-indigo-100/20">
                <div className="flex items-center gap-4 mb-10">
                  <div className="p-4 bg-indigo-600 text-white rounded-3xl"><Plus size={24}/></div>
                  <h3 className="font-black uppercase text-sm tracking-tight italic">Novo Item Acadêmico</h3>
                </div>
                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Enunciado da Questão</label>
                    <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Descreva a pergunta aqui..." className="w-full px-8 py-8 bg-slate-50 border-none rounded-[2.5rem] h-40 font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600 resize-none"></textarea>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-2">Alternativas Master</label>
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3">
                        <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-14 h-14 rounded-2xl font-black text-sm transition-all shadow-md ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border-2 border-slate-100 text-slate-300 hover:border-indigo-400'}`}>{String.fromCharCode(65+i)}</button>
                        <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Alternativa ${String.fromCharCode(65+i)}...`} className="flex-1 px-8 py-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600 transition-all" />
                      </div>
                    ))}
                  </div>
                  <button onClick={handleSaveQuestion} className="w-full py-7 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.4em] italic shadow-2xl hover:bg-indigo-700 active:scale-95 transition-all">Anexar ao Banco</button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-7 space-y-6">
              <div className="bg-white rounded-[4rem] border border-slate-200 overflow-hidden shadow-sm">
                <div className="p-10 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-4"><ListOrdered className="text-indigo-600" size={24}/><h4 className="font-black uppercase text-xs tracking-widest italic">Banco de Questões ({currentExam.questions?.length||0})</h4></div>
                  <span className="text-[10px] font-black text-slate-300 uppercase italic tracking-widest">Sincronizado</span>
                </div>
                <div className="divide-y divide-slate-100">
                  {(currentExam.questions || []).map((q, idx) => (
                    <div key={q.id} className="p-10 hover:bg-indigo-50/20 transition-all group">
                      <div className="flex items-start justify-between gap-6">
                        <div className="flex items-start gap-8 flex-1">
                          <span className="w-14 h-14 rounded-3xl bg-slate-900 text-white flex items-center justify-center font-black text-lg italic shadow-lg mt-1 group-hover:scale-110 transition-transform">#{idx+1}</span>
                          <div className="flex-1">
                            <p className="text-lg font-black uppercase italic text-slate-800 leading-tight mb-8 pr-10">{q.text}</p>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              {q.options.map((opt, oi) => (
                                <div key={oi} className={`px-6 py-3 rounded-2xl text-[10px] font-bold border flex items-center gap-3 transition-all ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-700 border-emerald-200 shadow-sm' : 'bg-white text-slate-400 border-slate-100'}`}>
                                  <span className={`w-6 h-6 rounded-lg flex items-center justify-center text-[10px] ${oi === q.correctOption ? 'bg-emerald-500 text-white' : 'bg-slate-100'}`}>{String.fromCharCode(65+oi)}</span>
                                  {opt}
                                </div>
                              ))}
                            </div>
                          </div>
                        </div>
                        <button onClick={async () => { if(confirm('Excluir esta questão?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-4 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all opacity-0 group-hover:opacity-100"><Trash2 size={24}/></button>
                      </div>
                    </div>
                  ))}
                  {(!currentExam.questions || currentExam.questions.length === 0) && (
                    <div className="p-40 text-center flex flex-col items-center gap-6">
                       <ClipboardList size={80} className="text-slate-100" />
                       <p className="text-[11px] font-black text-slate-300 uppercase italic tracking-[0.6em]">Nenhum item cadastrado</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // TELA CHEIA: SIMULADOR DE EXAME (SOLICITADO COMPACTO)
  if (fullScreenMode === 'test_simulation' && currentExam) {
    const q = currentExam.questions[currentQuestionIndex];
    const progress = ((currentQuestionIndex + 1) / (currentExam.questions?.length || 1)) * 100;
    const timerProgress = (timeLeft / 180) * 100;

    return (
      <div className="fixed inset-0 z-[1000] bg-[#0a0a0a] flex flex-col animate-in fade-in overflow-hidden text-white font-sans">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/5 rounded-full blur-[150px] -mr-80 -mt-80"></div>
        <header className="bg-black/40 backdrop-blur-3xl border-b border-white/5 px-6 md:px-12 py-5 flex items-center justify-between relative z-20">
           <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 rounded-xl shadow-2xl hidden sm:block"><Timer size={20}/></div>
              <div>
                <h2 className="text-lg font-black uppercase italic tracking-tighter leading-none">{currentExam.title}</h2>
                <div className="flex items-center gap-3 mt-1.5">
                   <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.3em]">Item {currentQuestionIndex + 1} de {currentExam.questions.length}</span>
                   <div className="w-32 h-1 bg-white/5 rounded-full overflow-hidden"><div className="h-full bg-indigo-500 transition-all duration-500" style={{ width: `${progress}%` }}></div></div>
                </div>
              </div>
           </div>
           <div className="flex items-center gap-6">
              <div className={`flex items-center gap-3 px-5 py-2.5 rounded-full border transition-all ${timeLeft < 30 ? 'bg-rose-500/10 border-rose-500 text-rose-500 animate-pulse' : 'bg-white/5 border-white/10 text-indigo-400'}`}>
                 <Timer size={16} /><span className="text-xs font-black tabular-nums tracking-widest">{formatTime(timeLeft)}</span>
              </div>
              <button onClick={() => { setFullScreenMode('none'); setTestStarted(false); }} className="p-3 bg-white/5 hover:bg-rose-600 text-white/50 hover:text-white rounded-full transition-all"><X size={20}/></button>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto custom-scrollbar relative z-10 flex flex-col">
           {!testStarted ? (
             <div className="flex-1 flex items-center justify-center p-6">
                <div className="bg-white text-slate-900 w-full max-w-2xl rounded-[4rem] p-16 text-center shadow-2xl animate-in zoom-in-95">
                   <div className="w-24 h-24 bg-indigo-50 rounded-[3rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><ShieldAlert size={50} className="animate-bounce-slow" /></div>
                   <h3 className="text-4xl font-black uppercase tracking-tighter italic mb-6">Protocolo de Exame</h3>
                   <div className="space-y-4 mb-14 text-slate-500 font-medium italic leading-relaxed text-sm text-left bg-slate-50 p-10 rounded-[3rem] border border-slate-100">
                      <div className="flex gap-4"><Clock size={20} className="text-rose-500 flex-shrink-0" /><p>Limite de <strong>3 minutos</strong> por item. O sistema salva automaticamente.</p></div>
                      <div className="flex gap-4"><Award size={20} className="text-emerald-500 flex-shrink-0" /><p>Média para aprovação configurada em <strong>{currentExam.passingGrade}%</strong>.</p></div>
                   </div>
                   <button onClick={() => { setTestStarted(true); setTimeLeft(180); setCurrentQuestionIndex(0); }} className="w-full py-8 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.5em] italic shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">Iniciar Simulação Agora</button>
                </div>
             </div>
           ) : q ? (
             <div className="flex-1 flex flex-col items-center justify-center p-12">
                <div className="w-full max-w-4xl space-y-12 animate-in fade-in slide-in-from-bottom-10 duration-500">
                   <div className="text-center space-y-8">
                      <div className="inline-block px-5 py-2 bg-indigo-600/20 text-indigo-400 text-[10px] font-black uppercase rounded-xl border border-indigo-500/30 tracking-widest italic">Análise de Conteúdo</div>
                      <h4 className="text-3xl md:text-5xl font-black text-white uppercase italic tracking-tighter leading-[1.1]">{q.text}</h4>
                   </div>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                      {q.options.map((opt, i) => (
                        <div 
                          key={i} 
                          onClick={() => setCurrentTestAnswers(prev => ({...prev, [q.id]: i}))}
                          className={`p-10 rounded-[3.5rem] border-2 flex items-center gap-8 transition-all cursor-pointer relative group ${currentTestAnswers[q.id] === i ? 'border-indigo-500 bg-indigo-600/10 shadow-[0_0_80px_rgba(79,70,229,0.2)]' : 'border-white/5 bg-white/5 hover:bg-white/10'}`}
                        >
                           {currentTestAnswers[q.id] === i && <div className="absolute -top-4 -right-4 bg-indigo-600 text-white p-3 rounded-full shadow-2xl animate-in zoom-in-50"><CheckCircle2 size={24}/></div>}
                           <div className={`w-14 h-14 rounded-3xl flex items-center justify-center font-black text-xl shadow-inner transition-colors ${currentTestAnswers[q.id] === i ? 'bg-indigo-500 text-white' : 'bg-zinc-800 text-white/20 border border-white/5'}`}>{String.fromCharCode(65+i)}</div>
                           <span className={`text-xl font-bold italic tracking-tight pr-6 ${currentTestAnswers[q.id] === i ? 'text-white' : 'text-white/40 group-hover:text-white transition-colors'}`}>{opt}</span>
                        </div>
                      ))}
                   </div>
                   <div className="flex flex-col items-center gap-10 pt-10">
                      <div className="w-full max-w-md h-1.5 bg-white/5 rounded-full overflow-hidden"><div className={`h-full transition-all duration-1000 linear ${timeLeft < 30 ? 'bg-rose-500' : 'bg-indigo-500'}`} style={{ width: `${timerProgress}%` }}></div></div>
                      <button 
                        disabled={currentTestAnswers[q.id] === undefined}
                        onClick={handleNextQuestion} 
                        className={`group px-24 py-10 rounded-[3.5rem] text-[12px] font-black uppercase tracking-[0.5em] italic shadow-2xl transition-all flex items-center gap-6 ${currentTestAnswers[q.id] !== undefined ? 'bg-white text-black hover:bg-indigo-500 hover:text-white active:scale-95' : 'bg-white/5 text-white/20 cursor-not-allowed border border-white/10'}`}
                      >
                         {currentQuestionIndex < currentExam.questions.length - 1 ? (
                           <>Próxima Etapa <ChevronRight size={20} className="group-hover:translate-x-2 transition-transform" /></>
                         ) : (
                           <>Finalizar e Salvar <ChevronLast size={20} /></>
                         )}
                      </button>
                   </div>
                </div>
             </div>
           ) : null}
        </div>
      </div>
    );
  }

  // RENDERIZAÇÃO DAS ABAS PRINCIPAIS
  return (
    <div className="space-y-6 pb-20 animate-in fade-in h-full">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-5 duration-500">
          <div className="bg-white p-12 rounded-[4.5rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-8">
            <div className="flex items-center gap-8">
              <div className="p-5 bg-indigo-600 text-white rounded-[2rem] shadow-xl shadow-indigo-100"><Layers size={32}/></div>
              <div><h1 className="text-3xl font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1><p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-1">Gestão Completa de Conteúdo EAD</p></div>
            </div>
            <div className="flex flex-wrap items-center gap-4 justify-center">
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-[2rem] text-[10px] font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-3"><Eye size={20}/> Preview Aluno</button>
              <button onClick={() => setIsSignModalOpen(true)} className="bg-amber-50 text-amber-600 px-8 py-4 rounded-[2rem] text-[10px] font-black uppercase hover:bg-amber-100 transition-all flex items-center gap-3 border border-amber-100"><PenTool size={20}/> {userSignature ? 'Editar Assinatura' : 'Coletar Assinatura'}</button>
              <div className="h-10 w-px bg-slate-200 hidden lg:block mx-2"></div>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-[1.5rem] px-8 py-4 text-[10px] font-black uppercase outline-none focus:ring-2 focus:ring-indigo-600 shadow-inner">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-10 py-5 rounded-[2rem] text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all active:scale-95 flex items-center gap-3"><Plus size={20}/> Novo Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[4rem] overflow-hidden group shadow-sm hover:shadow-2xl hover:border-indigo-100 transition-all duration-500">
                  <div className="bg-slate-50/50 px-12 py-8 border-b flex items-center justify-between group-hover:bg-white transition-colors">
                    <div className="flex items-center gap-6">
                      <span className="w-14 h-14 bg-indigo-100 text-indigo-700 rounded-[1.5rem] flex items-center justify-center font-black text-lg italic shadow-inner">#{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-sm uppercase italic tracking-[0.1em]">{mod.title}</h3>
                    </div>
                    <div className="flex items-center gap-3">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-8 py-4 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-2xl shadow-lg hover:scale-105 transition-all">Add Lição</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-4 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-2xl transition-all shadow-sm"><Edit3 size={20}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo permanentemente?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-4 text-slate-200 hover:text-rose-600 transition-all"><Trash2 size={20}/></button>
                    </div>
                  </div>
                  <div className="p-12 space-y-5">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-7 rounded-[3rem] flex items-center justify-between border border-slate-100 hover:border-indigo-200 hover:shadow-xl transition-all group/l">
                        <div className="flex items-center gap-7">
                          <span className="w-10 h-10 rounded-[1rem] bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all italic">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 text-xs uppercase italic tracking-wider">{l.title}</h4>
                            <div className="flex gap-4 mt-2">
                              {l.videoUrl && <span className="text-[9px] font-black text-rose-500 uppercase flex items-center gap-1.5 bg-rose-50 px-3 py-1 rounded-lg border border-rose-100 shadow-sm"><PlayCircle size={12}/> Vídeo Master Ativo</span>}
                              {l.materialUrl && <span className="text-[9px] font-black text-indigo-500 uppercase flex items-center gap-1.5 bg-indigo-50 px-3 py-1 rounded-lg border border-indigo-100 shadow-sm"><FileText size={12}/> Guia de Estudo</span>}
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-3 opacity-0 group-hover/l:opacity-100 transition-all">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-4 text-indigo-600 hover:bg-indigo-50 rounded-2xl transition-all shadow-sm bg-white"><Edit3 size={18}/></button>
                          <button onClick={async () => { if(confirm('Excluir aula?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-4 text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"><Trash2 size={18}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/30 p-10 rounded-[3.5rem] flex items-center justify-between border border-amber-100 shadow-sm hover:shadow-xl hover:bg-amber-50 transition-all duration-500">
                        <div className="flex items-center gap-7">
                          <div className="p-5 bg-amber-100 text-amber-600 rounded-[1.5rem] shadow-inner"><Award size={32}/></div>
                          <div><h4 className="font-black text-amber-900 text-sm uppercase italic">Avaliação Master: {ex.title}</h4><span className="text-[10px] font-black text-amber-600/60 uppercase italic tracking-[0.2em] mt-1 block">{ex.questions?.length||0} Itens Acadêmicos • {ex.passingGrade}% Média</span></div>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="px-10 py-5 bg-amber-600 text-white text-[11px] font-black uppercase rounded-[1.5rem] shadow-xl hover:bg-amber-700 transition-all active:scale-95 italic tracking-widest">Gerir Banco</button>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* FEEDBACK DASHBOARD (RESTAURADO E MELHORADO) */}
      {activeSub === 'feedback' && (
        <div className="space-y-10 animate-in fade-in duration-500">
          <div className="bg-white p-12 rounded-[4.5rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-8">
            <div className="flex items-center gap-8">
              <div className="p-6 bg-indigo-600 text-white rounded-[2.5rem] shadow-2xl shadow-indigo-100"><BarChart3 size={40}/></div>
