id, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-8 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase hover:bg-indigo-600 transition-all shadow-2xl italic tracking-[0.5em] active:scale-95">Salvar Agenda</button></div></div></div>
