                      <div className="p-14 border-b border-white/5 flex items-center justify-between"><h4 className="text-xs font-black uppercase italic text-indigo-400 tracking-widest">{activePanel === 'chat' ? 'Chat ao Vivo' : activePanel === 'participants' ? 'Turma Online' : 'Ajustes Master'}</h4><button onClick={() => setActivePanel('none')} className="p-4 bg-white/5 rounded-full"><X size={24}/></button></div>
