                                  <div className="relative"><Video size={18} className="absolute left-6 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-16 py-6 text-sm font-black outline-none appearance-none"><option value=""> Detectando Câmera...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                                  <div className="relative"><Mic size={18} className="absolute left-6 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLiveMedia(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-16 py-6 text-sm font-black outline-none appearance-none"><option value=""> Detectando Áudio...</option>{devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                               </div></div>
                               <div className="space-y-6"><h5 className="text-[10px] font-black uppercase tracking-[0.5em] text-white/20 italic">Cenário Virtual (Fundo)</h5><div className="grid grid-cols-2 gap-4">
