      {/* MODALS GERAIS */}
      {showPptUpload && (<div className="fixed inset-0 z-[2000] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in"><div className="bg-white w-full max-w-2xl rounded-[5rem] p-20 text-center shadow-2xl animate-in zoom-in-95"><div className="w-28 h-28 bg-indigo-50 rounded-[3.5rem] flex items-center justify-center mx-auto mb-10 text-indigo-600 shadow-inner"><Presentation size={60}/></div><h3 className="text-5xl font-black text-slate-900 uppercase tracking-tighter italic mb-4 leading-none">Lançar Apresentação</h3><div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-[4rem] p-24 mb-14 cursor-pointer transition-all ${selectedFileName ? 'border-emerald-200 bg-emerald-50/20' : 'border-slate-100 hover:border-indigo-400'}`}>{selectedFileName ? <div className="space-y-6"><CheckCircle2 size={100} className="text-emerald-500 mx-auto animate-in zoom-in-50" /><p className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">{selectedFileName}</p></div> : <><Upload size={80} className="text-slate-100 mb-4 mx-auto" /><span className="text-[12px] font-black uppercase text-slate-300 tracking-[0.5em] block">Escolher Documento Master</span><span className="text-[9px] font-bold text-slate-200 uppercase tracking-widest mt-2">Suporta PDF e PPTX</span></>}<input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { setSelectedFileName(e.target.files[0].name); } }} /></div><div className="flex gap-6"><button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-8 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest italic hover:bg-slate-200">Voltar</button><button disabled={!selectedFileName} onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className={`flex-1 py-8 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl transition-all tracking-[0.5em] italic ${selectedFileName ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-slate-200 cursor-not-allowed'}`}>Transmitir na Sala</button></div></div></div>)}

