      {isLessonModalOpen && (<div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6 animate-in zoom-in-95"><div className="bg-white w-full max-w-2xl rounded-[4.5rem] p-16 space-y-12 shadow-2xl overflow-y-auto max-h-[90vh] custom-scrollbar"><div><h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{editingLessonId ? 'Revisar Aula' : 'Nova Aula Master'}</h3></div><div className="space-y-8"><div className="space-y-3"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Título do Encontro</label><input value={lessonForm.title} onChange={e => setLessonForm({...lessonForm, title: e.target.value})} placeholder="Título bíblico..." className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black text-lg shadow-inner focus:ring-2 focus:ring-indigo-600 transition-all" /></div><div className="space-y-3"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Fonte de Vídeo (YouTube/Vimeo)</label><input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL Master..." className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black shadow-inner" /></div><div className="space-y-3"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Ementa Pedagógica</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Descrição master..." className="w-full px-12 py-10 bg-slate-50 border-none rounded-[3rem] h-48 font-medium text-base shadow-inner resize-none"></textarea></div></div><div className="flex gap-6 pt-4"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-8 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest italic">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-8 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.4em] italic">Publicar Aula</button></div></div></div>)}

      {/* MODAL EXAME - SELEÇÃO DE CURSO E MÓDULO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6 animate-in zoom-in-95">
