                 </div>
              </div>
              <div className="flex gap-6 pt-6"><button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-8 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest italic">Voltar</button><button onClick={async () => { const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); }} className="flex-1 py-8 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-700 tracking-[0.4em] italic active:scale-95 transition-all">Gravar Exame</button></div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-xl rounded-[4.5rem] p-20 text-center shadow-2xl"><div className="w-28 h-28 bg-emerald-50 rounded-[3.5rem] flex items-center justify-center mx-auto mb-10 text-emerald-600 shadow-inner"><FileText size={60}/></div><h3 className="text-5xl font-black text-slate-900 uppercase tracking-tighter mb-12 italic leading-none">Anexar Digital</h3><div className="space-y-8 mb-14 text-left"><div className="space-y-3"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Nome do Documento</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: Guia Master..." className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black text-lg shadow-inner" /></div><div className="space-y-3"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">URL do PDF/Drive</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL direta..." className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black shadow-inner" /></div></div><div className="flex gap-6"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-8 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest italic">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-8 bg-indigo-600 text-white rounded-[2.5rem] text-[11px] font-black uppercase shadow-2xl italic tracking-[0.4em] hover:bg-indigo-700">Publicar Agora</button></div></div></div>)}

      {isScheduleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-lg rounded-[4.5rem] p-16 shadow-2xl relative overflow-hidden"><div className="absolute top-0 right-0 w-40 h-40 bg-indigo-50 rounded-full -mr-20 -mt-20 opacity-50 blur-[80px]"></div><div className="flex items-center gap-8 mb-14"><div className="p-7 bg-indigo-600 text-white rounded-[2.5rem] shadow-2xl"><Bell size={40} className="animate-swing" /></div><h3 className="text-4xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Agendar Aula</h3></div><div className="space-y-8 mb-14"><div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Título da Transmissão</label><input id="sched-title-v3" placeholder="Ex: Teologia do Antigo Testamento..." className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black text-lg shadow-inner" /></div><div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Data e Horário</label><input id="sched-date-v3" type="datetime-local" className="w-full px-12 py-7 bg-slate-50 border-none rounded-[2.5rem] font-black text-lg shadow-inner" /></div></div><div className="flex gap-6"><button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-8 bg-slate-100 text-slate-400 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest italic hover:bg-slate-200">Cancelar</button><button onClick={async () => { const title = (document.getElementById('sched-title-v3') as HTMLInputElement).value; const date = (document.getElementById('sched-date-v3') as HTMLInputElement).value; if (title && date) { await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-8 bg-slate-900 text-white rounded-[2.5rem] text-[11px] font-black uppercase hover:bg-indigo-600 transition-all shadow-2xl italic tracking-[0.5em]">Confirmar Agenda</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Assinatura Digital de Certificados" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

