dCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-6 bg-slate-900 text-white rounded-[1.5rem] text-[9px] font-black uppercase hover:bg-indigo-600 transition-all shadow-xl italic tracking-[0.4em]">Confirmar Agenda</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Master" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

