ack uppercase text-slate-400 tracking-widest italic ml-4">Ementa Pedagógica</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Breve resumo da lição..." className="w-full px-8 py-6 bg-slate-50 border-none rounded-[2rem] h-32 font-medium text-xs shadow-inner resize-none"></textarea></div></div><div className="flex gap-4 pt-2"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest italic">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-6 bg-slate-900 text-white rounded-[1.5rem] text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.4em] italic">Publicar Aula Master</button></div></div></div>)}

