                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Vínculo de Módulo</label><select disabled={!examForm.courseId} value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-[1.5rem] text-[10px] font-black uppercase shadow-inner"><option value="">Selecione o Módulo...</option>{examCourseModules.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}</select></div>
                    <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Média de Corte %</label><input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-[1.5rem] font-black text-center text-sm shadow-inner" /></div>
                 </div>
              </div>
              <div className="flex gap-4 pt-4"><button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest italic">Voltar</button><button onClick={async () => { const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); }} className="flex-1 py-6 bg-indigo-600 text-white rounded-[1.5rem] text-[9px] font-black uppercase shadow-xl hover:bg-indigo-700 tracking-[0.4em] italic active:scale-95">Gravar Exame</button></div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-lg rounded-[3rem] p-16 text-center shadow-2xl"><div className="w-20 h-20 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 text-emerald-600 shadow-inner"><FileText size={40}/></div><h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mb-10 italic leading-none">Anexar Digital Master</h3><div className="space-y-6 mb-10 text-left"><div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Nome do Documento</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: Guia de Teologia Sistemática..." className="w-full px-8 py-4 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" /></div><div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Link Direto (Drive/PDF)</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL do Recurso..." className="w-full px-8 py-4 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" /></div></div><div className="flex gap-4"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest italic hover:bg-slate-200">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-6 bg-indigo-600 text-white rounded-[1.5rem] text-[9px] font-black uppercase shadow-2xl tracking-[0.4em] italic hover:bg-indigo-700 active:scale-95">Publicar Recurso</button></div></div></div>)}

      {isScheduleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-lg rounded-[3rem] p-12 shadow-2xl relative overflow-hidden text-slate-900"><div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full -mr-16 -mt-16 opacity-50 blur-[60px]"></div><div className="flex items-center gap-6 mb-10"><div className="p-4 bg-indigo-600 text-white rounded-[1.5rem] shadow-xl"><Bell size={32} /></div><h3 className="text-3xl font-black uppercase tracking-tighter italic leading-none">Agendar Aula Master</h3></div><div className="space-y-6 mb-10"><div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Nome da Transmissão</label><input id="sched-title-final" placeholder="Ex: Estudo do Livro de Romanos..." className="w-full px-10 py-5 bg-slate-50 border-none rounded-[2rem] font-black text-sm shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div><div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Data e Hora de Início</label><input id="sched-date-final" type="datetime-local" className="w-full px-10 py-5 bg-slate-50 border-none rounded-[2rem] font-black text-sm shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div></div><div className="flex gap-4"><button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest italic">Descartar</button><button onClick={async () => { const title = (document.getElementById('sched-title-final') as HTMLInputElement).value; const date = (document.getElementById('sched-date-final') as HTMLInputElement).value; if (title && date) { await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-6 bg-slate-900 text-white rounded-[1.5rem] text-[9px] font-black uppercase hover:bg-indigo-600 transition-all shadow-xl italic tracking-[0.4em]">Confirmar Agenda</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Master" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, Activity, PowerOff, UserPlus, ShieldX
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];

    // ATUALIZAÇÃO NO FIREBASE
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });

    // SINCRONIZA ESTADO LOCAL PARA REFLETIR IMEDIATAMENTE
    setCurrentExam({ ...currentExam, questions: up });
    setExams(prev => prev.map(e => e.id === currentExam.id ? { ...e, questions: up } : e));

    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;

    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];

    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      const newLesson: Lesson = {
        id: Math.random().toString(36).substr(2, 9),
        ...lessonForm,
        order: lessons.length + 1
      };
      lessons.push(newLesson);
    }

    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < (currentExam.questions?.length || 1) - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180); 
    } else {
      setFullScreenMode('none');
      setTestStarted(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  const examCourseModules = useMemo(() => modules.filter(m => m.courseId === examForm.courseId), [modules, examForm.courseId]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // RENDERIZAÇÃO DE TELA CHEIA: PREVIEW ALUNO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-xl">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-base font-black uppercase tracking-tight italic">Ambiente do Aluno</h2>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-6 py-2.5 bg-indigo-600 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-indigo-900/50">Sair da Simulação</button>
        </header>
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6 hidden md:block">
            <h3 className="text-[9px] font-black uppercase text-slate-400 mb-6 tracking-widest italic">Navegação do Curso</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-3">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 italic">
                    <span className="w-5 h-5 rounded bg-indigo-100 flex items-center justify-center text-[9px]">{idx + 1}</span> {m.title}
                  </div>
                  <div className="pl-6 space-y-2">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[10px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer group">
                        <PlayCircle size={12} className="text-slate-300 group-hover:text-indigo-600" /> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>
          <main className="flex-1 overflow-y-auto p-12 bg-white flex flex-col items-center">
            <div className="max-w-4xl w-full space-y-8 animate-in fade-in duration-700">
              <div className="aspect-video bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col items-center justify-center text-white/50 group relative overflow-hidden">
                 <Play size={80} className="text-white relative z-10" />
                 <p className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] relative z-10 text-white/70 italic">Streaming Master 4K</p>
              </div>
              <div className="space-y-6">
                <div className="flex items-center gap-4">
                   <div className="h-8 w-1 bg-indigo-600 rounded-full"></div>
                   <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Conteúdo Acadêmico</h1>
                </div>
                <p className="text-slate-500 leading-relaxed text-sm font-medium italic">O aluno terá acesso a esta interface limpa e focada para garantir o máximo aproveitamento dos estudos teológicos.</p>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }

  // TELA CHEIA: EDITOR DE QUESTÕES
  if (fullScreenMode === 'question_editor' && currentExam) {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-50 flex flex-col animate-in fade-in overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm text-slate-900">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 bg-slate-100 hover:bg-slate-200 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-lg font-black uppercase tracking-tighter italic leading-none">Gestão de Itens: {currentExam.title}</h2>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Ref: {currentExam.id.substring(0,8)}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="bg-slate-900 text-white px-8 py-3 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 shadow-xl tracking-widest">Finalizar Gestão</button>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50/50 p-8 flex gap-8">
            <div className="w-[400px] space-y-6 sticky top-0 h-fit">
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl">
                <div className="flex items-center gap-3 mb-6">
                  <div className="p-3 bg-indigo-600 text-white rounded-2xl"><Plus size={18}/></div>
                  <h3 className="font-black uppercase text-xs tracking-tight italic">Novo Item Acadêmico</h3>
                </div>
                <div className="space-y-6">
                  <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Enunciado da questão..." className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl h-32 font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 resize-none text-[11px]"></textarea>
                  <div className="space-y-2">
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-8 h-8 rounded-lg font-black text-[10px] transition-all shadow-md ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>{String.fromCharCode(65+i)}</button>
                        <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Alternativa ${String.fromCharCode(65+i)}...`} className="flex-1 px-4 py-2.5 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                      </div>
                    ))}
                  </div>
                  <button onClick={handleSaveQuestion} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Anexar ao Banco</button>
                </div>
              </div>
            </div>
            <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 overflow-hidden shadow-sm">
                <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3"><ListOrdered className="text-indigo-600" size={18}/><h4 className="font-black uppercase text-[10px] tracking-widest italic">Banco de Questões Ativo ({currentExam.questions?.length||0})</h4></div>
                </div>
                <div className="divide-y divide-slate-100">
                  {(currentExam.questions || []).map((q, idx) => (
                    <div key={q.id} className="p-6 hover:bg-indigo-50/20 transition-all group relative flex gap-5">
                       <span className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xs italic shadow-lg shrink-0">#{idx+1}</span>
                       <div className="flex-1">
                          <p className="text-xs font-black uppercase italic text-slate-800 leading-tight mb-4">{q.text}</p>
                          <div className="grid grid-cols-2 gap-2">
                            {q.options.map((opt, oi) => (
                              <div key={oi} className={`px-3 py-1.5 rounded-lg text-[9px] font-bold border ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-white text-slate-400 border-slate-100'}`}>{opt}</div>
                            ))}
                          </div>
                       </div>
                       <button onClick={async () => { if(confirm('Excluir?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-2 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
            </div>
        </div>
      </div>
    );
  }

  // RENDERIZAÇÃO DA SALA DE LIVE
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white animate-in fade-in overflow-hidden font-sans">
        <div className="absolute top-0 left-0 right-0 z-[1300] p-8 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-4 pointer-events-auto">
              <div className="bg-rose-600 px-6 py-3 rounded-2xl flex items-center gap-3 shadow-2xl border border-rose-500/20"><div className="w-2.5 h-2.5 bg-white rounded-full animate-ping"></div><span className="text-[9px] font-black uppercase tracking-[0.4em] italic">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-6 py-3 rounded-2xl border border-white/10 flex items-center gap-4 shadow-2xl"><Users size={16} className="text-indigo-400"/><span className="text-[9px] font-black uppercase tabular-nums">{allStudents.length} ALUNOS ONLINE</span></div>
           </div>
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-indigo-600 px-6 py-3 rounded-2xl text-[9px] font-black uppercase flex items-center gap-3 shadow-2xl italic tracking-widest border border-indigo-400/30"><ShieldCheck size={18}/> {user.displayName}</div>
           </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-10 lg:p-20">
              <div className="absolute inset-0 pointer-events-none z-[1250] overflow-hidden">
                 {activeReactions.map(r => (
                   <div key={r.id} className="absolute bottom-32 text-6xl animate-bounce-up opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
                 ))}
              </div>

              <div className={`w-full h-full max-w-[1920px] aspect-video bg-zinc-950 rounded-[3rem] overflow-hidden border border-white/5 relative group shadow-[0_60px_150px_rgba(0,0,0,1)]`}>
                 {isPresentationMode && selectedFileName ? (
                   <div className="w-full h-full bg-white flex flex-col items-center justify-center text-slate-900 relative animate-in fade-in duration-500">
                      <div className="absolute top-10 flex flex-col items-center gap-3">
                         <div className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[9px] font-black uppercase border border-indigo-100 tracking-widest">Documento Master Ativo</div>
                         <h5 className="font-black text-lg uppercase italic text-slate-900">{selectedFileName.split('.')[0]}</h5>
                      </div>
                      <div className="p-24 border-4 border-slate-100 rounded-[2.5rem] bg-slate-50 flex flex-col items-center justify-center text-center shadow-inner">
                         <Presentation size={150} className="text-indigo-600 mb-8 opacity-10" />
                         <p className="text-slate-400 font-black text-xl uppercase tracking-[0.5em] italic">SLIDE #{presentationSlide} • MÓDULO MASTER</p>
                      </div>
                      <div className="absolute inset-x-12 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                         <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-8 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronLeft size={40}/></button>
                         <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-8 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronRight size={40}/></button>
                      </div>
                   </div>
                 ) : (
                   <div className="relative w-full h-full overflow-hidden">
                      {/* VIRTUAL BACKGROUND SIMULATION */}
                      {virtualBg !== 'none' && (
                        <div 
                          className="absolute inset-0 z-0 bg-cover bg-center transition-all duration-700" 
                          style={{ 
                            backgroundImage: virtualBg === 'office' 
                              ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' 
                              : virtualBg === 'custom' && customBgUrl 
                                ? `url(${customBgUrl})` 
                                : 'none',
                            filter: virtualBg === 'blur' ? 'blur(40px)' : 'none'
                          }} 
                        />
                      )}

                      <video 
                        ref={videoRef} 
                        autoPlay 
                        playsInline 
                        muted 
                        className={`w-full h-full object-cover relative z-10 transition-all duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`} 
                        style={virtualBg !== 'none' && virtualBg !== 'blur' ? { 
                          maskImage: 'radial-gradient(circle, black 70%, transparent 100%)',
                          WebkitMaskImage: 'radial-gradient(circle, black 70%, transparent 100%)'
                        } : {}} 
                      />

                      {!videoActive && (
                        <div className="absolute inset-0 z-20 bg-zinc-900 flex flex-col items-center justify-center">
                          <div className="w-32 h-32 rounded-full bg-indigo-600 flex items-center justify-center font-black text-5xl text-white shadow-2xl">{user.displayName.charAt(0)}</div>
                          <p className="mt-8 text-[9px] font-black uppercase tracking-[0.5em] text-white/20 italic">Professor em Pausa Digital</p>
                        </div>
                      )}
                   </div>
                 )}

                 {/* CONTROLS DOCK - REDESIGNED */}
                 <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-5 bg-black/80 backdrop-blur-3xl px-10 py-6 rounded-[2.5rem] border border-white/10 shadow-2xl opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={toggleMic} className={`p-4 rounded-xl transition-all shadow-xl ${micActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{micActive ? <Mic size={20}/> : <MicOff size={20}/>}</button>
                    <button onClick={toggleVideo} className={`p-4 rounded-xl transition-all shadow-xl ${videoActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{videoActive ? <Video size={20}/> : <VideoOff size={20}/>}</button>
                    <div className="w-px h-8 bg-white/10 mx-1"></div>
                    <button onClick={startScreenShare} className={`p-4 rounded-xl transition-all shadow-xl ${screenShareActive ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} title="Compartilhar Tela"><Monitor size={20}/></button>

                    {/* SLIDE CONTROL: ONE CLICK TO OPEN, SECOND TO CLOSE */}
                    <button 
                      onClick={() => {
                        if (isPresentationMode) {
                          setIsPresentationMode(false);
                          setSelectedFileName(null);
                        } else {
                          setShowPptUpload(true);
                        }
                      }} 
                      className={`p-4 rounded-xl transition-all shadow-xl ${isPresentationMode ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} 
                      title={isPresentationMode ? "Encerrar Apresentação" : "Iniciar Apresentação"}
                    >
                      <Presentation size={20}/>
                    </button>

                    <div className="w-px h-8 bg-white/10 mx-1"></div>
                    <div className="flex gap-1.5 bg-black/60 p-1.5 rounded-2xl border border-white/5">
                       {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-2 hover:bg-white/10 rounded-lg transition-all text-lg active:scale-150">{e}</button>)}
                    </div>
                    <div className="w-px h-8 bg-white/10 mx-1"></div>
                    <button onClick={stopLive} className="px-8 py-5 bg-rose-600 hover:bg-rose-700 rounded-2xl text-[9px] font-black uppercase tracking-[0.3em] shadow-2xl transition-all italic text-white flex items-center gap-2"><PhoneOff size={18}/> Encerrar Aula</button>
                 </div>

                 {/* SIDE BUTTONS */}
                 <div className="absolute right-8 top-1/2 -translate-y-1/2 flex flex-col gap-4 opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-4 rounded-xl border transition-all shadow-2xl ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><MessageSquare size={24}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-4 rounded-xl border transition-all shadow-2xl ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Users size={24}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className={`p-4 rounded-xl border transition-all shadow-2xl ${activePanel === 'settings' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Settings size={24}/></button>
                 </div>
              </div>
           </div>

           {/* PANELS */}
           {activePanel !== 'none' && (
             <div className="w-[400px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right h-full shadow-2xl relative z-[1500]">
                <div className="p-8 border-b border-white/5 flex items-center justify-between"><h4 className="text-[10px] font-black uppercase italic text-indigo-400 tracking-widest">{activePanel === 'chat' ? 'Chat ao Vivo' : activePanel === 'participants' ? 'Turma Master' : 'Setup Studio'}</h4><button onClick={() => setActivePanel('none')} className="p-2 bg-white/5 rounded-full hover:bg-white/10"><X size={18}/></button></div>
                <div className="flex-1 overflow-y-auto p-6 space-y-5 custom-scrollbar">
                   {activePanel === 'chat' ? (
                     chatMessages.map((m, i) => (
                       <div key={i} className="animate-in fade-in slide-in-from-bottom-2"><div className="flex items-center gap-2 mb-1.5"><span className="text-[10px] font-black text-indigo-400 uppercase italic">{m.user}</span><span className="text-[8px] text-white/10">{m.time}</span></div><p className="text-[11px] font-medium text-white/60 bg-white/5 p-4 rounded-2xl border border-white/5 italic shadow-inner">"{m.text}"</p></div>
                     ))
                   ) : activePanel === 'participants' ? (
                     <div className="space-y-4">
                       <div className="p-5 bg-white/5 rounded-2xl border border-white/10 space-y-4 mb-4">
                         <h5 className="text-[8px] font-black uppercase text-slate-400 italic">Controle da Sala</h5>
                         <div className="grid grid-cols-2 gap-2">
                           <button onClick={() => setGlobalMute(!globalMute)} className={`py-3 rounded-xl border text-[8px] font-black uppercase transition-all flex items-center justify-center gap-2 ${globalMute ? 'bg-rose-600 border-rose-400 text-white shadow-lg' : 'bg-white/5 border-white/10 text-slate-300'}`}><VolumeX size={14}/> {globalMute ? 'Liberar Mics' : 'Silenciar Todos'}</button>
                           <button onClick={() => setGlobalCamBlock(!globalCamBlock)} className={`py-3 rounded-xl border text-[8px] font-black uppercase transition-all flex items-center justify-center gap-2 ${globalCamBlock ? 'bg-rose-600 border-rose-400 text-white shadow-lg' : 'bg-white/5 border-white/10 text-slate-300'}`}><UserX size={14}/> {globalCamBlock ? 'Liberar Cams' : 'Bloquear Cams'}</button>
                         </div>
                       </div>
                       {allStudents.map(s => (
                         <div key={s.uid} className="p-4 bg-white/5 rounded-[1.5rem] border border-white/5 flex items-center justify-between group/u hover:bg-indigo-600/10 transition-all"><div className="flex items-center gap-4"><div className="w-8 h-8 rounded-lg bg-zinc-900 border border-white/5 flex items-center justify-center font-black text-[10px] italic">{(s.displayName||'U').charAt(0)}</div><span className="text-[10px] font-black uppercase italic text-white/70">{s.displayName}</span></div><div className="flex gap-2 opacity-0 group-hover/u:opacity-100"><button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><VolumeX size={14}/></button><button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><PowerOff size={14}/></button></div></div>
                       ))}
                     </div>
                   ) : (
                      <div className="space-y-8">
                         <div className="space-y-4"><h5 className="text-[9px] font-black uppercase tracking-[0.5em] text-white/20 italic">Mídia Master</h5><div className="space-y-2">
                            <div className="relative"><Video size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-12 py-3 text-[10px] font-black outline-none appearance-none text-slate-300"><option value="">Detectando Câmera...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                            <div className="relative"><Mic size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLiveMedia(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-12 py-3 text-[10px] font-black outline-none appearance-none text-slate-300"><option value="">Detectando Áudio...</option>{devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                         </div></div>
                         <div className="space-y-4"><h5 className="text-[9px] font-black uppercase tracking-[0.5em] text-white/20 italic">Efeitos Visuais</h5><div className="grid grid-cols-2 gap-3">
                            {['none', 'blur', 'office', 'custom'].map(bg => (<button key={bg} onClick={() => { if(bg === 'custom') customBgInputRef.current?.click(); else setVirtualBg(bg as any); }} className={`p-5 rounded-2xl border text-[8px] font-black uppercase transition-all flex flex-col items-center gap-3 ${virtualBg === bg ? 'bg-indigo-600 border-indigo-400 text-white shadow-2xl' : 'bg-white/5 border-white/10 hover:bg-white/10 text-white/40'}`}><span className="p-3 bg-black/40 rounded-xl">{bg === 'none' ? <Video size={16} /> : bg === 'blur' ? <Sparkles size={16} /> : bg === 'office' ? <ImageIcon size={16} /> : <Upload size={16} />}</span>{bg}</button>))}
                         </div></div>
                      </div>
                   )}
                </div>
                {activePanel === 'chat' && (<div className="p-8 border-t border-white/5 bg-[#080808]"><div className="relative"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Mensagem..." className="w-full bg-white/5 border-none rounded-xl px-6 py-4 text-[11px] font-bold outline-none focus:ring-1 focus:ring-indigo-600 placeholder:text-white/10" /><button onClick={handleSendMessage} className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-indigo-500 hover:text-indigo-400"><Send size={20}/></button></div></div>)}
             </div>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in fade-in h-full text-slate-900">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-5 duration-500">
          <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-5">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-[1rem] shadow-xl shadow-indigo-100"><Layers size={20}/></div>
              <div><h1 className="text-lg font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1><p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Gestão de Conteúdo EAD</p></div>
            </div>
            <div className="flex flex-wrap items-center gap-3 justify-center">
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-5 py-2.5 rounded-xl text-[8px] font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-2"><Eye size={14}/> Preview</button>
              <button onClick={() => setIsSignModalOpen(true)} className="bg-amber-50 text-amber-600 px-5 py-2.5 rounded-xl text-[8px] font-black uppercase border border-amber-100 flex items-center gap-2"><PenTool size={14}/> Assinatura</button>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 text-[8px] font-black uppercase outline-none shadow-inner">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-6 py-3 rounded-xl text-[8px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all flex items-center gap-2"><Plus size={14}/> Novo Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-4">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[2rem] overflow-hidden group shadow-sm hover:shadow-md transition-all duration-500">
                  <div className="bg-slate-50/50 px-6 py-4 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="w-8 h-8 bg-indigo-100 text-indigo-700 rounded-lg flex items-center justify-center font-black text-xs italic shadow-inner">#{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-[10px] uppercase italic tracking-[0.1em]">{mod.title}</h3>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-4 py-2 bg-indigo-600 text-white text-[8px] font-black uppercase rounded-lg shadow-lg hover:scale-105 transition-all italic">Add Aula</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"><Edit3 size={14}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-2 text-slate-200 hover:text-rose-600 transition-all"><Trash2 size={14}/></button>
                    </div>
                  </div>
                  <div className="p-6 space-y-2">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-4 rounded-2xl flex items-center justify-between border border-slate-100 hover:border-indigo-100 transition-all group/l">
                        <div className="flex items-center gap-4 text-[9px]">
                          <span className="w-7 h-7 rounded bg-slate-50 flex items-center justify-center font-black text-slate-400 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all italic">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 uppercase italic tracking-tight">{l.title}</h4>
                          </div>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/l:opacity-100">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all bg-white"><Edit3 size={12}/></button>
                          <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-all"><Trash2 size={12}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/20 p-6 rounded-2xl flex items-center justify-between border border-amber-100 shadow-sm hover:bg-amber-50 transition-all duration-500">
                        <div className="flex items-center gap-4">
                          <div className="p-3 bg-amber-100 text-amber-600 rounded-xl shadow-inner"><Award size={18}/></div>
                          <div><h4 className="font-black text-amber-900 text-[10px] uppercase italic">{ex.title}</h4><span className="text-[8px] font-black text-amber-600/60 uppercase italic mt-0.5 block">{ex.questions?.length||0} Itens</span></div>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="px-5 py-2.5 bg-amber-600 text-white text-[8px] font-black uppercase rounded-lg shadow-xl hover:bg-amber-700 transition-all italic tracking-widest">Itens</button>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
