  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];

    // ATUALIZAÇÃO NO FIREBASE
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });

    // SINCRONIZA ESTADO LOCAL PARA REFLETIR IMEDIATAMENTE
    setCurrentExam({ ...currentExam, questions: up });
    setExams(prev => prev.map(e => e.id === currentExam.id ? { ...e, questions: up } : e));

    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;

    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];

    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      const newLesson: Lesson = {
        id: Math.random().toString(36).substr(2, 9),
        ...lessonForm,
        order: lessons.length + 1
      };
      lessons.push(newLesson);
    }

    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < (currentExam.questions?.length || 1) - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180); 
    } else {
      setFullScreenMode('none');
      setTestStarted(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  const examCourseModules = useMemo(() => modules.filter(m => m.courseId === examForm.courseId), [modules, examForm.courseId]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // RENDERIZAÇÃO DE TELA CHEIA: PREVIEW ALUNO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-xl">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-base font-black uppercase tracking-tight italic">Ambiente do Aluno</h2>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-6 py-2.5 bg-indigo-600 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-indigo-900/50">Sair da Simulação</button>
        </header>
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6 hidden md:block">
            <h3 className="text-[9px] font-black uppercase text-slate-400 mb-6 tracking-widest italic">Navegação do Curso</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-3">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 italic">
                    <span className="w-5 h-5 rounded bg-indigo-100 flex items-center justify-center text-[9px]">{idx + 1}</span> {m.title}
                  </div>
                  <div className="pl-6 space-y-2">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[10px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer group">
                        <PlayCircle size={12} className="text-slate-300 group-hover:text-indigo-600" /> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>
          <main className="flex-1 overflow-y-auto p-12 bg-white flex flex-col items-center">
            <div className="max-w-4xl w-full space-y-8 animate-in fade-in duration-700">
              <div className="aspect-video bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col items-center justify-center text-white/50 group relative overflow-hidden">
                 <Play size={80} className="text-white relative z-10" />
                 <p className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] relative z-10 text-white/70 italic">Streaming Master 4K</p>
              </div>
              <div className="space-y-6">
                <div className="flex items-center gap-4">
                   <div className="h-8 w-1 bg-indigo-600 rounded-full"></div>
                   <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Conteúdo Acadêmico</h1>
                </div>
                <p className="text-slate-500 leading-relaxed text-sm font-medium italic">O aluno terá acesso a esta interface limpa e focada para garantir o máximo aproveitamento dos estudos teológicos.</p>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }

  // TELA CHEIA: EDITOR DE QUESTÕES
  if (fullScreenMode === 'question_editor' && currentExam) {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-50 flex flex-col animate-in fade-in overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm text-slate-900">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 bg-slate-100 hover:bg-slate-200 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-lg font-black uppercase tracking-tighter italic leading-none">Gestão de Itens: {currentExam.title}</h2>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Ref: {currentExam.id.substring(0,8)}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="bg-slate-900 text-white px-8 py-3 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 shadow-xl tracking-widest">Finalizar Gestão</button>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50/50 p-8 flex gap-8">
            <div className="w-[400px] space-y-6 sticky top-0 h-fit">
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl">
                <div className="flex items-center gap-3 mb-6">
                  <div className="p-3 bg-indigo-600 text-white rounded-2xl"><Plus size={18}/></div>
                  <h3 className="font-black uppercase text-xs tracking-tight italic">Novo Item Acadêmico</h3>
                </div>
                <div className="space-y-6">
                  <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Enunciado da questão..." className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl h-32 font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 resize-none text-[11px]"></textarea>
                  <div className="space-y-2">
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-8 h-8 rounded-lg font-black text-[10px] transition-all shadow-md ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border-2 border-slate-100 text-slate-300'}`}>{String.fromCharCode(65+i)}</button>
                        <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Alternativa ${String.fromCharCode(65+i)}...`} className="flex-1 px-4 py-2.5 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                      </div>
                    ))}
                  </div>
                  <button onClick={handleSaveQuestion} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Anexar ao Banco</button>
                </div>
              </div>
            </div>
            <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 overflow-hidden shadow-sm">
                <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3"><ListOrdered className="text-indigo-600" size={18}/><h4 className="font-black uppercase text-[10px] tracking-widest italic">Banco de Questões Ativo ({currentExam.questions?.length||0})</h4></div>
                </div>
                <div className="divide-y divide-slate-100">
                  {(currentExam.questions || []).map((q, idx) => (
                    <div key={q.id} className="p-6 hover:bg-indigo-50/20 transition-all group relative flex gap-5">
                       <span className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xs italic shadow-lg shrink-0">#{idx+1}</span>
                       <div className="flex-1">
                          <p className="text-xs font-black uppercase italic text-slate-800 leading-tight mb-4">{q.text}</p>
                          <div className="grid grid-cols-2 gap-2">
                            {q.options.map((opt, oi) => (
                              <div key={oi} className={`px-3 py-1.5 rounded-lg text-[9px] font-bold border ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-white text-slate-400 border-slate-100'}`}>{opt}</div>
                            ))}
                          </div>
                       </div>
                       <button onClick={async () => { if(confirm('Excluir?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-2 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
            </div>
        </div>
      </div>
    );
  }

  // RENDERIZAÇÃO DA SALA DE LIVE
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white animate-in fade-in overflow-hidden font-sans">
        <div className="absolute top-0 left-0 right-0 z-[1300] p-8 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-4 pointer-events-auto">
              <div className="bg-rose-600 px-6 py-3 rounded-2xl flex items-center gap-3 shadow-2xl border border-rose-500/20"><div className="w-2.5 h-2.5 bg-white rounded-full animate-ping"></div><span className="text-[9px] font-black uppercase tracking-[0.4em] italic">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-6 py-3 rounded-2xl border border-white/10 flex items-center gap-4 shadow-2xl"><Users size={16} className="text-indigo-400"/><span className="text-[9px] font-black uppercase tabular-nums">{allStudents.length} ALUNOS ONLINE</span></div>
           </div>
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-indigo-600 px-6 py-3 rounded-2xl text-[9px] font-black uppercase flex items-center gap-3 shadow-2xl italic tracking-widest border border-indigo-400/30"><ShieldCheck size={18}/> {user.displayName}</div>
           </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-10 lg:p-20">
              <div className="absolute inset-0 pointer-events-none z-[1250] overflow-hidden">
                 {activeReactions.map(r => (
                   <div key={r.id} className="absolute bottom-32 text-6xl animate-bounce-up opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
                 ))}
              </div>

              <div className={`w-full h-full max-w-[1920px] aspect-video bg-zinc-950 rounded-[3rem] overflow-hidden border border-white/5 relative group shadow-[0_60px_150px_rgba(0,0,0,1)]`}>
                 {isPresentationMode && selectedFileName ? (
                   <div className="w-full h-full bg-white flex flex-col items-center justify-center text-slate-900 relative animate-in fade-in duration-500">
                      <div className="absolute top-10 flex flex-col items-center gap-3">
                         <div className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[9px] font-black uppercase border border-indigo-100 tracking-widest">Documento Master Ativo</div>
                         <h5 className="font-black text-lg uppercase italic text-slate-900">{selectedFileName.split('.')[0]}</h5>
                      </div>
                      <div className="p-24 border-4 border-slate-100 rounded-[2.5rem] bg-slate-50 flex flex-col items-center justify-center text-center shadow-inner">
                         <Presentation size={150} className="text-indigo-600 mb-8 opacity-10" />
                         <p className="text-slate-400 font-black text-xl uppercase tracking-[0.5em] italic">SLIDE #{presentationSlide} • MÓDULO MASTER</p>
                      </div>
                      <div className="absolute inset-x-12 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                         <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-8 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronLeft size={40}/></button>
                         <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-8 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronRight size={40}/></button>
                      </div>
                   </div>
                 ) : (
                   <div className="relative w-full h-full overflow-hidden">
                      {/* VIRTUAL BACKGROUND SIMULATION */}
                      {virtualBg !== 'none' && (
                        <div 
                          className="absolute inset-0 z-0 bg-cover bg-center transition-all duration-700" 
                          style={{ 
                            backgroundImage: virtualBg === 'office' 
                              ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' 
                              : virtualBg === 'custom' && customBgUrl 
                                ? `url(${customBgUrl})` 
                                : 'none',
                            filter: virtualBg === 'blur' ? 'blur(40px)' : 'none'
                          }} 
                        />
                      )}

                      <video 
                        ref={videoRef} 
                        autoPlay 
                        playsInline 
                        muted 
                        className={`w-full h-full object-cover relative z-10 transition-all duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`} 
                        style={virtualBg !== 'none' && virtualBg !== 'blur' ? { 
                          maskImage: 'radial-gradient(circle, black 70%, transparent 100%)',
                          WebkitMaskImage: 'radial-gradient(circle, black 70%, transparent 100%)'
                        } : {}} 
                      />

                      {!videoActive && (
                        <div className="absolute inset-0 z-20 bg-zinc-900 flex flex-col items-center justify-center">
                          <div className="w-32 h-32 rounded-full bg-indigo-600 flex items-center justify-center font-black text-5xl text-white shadow-2xl">{user.displayName.charAt(0)}</div>
                          <p className="mt-8 text-[9px] font-black uppercase tracking-[0.5em] text-white/20 italic">Professor em Pausa Digital</p>
                        </div>
                      )}
                   </div>
                 )}

                 {/* CONTROLS DOCK - REDESIGNED */}
                 <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-5 bg-black/80 backdrop-blur-3xl px-10 py-6 rounded-[2.5rem] border border-white/10 shadow-2xl opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={toggleMic} className={`p-4 rounded-xl transition-all shadow-xl ${micActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{micActive ? <Mic size={20}/> : <MicOff size={20}/>}</button>
                    <button onClick={toggleVideo} className={`p-4 rounded-xl transition-all shadow-xl ${videoActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{videoActive ? <Video size={20}/> : <VideoOff size={20}/>}</button>
                    <div className="w-px h-8 bg-white/10 mx-1"></div>
                    <button onClick={startScreenShare} className={`p-4 rounded-xl transition-all shadow-xl ${screenShareActive ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} title="Compartilhar Tela"><Monitor size={20}/></button>

                    {/* SLIDE CONTROL: ONE CLICK TO OPEN, SECOND TO CLOSE */}
                    <button 
                      onClick={() => {
                        if (isPresentationMode) {
                          setIsPresentationMode(false);
                          setSelectedFileName(null);
                        } else {
                          setShowPptUpload(true);
                        }
                      }} 
                      className={`p-4 rounded-xl transition-all shadow-xl ${isPresentationMode ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} 
                      title={isPresentationMode ? "Encerrar Apresentação" : "Iniciar Apresentação"}
