               <div className="text-center px-4 border-r border-slate-200">
                  <p className="text-2xl font-black text-emerald-600 leading-none tabular-nums">{statsFeedback.cats.elogio}</p>
                  <p className="text-[7px] font-black uppercase text-slate-400 mt-1.5 tracking-widest italic">Elogios</p>
               </div>
               <div className="text-center px-4">
                  <p className="text-2xl font-black text-rose-600 leading-none tabular-nums">{statsFeedback.cats.reclamacao}</p>
