                        </div>
                        <span className="w-8 text-[9px] font-black text-slate-900 tabular-nums text-right">{item.count}</span>
                     </div>
                   ))}
                </div>
             </div>
             <div className="bg-slate-900 text-white p-6 rounded-[2rem] shadow-2xl relative overflow-hidden group">
                <div className="relative z-10 space-y-5">
                   <h3 className="text-[10px] font-black uppercase tracking-widest italic text-indigo-400">Panorama Estratégico</h3>
                   <div className="space-y-2">
                      <p className="text-slate-300 text-[10px] italic leading-relaxed">Engajamento discente estabilizado em <strong>+94%</strong>.</p>
                      <div className="pt-4 grid grid-cols-2 gap-3 border-t border-white/5">
                         <div><p className="text-lg font-black tabular-nums">94%</p><p className="text-[6px] font-black uppercase text-white/30 tracking-widest">Retenção</p></div>
                         <div><p className="text-lg font-black tabular-nums">8.8</p><p className="text-[6px] font-black uppercase text-white/30 tracking-widest">Média</p></div>
                      </div>
                   </div>
                </div>
                <BarChart3 size={120} className="absolute -bottom-8 -right-8 text-white/5 group-hover:scale-125 transition-transform duration-1000" />
             </div>
          </div>
        </div>
      )}

      {/* MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-5">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-emerald-50 text-emerald-600 rounded-[1rem] shadow-sm"><FileText size={20}/></div>
              <div><h1 className="text-lg font-black uppercase italic tracking-tighter">Acervo Acadêmico</h1><p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Gestão de Documentos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-2 active:scale-95 tracking-widest italic"><Plus size={14}/> Novo Recurso</button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-6 rounded-2xl border border-slate-100 relative group hover:shadow-xl transition-all duration-500 text-center">
