                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-2 py-2.5 bg-slate-900 text-white rounded-lg text-[8px] font-black uppercase hover:bg-indigo-600 transition-all shadow-md italic"><ExternalLink size={12}/> Abrir</a>
                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-rose-500 transition-all"><Trash2 size={14}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
