                  <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="flex-1 py-3 bg-slate-900 text-white rounded-lg text-[8px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-all italic tracking-widest">Itens ({ex.questions?.length||0})</button>
                  <button onClick={() => { setCurrentExam(ex); setFullScreenMode('test_simulation'); setTestStarted(false); }} className="p-3 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all shadow-sm"><PlayCircle size={16}/></button>
                  <button onClick={async () => { if(confirm('Excluir permanentemente?')) await deleteDoc(doc(db, 'exams', ex.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-lg hover:bg-rose-600 hover:text-white transition-all shadow-sm"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* DIÁRIO / RELATÓRIO / FREQUÊNCIA */}
