ppercase text-slate-400 tracking-widest italic ml-3">Ementa Curricular</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo pedagógico..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-xl h-24 font-medium text-[11px] shadow-inner resize-none"></textarea></div></div><div className="flex gap-3 pt-2"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase tracking-widest italic">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.4em] italic">Publicar Aula</button></div></div></div>)}

