      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-lg rounded-[2.5rem] p-12 text-center shadow-2xl"><div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto mb-6 text-emerald-600 shadow-inner"><FileText size={32}/></div><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 italic leading-none">Anexar Digital Master</h3><div className="space-y-5 mb-8 text-left"><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4">Nome do Documento</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: Livro de Teologia..." className="w-full px-6 py-3 bg-slate-50 border-none rounded-xl font-black text-xs shadow-inner" /></div><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4">Link Direto (Drive/PDF)</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL master..." className="w-full px-6 py-3 bg-slate-50 border-none rounded-xl font-black text-xs shadow-inner" /></div></div><div className="flex gap-3"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase tracking-widest italic hover:bg-slate-200">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-2xl tracking-[0.4em] italic hover:bg-indigo-700 active:scale-95">Publicar Recurso</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica Master" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

