  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const startScreenShare = async () => {
    try {
      const screen = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = screen;
      setScreenShareActive(true);
      screen.getVideoTracks()[0].onended = () => {
        if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
        setScreenShareActive(false);
      };
    } catch (err) { console.error(err); }
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 3000);
  };

  const handleSendMessage = () => {
    if (!chatMessage.trim()) return;
    setChatMessages(prev => [...prev, { user: user.displayName, text: chatMessage, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) }]);
    setChatMessage('');
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];

    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });

    setCurrentExam({ ...currentExam, questions: up });
    setExams(prev => prev.map(e => e.id === currentExam.id ? { ...e, questions: up } : e));

    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;

    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];

    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      const newLesson: Lesson = {
        id: Math.random().toString(36).substr(2, 9),
        ...lessonForm,
        order: lessons.length + 1
      };
      lessons.push(newLesson);
    }

    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < (currentExam.questions?.length || 1) - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180); 
    } else {
      setFullScreenMode('none');
      setTestStarted(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  const examCourseModules = useMemo(() => modules.filter(m => m.courseId === examForm.courseId), [modules, examForm.courseId]);

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // VIEW: PREVIEW ALUNO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-xl">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-base font-black uppercase tracking-tight italic">Ambiente do Aluno</h2>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-6 py-2.5 bg-indigo-600 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-indigo-900/50">Sair da Simulação</button>
        </header>
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6 hidden md:block">
            <h3 className="text-[9px] font-black uppercase text-slate-400 mb-6 tracking-widest italic">Navegação do Curso</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-3">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 italic">
                    <span className="w-5 h-5 rounded bg-indigo-100 flex items-center justify-center text-[9px]">{idx + 1}</span> {m.title}
                  </div>
                  <div className="pl-6 space-y-2">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[10px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer group">
                        <PlayCircle size={12} className="text-slate-300 group-hover:text-indigo-600" /> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>
          <main className="flex-1 overflow-y-auto p-12 bg-white flex flex-col items-center">
            <div className="max-w-4xl w-full space-y-8 animate-in fade-in duration-700">
              <div className="aspect-video bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col items-center justify-center text-white/50 group relative overflow-hidden">
                 <Play size={80} className="text-white relative z-10" />
                 <p className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] relative z-10 text-white/70 italic">Streaming Master 4K</p>
              </div>
              <div className="space-y-6">
                <div className="flex items-center gap-4">
                   <div className="h-8 w-1 bg-indigo-600 rounded-full"></div>
                   <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Conteúdo Acadêmico</h1>
                </div>
                <p className="text-slate-500 leading-relaxed text-sm font-medium italic">Interface simulada com foco pedagógico absoluto.</p>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }

  // TELA CHEIA: EDITOR DE QUESTÕES
  if (fullScreenMode === 'question_editor' && currentExam) {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-50 flex flex-col animate-in fade-in overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-6 py-3 flex items-center justify-between sticky top-0 z-10 shadow-sm text-slate-900">
          <div className="flex items-center gap-3">
            <button onClick={() => setFullScreenMode('none')} className="p-1.5 bg-slate-100 hover:bg-slate-200 rounded-full"><ArrowLeft size={18}/></button>
            <div>
              <h2 className="text-sm font-black uppercase tracking-tighter italic leading-none">Banco de Itens: {currentExam.title}</h2>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">UID: {currentExam.id.substring(0,6)}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="bg-slate-900 text-white px-5 py-2 rounded-lg text-[9px] font-black uppercase hover:bg-indigo-600 shadow-md">Salvar Banco</button>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex gap-6">
            <div className="w-[340px] space-y-4 sticky top-0 h-fit">
              <div className="bg-white p-6 rounded-[1.5rem] border border-slate-200 shadow-lg">
                <div className="flex items-center gap-2 mb-4">
                  <div className="p-2 bg-indigo-600 text-white rounded-lg"><Plus size={14}/></div>
                  <h3 className="font-black uppercase text-[10px] tracking-tight italic">Nova Questão</h3>
                </div>
                <div className="space-y-4">
                  <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Enunciado..." className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl h-24 font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 resize-none text-[10px]"></textarea>
                  <div className="space-y-1.5">
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-7 h-7 rounded-md font-black text-[9px] transition-all shadow-sm ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border border-slate-100 text-slate-300'}`}>{String.fromCharCode(65+i)}</button>
                        <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Opção ${String.fromCharCode(65+i)}...`} className="flex-1 px-3 py-1.5 bg-slate-50 border-none rounded-lg text-[10px] font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                      </div>
                    ))}
                  </div>
                  <button onClick={handleSaveQuestion} className="w-full py-3 bg-indigo-600 text-white rounded-lg text-[9px] font-black uppercase shadow-lg hover:bg-indigo-700">Anexar Questão</button>
                </div>
              </div>
            </div>
            <div className="flex-1 bg-white rounded-[1.5rem] border border-slate-200 overflow-hidden shadow-sm">
                <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-2"><ListOrdered className="text-indigo-600" size={14}/><h4 className="font-black uppercase text-[9px] tracking-widest italic">Lista de Itens ({currentExam.questions?.length||0})</h4></div>
                </div>
                <div className="divide-y divide-slate-100">
                  {(currentExam.questions || []).map((q, idx) => (
                    <div key={q.id} className="p-5 hover:bg-indigo-50/10 transition-all group relative flex gap-4">
                       <span className="w-7 h-7 rounded-lg bg-slate-900 text-white flex items-center justify-center font-black text-[10px] italic shrink-0">#{idx+1}</span>
                       <div className="flex-1">
                          <p className="text-[11px] font-black uppercase italic text-slate-800 leading-tight mb-3">{q.text}</p>
                          <div className="grid grid-cols-2 gap-2">
                            {q.options.map((opt, oi) => (
                              <div key={oi} className={`px-2 py-1 rounded-md text-[8px] font-bold border ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-white text-slate-400 border-slate-100'}`}>{opt}</div>
                            ))}
                          </div>
                       </div>
                       <button onClick={async () => { if(confirm('Excluir?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-1.5 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-md transition-all opacity-0 group-hover:opacity-100"><Trash2 size={14}/></button>
                    </div>
                  ))}
                  {(currentExam.questions?.length === 0) && <div className="p-16 text-center text-slate-300 font-black text-[10px] uppercase italic">Banco Vazio</div>}
                </div>
            </div>
        </div>
      </div>
    );
  }

  // TELA CHEIA: SIMULADOR DE EXAME
  if (fullScreenMode === 'test_simulation' && currentExam) {
    const q = currentExam.questions?.[currentQuestionIndex];
    return (
      <div className="fixed inset-0 z-[1000] bg-black flex flex-col text-white animate-in fade-in overflow-hidden font-sans">
        <header className="bg-black/40 backdrop-blur-3xl border-b border-white/5 px-6 py-3 flex items-center justify-between relative z-20">
           <div className="flex items-center gap-3">
              <div className="p-1.5 bg-indigo-600 rounded-lg shadow-2xl"><Timer size={14}/></div>
              <div>
                <h2 className="text-[11px] font-black uppercase italic tracking-tighter leading-none">{currentExam.title}</h2>
                <span className="text-[7px] font-black text-white/30 uppercase tracking-[0.3em] mt-1 block">Item {currentQuestionIndex + 1} / {currentExam.questions?.length || 0}</span>
              </div>
           </div>
           <div className="flex items-center gap-4">
              <div className={`flex items-center gap-2 px-3 py-1 rounded-full border border-white/10 text-indigo-400`}>
                 <Timer size={12} /><span className="text-[10px] font-black tabular-nums">{formatTime(timeLeft)}</span>
              </div>
              <button onClick={() => { setFullScreenMode('none'); setTestStarted(false); }} className="p-2 bg-white/5 hover:bg-rose-600 text-white/50 rounded-full"><X size={14}/></button>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto relative z-10 flex flex-col items-center justify-center p-8">
           {!testStarted ? (
             <div className="bg-white text-slate-900 w-full max-w-md rounded-[2rem] p-10 text-center shadow-2xl animate-in zoom-in-95">
                <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto mb-6 text-indigo-600 shadow-inner"><ShieldAlert size={32} /></div>
                <h3 className="text-xl font-black uppercase tracking-tighter italic mb-4">Protocolo de Exame</h3>
                <div className="space-y-3 mb-8 text-slate-500 font-medium italic leading-relaxed text-[10px] text-left bg-slate-50 p-6 rounded-2xl border border-slate-100">
                   <div className="flex gap-3"><Clock size={14} className="text-rose-500" /><p>Tempo limite: <strong>3 minutos</strong> por questão.</p></div>
                   <div className="flex gap-3"><Award size={14} className="text-emerald-500" /><p>Aprovação mínima: <strong>{currentExam.passingGrade}%</strong>.</p></div>
                   <div className="flex gap-3"><Info size={14} className="text-indigo-500" /><p>Foco total: evite alternar abas durante o teste.</p></div>
                </div>
                <button onClick={() => { setTestStarted(true); setTimeLeft(180); setCurrentQuestionIndex(0); }} className="w-full py-4 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-[0.4em] italic hover:bg-indigo-600">Iniciar Simulação</button>
             </div>
           ) : q ? (
             <div className="w-full max-w-2xl space-y-8 animate-in fade-in slide-in-from-bottom-5 duration-500">
                <div className="text-center space-y-4">
                   <div className="inline-block px-4 py-1.5 bg-indigo-600/20 text-indigo-400 text-[8px] font-black uppercase rounded-lg border border-indigo-500/30 tracking-widest">Avaliação Discente</div>
                   <h4 className="text-2xl md:text-3xl font-black text-white uppercase italic tracking-tighter leading-tight">{q.text}</h4>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                   {q.options.map((opt, i) => (
                     <div key={i} onClick={() => setCurrentTestAnswers({...currentTestAnswers, [q.id]: i})} className={`p-5 rounded-2xl border-2 flex items-center gap-4 transition-all cursor-pointer relative ${currentTestAnswers[q.id] === i ? 'border-indigo-500 bg-indigo-600/10' : 'border-white/5 bg-white/5 hover:bg-white/10'}`}>
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-sm ${currentTestAnswers[q.id] === i ? 'bg-indigo-500 text-white' : 'bg-zinc-800 text-white/20'}`}>{String.fromCharCode(65+i)}</div>
                        <span className={`text-sm font-bold italic ${currentTestAnswers[q.id] === i ? 'text-white' : 'text-white/40'}`}>{opt}</span>
                     </div>
                   ))}
                </div>
                <div className="flex flex-col items-center pt-4">
                   <button disabled={currentTestAnswers[q.id] === undefined} onClick={handleNextQuestion} className="px-16 py-5 bg-white text-black rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] italic shadow-2xl hover:bg-indigo-500 hover:text-white transition-all active:scale-95">
                      {currentQuestionIndex < (currentExam.questions?.length || 1) - 1 ? 'Próxima Questão' : 'Finalizar Teste'}
                   </button>
                </div>
             </div>
           ) : null}
        </div>
      </div>
    );
  }

  // RENDERIZAÇÃO DA SALA DE LIVE
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white animate-in fade-in overflow-hidden font-sans">
        <div className="absolute top-0 left-0 right-0 z-[1300] p-6 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-rose-600 px-4 py-2 rounded-xl flex items-center gap-2.5 shadow-2xl border border-rose-500/20"><div className="w-2 h-2 bg-white rounded-full animate-ping"></div><span className="text-[8px] font-black uppercase tracking-[0.4em] italic leading-none">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 shadow-2xl"><Users size={14} className="text-indigo-400"/><span className="text-[8px] font-black uppercase tabular-nums">0 ALUNOS ONLINE</span></div>
           </div>
           <div className="flex items-center gap-2.5 pointer-events-auto">
              <div className="bg-indigo-600 px-4 py-2 rounded-xl text-[8px] font-black uppercase flex items-center gap-2.5 shadow-2xl italic tracking-widest border border-indigo-400/30"><ShieldCheck size={16}/> {user.displayName}</div>
           </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-6 lg:p-12">
              <div className="absolute inset-0 pointer-events-none z-[1250] overflow-hidden">
                 {activeReactions.map(r => (
                   <div key={r.id} className="absolute bottom-32 text-4xl animate-bounce-up opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
                 ))}
              </div>

              <div className={`w-full h-full max-w-[1600px] aspect-video bg-zinc-950 rounded-[2rem] overflow-hidden border border-white/5 relative group shadow-[0_40px_100px_rgba(0,0,0,1)] transition-all duration-700 ${activePanel !== 'none' ? 'lg:mr-8 scale-[0.98]' : ''}`}>
                 {isPresentationMode && selectedFileName ? (
                   <div className="w-full h-full bg-white flex flex-col items-center justify-center text-slate-900 relative animate-in fade-in duration-500">
                      <div className="absolute top-8 flex flex-col items-center gap-2">
                         <div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100 tracking-widest">Documento Master Ativo</div>
                         <h5 className="font-black text-base uppercase italic text-slate-900">{selectedFileName.split('.')[0]}</h5>
                      </div>
                      <div className="p-16 border-4 border-slate-100 rounded-[2rem] bg-slate-50 flex flex-col items-center justify-center text-center shadow-inner">
                         <Presentation size={100} className="text-indigo-600 mb-6 opacity-10" />
                         <p className="text-slate-400 font-black text-base uppercase tracking-[0.4em] italic">SLIDE #{presentationSlide} • MÓDULO MASTER</p>
                      </div>
                      <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                         <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronLeft size={32}/></button>
                         <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-2xl pointer-events-auto"><ChevronRight size={32}/></button>
                      </div>
                   </div>
                 ) : (
                   <div className="relative w-full h-full overflow-hidden">
                      {virtualBg !== 'none' && (
                        <div 
                          className="absolute inset-0 z-0 bg-cover bg-center transition-all duration-700" 
                          style={{ 
                            backgroundImage: virtualBg === 'office' 
                              ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' 
                              : virtualBg === 'custom' && customBgUrl 
                                ? `url(${customBgUrl})` 
                                : 'none',
                            filter: virtualBg === 'blur' ? 'blur(40px)' : 'none'
                          }} 
                        />
                      )}
                      <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover relative z-10 transition-all duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`} style={virtualBg !== 'none' && virtualBg !== 'blur' ? { maskImage: 'radial-gradient(circle, black 70%, transparent 100%)', WebkitMaskImage: 'radial-gradient(circle, black 70%, transparent 100%)' } : {}} />
                      {!videoActive && (
                        <div className="absolute inset-0 z-20 bg-zinc-900 flex flex-col items-center justify-center">
                          <div className="w-24 h-24 rounded-full bg-indigo-600 flex items-center justify-center font-black text-4xl text-white shadow-2xl">{user.displayName.charAt(0)}</div>
                          <p className="mt-6 text-[8px] font-black uppercase tracking-[0.5em] text-white/20 italic">Professor em Pausa Digital</p>
                        </div>
                      )}
                   </div>
                 )}

                 {/* CONTROLS DOCK */}
                 <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/80 backdrop-blur-3xl px-8 py-5 rounded-[2rem] border border-white/10 shadow-2xl opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={toggleMic} className={`p-3.5 rounded-xl transition-all shadow-xl ${micActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{micActive ? <Mic size={18}/> : <MicOff size={18}/>}</button>
                    <button onClick={toggleVideo} className={`p-3.5 rounded-xl transition-all shadow-xl ${videoActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{videoActive ? <Video size={18}/> : <VideoOff size={18}/>}</button>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <button onClick={startScreenShare} className={`p-3.5 rounded-xl transition-all shadow-xl ${screenShareActive ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} title="Compartilhar Tela"><Monitor size={18}/></button>
                    <button onClick={() => { if (isPresentationMode) { setIsPresentationMode(false); setSelectedFileName(null); } else { setShowPptUpload(true); } }} className={`p-3.5 rounded-xl transition-all shadow-xl ${isPresentationMode ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} title="Slides"><Presentation size={18}/></button>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <div className="flex gap-1 bg-black/60 p-1.5 rounded-xl border border-white/5">
                       {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-2 hover:bg-white/10 rounded-lg transition-all text-base active:scale-150">{e}</button>)}
                    </div>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <button onClick={stopLive} className="px-6 py-4 bg-rose-600 hover:bg-rose-700 rounded-xl text-[8px] font-black uppercase tracking-[0.3em] shadow-2xl transition-all italic text-white flex items-center gap-2"><PhoneOff size={16}/> Encerrar Aula</button>
                 </div>

                 <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col gap-3 opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-3.5 rounded-xl border transition-all shadow-2xl ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><MessageSquare size={22}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-3.5 rounded-xl border transition-all shadow-2xl ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Users size={22}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className={`p-3.5 rounded-xl border transition-all shadow-2xl ${activePanel === 'settings' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Settings size={22}/></button>
                 </div>
              </div>
           </div>

           {activePanel !== 'none' && (
             <div className="w-[360px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right h-full shadow-2xl relative z-[1500]">
                <div className="p-6 border-b border-white/5 flex items-center justify-between"><h4 className="text-[9px] font-black uppercase italic text-indigo-400 tracking-widest">{activePanel === 'chat' ? 'Chat Live' : activePanel === 'participants' ? 'Turma' : 'Setup'}</h4><button onClick={() => setActivePanel('none')} className="p-1.5 bg-white/5 rounded-full hover:bg-white/10"><X size={16}/></button></div>
                <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar">
                   {activePanel === 'chat' ? (
                     chatMessages.map((m, i) => (
                       <div key={i} className="animate-in fade-in slide-in-from-bottom-2"><div className="flex items-center gap-2 mb-1"><span className="text-[9px] font-black text-indigo-400 uppercase italic">{m.user}</span><span className="text-[7px] text-white/10">{m.time}</span></div><p className="text-[10px] font-medium text-white/60 bg-white/5 p-3 rounded-xl border border-white/5 italic">"{m.text}"</p></div>
                     ))
                   ) : activePanel === 'participants' ? (
                     <div className="space-y-3">
                       <div className="p-4 bg-white/5 rounded-xl border border-white/10 space-y-3 mb-3">
                         <h5 className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Moderação</h5>
                         <div className="grid grid-cols-2 gap-2">
                           <button onClick={() => setGlobalMute(!globalMute)} className={`py-2.5 rounded-lg border text-[7px] font-black uppercase transition-all flex items-center justify-center gap-1.5 ${globalMute ? 'bg-rose-600 border-rose-400 text-white shadow-lg' : 'bg-white/5 border-white/10 text-slate-300'}`}><VolumeX size={12}/> {globalMute ? 'Liberar' : 'Mudar Mic'}</button>
                           <button onClick={() => setGlobalCamBlock(!globalCamBlock)} className={`py-2.5 rounded-lg border text-[7px] font-black uppercase transition-all flex items-center justify-center gap-1.5 ${globalCamBlock ? 'bg-rose-600 border-rose-400 text-white shadow-lg' : 'bg-white/5 border-white/10 text-slate-300'}`}><UserX size={12}/> {globalCamBlock ? 'Liberar' : 'Mudar Cam'}</button>
                         </div>
                       </div>
                       {allStudents.length === 0 ? <p className="text-center text-[9px] text-white/20 italic p-10">Nenhum aluno online</p> : allStudents.map(s => (
                         <div key={s.uid} className="p-3 bg-white/5 rounded-xl border border-white/5 flex items-center justify-between group/u hover:bg-indigo-600/10 transition-all"><div className="flex items-center gap-3"><div className="w-7 h-7 rounded-lg bg-zinc-900 border border-white/5 flex items-center justify-center font-black text-[9px] italic">{(s.displayName||'U').charAt(0)}</div><span className="text-[9px] font-black uppercase italic text-white/70">{s.displayName}</span></div><div className="flex gap-1.5 opacity-0 group-hover/u:opacity-100"><button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><VolumeX size={12}/></button><button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><PowerOff size={12}/></button></div></div>
                       ))}
                     </div>
                   ) : (
                      <div className="space-y-6">
                         <div className="space-y-3"><h5 className="text-[8px] font-black uppercase tracking-[0.5em] text-white/20 italic">Mídia Master</h5><div className="space-y-1.5">
                            <div className="relative"><Video size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-9 py-2.5 text-[9px] font-black outline-none appearance-none text-slate-300"><option value="">Detectando Câmera...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                            <div className="relative"><Mic size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLiveMedia(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-9 py-2.5 text-[9px] font-black outline-none appearance-none text-slate-300"><option value="">Detectando Áudio...</option>{devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                         </div></div>
                         <div className="space-y-3"><h5 className="text-[8px] font-black uppercase tracking-[0.5em] text-white/20 italic">Fundo Virtual</h5><div className="grid grid-cols-2 gap-2">
                            {['none', 'blur', 'office', 'custom'].map(bg => (
                              <button key={bg} 
                                onClick={() => { if(bg === 'custom') customBgInputRef.current?.click(); else setVirtualBg(bg as any); }} 
                                className={`p-4 rounded-xl border text-[8px] font-black uppercase transition-all flex flex-col items-center gap-2 ${virtualBg === bg ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl' : 'bg-white/5 border-white/10 hover:bg-white/10 text-white/40'}`}
                              >
                                <span className="p-2.5 bg-black/40 rounded-lg">{bg === 'none' ? <Video size={14} /> : bg === 'blur' ? <Sparkles size={14} /> : bg === 'office' ? <ImageIcon size={14} /> : <Upload size={14} />}</span>{bg}
                              </button>
                            ))}
                         </div></div>
                      </div>
                   )}
                </div>
                {activePanel === 'chat' && (<div className="p-6 border-t border-white/5 bg-[#080808]"><div className="relative"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Sua mensagem..." className="w-full bg-white/5 border-none rounded-xl px-5 py-3.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-600 placeholder:text-white/10" /><button onClick={handleSendMessage} className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-indigo-500 hover:text-indigo-400"><Send size={18}/></button></div></div>)}
             </div>
           )}
        </div>
        <input type="file" ref={customBgInputRef} className="hidden" accept="image/*" onChange={e => { if(e.target.files?.[0]) { const reader = new FileReader(); reader.onload = (f) => { setCustomBgUrl(f.target?.result as string); setVirtualBg('custom'); }; reader.readAsDataURL(e.target.files[0]); }}} />
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in fade-in h-full text-slate-900">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-5 animate-in slide-in-from-bottom-5 duration-500">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-indigo-600 text-white rounded-[0.8rem] shadow-xl shadow-indigo-100"><Layers size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Matriz Acadêmica</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Gestão de Conteúdo EAD</p></div>
            </div>
            <div className="flex flex-wrap items-center gap-2 justify-center">
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-lg text-[8px] font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-1.5 italic"><Eye size={12}/> Preview</button>
              <button onClick={() => setIsSignModalOpen(true)} className="bg-amber-50 text-amber-600 px-4 py-2 rounded-lg text-[8px] font-black uppercase border border-amber-100 flex items-center gap-1.5 italic"><PenTool size={12}/> Assinatura</button>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-md px-3 py-1.5 text-[8px] font-black uppercase outline-none shadow-inner">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all flex items-center gap-1.5 italic"><Plus size={12}/> Novo Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-3">
            {modules.map(mod => {
              const moduleExams = exams.filter(e => e.moduleId === mod.id);
              return (
                <div key={mod.id} className="bg-white border border-slate-100 rounded-[1.5rem] overflow-hidden group shadow-sm hover:shadow-md transition-all duration-500">
                  <div className="bg-slate-50/50 px-5 py-3 border-b flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="w-7 h-7 bg-indigo-100 text-indigo-700 rounded-md flex items-center justify-center font-black text-[10px] italic shadow-inner">#{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-[9px] uppercase italic tracking-[0.1em]">{mod.title}</h3>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-3 py-1.5 bg-indigo-600 text-white text-[7px] font-black uppercase rounded-md shadow-lg hover:scale-105 transition-all italic">Add Aula</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-md transition-all"><Edit3 size={12}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-1.5 text-slate-200 hover:text-rose-600 transition-all"><Trash2 size={12}/></button>
                    </div>
                  </div>
                  <div className="p-5 space-y-1.5">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-3 rounded-xl flex items-center justify-between border border-slate-50 hover:border-indigo-50 transition-all group/l">
                        <div className="flex items-center gap-3 text-[8px]">
                          <span className="w-6 h-6 rounded bg-slate-50 flex items-center justify-center font-black text-slate-300 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all italic">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 uppercase italic tracking-tight">{l.title}</h4>
                          </div>
                        </div>
                        <div className="flex gap-1.5 opacity-0 group-hover/l:opacity-100">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-md transition-all bg-white"><Edit3 size={11}/></button>
                          <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-1.5 text-rose-500 hover:bg-rose-50 rounded-md transition-all"><Trash2 size={11}/></button>
                        </div>
                      </div>
                    ))}
                    {moduleExams.map(ex => (
                      <div key={ex.id} className="bg-amber-50/20 p-4 rounded-xl flex items-center justify-between border border-amber-50 shadow-sm hover:bg-amber-50 transition-all duration-500">
                        <div className="flex items-center gap-3">
                          <div className="p-2 bg-amber-100 text-amber-600 rounded-lg shadow-inner"><Award size={14}/></div>
                          <div><h4 className="font-black text-amber-900 text-[9px] uppercase italic">{ex.title}</h4><span className="text-[7px] font-black text-amber-600/60 uppercase italic mt-0.5 block">{ex.questions?.length||0} Itens</span></div>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="px-4 py-2 bg-amber-600 text-white text-[7px] font-black uppercase rounded-md shadow-xl hover:bg-amber-700 transition-all italic tracking-widest">Gerir Itens</button>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-5 animate-in fade-in duration-500">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-[0.8rem] shadow-sm"><FileText size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter">Acervo Acadêmico</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Gestão de Documentos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-1.5 italic tracking-widest"><Plus size={14}/> Novo Recurso</button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-4 rounded-xl border border-slate-50 relative group hover:shadow-lg transition-all duration-500 text-center">
                <div className="w-10 h-10 bg-slate-50 rounded-lg flex items-center justify-center mx-auto mb-3 shadow-inner"><FileText size={20} className="text-indigo-500" /></div>
                <h4 className="font-black text-slate-900 text-[8px] uppercase italic mb-4 leading-tight tracking-tight px-1 line-clamp-2 h-6">{m.title}</h4>
                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-1.5 py-2 bg-slate-900 text-white rounded-md text-[7px] font-black uppercase hover:bg-indigo-600 transition-all italic"><ExternalLink size={10}/> Abrir</a>
                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-rose-500 transition-all"><Trash2 size={12}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-5 animate-in fade-in duration-500">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-amber-50 text-amber-600 rounded-[0.8rem] shadow-sm"><Award size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter">Banca Examinadora</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Controle de Performance</p></div>
            </div>
