                <div className="flex flex-col items-center pt-4">
                   <button disabled={currentTestAnswers[q.id] === undefined} onClick={handleNextQuestion} className="px-12 py-5 bg-white text-black rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] italic shadow-2xl hover:bg-indigo-500 hover:text-white active:scale-95">
