                        <button onClick={toggleMic} className={`p-2.5 rounded-lg shadow-2xl transition-all ${micActive ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-rose-600 text-white'}`}>{micActive ? <Mic size={18}/> : <MicOff size={18}/>}</button>
                        <button onClick={toggleVideo} className={`p-2.5 rounded-lg shadow-2xl transition-all ${videoActive ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-rose-600 text-white'}`}>{videoActive ? <Video size={18}/> : <VideoOff size={18}/>}</button>
