              <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Link da Vídeo-Aula (Vimeo/YouTube)</label><input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL de Transmissão..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div>

              {/* MATERIAL DE APOIO - SELEÇÃO FLEXÍVEL */}
