                    <Database size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-indigo-300 pointer-events-none" />
                  </div>
                </div>
              </div>

              <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Ementa Pedagógica</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo do encontro..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl h-24 font-medium text-[10px] shadow-inner resize-none"></textarea></div>
            </div>
            <div className="flex gap-2 pt-1"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase tracking-widest italic hover:bg-slate-200">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic">Publicar Aula</button></div>
          </div>
        </div>
      )}

      {/* MODAL: PPT UPLOAD (FIXED) */}
      {showPptUpload && (
        <div className="fixed inset-0 z-[2000] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 text-center shadow-2xl animate-in zoom-in-95">
            <div className="w-16 h-16 bg-indigo-50 rounded-xl flex items-center justify-center mx-auto mb-6 text-indigo-600 shadow-inner"><Presentation size={32}/></div>
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic mb-2 leading-none">Exposição de Slides</h3>
            <div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-3xl p-12 mb-8 cursor-pointer transition-all ${selectedFileName ? 'border-emerald-200 bg-emerald-50/20' : 'border-slate-100 hover:border-indigo-400'}`}>
              {selectedFileName ? (
                <div className="space-y-3"><CheckCircle2 size={50} className="text-emerald-500 mx-auto" /><p className="text-xs font-black text-slate-900 uppercase italic tracking-tighter">{selectedFileName}</p></div>
              ) : (
                <><Upload size={32} className="text-slate-100 mb-3 mx-auto" /><span className="text-[8px] font-black uppercase text-slate-300 tracking-[0.5em] block">Escolher Documento Master (PDF/PPT)</span></>
              )}
              <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) setSelectedFileName(e.target.files[0].name); }} />
            </div>
            <div className="flex gap-2"><button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase italic">Voltar</button><button disabled={!selectedFileName} onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className={`flex-1 py-4 text-white rounded-xl text-[8px] font-black uppercase shadow-2xl tracking-[0.4em] italic ${selectedFileName ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-slate-200 cursor-not-allowed'}`}>Lançar na Sala</button></div>
          </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}

      {/* ESTILOS DE ANIMAÇÃO PARA EMOJIS MEET STYLE */}
      <style>{`
        @keyframes float-up {
          0% { transform: translateY(0) scale(0.5); opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { transform: translateY(-350px) scale(1.5); opacity: 0; }
        }
        .animate-float-up {
          animation: float-up 2.5s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, Activity, PowerOff, UserPlus, ShieldX,
  Link as LinkIcon, Database
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    for (let i = 0; i < 15; i++) {
      setTimeout(() => {
        const id = Date.now() + i;
        setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
        setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 2500);
      }, i * 150);
    }
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < (currentExam.questions?.length || 1) - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180); 
    } else {
      setFullScreenMode('none');
      setTestStarted(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // SALA DE LIVE ATIVA
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white overflow-hidden font-sans">
        <div className="absolute inset-0 pointer-events-none z-[1250] overflow-hidden">
           {activeReactions.map(r => (
             <div key={r.id} className="absolute bottom-32 text-6xl animate-reaction-float opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
           ))}
        </div>

        <div className="absolute top-0 left-0 right-0 z-[1300] p-6 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-rose-600 px-4 py-2 rounded-xl flex items-center gap-2 shadow-2xl border border-rose-500/20"><div className="w-2 h-2 bg-white rounded-full animate-ping"></div><span className="text-[8px] font-black uppercase italic tracking-widest">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 shadow-2xl"><Users size={14} className="text-indigo-400"/><span className="text-[8px] font-black uppercase tracking-widest">{allStudents.length} ALUNOS</span></div>
           </div>
           <div className="bg-indigo-600 px-4 py-2 rounded-xl text-[8px] font-black uppercase flex items-center gap-2 shadow-2xl italic tracking-widest border border-indigo-400/30 pointer-events-auto"><ShieldCheck size={16}/> {user.displayName}</div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-6">
              <div className={`w-full h-full max-w-[1600px] aspect-video bg-zinc-950 rounded-[2rem] overflow-hidden border border-white/5 relative group transition-all duration-700 shadow-2xl`}>
                 {/* Camadas da live: 1. Fundo, 2. Vídeo/Slides, 3. Controles */}
                 {virtualBg !== 'none' && (
                   <div className="absolute inset-0 z-0 bg-cover bg-center" style={{ 
                     backgroundImage: virtualBg === 'office' ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' : virtualBg === 'custom' && customBgUrl ? `url(${customBgUrl})` : 'none',
                     filter: virtualBg === 'blur' ? 'blur(30px)' : 'none'
                   }} />
                 )}

                 {isPresentationMode && selectedFileName ? (
                   <div className="absolute inset-0 z-20 bg-white flex flex-col items-center justify-center text-slate-900 animate-in fade-in">
                      <div className="absolute top-8 flex flex-col items-center gap-2">
                         <div className="px-4 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100">Documento Ativo</div>
                         <h5 className="font-black text-sm uppercase italic text-slate-900">{selectedFileName}</h5>
                      </div>
                      <Presentation size={120} className="text-indigo-600 opacity-10 mb-8" />
                      <p className="text-slate-400 font-black text-xl uppercase tracking-[0.4em] italic">Slide #{presentationSlide}</p>
                      <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                         <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-xl pointer-events-auto"><ChevronLeft size={32}/></button>
                         <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-xl pointer-events-auto"><ChevronRight size={32}/></button>
                      </div>
                   </div>
                 ) : (
                   <div className="relative w-full h-full z-10">
                      <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-all duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`} />
                      {!videoActive && <div className="absolute inset-0 z-20 bg-zinc-900 flex flex-col items-center justify-center"><div className="w-24 h-24 rounded-full bg-indigo-600 flex items-center justify-center font-black text-4xl text-white shadow-2xl">{user.displayName.charAt(0)}</div><p className="mt-4 text-[8px] font-black uppercase tracking-widest text-white/20 italic">Câmera em Pausa</p></div>}
                   </div>
                 )}

                 <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/80 backdrop-blur-3xl px-8 py-4 rounded-[2rem] border border-white/10 shadow-2xl z-[1400] opacity-0 group-hover:opacity-100 transition-all">
                    <button onClick={toggleMic} className={`p-3 rounded-xl transition-all ${micActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{micActive ? <Mic size={18}/> : <MicOff size={18}/>}</button>
                    <button onClick={toggleVideo} className={`p-3 rounded-xl transition-all ${videoActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{videoActive ? <Video size={18}/> : <VideoOff size={18}/>}</button>
                    <div className="w-px h-6 bg-white/10"></div>
                    <button onClick={() => setShowPptUpload(true)} className={`p-3 rounded-xl transition-all ${isPresentationMode ? 'bg-indigo-600' : 'bg-white/5 hover:bg-white/10'}`}><Presentation size={18}/></button>
                    <div className="w-px h-6 bg-white/10"></div>
                    <div className="flex gap-1 bg-black/40 p-1 rounded-xl">
                       {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-2 hover:bg-white/10 rounded-lg text-lg active:scale-125 transition-transform">{e}</button>)}
                    </div>
                    <div className="w-px h-6 bg-white/10"></div>
                    <button onClick={stopLive} className="px-6 py-3 bg-rose-600 hover:bg-rose-700 rounded-xl text-[8px] font-black uppercase tracking-widest italic flex items-center gap-2"><PhoneOff size={16}/> Encerrar</button>
                 </div>

                 <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col gap-3 z-[1400] opacity-0 group-hover:opacity-100 transition-all">
                    <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-3 rounded-xl border ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/80 border-white/10'}`}><MessageSquare size={20}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-3 rounded-xl border ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/80 border-white/10'}`}><Users size={20}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className={`p-3 rounded-xl border ${activePanel === 'settings' ? 'bg-indigo-600 border-indigo-400' : 'bg-black/80 border-white/10'}`}><Settings size={20}/></button>
                 </div>
              </div>
           </div>

           {activePanel !== 'none' && (
             <div className="w-[360px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right h-full z-[1500]">
                <div className="p-6 border-b border-white/5 flex items-center justify-between"><h4 className="text-[9px] font-black uppercase italic text-indigo-400 tracking-widest">{activePanel === 'chat' ? 'Chat ao Vivo' : activePanel === 'participants' ? 'Alunos' : 'Configurações'}</h4><button onClick={() => setActivePanel('none')}><X size={16}/></button></div>
                <div className="flex-1 overflow-y-auto p-5 space-y-4">
                   {activePanel === 'settings' && (
                     <div className="space-y-6">
                        <div className="space-y-3"><h5 className="text-[8px] font-black uppercase text-white/20 italic">Dispositivos</h5><div className="space-y-2">
                           <select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-[10px] font-black text-slate-300 outline-none"><option value="">Ajustar Câmera...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select>
                           <select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLiveMedia(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-[10px] font-black text-slate-300 outline-none"><option value="">Ajustar Áudio...</option>{devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select>
                        </div></div>
                        <div className="space-y-3"><h5 className="text-[8px] font-black uppercase text-white/20 italic">Cenário Digital</h5><div className="grid grid-cols-2 gap-2">
                           {['none', 'blur', 'office', 'custom'].map(bg => (
                             <button key={bg} onClick={() => { if(bg === 'custom') customBgInputRef.current?.click(); else setVirtualBg(bg as any); }} className={`p-4 rounded-xl border text-[8px] font-black uppercase transition-all flex flex-col items-center gap-2 ${virtualBg === bg ? 'bg-indigo-600 border-indigo-400' : 'bg-white/5 border-white/10'}`}>
                                <span className="p-2.5 bg-black/40 rounded-lg">{bg === 'none' ? <Video size={14} /> : bg === 'blur' ? <Sparkles size={14} /> : bg === 'office' ? <ImageIcon size={14} /> : <Upload size={14} />}</span>{bg}
                             </button>
                           ))}
                        </div></div>
                     </div>
                   )}
                </div>
             </div>
           )}
        </div>
        <input type="file" ref={customBgInputRef} className="hidden" accept="image/*" onChange={e => { if(e.target.files?.[0]) { const reader = new FileReader(); reader.onload = (f) => { setCustomBgUrl(f.target?.result as string); setVirtualBg('custom'); }; reader.readAsDataURL(e.target.files[0]); }}} />
        <style>{`
          @keyframes reaction-float {
            0% { transform: translateY(0) scale(0.5); opacity: 0; }
            10% { opacity: 1; }
            100% { transform: translateY(-400px) scale(1.5); opacity: 0; }
          }
          .animate-reaction-float { animation: reaction-float 2.5s ease-out forwards; }
        `}</style>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in fade-in h-full text-slate-900">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-5 animate-in slide-in-from-bottom-5">
           <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-indigo-600 text-white rounded-[0.8rem] shadow-xl shadow-indigo-100"><Layers size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Matriz Acadêmica</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-0.5">Gestão de Conteúdo EAD</p></div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-lg text-[8px] font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-1.5 italic"><Eye size={12}/> Preview</button>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-md px-3 py-1.5 text-[8px] font-black uppercase outline-none shadow-inner">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all flex items-center gap-1.5 italic"><Plus size={12}/> Novo Módulo</button>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-3">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[1.5rem] overflow-hidden group shadow-sm hover:shadow-md transition-all duration-500">
                  <div className="bg-slate-50/50 px-5 py-3 border-b flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="w-7 h-7 bg-indigo-100 text-indigo-700 rounded-md flex items-center justify-center font-black text-[10px] italic shadow-inner">#{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-[9px] uppercase italic tracking-[0.1em]">{mod.title}</h3>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-3 py-1.5 bg-indigo-600 text-white text-[7px] font-black uppercase rounded-md shadow-lg hover:scale-105 transition-all italic">Add Aula</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-md transition-all"><Edit3 size={12}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-1.5 text-slate-200 hover:text-rose-600 transition-all"><Trash2 size={12}/></button>
                    </div>
                  </div>
                  <div className="p-5 space-y-1.5">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-3 rounded-xl flex items-center justify-between border border-slate-50 hover:border-indigo-50 transition-all group/l">
                        <div className="flex items-center gap-3 text-[8px]">
                          <span className="w-6 h-6 rounded bg-slate-50 flex items-center justify-center font-black text-slate-300 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all italic">{i+1}</span>
                          <h4 className="font-black text-slate-900 uppercase italic tracking-tight">{l.title}</h4>
                        </div>
                        <div className="flex gap-1.5 opacity-0 group-hover/l:opacity-100">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-md transition-all bg-white"><Edit3 size={11}/></button>
                          <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-1.5 text-rose-500 hover:bg-rose-50 rounded-md transition-all"><Trash2 size={11}/></button>
                        </div>
                      </div>
                    ))}
                    {exams.filter(e => e.moduleId === mod.id).map(ex => (
                      <div key={ex.id} className="bg-amber-50/20 p-4 rounded-xl flex items-center justify-between border border-amber-50 shadow-sm">
                        <div className="flex items-center gap-3">
                          <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><Award size={14}/></div>
                          <div><h4 className="font-black text-amber-900 text-[9px] uppercase italic">{ex.title}</h4><span className="text-[7px] font-black text-amber-600/60 uppercase italic mt-0.5 block">{ex.questions?.length||0} Itens</span></div>
                        </div>
                        <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="px-4 py-2 bg-amber-600 text-white text-[7px] font-black uppercase rounded-md shadow-xl hover:bg-amber-700 transition-all italic tracking-widest">Gerir</button>
                      </div>
                    ))}
                  </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-5 animate-in fade-in">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-lg shadow-sm"><FileText size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Materiais</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Gestão de Arquivos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-1.5 italic tracking-widest"><Plus size={14}/> Novo Arquivo</button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-4 rounded-xl border border-slate-50 relative group hover:shadow-lg transition-all text-center">
                <div className="w-10 h-10 bg-slate-50 rounded-lg flex items-center justify-center mx-auto mb-3 shadow-inner"><FileText size={20} className="text-indigo-500" /></div>
                <h4 className="font-black text-slate-900 text-[8px] uppercase italic mb-4 leading-tight tracking-tight line-clamp-2 h-6">{m.title}</h4>
                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-1.5 py-2 bg-slate-900 text-white rounded-md text-[7px] font-black uppercase hover:bg-indigo-600 transition-all italic"><ExternalLink size={10}/> Ver</a>
                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-rose-500 transition-all"><Trash2 size={12}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-5 animate-in fade-in">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-amber-50 text-amber-600 rounded-lg shadow-sm"><Award size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Avaliações</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Controladoria</p></div>
            </div>
            <button onClick={() => { setExamForm({title:'', courseId: selectedCourseForModules, moduleId:'', type:'activity', passingGrade:70}); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic tracking-widest"><Plus size={14}/> Criar Avaliação</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
