                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-1.5 py-2 bg-slate-900 text-white rounded-md text-[7px] font-black uppercase hover:bg-indigo-600 transition-all italic"><ExternalLink size={10}/> Ver</a>
