                    <td className="px-5 py-2.5 font-black text-slate-600">92%</td>
                    <td className="px-5 py-2.5"><span className="px-3 py-1 bg-indigo-50 text-indigo-700 text-[8px] font-black uppercase rounded-md">9.2</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* AULA AO VIVO (RESTAURADO BROADCAST STUDIO) */}
      {activeSub === 'live' && !isLiveActive && (
        <div className="h-full flex flex-col animate-in fade-in">
          {showLobby ? (
            <div className="fixed inset-0 z-[2000] bg-slate-900 flex items-center justify-center p-6 animate-in zoom-in-95">
               <div className="bg-white w-full max-w-4xl rounded-[2.5rem] overflow-hidden flex flex-col md:flex-row shadow-2xl">
                  <div className="flex-1 bg-black relative flex items-center justify-center group overflow-hidden">
                     {virtualBg !== 'none' && (
                        <div className="absolute inset-0 z-0 bg-cover bg-center" style={{ 
                           backgroundImage: virtualBg === 'office' ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' : virtualBg === 'custom' && customBgUrl ? `url(${customBgUrl})` : 'none',
                           filter: virtualBg === 'blur' ? 'blur(20px)' : 'none'
                        }}></div>
                     )}
                     <video ref={lobbyVideoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-all relative z-10 ${videoActive ? 'opacity-100' : 'opacity-0'}`} />
                     {!videoActive && <div className="absolute inset-0 z-20 flex items-center justify-center"><div className="w-16 h-16 rounded-full bg-indigo-600 flex items-center justify-center font-black text-2xl text-white shadow-2xl">P</div></div>}
                     <div className="absolute bottom-5 left-1/2 -translate-x-1/2 z-30 flex gap-2">
                        <button onClick={toggleMic} className={`p-2.5 rounded-lg shadow-2xl transition-all ${micActive ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-rose-600 text-white'}`}>{micActive ? <Mic size={18}/> : <MicOff size={18}/>}</button>
                        <button onClick={toggleVideo} className={`p-2.5 rounded-lg shadow-2xl transition-all ${videoActive ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-rose-600 text-white'}`}>{videoActive ? <Video size={18}/> : <VideoOff size={18}/>}</button>
                     </div>
                  </div>
                  <div className="w-full md:w-[360px] p-8 space-y-6 flex flex-col justify-center bg-white">
                     <div className="space-y-1"><h3 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Setup da Aula</h3><p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest italic leading-none">Ajuste seu ambiente master</p></div>
                     <div className="space-y-5">
                        <div className="space-y-1.5"><label className="text-[7px] font-black uppercase text-indigo-600 ml-2 tracking-widest">Fonte de Vídeo</label><select onChange={e => { setSelectedDevices({...selectedDevices, video: e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-slate-50 border-none rounded-lg px-3 py-2 text-[9px] font-black shadow-inner appearance-none outline-none focus:ring-1 focus:ring-indigo-600"><option value="">Detectando...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                        <div className="space-y-1.5"><label className="text-[7px] font-black uppercase text-indigo-600 ml-2 tracking-widest">Cenário Digital</label><div className="grid grid-cols-4 gap-2">
                           {['none', 'blur', 'office', 'custom'].map(b => (
                             <button key={b} onClick={() => { if(b === 'custom') customBgInputRef.current?.click(); else setVirtualBg(b as any); }} className={`py-2.5 rounded-lg border flex flex-col items-center justify-center gap-1 transition-all ${virtualBg === b ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-slate-100'}`}>
                                {b === 'none' ? <Video size={10}/> : b === 'blur' ? <Sparkles size={10}/> : b === 'office' ? <ImageIcon size={10}/> : <Upload size={10}/>}
                                <span className="text-[6px] font-black uppercase">{b}</span>
                             </button>
                           ))}
                        </div></div>
                     </div>
                     <div className="flex gap-2 pt-2"><button onClick={() => setShowLobby(false)} className="flex-1 py-3 bg-slate-100 text-slate-400 rounded-lg text-[8px] font-black uppercase tracking-widest italic">Voltar</button><button onClick={startLiveFromLobby} className="flex-1 py-3 bg-indigo-600 text-white rounded-lg text-[8px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all italic tracking-widest">Abrir Sala</button></div>
                  </div>
               </div>
            </div>
          ) : (
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-6 items-center">
              <div className="bg-white p-12 rounded-[3rem] border border-slate-200 shadow-sm text-center flex flex-col items-center justify-center">
                <div className="w-16 h-16 bg-rose-50 rounded-2xl flex items-center justify-center mb-6 animate-pulse"><Radio size={32} className="text-rose-600" /></div>
                <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-2 italic leading-none">Broadcast Studio</h2>
                <p className="text-slate-400 text-[8px] font-medium uppercase tracking-widest italic mb-8">Conexão direta para transmissão da palavra.</p>
                <button onClick={startLobby} className="bg-slate-900 text-white px-10 py-4 rounded-xl text-[9px] font-black uppercase shadow-xl hover:bg-rose-600 transition-all flex items-center gap-2 italic tracking-widest"><Tv size={16}/> Configurar Início</button>
              </div>
              {/* RESTAURAÇÃO DA AGENDA DO PROFESSOR */}
