                  <div className="flex items-center justify-between mb-8"><div className="flex items-center gap-4"><div className="p-3 bg-amber-50 text-amber-600 rounded-xl shadow-inner"><Calendar size={20}/></div><h3 className="font-black text-slate-900 uppercase text-[10px] italic tracking-widest leading-none">Minha Agenda</h3></div><button onClick={() => setIsScheduleModalOpen(true)} className="p-3 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 shadow-xl transition-all"><Plus size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                     {scheduledClasses.map(s => (
                       <div key={s.id} className="p-6 bg-slate-50 border border-slate-100 rounded-2xl flex justify-between items-center group hover:bg-white hover:shadow-lg transition-all duration-500">
                          <div className="flex items-center gap-4"><div><span className="text-[8px] font-black text-indigo-600 uppercase block mb-1 tracking-widest italic">{s.date?.seconds ? new Date(s.date.seconds * 1000).toLocaleString() : new Date(s.date).toLocaleString()}</span><span className="font-black text-slate-900 uppercase text-xs italic leading-none tracking-tight">{s.title}</span></div></div>
                          <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'scheduledClasses', s.id)); }} className="p-3 text-slate-200 hover:text-rose-600 bg-white rounded-lg shadow-sm"><Trash2 size={16}/></button>
                       </div>
                     ))}
                  </div>
              </div>
            </div>
          )}
          <input type="file" ref={customBgInputRef} className="hidden" accept="image/*" onChange={e => { if(e.target.files?.[0]) { const reader = new FileReader(); reader.onload = (f) => { setCustomBgUrl(f.target?.result as string); setVirtualBg('custom'); }; reader.readAsDataURL(e.target.files[0]); }}} />
        </div>
      )}

      {/* MODAIS (RESTAURADOS) */}
      {isModuleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-md rounded-[2rem] p-8 text-center shadow-2xl"><div className="w-14 h-14 bg-indigo-50 rounded-xl flex items-center justify-center mx-auto mb-6 text-indigo-600 shadow-inner"><Layers size={28}/></div><h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mb-6 italic leading-none">Módulo Master</h3><input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título..." className="w-full px-6 py-3.5 bg-slate-50 border-none rounded-xl font-black text-[11px] shadow-inner mb-8" /><div className="flex gap-2"><button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase italic">Cancelar</button><button onClick={async () => { if(!moduleTitle) return; if(currentModuleId) { await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle }); } else { await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); } setIsModuleModalOpen(false); }} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[8px] font-black uppercase italic shadow-xl">Salvar</button></div></div></div>)}

      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6 animate-in zoom-in-95">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-8 space-y-6 shadow-2xl overflow-y-auto max-h-[90vh] text-slate-900 custom-scrollbar">
            <div><h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{editingLessonId ? 'Revisar Aula' : 'Nova Aula Master'}</h3><p className="text-[7px] font-black text-slate-400 uppercase tracking-[0.4em] mt-1.5 italic">Integração Acadêmica Completa</p></div>
            <div className="space-y-4">
              <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Título do Encontro</label><input value={lessonForm.title} onChange={e => setLessonForm({...lessonForm, title: e.target.value})} placeholder="Título Bíblico..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[11px] shadow-inner focus:ring-1 focus:ring-indigo-600 transition-all" /></div>
              <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Link da Vídeo-Aula (Vimeo/YouTube)</label><input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL de Transmissão..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div>
              <div className="space-y-2.5">
                <label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Material de Apoio</label>
                <div className="grid grid-cols-2 gap-2">
                  <div className="relative"><LinkIcon size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" /><input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link Externo..." className="w-full pl-8 pr-4 py-3 bg-slate-50 border-none rounded-xl font-black text-[9px] shadow-inner" /></div>
                  <div className="relative"><select onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border-none rounded-xl font-black text-[9px] shadow-inner text-indigo-700 outline-none appearance-none cursor-pointer"><option value="">Do Acervo...</option>{materials.filter(m => m.courseId === selectedCourseForModules).map(m => <option key={m.id} value={m.url}>{m.title}</option>)}</select><Database size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-indigo-300 pointer-events-none" /></div>
                </div>
              </div>
              <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Ementa Pedagógica</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo do encontro..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl h-24 font-medium text-[10px] shadow-inner resize-none"></textarea></div>
            </div>
            <div className="flex gap-2 pt-1"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase tracking-widest italic hover:bg-slate-200">Cancelar</button><button onClick={handleSaveLesson} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic">Publicar Aula</button></div>
          </div>
        </div>
      )}

      {showPptUpload && (
        <div className="fixed inset-0 z-[2100] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 text-center shadow-2xl">
            <div className="w-16 h-16 bg-indigo-50 rounded-xl flex items-center justify-center mx-auto mb-6 text-indigo-600 shadow-inner"><Presentation size={32}/></div>
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic mb-2 leading-none">Exposição de Slides</h3>
            <div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-3xl p-12 mb-8 cursor-pointer transition-all ${selectedFileName ? 'border-emerald-200 bg-emerald-50/20' : 'border-slate-100 hover:border-indigo-400'}`}>
              {selectedFileName ? (
                <div className="space-y-3"><CheckCircle2 size={50} className="text-emerald-500 mx-auto" /><p className="text-xs font-black text-slate-900 uppercase italic tracking-tighter">{selectedFileName}</p></div>
              ) : (
                <><Upload size={32} className="text-slate-100 mb-3 mx-auto" /><span className="text-[8px] font-black uppercase text-slate-300 tracking-[0.5em] block">Escolher Documento Master (PDF/PPT)</span></>
              )}
              <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) setSelectedFileName(e.target.files[0].name); }} />
            </div>
            <div className="flex gap-2"><button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase italic">Voltar</button><button disabled={!selectedFileName} onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className={`flex-1 py-4 text-white rounded-xl text-[8px] font-black uppercase shadow-2xl tracking-[0.4em] italic ${selectedFileName ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-slate-200 cursor-not-allowed'}`}>Lançar na Sala</button></div>
          </div>
        </div>
      )}

      {isExamModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[1.8rem] p-8 space-y-6 shadow-2xl">
              <div className="flex items-center gap-3"><div className="p-2 bg-amber-50 text-amber-600 rounded-lg shadow-sm"><Award size={20}/></div><h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Setup Exame</h3></div>
              <div className="space-y-4">
                 <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Título</label><input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Avaliação Master..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[11px] shadow-inner" /></div>
                 <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Curso</label><select value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value, moduleId: ''})} className="w-full px-5 py-2.5 bg-slate-50 border-none rounded-xl text-[9px] font-black uppercase shadow-inner"><option value="">Selecione...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                 <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Módulo</label><select disabled={!examForm.courseId} value={examForm.moduleId} onChange={e => setExamForm({...examForm, moduleId: e.target.value})} className="w-full px-5 py-2.5 bg-slate-50 border-none rounded-xl text-[9px] font-black uppercase shadow-inner"><option value="">Módulo...</option>{modules.filter(m => m.courseId === examForm.courseId).map(m => <option key={m.id} value={m.id}>{m.title}</option>)}</select></div>
                    <div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Corte %</label><input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-5 py-2.5 bg-slate-50 border-none rounded-xl font-black text-center text-[11px] shadow-inner" /></div>
                 </div>
              </div>
              <div className="flex gap-2 pt-2"><button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase italic">Voltar</button><button onClick={async () => { const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); }} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[8px] font-black uppercase shadow-xl hover:bg-indigo-700 active:scale-95 italic">Gravar Exame</button></div>
           </div>
        </div>
      )}

      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-sm rounded-[2rem] p-8 text-center shadow-2xl"><div className="w-12 h-12 bg-emerald-50 rounded-xl flex items-center justify-center mx-auto mb-5 text-emerald-600 shadow-inner"><FileText size={24}/></div><h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mb-6 italic leading-none">Anexar Master</h3><div className="space-y-4 mb-6 text-left"><div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 ml-3">Nome</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: Livro..." className="w-full px-5 py-2.5 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div><div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 ml-3">Link</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL..." className="w-full px-5 py-2.5 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div></div><div className="flex gap-2"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-3.5 bg-slate-100 text-slate-400 rounded-lg text-[8px] font-black uppercase italic hover:bg-slate-200">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-3.5 bg-indigo-600 text-white rounded-lg text-[8px] font-black uppercase shadow-2xl italic hover:bg-indigo-700 active:scale-95">Publicar Recurso</button></div></div></div>)}

      {isScheduleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-sm rounded-[1.8rem] p-8 shadow-2xl relative overflow-hidden text-slate-900"><div className="absolute top-0 right-0 w-24 h-24 bg-indigo-50 rounded-full -mr-12 -mt-12 opacity-50 blur-[50px]"></div><div className="flex items-center gap-3 mb-6"><div className="p-2.5 bg-indigo-600 text-white rounded-lg shadow-xl"><Bell size={18} /></div><h3 className="text-xl font-black uppercase tracking-tighter italic leading-none">Agendar Aula</h3></div><div className="space-y-4 mb-8"><div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Título</label><input id="sched-title-final" placeholder="Ex: Teologia Sistemática..." className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div><div className="space-y-1"><label className="text-[7px] font-black uppercase text-slate-400 tracking-widest italic ml-3">Data/Hora</label><input id="sched-date-final" type="datetime-local" className="w-full px-5 py-3 bg-slate-50 border-none rounded-xl font-black text-[10px] shadow-inner" /></div></div><div className="flex gap-2"><button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[8px] font-black uppercase italic">Sair</button><button onClick={async () => { const title = (document.getElementById('sched-title-final') as HTMLInputElement).value; const date = (document.getElementById('sched-date-final') as HTMLInputElement).value; if (title && date) { await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-4 bg-slate-900 text-white rounded-xl text-[8px] font-black uppercase hover:bg-indigo-600 transition-all italic">Confirmar</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Assinatura Acadêmica" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, Activity, PowerOff, UserPlus, ShieldX,
  Link as LinkIcon, Database, Paperclip
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string, attachment?: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);
  const chatAttachmentRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    for (let i = 0; i < 15; i++) {
      setTimeout(() => {
        const id = Date.now() + i;
        setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
        setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 2500);
      }, i * 150);
    }
  };

  const handleSendMessage = (attachment?: string) => {
    if (!chatMessage.trim() && !attachment) return;
    setChatMessages(prev => [...prev, { 
      user: user.displayName, 
      text: chatMessage, 
      time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}),
      attachment 
    }]);
    setChatMessage('');
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setCurrentExam({ ...currentExam, questions: up });
    setExams(prev => prev.map(e => e.id === currentExam.id ? { ...e, questions: up } : e));
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // VIEW: PREVIEW ALUNO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-8 py-4 flex items-center justify-between sticky top-0 z-10 shadow-xl">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h2 className="text-base font-black uppercase tracking-tight italic">Ambiente do Aluno</h2>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{courses.find(c => c.id === selectedCourseForModules)?.nome}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-6 py-2.5 bg-indigo-600 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-indigo-900/50">Sair da Simulação</button>
        </header>
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6 hidden md:block">
            <h3 className="text-[9px] font-black uppercase text-slate-400 mb-6 tracking-widest italic">Conteúdo Acadêmico</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-3">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 italic">
                    <span className="w-5 h-5 rounded bg-indigo-100 flex items-center justify-center text-[9px]">{idx + 1}</span> {m.title}
                  </div>
                  <div className="pl-6 space-y-2">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[10px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer group">
                        <PlayCircle size={12} className="text-slate-300 group-hover:text-indigo-600" /> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>
          <main className="flex-1 overflow-y-auto p-12 bg-white flex flex-col items-center">
            <div className="max-w-4xl w-full space-y-8 animate-in fade-in duration-700">
              <div className="aspect-video bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col items-center justify-center text-white/50 group relative overflow-hidden">
                 <Play size={80} className="text-white relative z-10" />
                 <p className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] relative z-10 text-white/70 italic">Streaming Master 4K</p>
              </div>
              <div className="space-y-6">
                <div className="flex items-center gap-4">
                   <div className="h-8 w-1 bg-indigo-600 rounded-full"></div>
                   <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Aula Inaugural</h1>
                </div>
                <p className="text-slate-500 leading-relaxed text-sm font-medium italic">Seu aprendizado sem limites.</p>
              </div>
            </div>
          </main>
        </div>
      </div>
    );
  }

  // TELA CHEIA: EDITOR DE QUESTÕES
  if (fullScreenMode === 'question_editor' && currentExam) {
    return (
      <div className="fixed inset-0 z-[1100] bg-slate-50 flex flex-col animate-in fade-in overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-6 py-3 flex items-center justify-between sticky top-0 z-10 shadow-sm text-slate-900">
          <div className="flex items-center gap-3">
            <button onClick={() => setFullScreenMode('none')} className="p-1.5 bg-slate-100 hover:bg-slate-200 rounded-full"><ArrowLeft size={18}/></button>
            <div>
              <h2 className="text-sm font-black uppercase tracking-tighter italic leading-none">Editor de Itens: {currentExam.title}</h2>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">UID: {currentExam.id.substring(0,6)}</p>
            </div>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="bg-slate-900 text-white px-5 py-2 rounded-lg text-[9px] font-black uppercase hover:bg-indigo-600 shadow-md">Salvar Banco</button>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex gap-6">
            <div className="w-[340px] space-y-4 sticky top-0 h-fit">
              <div className="bg-white p-6 rounded-[1.5rem] border border-slate-200 shadow-lg">
                <div className="flex items-center gap-2 mb-4">
                  <div className="p-2 bg-indigo-600 text-white rounded-lg"><Plus size={14}/></div>
                  <h3 className="font-black uppercase text-[10px] tracking-tight italic">Nova Questão</h3>
                </div>
                <div className="space-y-4">
                  <textarea value={questionForm.text} onChange={e => setQuestionForm({...questionForm, text: e.target.value})} placeholder="Enunciado..." className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl h-24 font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 resize-none text-[10px]"></textarea>
                  <div className="space-y-1.5">
                    {questionForm.options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <button onClick={() => setQuestionForm({...questionForm, correct: i})} className={`w-7 h-7 rounded-md font-black text-[9px] transition-all shadow-sm ${questionForm.correct === i ? 'bg-emerald-500 text-white' : 'bg-white border border-slate-100 text-slate-300'}`}>{String.fromCharCode(65+i)}</button>
                        <input value={opt} onChange={e => { const up = [...questionForm.options]; up[i] = e.target.value; setQuestionForm({...questionForm, options: up}); }} placeholder={`Opção ${String.fromCharCode(65+i)}...`} className="flex-1 px-3 py-1.5 bg-slate-50 border-none rounded-lg text-[10px] font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                      </div>
                    ))}
                  </div>
                  <button onClick={handleSaveQuestion} className="w-full py-3 bg-indigo-600 text-white rounded-lg text-[9px] font-black uppercase shadow-lg hover:bg-indigo-700">Anexar Questão</button>
                </div>
              </div>
            </div>
            <div className="flex-1 bg-white rounded-[1.5rem] border border-slate-200 overflow-hidden shadow-sm">
                <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-2"><ListOrdered className="text-indigo-600" size={14}/><h4 className="font-black uppercase text-[9px] tracking-widest italic">Lista de Itens ({currentExam.questions?.length||0})</h4></div>
                </div>
                <div className="divide-y divide-slate-100">
                  {(currentExam.questions || []).map((q, idx) => (
                    <div key={q.id} className="p-5 hover:bg-indigo-50/10 transition-all group relative flex gap-4">
                       <span className="w-7 h-7 rounded-lg bg-slate-900 text-white flex items-center justify-center font-black text-[10px] italic shrink-0">#{idx+1}</span>
                       <div className="flex-1">
                          <p className="text-[11px] font-black uppercase italic text-slate-800 leading-tight mb-3">{q.text}</p>
                          <div className="grid grid-cols-2 gap-2">
                            {q.options.map((opt, oi) => (
                              <div key={oi} className={`px-2 py-1 rounded-md text-[8px] font-bold border ${oi === q.correctOption ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-white text-slate-400 border-slate-100'}`}>{opt}</div>
                            ))}
                          </div>
                       </div>
                       <button onClick={async () => { if(confirm('Excluir?')) { const up = currentExam.questions.filter(i => i.id !== q.id); await updateDoc(doc(db, 'exams', currentExam.id), { questions: up }); setCurrentExam({...currentExam, questions: up}); }}} className="p-1.5 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-md transition-all opacity-0 group-hover:opacity-100"><Trash2 size={14}/></button>
                    </div>
                  ))}
                </div>
            </div>
        </div>
      </div>
