slate-400 tracking-widest italic ml-3">Resumo Pedagógico</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo e objetivos da aula..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl h-28 font-medium text-[11px] shadow-inner resize-none"></textarea></div></div><div className="flex gap-3 pt-2"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase tracking-widest italic hover:bg-slate-200 transition-colors">Voltar</button><button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl shadow-slate-200 hover:bg-indigo-600 transition-all italic">Publicar Aula</button></div></div></div>)}

      {showPptUpload && (<div className="fixed inset-0 z-[2200] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in"><div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 text-center shadow-2xl animate-in zoom-in-95"><div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-8 text-indigo-600 shadow-inner"><Presentation size={40}/></div><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic mb-4 leading-none">Exposição Acadêmica</h3><div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-[2.5rem] p-14 mb-10 cursor-pointer transition-all ${selectedFileName ? 'border-emerald-200 bg-emerald-50/20 shadow-inner' : 'border-slate-100 hover:border-indigo-400 shadow-sm'}`}>{selectedFileName ? <div className="space-y-4"><CheckCircle2 size={60} className="text-emerald-500 mx-auto" /><p className="text-sm font-black text-slate-900 uppercase italic tracking-tighter">{selectedFileName}</p></div> : <><Upload size={40} className="text-slate-200 mb-4 mx-auto" /><span className="text-[9px] font-black uppercase text-slate-300 tracking-[0.5em] block leading-none">Escolher Master (PDF/PPTX)</span></>}<input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { setSelectedFileName(e.target.files[0].name); } }} /></div><div className="flex gap-3"><button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Voltar</button><button disabled={!selectedFileName} onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className={`flex-1 py-5 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl tracking-[0.4em] italic transition-all ${selectedFileName ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200' : 'bg-slate-200 cursor-not-allowed'}`}>Lançar Slides</button></div></div></div>)}

