              </div>
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 h-full overflow-hidden flex flex-col shadow-sm">
                  <div className="flex items-center justify-between mb-10"><div className="flex items-center gap-5"><div className="p-4 bg-amber-50 text-amber-600 rounded-2xl shadow-inner"><Calendar size={24}/></div><h3 className="font-black text-slate-900 uppercase text-xs italic tracking-widest leading-none">Agenda Docente</h3></div><button onClick={() => setIsScheduleModalOpen(true)} className="px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 shadow-2xl transition-all text-[9px] font-black uppercase italic tracking-widest flex items-center gap-2"><Plus size={16}/> Schedule a Class</button></div>
                  <div className="flex-1 overflow-y-auto space-y-4 pr-3 custom-scrollbar">
                     {scheduledClasses.length === 0 ? (
                       <div className="h-full flex flex-col items-center justify-center text-slate-300 italic p-10 text-center"><ClipboardList size={40} className="mb-4 opacity-20"/><p className="text-[10px] font-black uppercase tracking-widest">Nenhuma aula agendada</p></div>
                     ) : scheduledClasses.map(s => (
                       <div key={s.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl flex justify-between items-center group hover:bg-white hover:shadow-xl hover:border-indigo-100 transition-all duration-500">
