                          <button onClick={async () => { if(confirm('Deseja excluir este agendamento?')) await deleteDoc(doc(db, 'scheduledClasses', s.id)); }} className="p-3.5 text-slate-200 hover:text-rose-600 bg-white rounded-xl shadow-sm border border-slate-100 group-hover:scale-110 transition-all"><Trash2 size={18}/></button>
                       </div>
                     ))}
                  </div>
              </div>
            </div>
          )}
        </div>
