      {/* MODALS ACADÊMICOS */}
      {isModuleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-center shadow-2xl"><div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto mb-8 text-indigo-600 shadow-inner"><Layers size={32}/></div><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 italic leading-none">{currentModuleId ? 'Revisar Módulo' : 'Novo Módulo Master'}</h3><div className="space-y-1.5 text-left mb-10"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Estrutura Curricular</label><input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Ex: Teologia Sistemática..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl outline-none font-black text-xs shadow-inner focus:ring-1 focus:ring-indigo-600 transition-all" /></div><div className="flex gap-3"><button onClick={() => { setIsModuleModalOpen(false); setModuleTitle(''); setCurrentModuleId(null); }} className="flex-1 py-4.5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase tracking-widest italic">Cancelar</button><button onClick={async () => { if(!moduleTitle) return; if(currentModuleId) { await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle }); } else { await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() }); } setIsModuleModalOpen(false); }} className="flex-1 py-4.5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl shadow-indigo-100 italic hover:bg-indigo-700">Gravar Dados</button></div></div></div>)}

