         <div className="flex gap-3 pt-2"><button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase italic">Voltar</button><button onClick={async () => { const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl shadow-indigo-100 hover:bg-indigo-700 italic">Gravar Avaliação</button></div>
      </div></div>)}

      {isScheduleModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden text-slate-900 text-center"><div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full -mr-16 -mt-16 opacity-50 blur-[60px]"></div><div className="w-16 h-16 bg-indigo-600 text-white rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-xl"><Bell size={32} /></div><h3 className="text-2xl font-black uppercase tracking-tighter italic leading-none mb-10">Agendar Novo Encontro</h3><div className="space-y-5 mb-10 text-left"><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Tema da Aula</label><input id="sched-title-final" placeholder="Ex: Teologia Contemporânea..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Cronograma (Data/Hora)</label><input id="sched-date-final" type="datetime-local" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div></div><div className="flex gap-3"><button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase italic tracking-widest">Sair</button><button onClick={async () => { const title = (document.getElementById('sched-title-final') as HTMLInputElement).value; const date = (document.getElementById('sched-date-final') as HTMLInputElement).value; if (title && date) { await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() }); setIsScheduleModalOpen(false); } }} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase hover:bg-indigo-600 shadow-2xl transition-all italic tracking-widest">Confirmar Agendamento</button></div></div></div>)}

      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95"><div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-center shadow-2xl"><div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto mb-8 text-emerald-600 shadow-inner"><FileText size={32}/></div><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 italic leading-none">Anexar Material Master</h3><div className="space-y-5 mb-10 text-left"><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Nome do Recurso</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: E-book Teologia..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Link (Drive/Cloud)</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div></div><div className="flex gap-3"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase italic">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl italic hover:bg-indigo-700">Publicar Agora</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Validação Docente" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, Activity, PowerOff, UserPlus, ShieldX,
  Link as LinkIcon, Database, Paperclip
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [presentationSlide, setPresentationSlide] = useState(1);
  const [showPptUpload, setShowPptUpload] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string, attachment?: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [virtualBg, setVirtualBg] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [customBgUrl, setCustomBgUrl] = useState<string | null>(null);
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null);
  const [globalMute, setGlobalMute] = useState(false);
  const [globalCamBlock, setGlobalCamBlock] = useState(false);

  // Academic States
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));

  // Modais
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  // Telas Cheias
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'test_simulation' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);

  // Simulation
  const [testStarted, setTestStarted] = useState(false);
  const [currentTestAnswers, setCurrentTestAnswers] = useState<Record<string, number>>({});
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(180); 

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const customBgInputRef = useRef<HTMLInputElement>(null);
  const chatAttachmentRef = useRef<HTMLInputElement>(null);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleNextQuestion = () => {
    if (!currentExam) return;
    if (currentQuestionIndex < (currentExam.questions?.length || 0) - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setTimeLeft(180);
    } else {
      setTestStarted(false);
      setFullScreenMode('none');
      alert('Simulação finalizada!');
    }
  };

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const fetchSig = async () => {
      const d = await getDoc(doc(db, 'users', user.uid));
      if (d.exists()) setUserSignature(d.data().signatureUrl || null);
    };
    fetchSig();

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  useEffect(() => {
    let timer: any;
    if (testStarted && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (timeLeft === 0 && testStarted) {
      handleNextQuestion();
    }
    return () => clearInterval(timer);
  }, [testStarted, timeLeft]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia(selectedDevices.video, selectedDevices.audio);
  };

  const startLiveFromLobby = () => {
    setIsLiveActive(true);
    setShowLobby(false);
    setTimeout(() => {
      if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current;
    }, 200);
  };

  const stopLive = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsLiveActive(false);
    setIsPresentationMode(false);
    setScreenShareActive(false);
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    for (let i = 0; i < 15; i++) {
      setTimeout(() => {
        const id = Date.now() + i;
        setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
        setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 2500);
      }, i * 150);
    }
  };

  const handleSendMessage = (attachment?: string) => {
    if (!chatMessage.trim() && !attachment) return;
    setChatMessages(prev => [...prev, { 
      user: user.displayName, 
      text: chatMessage, 
      time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}),
      attachment 
    }]);
    setChatMessage('');
  };

  const handleSaveQuestion = async () => {
    if (!currentExam || !questionForm.text) return;
    const newQ = { id: Math.random().toString(36).substr(2,9), text: questionForm.text, options: [...questionForm.options], correctOption: questionForm.correct };
    const up = [...(currentExam.questions || []), newQ];
    await updateDoc(doc(db, 'exams', currentExam.id), { questions: up });
    setCurrentExam({ ...currentExam, questions: up });
    setExams(prev => prev.map(e => e.id === currentExam.id ? { ...e, questions: up } : e));
    setQuestionForm({ text: '', options: ['', '', '', ''], correct: 0 });
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const statsFeedback = useMemo(() => {
    const relevant = feedbacks.filter(f => f.courseId === selectedCourseForModules);
    const total = relevant.length;
    const avg = total > 0 ? (relevant.reduce((a, b) => a + (b.rating || 0), 0) / total).toFixed(1) : '0.0';
    const cats = { elogio: relevant.filter(f => f.type === 'elogio').length, reclamacao: relevant.filter(f => f.type === 'reclamacao').length, sugestao: relevant.filter(f => f.type === 'sugestao').length };
    const dist = [1,2,3,4,5].map(s => ({ star: s, count: relevant.filter(f => f.rating === s).length }));
    return { avg, total, cats, dist, relevant };
  }, [feedbacks, selectedCourseForModules]);

  if (loading) return <div className="h-full flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // SALA DE LIVE ATIVA
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white overflow-hidden font-sans">
        <div className="absolute inset-0 pointer-events-none z-[1250] overflow-hidden">
           {activeReactions.map(r => (
             <div key={r.id} className="absolute bottom-32 text-6xl animate-reaction-float opacity-0" style={{ left: `${r.left}%` }}>{r.emoji}</div>
           ))}
        </div>

        <div className="absolute top-0 left-0 right-0 z-[1300] p-6 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-rose-600 px-4 py-2 rounded-xl flex items-center gap-2 shadow-2xl border border-rose-500/20"><div className="w-2 h-2 bg-white rounded-full animate-ping"></div><span className="text-[8px] font-black uppercase italic tracking-widest">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 shadow-2xl"><Users size={14} className="text-indigo-400"/><span className="text-[8px] font-black uppercase tracking-widest">{allStudents.length} ALUNOS</span></div>
           </div>
           <div className="bg-indigo-600 px-4 py-2 rounded-xl text-[8px] font-black uppercase flex items-center gap-2 shadow-2xl italic tracking-widest border border-indigo-400/30 pointer-events-auto"><ShieldCheck size={16}/> {user.displayName}</div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-6 lg:p-10">
              <div className={`w-full h-full max-w-[1600px] aspect-video bg-zinc-950 rounded-[2.5rem] overflow-hidden border border-white/5 relative group transition-all duration-700 shadow-[0_50px_100px_rgba(0,0,0,0.8)]`}>
                 {/* Camadas da live: 1. Fundo, 2. Vídeo/Slides, 3. Controles */}
                 {virtualBg !== 'none' && (
                   <div className="absolute inset-0 z-0 bg-cover bg-center" style={{ 
                     backgroundImage: virtualBg === 'office' ? 'url(https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80)' : virtualBg === 'custom' && customBgUrl ? `url(${customBgUrl})` : 'none',
                     filter: virtualBg === 'blur' ? 'blur(30px)' : 'none'
                   }} />
                 )}

                 {isPresentationMode && selectedFileName ? (
                   <div className="absolute inset-0 z-20 bg-white flex flex-col items-center justify-center text-slate-900 animate-in fade-in">
                      <div className="absolute top-8 flex flex-col items-center gap-2">
                         <div className="px-4 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100">Documento Ativo</div>
                         <h5 className="font-black text-base uppercase italic text-slate-900">{selectedFileName}</h5>
                      </div>
                      <Presentation size={120} className="text-indigo-600 opacity-10 mb-8" />
                      <p className="text-slate-400 font-black text-xl uppercase tracking-[0.4em] italic">Slide #{presentationSlide}</p>
                      <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none">
                         <button onClick={() => setPresentationSlide(Math.max(1, presentationSlide - 1))} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-xl pointer-events-auto"><ChevronLeft size={32}/></button>
                         <button onClick={() => setPresentationSlide(presentationSlide + 1)} className="p-6 bg-slate-50 rounded-full text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-xl pointer-events-auto"><ChevronRight size={32}/></button>
                      </div>
                   </div>
                 ) : (
                   <div className="relative w-full h-full z-10 overflow-hidden">
                      <video 
                        ref={videoRef} 
                        autoPlay 
                        playsInline 
                        muted 
                        className={`w-full h-full object-cover transition-all duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`}
                        style={virtualBg !== 'none' ? { maskImage: 'radial-gradient(ellipse at center, black 70%, transparent 100%)', WebkitMaskImage: 'radial-gradient(ellipse at center, black 70%, transparent 100%)' } : {}}
                      />
                      {!videoActive && <div className="absolute inset-0 z-20 bg-zinc-900 flex flex-col items-center justify-center"><div className="w-24 h-24 rounded-full bg-indigo-600 flex items-center justify-center font-black text-4xl text-white shadow-2xl">{user.displayName.charAt(0)}</div><p className="mt-4 text-[8px] font-black uppercase tracking-widest text-white/20 italic">Câmera em Pausa</p></div>}
                   </div>
                 )}

                 {/* DOCK CONTROLES */}
                 <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/80 backdrop-blur-3xl px-8 py-4 rounded-[2rem] border border-white/10 shadow-2xl z-[1400] opacity-0 group-hover:opacity-100 transition-all">
                    <button onClick={toggleMic} className={`p-3 rounded-xl transition-all shadow-xl ${micActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{micActive ? <Mic size={18}/> : <MicOff size={18}/>}</button>
                    <button onClick={toggleVideo} className={`p-3 rounded-xl transition-all shadow-xl ${videoActive ? 'bg-white/5 hover:bg-white/10 text-white' : 'bg-rose-600'}`}>{videoActive ? <Video size={18}/> : <VideoOff size={18}/>}</button>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <button onClick={() => setShowPptUpload(true)} className={`p-3 rounded-xl transition-all shadow-xl ${isPresentationMode ? 'bg-indigo-600 text-white' : 'bg-white/5 hover:bg-white/10 text-white'}`} title="Transmitir Slides"><Presentation size={18}/></button>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <div className="flex gap-1 bg-black/40 p-1 rounded-xl border border-white/5">
                       {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} onClick={() => triggerReaction(e)} className="p-2 hover:bg-white/10 rounded-lg text-lg active:scale-125 transition-transform">{e}</button>)}
                    </div>
                    <div className="w-px h-6 bg-white/10 mx-1"></div>
                    <button onClick={stopLive} className="px-8 py-3 bg-rose-600 hover:bg-rose-700 rounded-xl text-[8px] font-black uppercase tracking-[0.2em] shadow-2xl transition-all italic text-white flex items-center gap-2"><PhoneOff size={16}/> Encerrar Aula</button>
                 </div>

                 <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col gap-3 z-[1400] opacity-0 group-hover:opacity-100 transition-all">
                    <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-3.5 rounded-2xl border transition-all shadow-2xl ${activePanel === 'chat' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><MessageSquare size={22}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'participants' ? 'none' : 'participants')} className={`p-3.5 rounded-2xl border transition-all shadow-2xl ${activePanel === 'participants' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Users size={22}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'settings' ? 'none' : 'settings')} className={`p-3.5 rounded-2xl border transition-all shadow-2xl ${activePanel === 'settings' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/80 border-white/10 text-white'}`}><Settings size={22}/></button>
                 </div>
              </div>
           </div>

           {activePanel !== 'none' && (
             <div className="w-[380px] bg-zinc-950 border-l border-white/5 flex flex-col animate-in slide-in-from-right h-full z-[1500] shadow-2xl">
                <div className="p-6 border-b border-white/5 flex items-center justify-between">
                  <h4 className="text-[10px] font-black uppercase italic text-indigo-400 tracking-widest">{activePanel === 'chat' ? 'Chat Acadêmico' : activePanel === 'participants' ? 'Turma Online' : 'Configurações Master'}</h4>
                  <button onClick={() => setActivePanel('none')} className="p-1.5 bg-white/5 rounded-full hover:bg-white/10 transition-colors"><X size={16}/></button>
                </div>
                <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar">
                   {activePanel === 'chat' ? (
                     <>
                       {chatMessages.map((m, i) => (
                         <div key={i} className="animate-in fade-in slide-in-from-bottom-2">
                           <div className="flex items-center gap-2 mb-1">
                             <span className="text-[9px] font-black text-indigo-400 uppercase italic">{m.user}</span>
                             <span className="text-[7px] text-white/20">{m.time}</span>
                           </div>
                           <div className="bg-white/5 p-3 rounded-2xl border border-white/5 text-[10px] font-medium italic text-slate-300">
                             {m.text && <p className="mb-2">"{m.text}"</p>}
                             {m.attachment && (
                               <div className="flex items-center gap-2 p-2 bg-black/40 rounded-xl border border-white/5 mt-1 group">
                                 <FileText size={14} className="text-indigo-400" />
                                 <span className="flex-1 truncate text-[8px] font-black uppercase">{m.attachment}</span>
                                 <ExternalLink size={12} className="text-white/20 group-hover:text-white" />
                               </div>
                             )}
                           </div>
                         </div>
                       ))}
                     </>
                   ) : activePanel === 'participants' ? (
                     <div className="space-y-4">
                       <div className="p-4 bg-white/5 rounded-2xl border border-white/10 space-y-3">
                         <h5 className="text-[8px] font-black uppercase text-slate-500 tracking-widest italic">Controles Globais</h5>
                         <div className="grid grid-cols-2 gap-2">
                           <button onClick={() => setGlobalMute(!globalMute)} className={`py-2.5 rounded-xl border text-[8px] font-black uppercase flex items-center justify-center gap-2 transition-all ${globalMute ? 'bg-rose-600 border-rose-400' : 'bg-white/5 border-white/10'}`}>
                             {globalMute ? <VolumeX size={14}/> : <Mic size={14}/>} {globalMute ? 'Liberar' : 'Mutar Todos'}
                           </button>
                           <button onClick={() => setGlobalCamBlock(!globalCamBlock)} className={`py-2.5 rounded-xl border text-[8px] font-black uppercase flex items-center justify-center gap-2 transition-all ${globalCamBlock ? 'bg-rose-600 border-rose-400' : 'bg-white/5 border-white/10'}`}>
                             {globalCamBlock ? <UserX size={14}/> : <Video size={14}/>} {globalCamBlock ? 'Liberar' : 'Bloquear Cams'}
                           </button>
                         </div>
                       </div>
                       {allStudents.map(s => (
                         <div key={s.uid} className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/5 group">
                           <div className="flex items-center gap-3">
                             <div className="w-8 h-8 rounded-lg bg-zinc-900 flex items-center justify-center font-black text-xs italic text-indigo-400">{(s.displayName||'U').charAt(0)}</div>
                             <span className="text-[10px] font-black uppercase italic text-slate-300">{s.displayName}</span>
                           </div>
                           <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                             <button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><VolumeX size={12}/></button>
                             <button className="p-2 bg-white/5 hover:bg-rose-600 rounded-lg transition-all"><PowerOff size={12}/></button>
                           </div>
                         </div>
                       ))}
                     </div>
                   ) : (
                     <div className="space-y-6">
                        <div className="space-y-3"><h5 className="text-[8px] font-black uppercase text-white/20 italic tracking-widest">Fonte Master</h5><div className="space-y-2">
                           <div className="relative"><Video size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.video} onChange={e => { setSelectedDevices({...selectedDevices, video:e.target.value}); startLiveMedia(e.target.value, selectedDevices.audio); }} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-3 text-[10px] font-black text-slate-300 outline-none appearance-none"><option value="">Ajustar Câmera...</option>{devices.video.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                           <div className="relative"><Mic size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" /><select value={selectedDevices.audio} onChange={e => { setSelectedDevices({...selectedDevices, audio:e.target.value}); startLiveMedia(selectedDevices.video, e.target.value); }} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-3 text-[10px] font-black text-slate-300 outline-none appearance-none"><option value="">Ajustar Áudio...</option>{devices.audio.map(d => <option key={d.deviceId} value={d.deviceId}>{d.label}</option>)}</select></div>
                        </div></div>
                        <div className="space-y-3"><h5 className="text-[8px] font-black uppercase text-white/20 italic tracking-widest">Cenário Digital</h5><div className="grid grid-cols-2 gap-2">
                           {['none', 'blur', 'office', 'custom'].map(bg => (
                             <button key={bg} onClick={() => { if(bg === 'custom') customBgInputRef.current?.click(); else setVirtualBg(bg as any); }} className={`p-4 rounded-2xl border text-[9px] font-black uppercase transition-all flex flex-col items-center gap-3 ${virtualBg === bg ? 'bg-indigo-600 border-indigo-400 text-white shadow-2xl' : 'bg-white/5 border-white/10 hover:bg-white/10 text-white/40'}`}>
                                <span className="p-3 bg-black/40 rounded-xl">{bg === 'none' ? <Video size={16} /> : bg === 'blur' ? <Sparkles size={16} /> : bg === 'office' ? <ImageIcon size={16} /> : <Upload size={16} />}</span>{bg}
                             </button>
                           ))}
                        </div></div>
                     </div>
                   )}
                </div>
                {activePanel === 'chat' && (
                  <div className="p-6 border-t border-white/5 bg-[#080808]">
                    <div className="relative flex items-center gap-2">
                      <button onClick={() => chatAttachmentRef.current?.click()} className="p-2.5 text-white/20 hover:text-indigo-400 transition-colors bg-white/5 rounded-xl"><Paperclip size={18}/></button>
                      <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Mensagem acadêmica..." className="flex-1 bg-white/5 border-none rounded-xl px-4 py-3.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-600 placeholder:text-white/10" />
                      <button onClick={() => handleSendMessage()} className="p-2.5 text-indigo-500 hover:text-indigo-400 bg-indigo-500/10 rounded-xl transition-all"><Send size={18}/></button>
                    </div>
                  </div>
                )}
             </div>
           )}
        </div>
        {/* CRITICAL FIX: Z-INDEX 3000 AND MOVED TO END TO OVERLAY ACTIVE LIVE */}
        {showPptUpload && (
          <div className="fixed inset-0 z-[3000] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 text-center shadow-2xl animate-in zoom-in-95">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-8 text-indigo-600 shadow-inner"><Presentation size={40}/></div>
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic mb-4 leading-none">Exposição Acadêmica</h3>
              <div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-[2.5rem] p-14 mb-10 cursor-pointer transition-all ${selectedFileName ? 'border-emerald-200 bg-emerald-50/20 shadow-inner' : 'border-slate-100 hover:border-indigo-400 shadow-sm'}`}>
                {selectedFileName ? (
                  <div className="space-y-4"><CheckCircle2 size={60} className="text-emerald-500 mx-auto" /><p className="text-sm font-black text-slate-900 uppercase italic tracking-tighter">{selectedFileName}</p></div>
                ) : (
                  <><Upload size={40} className="text-slate-200 mb-4 mx-auto" /><span className="text-[9px] font-black uppercase text-slate-300 tracking-[0.5em] block leading-none">Escolher Master (PDF/PPTX)</span></>
                )}
                <input type="file" ref={fileInputRef} className="hidden" accept=".pptx,.ppt,.pdf" onChange={(e) => { if(e.target.files?.[0]) { setSelectedFileName(e.target.files[0].name); } }} />
              </div>
              <div className="flex gap-3">
                <button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Voltar</button>
                <button disabled={!selectedFileName} onClick={() => { setIsPresentationMode(true); setShowPptUpload(false); }} className={`flex-1 py-5 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl tracking-[0.4em] italic transition-all ${selectedFileName ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200' : 'bg-slate-200 cursor-not-allowed'}`}>Lançar Slides</button>
              </div>
            </div>
          </div>
        )}
        <input type="file" ref={customBgInputRef} className="hidden" accept="image/*" onChange={e => { if(e.target.files?.[0]) { const reader = new FileReader(); reader.onload = (f) => { setCustomBgUrl(f.target?.result as string); setVirtualBg('custom'); }; reader.readAsDataURL(e.target.files[0]); }}} />
        <input type="file" ref={chatAttachmentRef} className="hidden" onChange={e => { if(e.target.files?.[0]) handleSendMessage(e.target.files[0].name); }} />
        <style>{`
          @keyframes reaction-float {
            0% { transform: translateY(0) scale(0.5); opacity: 0; }
            10% { opacity: 1; }
            100% { transform: translateY(-400px) scale(1.5); opacity: 0; }
          }
          .animate-reaction-float { animation: reaction-float 2.5s ease-out forwards; }
        `}</style>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in fade-in h-full text-slate-900">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-5 animate-in slide-in-from-bottom-5">
           <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100"><Layers size={22}/></div>
              <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Matriz Acadêmica</h1><p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-1">Gestão de Conteúdo EAD</p></div>
            </div>

            <div className="flex flex-wrap items-center gap-3">
              {userSignature && (
                <div className="flex items-center gap-3 px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-2xl shadow-inner group">
                   <img src={userSignature} alt="Signature" className="h-6 grayscale opacity-40 group-hover:opacity-100 transition-opacity" />
                   <span className="text-[7px] font-black uppercase text-slate-400 italic">Docente Validado</span>
                </div>
              )}
              <button onClick={() => setIsSignModalOpen(true)} className="bg-amber-50 text-amber-600 px-5 py-3 rounded-xl text-[8px] font-black uppercase border border-amber-100 flex items-center gap-2 hover:bg-amber-100 transition-all italic"><PenTool size={14}/> Coletar Assinatura</button>
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-5 py-3 rounded-xl text-[8px] font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-2 italic"><Eye size={14}/> Preview Aluno</button>
              <select value={selectedCourseForModules} onChange={e => setSelectedCourseForModules(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-[9px] font-black uppercase outline-none shadow-inner">
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-6 py-3 rounded-xl text-[8px] font-black uppercase shadow-2xl shadow-indigo-200 hover:bg-indigo-700 transition-all flex items-center gap-2 italic tracking-widest"><Plus size={16}/> Novo Módulo</button>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[2.5rem] overflow-hidden group shadow-sm hover:shadow-xl hover:border-indigo-100 transition-all duration-500">
                  <div className="bg-slate-50/50 px-8 py-5 border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="w-10 h-10 bg-indigo-100 text-indigo-700 rounded-xl flex items-center justify-center font-black text-sm italic shadow-inner">#{mod.order}</span>
                      <h3 className="font-black text-slate-800 text-sm uppercase italic tracking-[0.1em]">{mod.title}</h3>
                    </div>
                    <div className="flex items-center gap-3">
                      <button onClick={() => { setExamForm({title:'', courseId: selectedCourseForModules, moduleId: mod.id, type:'activity', passingGrade:70}); setIsExamModalOpen(true); }} className="px-4 py-2.5 bg-amber-50 text-amber-600 text-[8px] font-black uppercase rounded-lg border border-amber-100 hover:bg-amber-100 transition-all italic tracking-widest flex items-center gap-2"><Award size={14}/> Criar Avaliação</button>
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-5 py-2.5 bg-indigo-600 text-white text-[8px] font-black uppercase rounded-lg shadow-lg hover:scale-105 transition-all italic tracking-widest">Add Aula</button>
                      <button onClick={() => { setModuleTitle(mod.title); setCurrentModuleId(mod.id); setIsModuleModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"><Edit3 size={16}/></button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-2 text-slate-200 hover:text-rose-600 transition-all"><Trash2 size={16}/></button>
                    </div>
                  </div>
                  <div className="p-8 space-y-3">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-white p-5 rounded-2xl flex items-center justify-between border border-slate-50 hover:border-indigo-100 transition-all group/l shadow-sm">
                        <div className="flex items-center gap-4">
                          <span className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center font-black text-slate-300 group-hover/l:bg-indigo-600 group-hover/l:text-white transition-all italic text-xs">{i+1}</span>
                          <div>
                            <h4 className="font-black text-slate-900 uppercase italic tracking-tight text-xs leading-none">{l.title}</h4>
                            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-1">Status: Publicado</p>
                          </div>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover/l:opacity-100 transition-opacity">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-2.5 text-indigo-600 hover:bg-indigo-100 rounded-xl transition-all bg-white border border-slate-100 shadow-sm"><Edit3 size={14}/></button>
                          <button onClick={async () => { if(confirm('Excluir?')) { const up = mod.lessons.filter(item => item.id !== l.id); await updateDoc(doc(db, 'modulos', mod.id), { lessons: up }); }}} className="p-2.5 text-rose-500 hover:bg-rose-50 rounded-xl transition-all border border-slate-100 shadow-sm"><Trash2 size={14}/></button>
                        </div>
                      </div>
                    ))}
                    {exams.filter(e => e.moduleId === mod.id).map(ex => (
                      <div key={ex.id} className="bg-amber-50/20 p-6 rounded-2xl flex items-center justify-between border border-amber-100 shadow-sm group/e hover:bg-amber-50 transition-all">
                        <div className="flex items-center gap-5">
                          <div className="p-3 bg-amber-100 text-amber-600 rounded-xl shadow-inner"><Award size={22}/></div>
                          <div>
                             <h4 className="font-black text-amber-900 text-xs uppercase italic leading-none">{ex.title}</h4>
                             <span className="text-[8px] font-black text-amber-600/60 uppercase italic mt-1.5 block tracking-widest">{ex.questions?.length||0} Itens Acadêmicos</span>
                          </div>
                        </div>
                        <div className="flex gap-2">
                           <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="px-6 py-3 bg-amber-600 text-white text-[9px] font-black uppercase rounded-xl shadow-xl hover:bg-amber-700 transition-all italic tracking-widest">Gerir Itens</button>
                           <button onClick={() => { setCurrentExam(ex); setFullScreenMode('test_simulation'); setTestStarted(false); }} className="p-3 bg-white text-amber-600 border border-amber-200 rounded-xl hover:bg-amber-600 hover:text-white transition-all"><Eye size={18}/></button>
                        </div>
                      </div>
                    ))}
                  </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* MATERIAIS */}
      {activeSub === 'materiais' && (
        <div className="space-y-5 animate-in fade-in">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-lg shadow-sm"><FileText size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Materiais</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Gestão de Arquivos</p></div>
            </div>
            <button onClick={() => setIsMaterialModalOpen(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-1.5 italic tracking-widest"><Plus size={14}/> Novo Arquivo</button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {materials.filter(m => m.courseId === selectedCourseForModules).map(m => (
              <div key={m.id} className="bg-white p-6 rounded-3xl border border-slate-100 relative group hover:shadow-2xl hover:border-indigo-200 transition-all text-center">
                <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-inner group-hover:bg-indigo-50 transition-colors"><FileText size={24} className="text-indigo-500" /></div>
                <h4 className="font-black text-slate-900 text-[10px] uppercase italic mb-5 leading-tight tracking-tight line-clamp-2 h-8">{m.title}</h4>
                <a href={m.url} target="_blank" className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl text-[8px] font-black uppercase hover:bg-indigo-600 transition-all italic"><ExternalLink size={12}/> Abrir</a>
                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-slate-200 hover:text-rose-500 transition-all"><Trash2 size={14}/></button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* AVALIAÇÃO */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-5 animate-in fade-in">
          <div className="bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-amber-50 text-amber-600 rounded-lg shadow-sm"><Award size={18}/></div>
              <div><h1 className="text-base font-black uppercase italic tracking-tighter leading-none">Banca de Avaliação</h1><p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Controladoria Acadêmica</p></div>
            </div>
            <button onClick={() => { setExamForm({title:'', courseId: selectedCourseForModules, moduleId:'', type:'activity', passingGrade:70}); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[8px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-1.5 italic tracking-widest"><Plus size={14}/> Criar Avaliação</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(ex => (
              <div key={ex.id} className="bg-white p-6 rounded-3xl border border-slate-100 group relative hover:shadow-2xl transition-all duration-500">
                <div className="flex justify-between items-start mb-6">
                  <div className="p-3 bg-slate-50 rounded-xl shadow-inner group-hover:bg-amber-50 transition-colors"><Award size={24} className={ex.type === 'evaluation' ? 'text-amber-500' : 'text-emerald-500'} /></div>
                  <div className="text-right flex flex-col">
                    <span className="text-[7px] font-black uppercase text-slate-400 italic">Corte</span>
                    <span className="text-xl font-black text-slate-900 tabular-nums leading-none tracking-tighter">{ex.passingGrade}%</span>
                  </div>
                </div>
                <h4 className="font-black text-slate-900 text-xs uppercase italic mb-6 line-clamp-1 group-hover:text-indigo-600 transition-colors">{ex.title}</h4>
                <div className="flex gap-2 items-center">
                  <button onClick={() => { setCurrentExam(ex); setFullScreenMode('question_editor'); }} className="flex-1 py-3 bg-slate-900 text-white rounded-xl text-[8px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-all italic tracking-widest">Itens ({ex.questions?.length||0})</button>
                  <button onClick={() => { setCurrentExam(ex); setFullScreenMode('test_simulation'); setTestStarted(false); }} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm border border-indigo-100"><Eye size={16}/></button>
                  <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'exams', ex.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-600 transition-all shadow-sm border border-rose-100"><Trash2 size={16}/></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

