                           <div className="bg-white/5 p-3 rounded-2xl border border-white/5 text-[10px] font-medium italic text-slate-300">
                             {m.text && <p className="mb-2">"{m.text}"</p>}
                             {m.attachment && (
                               <div className="flex items-center gap-2 p-2 bg-black/40 rounded-xl border border-white/5 mt-1 group">
