              <div className="flex gap-3">
                <button onClick={() => { setShowPptUpload(false); setSelectedFileName(null); }} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Voltar</button>
