                      <button onClick={() => handleSendMessage()} className="p-3 text-indigo-500 hover:text-indigo-400 hover:scale-110 bg-indigo-500/10 rounded-2xl transition-all shadow-lg active:scale-95"><Send size={22}/></button>
                    </div>
                  </div>
                )}
             </div>
