slate-400 tracking-widest italic ml-3">Resumo Pedagógico</label><textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo e objetivos da aula..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl h-28 font-medium text-[11px] shadow-inner resize-none"></textarea></div></div><div className="flex gap-3 pt-2"><button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase tracking-widest italic hover:bg-slate-200 transition-colors">Voltar</button><button onClick={handleSaveLesson} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl shadow-slate-200 hover:bg-indigo-600 transition-all italic">Publicar Aula</button></div></div></div>)}

      {isExamModalOpen && (<div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6 animate-in zoom-in-95"><div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 space-y-8 shadow-2xl">
         <div className="flex items-center gap-4"><div className="p-3 bg-amber-50 text-amber-600 rounded-xl shadow-inner border border-amber-100"><Award size={24}/></div><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Configuração de Exame</h3></div>
         <div className="space-y-5">
            <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Título da Avaliação</label><input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Avaliação Master do Módulo..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner focus:ring-1 focus:ring-indigo-600" /></div>
            <div className="grid grid-cols-2 gap-4">
               <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Média Corte %</label><input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div>
               <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 tracking-widest italic ml-4">Tipo Acadêmico</label><select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option value="activity">Atividade</option><option value="evaluation">Prova Final</option></select></div>
            </div>
         </div>
         <div className="flex gap-3 pt-2"><button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase italic">Voltar</button><button onClick={async () => { const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() }; if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload); else await addDoc(collection(db, 'exams'), payload); setIsExamModalOpen(false); }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl shadow-indigo-100 hover:bg-indigo-700 italic">Gravar Avaliação</button></div>
      </div></div>)}

      {isSignModalOpen && <SignaturePad title="Validação Docente" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

