                <button onClick={startLobby} className="bg-slate-900 text-white px-12 py-5 rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-rose-600 transition-all flex items-center gap-3 italic tracking-widest active:scale-95"><Tv size={20}/> Configurar Início</button>
