      {isMaterialModalOpen && (<div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl animate-in zoom-in-95 text-slate-900"><div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-center shadow-2xl"><div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto mb-8 text-emerald-600 shadow-inner"><FileText size={32}/></div><h3 className="text-2xl font-black uppercase tracking-tighter mb-8 italic leading-none">Anexar Material Master</h3><div className="space-y-5 mb-10 text-left"><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Nome do Recurso</label><input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Ex: E-book Teologia..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div><div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Link (Cloud/PDF)</label><input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="URL..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" /></div></div><div className="flex gap-3"><button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[9px] font-black uppercase italic">Cancelar</button><button onClick={async () => { if(materialTitle && materialUrl) { await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() }); setIsMaterialModalOpen(false); }}} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl italic hover:bg-indigo-700">Publicar Agora</button></div></div></div>)}

      {isSignModalOpen && <SignaturePad title="Validação Docente" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setUserSignature(b); setIsSignModalOpen(false); }} />}
    </div>
  );
};

