                <h3 className="text-[10px] font-black uppercase tracking-[0.3em] italic flex items-center gap-3 text-slate-800"><Activity size={16} className="text-indigo-600" /> Distribuição Qualitativa</h3>
                <div className="space-y-4">
                   {statsFeedback.dist.reverse().map(item => (
                     <div key={item.star} className="flex items-center gap-6 group">
                        <div className="flex items-center gap-1 w-16"><span className="text-[11px] font-black text-slate-800 tabular-nums">{item.star}</span><Star size={12} className="fill-amber-400 text-amber-400" /></div>
                        <div className="flex-1 h-2 bg-slate-50 rounded-full overflow-hidden shadow-inner group-hover:bg-slate-100 transition-colors">
                           <div className={`h-full transition-all duration-1000 linear shadow-lg ${item.star >= 4 ? 'bg-emerald-500' : item.star === 3 ? 'bg-amber-400' : 'bg-rose-500'}`} style={{ width: `${statsFeedback.total > 0 ? (item.count / statsFeedback.total) * 100 : 0}%` }}></div>
                        </div>
                        <span className="w-10 text-[10px] font-black text-slate-900 tabular-nums text-right">{item.count}</span>
                     </div>
                   ))}
                </div>
             </div>
             <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden group">
                <div className="relative z-10 space-y-6">
                   <h3 className="text-[10px] font-black uppercase tracking-widest italic text-indigo-400">Análise de Retenção</h3>
                   <div className="space-y-3">
                      <p className="text-slate-300 text-[11px] italic leading-relaxed">Engajamento discente estabilizado em <strong>+{statsFeedback.fidelityRate}%</strong>.</p>
                      <div className="pt-6 grid grid-cols-2 gap-4 border-t border-white/5">
                        <div><p className="text-2xl font-black tracking-tighter tabular-nums">{statsFeedback.fidelityRate}%</p><p className="text-[7px] font-black uppercase text-white/30 tracking-widest">Fidelidade</p></div>
                        <div><p className="text-2xl font-black tracking-tighter tabular-nums">{statsFeedback.avg}</p><p className="text-[7px] font-black uppercase text-white/30 tracking-widest">Média NPS</p></div>
                      </div>
                   </div>
                </div>
                <BarChart3 size={150} className="absolute -bottom-10 -right-10 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        </div>
      )}

      {/* DIÁRIO / RELATÓRIO / FREQUÊNCIA */}
      {(['diario', 'relatorio', 'frequencia'] as ProfessorSubView[]).includes(activeSub) && (
        <div className="space-y-5 animate-in fade-in flex flex-col h-full">
          <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-5 shrink-0">
            <div className="p-3.5 bg-slate-900 text-white rounded-2xl shadow-2xl">
