      {/* AULA AO VIVO (SETUP) */}
      {activeSub === 'live' && !isLiveActive && (
        <div className="h-full flex flex-col animate-in fade-in">
          {showLobby ? (
            <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
               <div className="bg-white w-full max-w-5xl rounded-[3rem] overflow-hidden flex flex-col md:flex-row shadow-2xl">
