import React, { useState, useEffect } from 'react';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import { UserRole, MainView, User, ProfessorSubView } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSubView, setActiveProfessorSubView] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    // FIX: Using correctly imported onAuthStateChanged from firebase/auth
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          // FIX: Using correctly imported doc and getDoc from firebase/firestore
          const userDoc = await getDoc(doc(db, 'users', user.uid));
          const userData = userDoc.data();
          const role = (userData?.role as UserRole) || 'aluno';

          setCurrentUser({
            uid: user.uid,
            email: user.email,
            displayName: userData?.nome || user.displayName || 'Usuário',
            role: role,
            photoURL: user.photoURL || undefined
          });
        } catch (error) {
          console.error("Erro ao buscar perfil RBAC:", error);
          setCurrentUser(null);
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
          <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Escola Bíblica EAD</p>
        </div>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  const handleOpenLiveFromDashboard = () => {
    setActiveView('professor');
    setActiveProfessorSubView('live');
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView onOpenLive={handleOpenLiveFromDashboard} />;
      case 'professor': return <ProfessorView user={currentUser} activeSubView={activeProfessorSubView} />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView onOpenLive={handleOpenLiveFromDashboard} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSubView} 
            setActiveSub={setActiveProfessorSubView} 
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8 h-full">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { collection, query, limit, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Course } from '../types';
import { Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv } from 'lucide-react';

interface DashboardViewProps {
  onOpenLive?: () => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ onOpenLive }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        // FIX: Using correctly imported firestore functions
        const q = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'), limit(10));
        const querySnapshot = await getDocs(q);
        const fetched: Course[] = [];
        querySnapshot.forEach((doc) => {
          fetched.push({ id: doc.id, ...doc.data() } as Course);
        });
        setCourses(fetched);
      } catch (err) { console.error(err); } finally { setLoading(false); }
    };
    fetchCourses();
  }, []);

  const stats = [
    { label: 'Alunos Ativos', value: '1.248', icon: <Users size={20} />, trend: '+12.5%', color: 'indigo' },
    { label: 'Certificados', value: '452', icon: <FileBadge size={20} />, trend: '+4.1%', color: 'amber' },
    { label: 'Engajamento', value: '88.2%', icon: <Activity size={20} />, trend: '+2.0%', color: 'emerald' },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-700">
      <header>
        <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase">Painel de Controle</h1>
        <p className="text-slate-500 text-sm">Bem-vindo à central administrativa da Escola Bíblica.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex items-start justify-between group hover:border-indigo-300 transition-all">
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
              <div className="flex items-baseline gap-2">
                <h3 className="text-2xl font-black text-slate-900">{stat.value}</h3>
                <span className="text-[10px] font-bold text-emerald-600 flex items-center bg-emerald-50 px-2 py-0.5 rounded-full">
                  <TrendingUp size={10} className="mr-0.5" /> {stat.trend}
                </span>
              </div>
            </div>
            <div className={`p-3 bg-${stat.color}-50 text-${stat.color}-600 rounded-2xl group-hover:scale-110 transition-transform`}>
              {stat.icon}
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Cursos Recentes</h2>
            <button className="text-[10px] font-black uppercase text-indigo-600 hover:text-indigo-800 bg-indigo-50 px-4 py-2 rounded-xl transition-all">Ver Todos</button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                <tr>
                  <th className="px-8 py-4">Disciplina</th>
                  <th className="px-8 py-4">Matrículas</th>
                  <th className="px-8 py-4">Status</th>
                  <th className="px-8 py-4"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 text-sm">
                {loading ? (
                  <tr><td colSpan={4} className="p-12 text-center text-slate-400 text-[10px] font-black uppercase italic tracking-widest">Carregando Fluxo de Dados...</td></tr>
                ) : courses.map(c => (
                  <tr key={c.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="flex flex-col">
                        <span className="font-black text-slate-900 text-xs uppercase tracking-tight">{c.nome}</span>
                        <span className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">ID: {c.id.substring(0,8)}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5 font-black text-slate-600 text-xs">{c.inscritos} Alunos</td>
                    <td className="px-8 py-5">
                      <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${c.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                        {c.status}
                      </span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <button className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"><ArrowUpRight size={16} /></button>
