                   <button key={i} className="w-full flex items-center justify-between px-6 py-4 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase tracking-widest group border border-transparent hover:border-indigo-400">
                     {item}
